### VERSIONSVERWALTUNG
### ===================================


def get_saved_version():
    """Liest die gespeicherte Version aus der Benutzerdaten-Verzeichnis."""
    user_base = Config.get_user_data_dir() if getattr(sys, "frozen", False) else None
    if not user_base:
        return None

    version_file = os.path.join(user_base, ".version")
    try:
        if os.path.exists(version_file):
            with open(version_file, "r", encoding="utf-8") as f:
                return f.read().strip()
    except Exception as e:
        print(f"Fehler beim Lesen der Version: {e}")
    return None


def save_current_version():
    """Speichert die aktuelle APP_VERSION im Benutzerdaten-Verzeichnis."""
    user_base = Config.get_user_data_dir() if getattr(sys, "frozen", False) else None
    if not user_base:
        return

    version_file = os.path.join(user_base, ".version")
    try:
        with open(version_file, "w", encoding="utf-8") as f:
            f.write(APP_VERSION)
        print(f"✅ Version {APP_VERSION} gespeichert")
    except Exception as e:
        print(f"Fehler beim Speichern der Version: {e}")


###===================================
### UPDATE CHECK (GitHub API)
###===================================

"""Die GitHub‑API liefert immer
    das neueste verfügbare Release. Wenn ein Release gelöscht, wird stattdessen das nächstjüngere (oder gar keines) zurückgegeben.
    In diesem Fall wird keine neue Version erkannt
    """


class UpdateCheckThread(QThread):
    """Prüft im Hintergrund, ob eine neuere Version auf GitHub existiert."""

    update_available = pyqtSignal(str, str)  # (tag_name, html_url)

    def run(self):
        try:
            import requests

            url = "https://api.github.com/repos/BinhDiez/PDFDarkView/releases/latest"
            resp = requests.get(url, timeout=5)
            if resp.status_code == 200:
                data = resp.json()
                latest_tag = data["tag_name"]
                # Entferne führendes 'v', falls vorhanden
                latest_version = (
                    latest_tag[1:] if latest_tag.startswith("v") else latest_tag
                )
                if self._version_greater(latest_version, APP_VERSION):
                    self.update_available.emit(latest_tag, data["html_url"])
        except Exception:
            # Alle Fehler (Netzwerk, Timeout, JSON‑Fehler) werden ignoriert
            pass

    @staticmethod
    def _version_greater(v1, v2):
        """Vergleicht zwei SemVer‑Strings (z.B. '2.0.1' > '2.0.0')."""

        def to_list(v):
            return [int(x) for x in v.split(".")]

        return to_list(v1) > to_list(v2)


###===================================
### TRANSLATIONS UPDATE (ASYNC)
###===================================


class TranslationsUpdateThread(QThread):
    """
    Thread für asynchrones Herunterladen von Übersetzungen von GitHub.
    """

    progress = pyqtSignal(str)  # Statusmeldung
    finished = pyqtSignal(
        bool, str, int, int
    )  # (success, message, new_count, updated_count)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._is_cancelled = False

    def cancel(self):
        """Bricht den Download ab."""
        self._is_cancelled = True

    def run(self):
        """Führt den Download im Hintergrund durch."""
        try:
            import requests

            # GitHub API für den translations Ordner
            url = "https://api.github.com/repos/BinhDiez/PDFDarkView/contents/translations"

            self.progress.emit(self.tr("translations_downloading"))

            response = requests.get(url, timeout=10)
            if response.status_code != 200:
                self.finished.emit(
                    False, f"GitHub API Fehler: {response.status_code}", 0, 0
                )
                return

            files = response.json()

            # Nur .py Dateien filtern (translations_*.py)
            language_files = [
                f
                for f in files
                if f["name"].endswith(".py") and f["name"].startswith("translations_")
            ]

            if not language_files:
                self.finished.emit(False, "Keine Übersetzungsdateien gefunden", 0, 0)
                return

            # User-Verzeichnis für Übersetzungen
            user_base = Config.get_user_data_dir()
            if not user_base:
                self.finished.emit(False, "Benutzerverzeichnis nicht gefunden", 0, 0)
                return

            translations_dir = os.path.join(user_base, "translations")
            os.makedirs(translations_dir, exist_ok=True)

            updated_count = 0
            new_count = 0
            unchanged_count = 0

            total_files = len(language_files)

            # Jede Sprachdatei herunterladen
            for i, file_info in enumerate(language_files):
                # Prüfen ob abgebrochen
                if self._is_cancelled:
                    self.finished.emit(
                        False, "Download abgebrochen", new_count, updated_count
                    )
                    return

                filename = file_info["name"]
                download_url = file_info["download_url"]

                try:
                    # Datei herunterladen
                    file_response = requests.get(download_url, timeout=10)
                    if file_response.status_code == 200:
                        dst_path = os.path.join(translations_dir, filename)

                        # Prüfen ob Datei existiert und identisch ist
                        if os.path.exists(dst_path):
                            with open(dst_path, "rb") as f:
                                existing_content = f.read()

                            if existing_content == file_response.content:
                                unchanged_count += 1
                                continue  # Identisch → überspringen
                            else:
                                updated_count += 1
                        else:
                            new_count += 1

                        # Datei speichern
                        with open(dst_path, "wb") as f:
                            f.write(file_response.content)

                        # Fortschritt anzeigen (jede 5. Datei)
                        if (i + 1) % 5 == 0 or i == total_files - 1:
                            self.progress.emit(f"{i+1}/{total_files}")

                except Exception as e:
                    print(f"  ❌ Fehler bei {filename}: {e}")

            # Erfolgsmeldung
            if new_count == 0 and updated_count == 0 and unchanged_count > 0:
                self.finished.emit(
                    True, "Alle Übersetzungen sind bereits aktuell.", 0, 0
                )
            else:
                self.finished.emit(
                    True,
                    f"{new_count} neu, {updated_count} aktualisiert",
                    new_count,
                    updated_count,
                )

        except requests.exceptions.Timeout:
            self.finished.emit(
                False, "Zeitüberschreitung beim Verbinden zu GitHub", 0, 0
            )
        except Exception as e:
            self.finished.emit(False, f"Fehler: {str(e)}", 0, 0)


