class Config:
    EXTRA_MENU = False  # Sichtbarkeit des Menüs für Externe Programme

    @staticmethod
    def get_script_dir():
        """Liefert den Pfad zum Skript, auch wenn gebundelt oder gefroren"""
        if getattr(sys, "frozen", False):
            return os.path.dirname(sys.executable)
        elif "__file__" in globals():
            return os.path.dirname(os.path.abspath(__file__))
        else:
            return os.getcwd()

    # Basisverzeichnis - WIRD IN initialize() GESETZT
    SCRIPT_DIR = None
    BASE_DIR = None

    @classmethod
    def initialize(cls):
        """Initialisiert die Pfade - muss nach Klassen-Definition aufgerufen werden"""
        cls.SCRIPT_DIR = cls.get_script_dir()
        cls.BASE_DIR = os.path.dirname(cls.SCRIPT_DIR)

        # Debug-Ausgabe
        print(f"=== CONFIG INITIALIZED ===")
        print(f"SCRIPT_DIR: {cls.SCRIPT_DIR}")
        print(f"BASE_DIR: {cls.BASE_DIR}")

        # Jetzt alle pfadabhängigen Variablen setzen
        cls._initialize_paths()
        cls._debug_tool_paths()

        print("=== END CONFIG INIT ===")

    @classmethod
    def _find_ocr_tools(cls):
        start_time = time.time()
        # print(f"[TIMING] _find_ocr_tools started")

        # ----- 1. Bundle-Modus (PyInstaller .app) -----
        if getattr(sys, "frozen", False):
            base_path = sys._MEIPASS
            bundle_bin = os.path.join(base_path, "tools", "bin")
            bundle_lib = os.path.join(base_path, "tools", "lib")

            if platform.system() == "Windows":
                exe_ext = ".exe"
            else:
                exe_ext = ""

            tesseract_candidate = os.path.join(bundle_bin, f"tesseract{exe_ext}")
            ocrmypdf_candidate = os.path.join(bundle_bin, f"ocrmypdf{exe_ext}")

            if os.path.exists(tesseract_candidate):
                cls.TESSERACT_PATH = tesseract_candidate
                cls.POPPLER_PATH = bundle_bin
                if platform.system() == "Darwin":
                    if "DYLD_LIBRARY_PATH" in os.environ:
                        os.environ["DYLD_LIBRARY_PATH"] = bundle_lib + ":" + os.environ["DYLD_LIBRARY_PATH"]
                    else:
                        os.environ["DYLD_LIBRARY_PATH"] = bundle_lib

                cls.OCRMYPDF_PATH = ocrmypdf_candidate if os.path.exists(ocrmypdf_candidate) else None

                # Tessdata
                user_dir = cls.get_user_data_dir()
                tessdata_ok = False
                if user_dir:
                    user_tessdata = os.path.join(user_dir, "tessdata")
                    if os.path.exists(user_tessdata):
                        os.environ["TESSDATA_PREFIX"] = user_tessdata
                        tessdata_ok = True
                        # print(f"DEBUG: Verwende Tessdata aus Userverzeichnis: {user_tessdata}")
                if not tessdata_ok:
                    bundle_tessdata = os.path.join(base_path, "default_data", "tessdata")
                    if os.path.exists(bundle_tessdata):
                        os.environ["TESSDATA_PREFIX"] = bundle_tessdata
                        print(f"DEBUG: Verwende Tessdata aus Bundle: {bundle_tessdata}")
                    else:
                        print("WARNUNG: Kein Tessdata-Ordner verfügbar.")

                elapsed = time.time() - start_time
                print(f"[TIMING] _find_ocr_tools (Bundle) completed in {elapsed:.3f}s")
                return (cls.TESSERACT_PATH, cls.OCRMYPDF_PATH)

        # ----- 2. System-Suche (nicht gebündelt) -----
        tesseract_path = None
        ocrmypdf_path = None

        # 2.1 shutil.which (sehr schnell, plattformunabhängig)
        # print("[TIMING] Suche mit shutil.which...")
        tesseract_path = shutil.which("tesseract")
        ocrmypdf_path = shutil.which("ocrmypdf")

        if tesseract_path:
            print(f"[TIMING] Tesseract gefunden mit shutil.which: {tesseract_path}")
        if ocrmypdf_path:
            print(f"[TIMING] OCRmyPDF gefunden mit shutil.which: {ocrmypdf_path}")

        # 2.2 Falls nicht gefunden, durchsuche bekannte Pfade (ohne subprocess)
        if not tesseract_path:
            possible_tesseract_paths = []
            if platform.system() == "Darwin":
                possible_tesseract_paths = [
                    "/usr/local/bin/tesseract",
                    "/opt/homebrew/bin/tesseract",
                    "/usr/local/opt/tesseract/bin/tesseract",
                    "/opt/local/bin/tesseract",
                    "/usr/bin/tesseract",
                ]
            elif platform.system() == "Windows":
                possible_tesseract_paths = [
                    r"C:\Program Files\Tesseract-OCR\tesseract.exe",
                    r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
                ]
            else:  # Linux
                possible_tesseract_paths = [
                    "/usr/bin/tesseract",
                    "/usr/local/bin/tesseract",
                    "/opt/homebrew/bin/tesseract",
                ]
            for path in possible_tesseract_paths:
                if os.path.exists(path):
                    tesseract_path = path
                    print(f"[TIMING] Tesseract gefunden in Pfadliste: {tesseract_path}")
                    break

        if not ocrmypdf_path:
            possible_ocrmypdf_paths = []
            if platform.system() == "Darwin":
                possible_ocrmypdf_paths = [
                    "/usr/local/bin/ocrmypdf",
                    "/opt/homebrew/bin/ocrmypdf",
                    "/opt/local/bin/ocrmypdf",
                    "/usr/bin/ocrmypdf",
                ]
                python_version = f"{sys.version_info.major}.{sys.version_info.minor}"
                possible_ocrmypdf_paths.extend([
                    f"/Library/Frameworks/Python.framework/Versions/{python_version}/bin/ocrmypdf",
                    f"/opt/homebrew/opt/python@{python_version}/bin/ocrmypdf",
                    f"/usr/local/opt/python@{python_version}/bin/ocrmypdf",
                    os.path.join(sys.prefix, "bin", "ocrmypdf"),
                    os.path.join(os.path.dirname(sys.executable), "ocrmypdf"),
                ])
            elif platform.system() == "Windows":
                possible_ocrmypdf_paths = [
                    os.path.join(sys.prefix, "Scripts", "ocrmypdf.exe"),
                    os.path.join(os.path.expanduser("~"), "AppData", "Local", "Programs", "Python",
                                f"Python{sys.version_info.major}{sys.version_info.minor}", "Scripts", "ocrmypdf.exe"),
                ]
            else:  # Linux
                possible_ocrmypdf_paths = [
                    "/usr/bin/ocrmypdf",
                    "/usr/local/bin/ocrmypdf",
                    os.path.join(sys.prefix, "bin", "ocrmypdf"),
                ]
            for path in possible_ocrmypdf_paths:
                if os.path.exists(path):
                    ocrmypdf_path = path
                    print(f"[TIMING] OCRmyPDF gefunden in Pfadliste: {ocrmypdf_path}")
                    break

        # 2.3 Letzter Fallback: subprocess mit Timeout (nur wenn noch nicht gefunden)
        if not tesseract_path:
            try:
                print("[TIMING] Versuche 'which tesseract' mit subprocess (Timeout 2s)...")
                if platform.system() in ["Darwin", "Linux"]:
                    result = subprocess.run(["which", "tesseract"], capture_output=True, text=True, timeout=2)
                else:
                    result = subprocess.run(["where", "tesseract"], capture_output=True, text=True, timeout=2, shell=True)
                if result.returncode == 0 and result.stdout.strip():
                    tesseract_path = result.stdout.strip().split("\n")[0]
                    print(f"[TIMING] Tesseract gefunden via subprocess: {tesseract_path}")
            except subprocess.TimeoutExpired:
                print("[TIMING] subprocess für Tesseract timeout")
            except Exception as e:
                print(f"[TIMING] subprocess Fehler bei Tesseract: {e}")

        if not ocrmypdf_path:
            try:
                print("[TIMING] Versuche 'which ocrmypdf' mit subprocess (Timeout 2s)...")
                if platform.system() in ["Darwin", "Linux"]:
                    result = subprocess.run(["which", "ocrmypdf"], capture_output=True, text=True, timeout=2)
                else:
                    result = subprocess.run(["where", "ocrmypdf"], capture_output=True, text=True, timeout=2, shell=True)
                if result.returncode == 0 and result.stdout.strip():
                    ocrmypdf_path = result.stdout.strip().split("\n")[0]
                    print(f"[TIMING] OCRmyPDF gefunden via subprocess: {ocrmypdf_path}")
            except subprocess.TimeoutExpired:
                print("[TIMING] subprocess für ocrmypdf timeout")
            except Exception as e:
                print(f"[TIMING] subprocess Fehler bei ocrmypdf: {e}")

        # Poppler-Pfad setzen (Fallback)
        if platform.system() == "Darwin":
            cls.POPPLER_PATH = "/usr/local/bin"
        elif platform.system() == "Windows":
            cls.POPPLER_PATH = r"C:\Program Files\poppler-23.08.0\Library\bin"
        else:
            cls.POPPLER_PATH = "/usr/bin"

        elapsed = time.time() - start_time
        print(f"[TIMING] _find_ocr_tools (System) completed in {elapsed:.3f}s")
        return (tesseract_path, ocrmypdf_path)

    @classmethod
    def _initialize_paths(cls):
        """Initialisiert alle pfadabhängigen Variablen – im Bundle-Modus mit externem Benutzerordner."""

        start_time = time.time()

        # ------------------------------
        # 1. Logging
        # ------------------------------

        # --> wird in class PDFLogger definiert

        # ------------------------------
        # 2. Ressourcen (GUI-Bilder bleiben im Bundle)
        # ------------------------------
        if getattr(sys, "frozen", False):
            # BUNDLE-MODUS: Ressourcen aus _MEIPASS laden
            base_path = sys._MEIPASS
            cls.IMAGE_PATH = os.path.join(base_path, "png", "BinhDiez.png")
            cls.APP_ICON_PATH = os.path.join(base_path, "png", "PDFDarkView.png")
        else:
            # ENTWICKLUNGS-MODUS: Relative Pfade vom Skript aus
            # Hier verwenden wir SCRIPT_DIR, das im Entwicklungsmodus das Skriptverzeichnis ist
            cls.IMAGE_PATH = os.path.join(cls.SCRIPT_DIR, "png", "BinhDiez.png")
            cls.APP_ICON_PATH = os.path.join(cls.SCRIPT_DIR, "png", "PDFDarkView.png")

        # Debug-Ausgabe (optional, hilft bei der Fehlersuche)
        # print(f"DEBUG IMAGE_PATH: {cls.IMAGE_PATH} | Existiert: {os.path.exists(cls.IMAGE_PATH)}")

        # print(f"DEBUG APP_ICON_PATH: {cls.APP_ICON_PATH} | Existiert: {os.path.exists(cls.APP_ICON_PATH)}")

        # ------------------------------
        # 3. Externe Tools (EXTRA_MENU) – unverändert
        # ------------------------------
        if Config.EXTRA_MENU:
            cls.EXT_PY1_PATH = os.path.join(
                cls.BASE_DIR, "PDFSplitter", "PDFSplitter.py"
            )
            cls.EXT_PY2_PATH = os.path.join(cls.BASE_DIR, "PDFJoiner", "PDFJoiner.py")
            cls.EXT_PY3_PATH = os.path.join(cls.BASE_DIR, "PDFRename", "PDFRename.py")
            cls.EXT_PY4_PATH = os.path.join(
                cls.BASE_DIR, "PDFTranslate", "PDFTranslate.py"
            )
            cls.EXT_PY5_PATH = os.path.join(
                cls.BASE_DIR, "PDFFormTool", "PDFFormTool.py"
            )
            cls.EXT_PY6_PATH = os.path.join(
                cls.BASE_DIR, "PDFSigningTool", "PDFSigningTool.py"
            )
            cls.EXT_PY7_PATH = os.path.join(cls.BASE_DIR, "PDFSpeak", "PDFSpeak.py")
            cls.EXT_PY8_PATH = (
                os.path.join(cls.BASE_DIR, "PDFTools.app")
                if platform.system() == "Darwin"
                else os.path.join(cls.BASE_DIR, "PDFTools", "PDFTools.py")
            )

        # ------------------------------
        # 4. Datenverzeichnisse – im Bundle extern, sonst lokal
        # ------------------------------
        if getattr(sys, "frozen", False):
            # Externer Basisordner für alle Benutzerdaten
            user_base = cls.get_user_data_dir()  # ← erstellt den Ordner
            # Einzelne Unterverzeichnisse (werden später durch _ensure_user_data befüllt)
            cls.DATA_DIR = os.path.join(user_base, "Daten")
            cls.SIGNATURES_DIR = os.path.join(user_base, "Signatures")
            cls.TESSDATA_DIR = os.path.join(user_base, "tessdata")
            cls.TRANSLATIONS_DIR = os.path.join(user_base, "translations")
        else:
            # Entwicklungsmodus: lokale Ordner im Skriptverzeichnis
            cls.DATA_DIR = os.path.join(cls.SCRIPT_DIR, "Daten")
            cls.SIGNATURES_DIR = os.path.join(cls.SCRIPT_DIR, "Signatures")
            cls.TESSDATA_DIR = os.path.join(
                cls.SCRIPT_DIR, "tools", "share", "tessdata"
            )
            cls.TRANSLATIONS_DIR = os.path.join(cls.SCRIPT_DIR, "translations")

        # Ordner ggf. anlegen (nur im Entwicklungsmodus; im Bundle erledigt _ensure_user_data)
        if not getattr(sys, "frozen", False):
            os.makedirs(cls.DATA_DIR, exist_ok=True)
            print(
                f"Daten-Verzeichnis: {cls.DATA_DIR} | Existiert: {os.path.exists(cls.DATA_DIR)}\n"
            )
            os.makedirs(cls.SIGNATURES_DIR, exist_ok=True)
            os.makedirs(cls.TESSDATA_DIR, exist_ok=True)
            os.makedirs(cls.TRANSLATIONS_DIR, exist_ok=True)

        # Passwort-Datenbank
        cls.PASSWORD_DB_PATH = os.path.join(cls.DATA_DIR, "passwords.json")

        # ------------------------------
        # 5. Default-Daten beim ersten Start kopieren (nur Bundle)
        # ------------------------------
        if getattr(sys, "frozen", False):
            cls._ensure_user_data()

        # ------------------------------
        # 6. OCR-Konfiguration (wie gehabt)
        # ------------------------------
        cls.TESSERACT_PATH, cls.OCRMYPDF_PATH = cls._find_ocr_tools()
        cls.OCR_ENGINE = "ocrmypdf"
        cls.OCR_DPI = 300
        cls.OCR_LANGUAGE = "deu+eng+fra+ita+spa+por+nld+swe+fin+dan+nor+rus"
        cls.OCR_CONFIG = "--psm 6 --oem 3 -c preserve_interword_spaces=1"

        # Poppler Pfade
        if platform.system() == "Darwin":
            cls.POPPLER_PATHS = [
                "/opt/homebrew/bin",
                "/usr/local/bin",
                "/opt/local/bin",
                "/usr/bin",
            ]
        elif platform.system() == "Windows":
            cls.POPPLER_PATHS = [
                r"C:\Program Files\poppler-23.08.0\Library\bin",
                r"C:\Program Files\poppler\bin",
            ]
        else:
            cls.POPPLER_PATHS = ["/usr/bin", "/usr/local/bin"]

        elapsed = time.time() - start_time
        print(f"[TIMING] _initialize_paths abgeschlossen in {elapsed:.3f}s")

    @classmethod
    def _ensure_user_data(cls):
        """
        Kopiert die Default-Daten aus dem Bundle ins Benutzerverzeichnis.

        - tessdata/, Signatures/, png/ usw.: NUR beim ersten Start kopieren
        - translations/:
            - Basis-Sprachen (de, en, vi) werden bei Versionswechsel aktualisiert
            - Alle weiteren Sprachen können über 'Einstellungen → Übersetzungen aktualisieren'
            manuell von GitHub heruntergeladen werden
        """
        if not getattr(sys, "frozen", False):
            return  # Nur im Bundle-Modus aktiv

        user_base = cls.get_user_data_dir()
        if not user_base:
            return

        src_base = os.path.join(sys._MEIPASS, "default_data")
        if not os.path.exists(src_base):
            print("⚠️ Kein 'default_data' Ordner im Bundle – überspringe Kopie.")
            return

        # Ziel: User translations Verzeichnis
        translations_dir = os.path.join(user_base, "translations")
        os.makedirs(translations_dir, exist_ok=True)

        # Gespeicherte Version laden
        saved_version = get_saved_version()
        current_version = APP_VERSION

        # Prüfen, ob Versionswechsel stattgefunden hat
        version_changed = saved_version != current_version

        print(f"📌 Gespeicherte Version: {saved_version}")
        print(f"📌 Aktuelle Version: {current_version}")
        print(f"📌 Versionswechsel: {'JA' if version_changed else 'NEIN'}")

        # ----- 1. ALLE Ordner NUR beim ersten Start kopieren -----
        # Welche Ordner sollen NUR initial kopiert werden (kein Überschreiben)?
        INITIAL_ONLY = {
            "tessdata",
            "Signatures",
            "png",
        }  # Ordner die nur beim ersten Start kopiert werden

        print("📋 Kopiere Initial-Ordner (nur wenn nicht vorhanden)...")

        for item in os.listdir(src_base):
            src_path = os.path.join(src_base, item)
            dst_path = os.path.join(user_base, item)

            # NUR die Ordner aus INITIAL_ONLY verarbeiten
            if item in INITIAL_ONLY:
                if not os.path.exists(dst_path):
                    try:
                        if os.path.isdir(src_path):
                            shutil.copytree(src_path, dst_path)
                            print(f"  ✅ Initial kopiert: {item} → {dst_path}")
                        else:
                            shutil.copy2(src_path, dst_path)
                            print(f"  ✅ Initial kopiert: {item} → {dst_path}")
                    except Exception as e:
                        print(f"  ❌ Fehler bei {item}: {e}")
                else:
                    print(f"  ⏭️ Überspringe {item} (existiert bereits)")

        # ----- 2. Basis-Sprachen (de, en, vi) aus Bundle kopieren -----
        print("📋 Kopiere Basis-Sprachen (de, en, vi) aus Bundle...")

        # Nur die 3 Basis-Sprachen (immer aus default_data/translations)
        base_languages = [
            "translations_de.py",
            "translations_en.py",
            "translations_vi.py",
        ]

        # Quelle für Basis-Sprachen
        src_translations = os.path.join(src_base, "translations")

        for filename in base_languages:
            src_file = os.path.join(src_translations, filename)
            dst_file = os.path.join(translations_dir, filename)

            if os.path.exists(src_file):
                try:
                    # Bei Versionswechsel oder nicht vorhanden: überschreiben/kopieren
                    if version_changed or not os.path.exists(dst_file):
                        shutil.copy2(src_file, dst_file)
                        print(
                            f"  ✅ {'Aktualisiert' if version_changed else 'Kopiert'}: {filename}"
                        )
                    else:
                        print(
                            f"  ⏭️ Überspringe {filename} (existiert bereits, kein Versionswechsel)"
                        )
                except Exception as e:
                    print(f"  ❌ Fehler bei {filename}: {e}")
            else:
                print(f"  ⚠️ {filename} nicht in {src_translations} gefunden")

        # ----- 3. Bei Versionswechsel: Version speichern (KEINE Abfrage!) -----
        if version_changed:
            print("🔄 Versionswechsel erkannt - Version wird aktualisiert")
            # Neue Version speichern
            save_current_version()
            print(f"✅ Version auf {current_version} aktualisiert")

            # KEINE Abfrage für GitHub-Download!
            # Der Benutzer kann über das Menü 'Extras → Übersetzungen aktualisieren'
            # alle Sprachen manuell herunterladen
        else:
            print("⏭️ Kein Versionswechsel - Basis-Sprachen bleiben unverändert")

        # Marker für erfolgreiche Initialisierung
        marker = os.path.join(user_base, ".initialized")
        if not os.path.exists(marker):
            with open(marker, "w") as f:
                f.write("initialized")
            print("✅ Initialisierung abgeschlossen")

            # Hinweis für neue Benutzer (nur beim ersten Start)
            print(
                "💡 Hinweis: Weitere Sprachen können über 'Extras → Übersetzungen aktualisieren' heruntergeladen werden."
            )

    @classmethod
    def _ask_and_update_translations_async(cls, parent=None):
        """
        Fragt den Benutzer, ob alle Übersetzungen von GitHub heruntergeladen werden sollen.
        """
        if not getattr(sys, "frozen", False):
            return

        # Prüfen ob bereits ein Download läuft
        if (
            hasattr(cls, "_update_thread")
            and cls._update_thread
            and cls._update_thread.isRunning()
        ):
            if parent:
                myUniversalDialog(
                    parent,
                    title=parent.tr("translations_update_in_progress_title"),
                    message=parent.tr("translations_update_in_progress"),
                    buttons=[(parent.tr("btn_ok"), "primary", "ok", 100)],
                    icon_type="",
                    text_alignment=Qt.AlignLeft,
                    default_button="ok",
                ).exec_()
            return

        # Translations-Pfad für die Nachricht
        user_base = cls.get_user_data_dir()
        translations_path = (
            os.path.join(user_base, "translations") if user_base else "Unbekannt"
        )

        # Anzahl der verfügbaren Sprachen ermitteln (über parent.lang)
        total_languages = 0
        if parent and hasattr(parent, "lang"):
            total_languages = parent.lang.get_available_languages_count()

        # Dialog anzeigen (wenn parent übergeben)
        if parent:
            message = parent.tr("ask_download_all_translations").format(
                translations_path=translations_path, total_languages=total_languages
            )

            dialog = myUniversalDialog(
                parent,
                title=parent.tr("download_all_translations"),
                message=message,
                buttons=[
                    (parent.tr("download_translations"), "primary", "ok", 160),
                    (parent.tr("btn_cancel"), "secondary", "cancel", 120),
                ],
                icon_type="",
                text_alignment=Qt.AlignLeft,
                default_button="cancel",
            )
            dialog.exec_()

            if dialog.result_value != "ok":
                print("⏭️ Benutzer hat Übersetzungs-Update abgelehnt")
                return

        # Asynchronen Download starten
        cls._start_translations_update(parent)

    @classmethod
    def _start_translations_update(cls, parent=None):
        """Startet den asynchronen Download der Übersetzungen."""
        if not getattr(sys, "frozen", False):
            return

        # Alten Thread aufräumen
        if hasattr(cls, "_update_thread"):
            if cls._update_thread and cls._update_thread.isRunning():
                cls._update_thread.cancel()
                cls._update_thread.wait()
            cls._update_thread = None

        # Neuen Thread erstellen
        cls._update_thread = TranslationsUpdateThread(parent)

        # Status-Update in der Statusleiste anzeigen
        if parent and hasattr(parent, "statusBar"):
            parent.statusBar().showMessage(
                parent.tr("translations_update_in_progress"), 3000
            )

        # Signale verbinden
        cls._update_thread.progress.connect(lambda msg: print(f"📥 {msg}"))

        cls._update_thread.finished.connect(
            lambda success, message, new_count, updated_count: cls._on_translations_update_finished(
                success, message, new_count, updated_count, parent
            )
        )

        # Thread starten
        cls._update_thread.start()
        print("🔄 Übersetzungs-Update im Hintergrund gestartet...")

    @classmethod
    def _on_translations_update_finished(
        cls, success, message, new_count, updated_count, parent=None
    ):
        """Callback wenn der Übersetzungs-Download abgeschlossen ist."""
        if success:
            if new_count == 0 and updated_count == 0:
                # Alles aktuell
                status_msg = (
                    parent.tr("translations_update_no_changes")
                    if parent
                    else "Alle Übersetzungen sind aktuell"
                )
                print(f"✅ {status_msg}")

                if parent and hasattr(parent, "statusBar"):
                    parent.statusBar().showMessage(status_msg, 3000)

                # Optional: Kurze Info-Meldung
                if parent:
                    myUniversalDialog(
                        parent,
                        title=parent.tr("translations_updated"),
                        message=status_msg,
                        buttons=[(parent.tr("btn_ok"), "success", "ok", 100)],
                        icon_type="",
                        text_alignment=Qt.AlignLeft,
                        default_button="ok",
                    ).exec_()
            else:
                # Erfolgreich aktualisiert
                total = new_count + updated_count
                status_msg = (
                    parent.tr(
                        "translations_update_success", total, new_count, updated_count
                    )
                    if parent
                    else f"{total} Übersetzungen aktualisiert"
                )
                print(f"✅ {status_msg}")

                if parent and hasattr(parent, "statusBar"):
                    parent.statusBar().showMessage(status_msg, 5000)

                # Erfolgs-Dialog
                if parent:
                    myUniversalDialog(
                        parent,
                        title=parent.tr("translations_updated"),
                        message=status_msg,
                        buttons=[(parent.tr("btn_ok"), "success", "ok", 100)],
                        icon_type="success",
                        text_alignment=Qt.AlignLeft,
                        default_button="ok",
                    ).exec_()
        else:
            # Fehler
            error_msg = (
                parent.tr("translations_update_error")
                if parent
                else "Fehler beim Update"
            )
            print(f"❌ {error_msg}: {message}")

            if parent and hasattr(parent, "statusBar"):
                parent.statusBar().showMessage(f"{error_msg}: {message}", 5000)

            # Fehler-Dialog nur bei nicht-abgebrochenen Downloads
            if not (
                hasattr(cls._update_thread, "_is_cancelled")
                and cls._update_thread._is_cancelled
            ):
                if parent:
                    # Prüfen ob es ein Internet-Problem war
                    if "internet" in message.lower() or "connection" in message.lower():
                        icon_type = "warning"
                    else:
                        icon_type = "error"

                    dialog = myUniversalDialog(
                        parent,
                        title=error_msg,
                        message=f"{error_msg}\n\n{message}",
                        buttons=[
                            (parent.tr("btn_ok"), "primary", "ok", 100),
                            (parent.tr("btn_retry"), "secondary", "retry", 100),
                        ],
                        icon_type=icon_type,
                        text_alignment=Qt.AlignLeft,
                        default_button="ok",
                    )
                    dialog.exec_()

                    # Bei Wiederholung: nochmal versuchen
                    if dialog.result_value == "retry":
                        from PyQt5.QtCore import QTimer

                        QTimer.singleShot(
                            500, lambda: cls.manual_translations_update(parent)
                        )

        # Thread aufräumen
        if hasattr(cls, "_update_thread"):
            cls._update_thread = None

    @classmethod
    def _check_internet_connection(cls):
        """
        Prüft ob eine Internetverbindung besteht.
        Verwendet mehrere Methoden für höhere Zuverlässigkeit.
        """
        # Methode 1: Socket-Verbindung zu Google DNS
        try:
            import socket

            socket.setdefaulttimeout(3)
            socket.socket(socket.AF_INET, socket.SOCK_STREAM).connect(("8.8.8.8", 53))
            return True
        except:
            pass

        # Methode 2: HTTP-Request zu GitHub API (leicht)
        try:
            import requests

            response = requests.get("https://api.github.com", timeout=3)
            if response.status_code == 200:
                return True
        except:
            pass

        # Methode 3: Ping zu einem bekannten Server (nur Unix)
        if platform.system() != "Windows":
            try:
                result = subprocess.run(
                    ["ping", "-c", "1", "-W", "2", "8.8.8.8"],
                    capture_output=True,
                    timeout=3,
                )
                if result.returncode == 0:
                    return True
            except:
                pass

        return False

    @classmethod
    def manual_translations_update(cls, parent=None):
        """
        Manuelles Aktualisieren der GUI Übersetzungen.
        Wird aufgerufen wenn der Benutzer 'Einstellungen → Übersetzungen aktualisieren' wählt.
        """
        if not getattr(sys, "frozen", False):
            print("ℹ️ Manuelles Update nur im Bundle-Modus verfügbar")
            if parent:
                myUniversalDialog(
                    parent,
                    title=parent.tr("translations_update_not_available_title"),
                    message=parent.tr("translations_update_not_available_message"),
                    buttons=[(parent.tr("btn_ok"), "primary", "ok", 100)],
                    icon_type="",
                    text_alignment=Qt.AlignLeft,
                    default_button="ok",
                ).exec_()
            return

        # Prüfen ob bereits ein Download läuft
        if (
            hasattr(cls, "_update_thread")
            and cls._update_thread
            and cls._update_thread.isRunning()
        ):
            if parent:
                myUniversalDialog(
                    parent,
                    title=parent.tr("translations_update_in_progress_title"),
                    message=parent.tr("translations_update_in_progress"),
                    buttons=[(parent.tr("btn_ok"), "primary", "ok", 100)],
                    icon_type="",
                    text_alignment=Qt.AlignLeft,
                    default_button="ok",
                ).exec_()
            return

        # ----- INTERNETVERBINDUNG PRÜFEN (MIT USER-FEEDBACK) -----
        if not cls._check_internet_connection():
            print(
                "⚠️ Keine Internetverbindung - Übersetzungen können nicht aktualisiert werden"
            )

            if parent:
                # Detaillierte Fehlermeldung mit Lösungsvorschlägen
                message = parent.tr("translations_update_no_internet_message")
                dialog = myUniversalDialog(
                    parent,
                    title=parent.tr("translations_update_no_internet_title"),
                    message=message,
                    buttons=[
                        (parent.tr("btn_ok"), "primary", "ok", 100),
                        (parent.tr("btn_retry"), "secondary", "retry", 100),
                    ],
                    icon_type="",
                    text_alignment=Qt.AlignLeft,
                    default_button="ok",
                )
                dialog.exec_()

                # Bei Wiederholung: nochmal versuchen
                if dialog.result_value == "retry":
                    # Rekursiver Aufruf (aber mit kurzer Verzögerung um Rekursion zu vermeiden)
                    from PyQt5.QtCore import QTimer

                    QTimer.singleShot(
                        500, lambda: cls.manual_translations_update(parent)
                    )
            return

        # Dialog für Download anzeigen
        cls._ask_and_update_translations_async(parent)

