class FilenameSettingsDialog(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.parent = parent

        # --- Bildschirmgröße für maximale Dialogmaße ermitteln ---
        screen = QApplication.primaryScreen()
        screen_geometry = screen.availableGeometry()
        max_dialog_height = int(
            screen_geometry.height() * 0.8
        )  # 80% der verfügbaren Höhe
        max_dialog_width = int(
            screen_geometry.width() * 0.9
        )  # 90% der verfügbaren Breite

        self.setWindowTitle(parent.tr("filename_settings_title"))

        self.setMinimumWidth(950)
        self.setMinimumHeight(750)
        self.setModal(True)
        self.setMaximumSize(max_dialog_width, max_dialog_height)
        self.setSizeGripEnabled(True)
        self._overwrite_info_showing = False

        self.settings = QSettings("BinhDiez", "PDFDarkView")
        self.load_settings()
        self.init_ui()
        self.update_preview()

    def load_settings(self):
        """Lädt alle Einstellungen."""
        self.behavior = self.settings.value(
            "filename/behavior", "new_file", type=str
        )
        self.use_timestamp = self.settings.value(
            "filename/use_timestamp", True, type=bool
        )
        self.timestamp_format = self.settings.value(
            "filename/timestamp_format", "%Y%m%d_%H%M%S", type=str
        )
        self.timestamp_position = self.settings.value(
            "filename/timestamp_position", "after", type=str
        )
        self.separator = self.settings.value("filename/separator", "_", type=str)

        # NEU: Benutzername in Suffixen verwenden
        self.use_username_in_suffix = self.settings.value(
            "filename/use_username_in_suffix", False, type=bool
        )

        # WICHTIG: Gespeicherten Benutzernamen laden, aber wenn leer, den System-Benutzernamen verwenden
        saved_username = self.settings.value("filename/username", "", type=str)
        if saved_username:
            self.username = saved_username
        else:
            # Kein gespeicherter Benutzername -> System-Benutzernamen ermitteln und speichern
            self.username = self._get_system_username()
            # Sofort speichern, damit er beim nächsten Mal verfügbar ist
            self.settings.setValue("filename/username", self.username)
            self.settings.sync()

        self.create_backup = self.settings.value("create_backup", True, type=bool)

    def _get_system_username(self):
        """Ermittelt den System-Benutzernamen und formatiert ihn."""
        try:
            import getpass
            username = getpass.getuser()

            # Formatierung: Erster Buchstabe groß, Rest klein
            if username:
                # Punkt als Trennzeichen behandeln (z.B. m.mustermann)
                if '.' in username:
                    parts = username.split('.')
                    formatted_parts = []
                    for part in parts:
                        if part:
                            formatted_parts.append(part[0].upper() + part[1:].lower())
                    return '.'.join(formatted_parts)
                else:
                    return username[0].upper() + username[1:].lower()
            return ""
        except:
            return ""

