class PasswordDialog(QDialog):
    """Dialog für Passwortabfrage mit allen erweiterten Funktionen"""

    def __init__(self, parent=None, pdf_path=None, saved_password=None):
        super().__init__(parent)
        self.pdf_path = pdf_path
        self.password = None
        self.action = None

        # saved_password wird nicht mehr im Feld angezeigt, wir speichern ihn nur für den Fall,
        # dass der Benutzer später den "Passwortmanager" öffnet und wir den Fokus setzen wollen.
        self.saved_password = saved_password

        # Language-Instanz vom Hauptfenster übernehmen
        if parent and hasattr(parent, "lang"):
            self.lang = parent.lang
        else:

            self.lang = Language()

        self.setWindowTitle(self.lang.tr("password_required"))
        self.setWindowModality(Qt.WindowModal)
        self.setFixedSize(700, 440)

        # Finde Hauptfenster
        self.main_window = self._find_main_window(self)
        self.voice_enabled = self._get_voice_enabled()

        # Sprachausgabe beim Öffnen
        if self.main_window and self.voice_enabled and hasattr(self.main_window, "say"):
            self.main_window.say(self.lang.tr("password_enter"))

        # ✅ FOCUS_STYLE hier einbinden
        self.setStyleSheet(f"""
            QDialog {{
                background-color: #222222;
                color: white;
            }}
            QCheckBox {{
                color: white;
            }}
            QLabel {{
                color: white;
            }}
            {FOCUS_STYLE}
        """)

        flags = (
            Qt.Window
            | Qt.CustomizeWindowHint
            | Qt.WindowTitleHint
            | Qt.WindowStaysOnTopHint
        )
        self.setWindowFlags(flags)

        self.init_ui(saved_password)

    def init_ui(self, saved_password):
        layout = QVBoxLayout()
        layout.setContentsMargins(15, 15, 15, 15)

        # Header Bereich
        header = QWidget()
        header_layout = QHBoxLayout(header)
        header_layout.setContentsMargins(0, 0, 0, 15)
        header_layout.setSpacing(10)

        # linker Stretch → zieht alles zur Mitte
        header_layout.addStretch(1)

        if os.path.exists(Config.IMAGE_PATH):
            self.logo_label = QLabel()
            logo_pixmap = QPixmap(Config.IMAGE_PATH).scaled(
                80, 80, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            self.logo_label.setPixmap(logo_pixmap)
            self.logo_label.setAlignment(Qt.AlignVCenter)
            header_layout.addWidget(self.logo_label)

            header_layout.addStretch(1)

        self.title_label = QLabel(self.lang.tr("password_required"))
        self.title_label.setStyleSheet("""
            QLabel {
                color: white;
                font-size: 20px;
                font-weight: bold;
                padding: 5px;
            }
        """)
        self.title_label.setAlignment(Qt.AlignCenter)
        header_layout.addWidget(self.title_label)
        header_layout.addStretch(1)

        if os.path.exists(Config.APP_ICON_PATH):
            self.icon_label = QLabel()
            icon_pixmap = QPixmap(Config.APP_ICON_PATH).scaled(
                50, 50, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            self.icon_label.setPixmap(icon_pixmap)
            self.icon_label.setAlignment(Qt.AlignVCenter)
            header_layout.addWidget(self.icon_label)

        # rechter Stretch → hält die Gruppe zentriert
        header_layout.addStretch(1)

        layout.addWidget(header)

        # Info Text
        filename = os.path.basename(self.pdf_path)
        info_label = QLabel(self.lang.tr("password_enter") + f" '{filename}'.")
        info_label.setStyleSheet("font-size: 14px;")
        info_label.setWordWrap(True)
        layout.addWidget(info_label)

        layout.addSpacing(10)

        # Passwort-Eingabe
        self.password_widget = PasswordInputWidget(
            show_confirm=False, show_strength=False, mode="open"
        )

        layout.addWidget(self.password_widget)

        layout.addSpacing(10)

        # Checkbox für Passwort speichern
        self.save_checkbox = QCheckBox(self.lang.tr("password_save"))

        # Prüfe ob Master-Passwort gesetzt ist
        if PDFPasswordManager.is_master_password_set():
            self.save_checkbox = QCheckBox(self.lang.tr("password_save"))
            self.save_checkbox.setChecked(True)
            layout.addWidget(self.save_checkbox)
        else:
            # Kein Master-PW: Checkbox ausgrauen und Text ändern
            self.save_checkbox = QCheckBox(
                self.lang.tr("password_save_master_required")
            )
            self.save_checkbox.setChecked(False)
            self.save_checkbox.setEnabled(False)
            layout.addWidget(self.save_checkbox)
            # Optional: Hinweis-Label einfügen
            hint_label = QLabel(self.lang.tr("password_save_hint"))
            hint_label.setStyleSheet("color: #FF9800; font-size: 14px;")
            layout.addWidget(hint_label)

        layout.addWidget(self.save_checkbox)

        # Gespeicherte Passwörter Hinweis
        if saved_password:
            saved_label = QLabel(self.lang.tr("password_saved"))
            saved_label.setStyleSheet("color: #4CAF50; font-size: 12px;")
            layout.addWidget(saved_label)

        layout.addSpacing(20)

        # Button Bereich - Reihenfolge anpassen
        button_layout = QHBoxLayout()

        # Öffnen Button - Jetzt LINKS (Primäraktion)
        self.open_button = QPushButton(self.lang.tr("btn_open"))
        self.main_window.style_button(self.open_button, "primary", (120, 25))
        self.open_button.clicked.connect(self.on_open_clicked)
        self.open_button.setFocusPolicy(Qt.StrongFocus)  # Fokus erlaubt
        button_layout.addWidget(self.open_button)

        # Passwort entfernen Button
        self.remove_button = QPushButton(self.lang.tr("btn_remove_password"))
        self.main_window.style_button(self.remove_button, "danger", (200, 25))
        self.remove_button.clicked.connect(self.on_remove_clicked)
        self.remove_button.setFocusPolicy(Qt.StrongFocus)  # Fokus erlaubt
        button_layout.addWidget(self.remove_button)

        # Passwortverwaltung Button - Jetzt RECHTS
        self.manage_button = QPushButton(self.lang.tr("btn_manage"))
        self.main_window.style_button(self.manage_button, "primary", (200, 25))
        self.manage_button.clicked.connect(self.on_manage_clicked)
        self.manage_button.setFocusPolicy(Qt.StrongFocus)  # Fokus erlaubt
        button_layout.addWidget(self.manage_button)

        layout.addLayout(button_layout)
        self.setLayout(layout)

        # Öffnen als Default-Button setzen
        self.open_button.setDefault(True)

        # Tab-Reihenfolge festlegen
        self.setTabOrder(self.password_widget.password_input, self.open_button)
        self.setTabOrder(self.open_button, self.remove_button)
        self.setTabOrder(self.remove_button, self.manage_button)
        self.setTabOrder(
            self.manage_button, self.password_widget.password_input
        )  # Zyklisch

        # Automatisch Fokus setzen
        self.password_widget.password_input.setFocus()

        # Enter-Taste im Passwortfeld behandeln
        def on_password_enter():
            # Direkt "Öffnen" auslösen
            self.on_open_clicked()

        self.password_widget.password_input.returnPressed.connect(on_password_enter)

        # ESC-Taste zum Abbrechen
        self.escape_shortcut = QShortcut(QKeySequence("Esc"), self)
        self.escape_shortcut.activated.connect(self.reject)

    def keyPressEvent(self, event):
        """Tastaturnavigation mit Pfeiltasten"""
        # Pfeiltasten zwischen Buttons
        if event.key() == Qt.Key_Left:
            current = self.focusWidget()
            if current == self.remove_button:
                self.open_button.setFocus()
            elif current == self.manage_button:
                self.remove_button.setFocus()
            elif current == self.open_button:
                self.manage_button.setFocus()  # Zyklisch
            event.accept()
            return

        elif event.key() == Qt.Key_Right:
            current = self.focusWidget()
            if current == self.open_button:
                self.remove_button.setFocus()
            elif current == self.remove_button:
                self.manage_button.setFocus()
            elif current == self.manage_button:
                self.open_button.setFocus()  # Zyklisch
            event.accept()
            return

        # Tab-Taste (vorwärts)
        elif event.key() == Qt.Key_Tab:
            current = self.focusWidget()
            if current == self.password_widget.password_input:
                self.open_button.setFocus()
            elif current == self.open_button:
                self.remove_button.setFocus()
            elif current == self.remove_button:
                self.manage_button.setFocus()
            elif current == self.manage_button:
                self.password_widget.password_input.setFocus()
            event.accept()
            return

        # Shift+Tab (rückwärts)
        elif event.key() == Qt.Key_Backtab:
            current = self.focusWidget()
            if current == self.password_widget.password_input:
                self.manage_button.setFocus()
            elif current == self.manage_button:
                self.remove_button.setFocus()
            elif current == self.remove_button:
                self.open_button.setFocus()
            elif current == self.open_button:
                self.password_widget.password_input.setFocus()
            event.accept()
            return

        # Enter-Taste: Standardverhalten (Buttons reagieren wegen Default=True)
        elif event.key() in (Qt.Key_Return, Qt.Key_Enter):
            current = self.focusWidget()
            if current in [self.open_button, self.remove_button, self.manage_button]:
                current.click()
                event.accept()
                return

        super().keyPressEvent(event)

    def on_open_clicked(self):
        self.password = self.password_widget.get_password()
        if not self.password:
            dialog = myUniversalDialog(
                self,
                title=self.lang.tr("password_required"),
                message=self.lang.tr("password_enter"),
                buttons=[(self.lang.tr("btn_ok"), "primary", "ok")],
                icon_type="",
                voice_message=self.lang.tr("password_enter"),
                text_alignment=Qt.AlignLeft,
            )
            dialog.exec_()
            return

        self.action = "open"
        self.accept()

    def on_remove_clicked(self):
        self.password = self.password_widget.get_password()
        if not self.password:
            dialog = myUniversalDialog(
                self,
                title=self.lang.tr("password_required"),
                message=self.lang.tr("btn_remove_password"),
                buttons=[(self.lang.tr("btn_ok"), "primary", "ok")],
                icon_type="",
                voice_message=self.lang.tr("btn_remove_password"),
                text_alignment=Qt.AlignLeft,
            )
            dialog.exec_()
            return

        self.action = "remove"
        self.accept()

    def on_manage_clicked(self):
        """Öffnet die Passwortverwaltung im Auswahl-Modus."""
        self.action = "manage"
        # Hauptfenster-Referenz mitgeben
        manager = EnhancedPasswordManagerDialog(
            self,
            select_mode=True,
            current_pdf_path=self.pdf_path,
            main_window=self.main_window,  # <-- wichtig
        )
        if manager.exec_() == QDialog.Accepted and manager.selected_password:
            self.password = manager.selected_password
            self.action = "use_saved"
            self.accept()

    def _find_main_window(self, widget):
        """Findet das Hauptfenster (PDFViewer) in der Widget-Hierarchie"""
        if widget is None:
            return None

        print(f"DEBUG myUniversalDialog._find_main_window: Starte mit {widget}")
        current = widget

        # Zuerst versuchen, das Hauptfenster direkt zu finden
        while current is not None:
            if isinstance(current, QMainWindow) and hasattr(current, "voice_enabled"):
                print(
                    f"DEBUG: Direktes Hauptfenster gefunden: {current}, voice_enabled={current.voice_enabled}"
                )
                return current

            # Prüfe, ob current selbst ein Hauptfenster ist (PDFViewer)
            if hasattr(current, "voice_enabled") and hasattr(current, "page_changed"):
                print(
                    f"DEBUG: PDFViewer gefunden: {current}, voice_enabled={current.voice_enabled}"
                )
                return current

            # Zu Parent gehen
            try:
                parent = current.parent()
                if parent == current:  # Vermeide Endlosschleife
                    break
                current = parent
            except:
                break

        # Alternative: Alle Top-Level-Widgets durchsuchen
        print("DEBUG: Durchsuche Top-Level-Widgets...")
        app = QApplication.instance()
        if app:
            for widget in app.topLevelWidgets():
                if isinstance(widget, QMainWindow) and hasattr(widget, "voice_enabled"):
                    print(
                        f"DEBUG: Hauptfenster in Top-Level gefunden: {widget}, voice_enabled={widget.voice_enabled}"
                    )
                    return widget

        print("DEBUG: Kein Hauptfenster gefunden - verwende Standard-Hauptfenster")
        # Fallback: Versuche das aktive Fenster zu finden
        for widget in app.topLevelWidgets():
            if widget.isActiveWindow():
                return widget

        return None  # Explizit None zurückgeben

    def _get_voice_enabled(self):
        """Bestimmt ob Sprachausgabe aktiviert ist"""
        # 1. Direkt vom Hauptfenster
        if self.main_window and hasattr(self.main_window, "voice_enabled"):
            print(
                f"DEBUG _get_voice_enabled: main_window.voice_enabled={self.main_window.voice_enabled}"
            )
            return self.main_window.voice_enabled

        # 2. Vom parent widget
        if self.parent_widget:
            # Prüfe ob parent selbst PDFViewer ist
            if hasattr(self.parent_widget, "voice_enabled"):
                print(
                    f"DEBUG _get_voice_enabled: parent.voice_enabled={self.parent_widget.voice_enabled}"
                )
                return self.parent_widget.voice_enabled

            # Prüfe ob parent ein main_window Attribut hat
            if (
                hasattr(self.parent_widget, "main_window")
                and self.parent_widget.main_window
            ):
                if hasattr(self.parent_widget.main_window, "voice_enabled"):
                    return self.parent_widget.main_window.voice_enabled

        # 3. Fallback: Sprachausgabe deaktivieren
        print("DEBUG _get_voice_enabled: Fallback auf False")
        return False

    def on_save_checkbox_changed(self, state):
        """Wenn Master-PW gesetzt ist, normale Behandlung"""
        # Nichts Besonderes, Checkbox funktioniert normal
        pass

    def on_save_checkbox_without_master(self, state):
        """Wenn kein Master-PW gesetzt ist, erzwinge Einrichtung"""
        if state == Qt.Checked:
            # Frage ob Master-Passwort eingerichtet werden soll
            dialog = myUniversalDialog(
                self,
                title=self.lang.tr("master_password_required"),
                message=self.lang.tr(
                    "master_password_for_spasswords"
                ),  # Wiederverwenden
                buttons=[
                    (self.lang.tr("confirm_yes"), "primary", "yes"),
                    (self.lang.tr("confirm_no"), "danger", "no"),
                ],
                icon_type="",
                text_alignment=Qt.AlignLeft,
            )

            if dialog.exec_() == QDialog.Accepted and dialog.result_value == "yes":
                setup_dialog = MasterPasswordDialog(self, mode="setup")
                if setup_dialog.exec_() == QDialog.Accepted:
                    # Master-PW wurde erfolgreich eingerichtet
                    # Checkbox bleibt aktiviert
                    self.save_checkbox.setChecked(True)
                    # Verbindung umstellen auf normale Behandlung
                    self.save_checkbox.stateChanged.disconnect()
                    self.save_checkbox.stateChanged.connect(
                        self.on_save_checkbox_changed
                    )
                    return
                else:
                    # Setup abgebrochen, Checkbox zurücksetzen
                    self.save_checkbox.setChecked(False)
                    return
            else:
                # Benutzer möchte kein Master-PW einrichten, Checkbox zurücksetzen
                self.save_checkbox.setChecked(False)
                return
        else:
            # Checkbox wurde deaktiviert, normaler Vorgang
            pass


