class PasswordInputWidget(QWidget):
    """Erweiterte Passwort-Eingabe mit allen gewünschten Funktionen"""

    def __init__(self, parent=None, show_confirm=True, show_strength=True, mode="new"):
        super().__init__(parent)
        self.show_confirm = show_confirm
        self.show_strength = show_strength
        self.mode = mode

        # Language-Instanz vom Parent übernehmen
        if parent and hasattr(parent, "lang"):
            self.lang = parent.lang
        else:
            # Fallback: Importiere Language nur wenn nötig
            try:
                self.lang = Language()
            except ImportError:
                # Einfache Dummy-Klasse
                class DummyLang:
                    def tr(self, key, *args, **kwargs):
                        return key

                self.lang = DummyLang()

        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout()
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(5)

        # Erste Passwortzeile
        pw1_layout = QHBoxLayout()

        # Passwort Label
        if self.mode == "new":
            label_text = self.lang.tr("password_new") + ":"
        else:
            label_text = self.lang.tr("password_required") + ":"

        pw_label1 = QLabel(label_text)
        pw_label1.setMinimumWidth(120)  # minimumWidth
        pw_label1.setSizePolicy(
            QSizePolicy.Minimum, QSizePolicy.Fixed
        )  # Erlaubt Wachstum
        pw1_layout.addWidget(pw_label1)

        # Passwort Eingabefeld
        self.password_input = QLineEdit()
        self.password_input.setEchoMode(QLineEdit.Password)
        self.password_input.textChanged.connect(self.on_password_changed)
        pw1_layout.addWidget(self.password_input, 1)

        # NUR im 'new' Modus: Generator und Kopieren Buttons anzeigen
        if self.mode == "new":
            # "Zufallsgenerator" Button
            self.generate_password_btn = QToolButton()
            self.generate_password_btn.setText("🎲")
            self.generate_password_btn.setToolTip(self.lang.tr("generator_title"))
            self.generate_password_btn.setFocusPolicy(Qt.NoFocus)
            self.generate_password_btn.clicked.connect(self.show_generator_dialog)
            self.generate_password_btn.setStyleSheet("""
                QToolButton {
                    border: 1px solid #666;
                    border-radius: 3px;
                    padding: 3px;
                    background: qlineargradient(x1: 0, y1: 0, x2: 0, y2: 1,
                                            stop: 0 #555, stop: 1 #333);
                    color: white;
                    font-size: 12px;
                    min-width: 24px;
                    min-height: 24px;
                }
                QToolButton:hover {
                    background: qlineargradient(x1: 0, y1: 0, x2: 0, y2: 1,
                                            stop: 0 #666, stop: 1 #444);
                }
                QToolButton:pressed {
                    background: qlineargradient(x1: 0, y1: 0, x2: 0, y2: 1,
                                            stop: 0 #444, stop: 1 #222);
                }
            """)
