### 5. PDFPasswordManager mit Master-Passwort-Support
### ==================================================



class PDFPasswordManager:
    """· Verwaltet ALLE gespeicherten PDF-Passwörter
      mit 3-Stufiger Suche
    · Verschlüsselt/entschlüsselt Passwörter
    · Master-Passwort-System
    """

    MASTER_PASSWORD_SETTING = "master_password_hash"
    MASTER_PASSWORD_ENABLED = "master_password_enabled"

    # ========== Verschlüsselung ==========

    @staticmethod
    def get_encryption_key():
        """Erzeugt einen Verschlüsselungsschlüssel für die normalen Passwörter"""
        salt = b"PDFDarkView_Salt_2024"
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(b"PDFDarkView_MasterKey"))
        return key

    @staticmethod
    def get_master_encryption_key(master_password):
        """Erzeugt einen Verschlüsselungsschlüssel aus dem Master-Passwort"""
        if not master_password:
            raise ValueError("Master-Passwort erforderlich")

        salt = b"PDFDarkView_Master_Salt_2024"
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=200000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(master_password.encode()))
        return key

    @staticmethod
    def hash_master_password(password):
        """Erstellt einen Hash des Master-Passworts"""
        salt = b"PDFDarkView_Master_Hash_Salt"
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=64,
            salt=salt,
            iterations=300000,
        )
        hash_bytes = kdf.derive(password.encode())
        return base64.urlsafe_b64encode(hash_bytes).decode()

    @staticmethod
    def verify_master_password(password, stored_hash):
        """Überprüft ein Master-Passwort"""
        try:
            new_hash = PDFPasswordManager.hash_master_password(password)
            return new_hash == stored_hash
        except:
            return False

    @staticmethod
    def load_master_password_settings():
        """Lädt die Master-Passwort-Einstellungen"""
        try:
            settings_path = os.path.join(Config.DATA_DIR, "master_password.json")
            if os.path.exists(settings_path):
                with open(settings_path, "r", encoding="utf-8") as f:
                    return json.load(f)
        except Exception as e:
            print(f"Fehler beim Laden der Master-Passwort-Einstellungen: {e}")
        return {}

    @staticmethod
    def save_master_password_settings(settings):
        """Speichert die Master-Passwort-Einstellungen"""
        try:
            os.makedirs(Config.DATA_DIR, exist_ok=True)
            settings_path = os.path.join(Config.DATA_DIR, "master_password.json")
            with open(settings_path, "w", encoding="utf-8") as f:
                json.dump(settings, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"Fehler beim Speichern der Master-Passwort-Einstellungen: {e}")

    @staticmethod
    def is_master_password_set():
        """Prüft ob ein Master-Passwort gesetzt ist"""
        settings = PDFPasswordManager.load_master_password_settings()
        has_hash = bool(settings.get(PDFPasswordManager.MASTER_PASSWORD_SETTING, ""))
        is_enabled = settings.get(PDFPasswordManager.MASTER_PASSWORD_ENABLED, False)
        return has_hash and is_enabled

    @staticmethod
    def set_master_password(password):
        """Setzt ein Master-Passwort"""
        settings = {
            PDFPasswordManager.MASTER_PASSWORD_SETTING: PDFPasswordManager.hash_master_password(
                password
            ),
            PDFPasswordManager.MASTER_PASSWORD_ENABLED: True,
        }
        PDFPasswordManager.save_master_password_settings(settings)

    @staticmethod
    def remove_master_password_and_data():
        """Entfernt Master-Passwort und LÖSCHT alle Passwörter"""
        try:
            # 1. Passwort-Datenbank löschen
            if os.path.exists(Config.PASSWORD_DB_PATH):
                os.remove(Config.PASSWORD_DB_PATH)
                print(f"Passwort-Datenbank gelöscht: {Config.PASSWORD_DB_PATH}")

            # 2. Master-PW Einstellungen löschen
            settings_path = os.path.join(Config.DATA_DIR, "master_password.json")
            if os.path.exists(settings_path):
                os.remove(settings_path)
                print(f"Master-PW Einstellungen gelöscht: {settings_path}")

            return True
        except Exception as e:
            print(f"Fehler beim Löschen: {e}")
            return False

    @staticmethod
    def verify_master_auth(password):
        """Verifiziert die Master-Authentifizierung"""
        settings = PDFPasswordManager.load_master_password_settings()

        if not settings.get(PDFPasswordManager.MASTER_PASSWORD_ENABLED, False):
            return True  # Kein Master-Passwort gesetzt = immer erlaubt

        stored_hash = settings.get(PDFPasswordManager.MASTER_PASSWORD_SETTING, "")
        return PDFPasswordManager.verify_master_password(password, stored_hash)

    @staticmethod
    def encrypt_password(password, master_password=None):
        """Verschlüsselt ein Passwort - mit oder ohne Master-PW"""
        try:
            if master_password:
                # Mit Master-PW verschlüsseln
                key = PDFPasswordManager.get_master_encryption_key(master_password)
            else:
                # Standard-Verschlüsselung
                key = PDFPasswordManager.get_encryption_key()

            cipher = Fernet(key)
            encrypted = cipher.encrypt(password.encode()).decode()
            return encrypted
        except Exception as e:
            print(f"Fehler beim Verschlüsseln: {e}")
            return None

    @staticmethod
    def decrypt_password(encrypted_password, master_password=None):
        """Entschlüsselt ein Passwort - versucht beide Methoden"""
        try:
            # Zuerst mit Master-PW versuchen (wenn angegeben)
            if master_password:
                try:
                    key = PDFPasswordManager.get_master_encryption_key(master_password)
                    cipher = Fernet(key)
                    return cipher.decrypt(encrypted_password.encode()).decode()
                except:
                    pass  # Nicht mit diesem Master-PW verschlüsselt

            # Dann mit Standard-Schlüssel versuchen (immer möglich)
            key = PDFPasswordManager.get_encryption_key()
            cipher = Fernet(key)
            return cipher.decrypt(encrypted_password.encode()).decode()

        except Exception as e:
            print(f"Fehler beim Entschlüsseln: {e}")
            return None

    # ========== NEUE ID- und HASH-Methoden ==========

    @staticmethod
    def get_document_id(pdf_path):
        print(f"\n[DEBUG get_document_id] Start für: {pdf_path}")
        try:
            with open(pdf_path, "rb") as f:
                # Erhöhe den Suchbereich auf 64 KB, um ID sicher zu finden
                content = f.read(65536)
                import re

                # Suche nach /ID [ <hex> <hex> ]
                match = re.search(
                    rb"/ID\s*\[\s*<([0-9a-fA-F]+)>", content, re.IGNORECASE
                )
                if match:
                    pdf_id = match.group(1).decode("ascii")
                    print(
                        f"[DEBUG get_document_id] ✅ Regex (spitze Klammern) -> ID: {pdf_id[:30]}..."
                    )
                    return pdf_id
                # Alternativ: /ID [ (hex) (hex) ]
                match = re.search(
                    rb"/ID\s*\[\s*\(([0-9a-fA-F]+)\)", content, re.IGNORECASE
                )
                if match:
                    pdf_id = match.group(1).decode("ascii")
                    print(
                        f"[DEBUG get_document_id] ✅ Regex (runde Klammern) -> ID: {pdf_id[:30]}..."
                    )
                    return pdf_id
                print(
                    "[DEBUG get_document_id] ❌ Keine ID in den ersten 64 KB gefunden."
                )
        except Exception as e:
            print(f"[DEBUG get_document_id] ❌ Fehler: {e}")
        return None

    @staticmethod
    def get_file_hash(pdf_path):
        print(f"\n[DEBUG get_file_hash] Start für: {pdf_path}")
        try:
            import hashlib

            hasher = hashlib.sha256()
            with open(pdf_path, "rb") as f:
                for chunk in iter(lambda: f.read(65536), b""):
                    hasher.update(chunk)
            file_hash = hasher.hexdigest()
            print(
                f"[DEBUG get_file_hash] ✅ SHA-256: {file_hash[:30]}... ({len(file_hash)} Zeichen)"
            )
            return file_hash
        except Exception as e:
            print(f"[DEBUG get_file_hash] ❌ Fehler: {e}")
            return None

    # ========== Laden/Speichern der Passwort-DB (angepasst) ==========
    @staticmethod
    def load_passwords():
        try:
            if os.path.exists(Config.PASSWORD_DB_PATH):
                with open(Config.PASSWORD_DB_PATH, "r", encoding="utf-8") as f:
                    data = json.load(f)
                    if isinstance(data, dict):
                        return data
                    else:
                        print(
                            "WARNUNG: passwords.json ist kein Dictionary. Korrigiere..."
                        )
                        return {}
            else:
                return {}
        except Exception as e:
            print(f"Fehler beim Laden der Passwörter: {e}")
            return {}

    @staticmethod
    def save_passwords(password_db):
        print(f"DEBUG save_passwords: wird aufgerufen mit {len(password_db)} Einträgen")
        try:
            os.makedirs(Config.DATA_DIR, exist_ok=True)
            if os.path.exists(Config.PASSWORD_DB_PATH):
                shutil.copy2(Config.PASSWORD_DB_PATH, Config.PASSWORD_DB_PATH + ".bak")
            with open(Config.PASSWORD_DB_PATH, "w", encoding="utf-8") as f:
                json.dump(password_db, f, ensure_ascii=False, indent=2)
            print("DEBUG save_passwords: erfolgreich gespeichert")
        except Exception as e:
            print(f"Fehler beim Speichern der Passwörter: {e}")

    @staticmethod
    def migrate_old_entries():
        """Wandelt alte Pfad-basierte Einträge in das neue Format um."""
        passwords = PDFPasswordManager.load_passwords()
        modified = False
        for path, value in list(passwords.items()):
            if isinstance(value, str):  # Alter Eintrag (nur verschlüsseltes Passwort)
                pdf_id = PDFPasswordManager.get_document_id(path)
                file_hash = PDFPasswordManager.get_file_hash(path)
                passwords[path] = {
                    "password": value,
                    "pdf_id": pdf_id,
                    "sha256": file_hash,
                    "last_path": path,
                }
                modified = True
        if modified:
            PDFPasswordManager.save_passwords(passwords)
            print("Migration alter Passworteinträge abgeschlossen.")

    # ========== Speichern und Abrufen mit dreistufiger Suche ==========
    @staticmethod
    def save_password(pdf_path, password, master_password=None):
        print(f"\n[DEBUG save_password] START für: {pdf_path}")
        if not PDFPasswordManager.is_master_password_set():
            print(
                "[DEBUG save_password] ❌ Master-Passwort nicht gesetzt – Speichern verweigert."
            )
            return False

        encrypted = PDFPasswordManager.encrypt_password(password, master_password)
        if not encrypted:
            print("[DEBUG save_password] ❌ Verschlüsselung fehlgeschlagen.")
            return False

        pdf_id = PDFPasswordManager.get_document_id(pdf_path)
        file_hash = PDFPasswordManager.get_file_hash(pdf_path)

        passwords = PDFPasswordManager.load_passwords()
        old = passwords.get(pdf_path)
        if old:
            print(
                f"[DEBUG save_password] 📝 Überschreibe bestehenden Eintrag für {pdf_path}"
            )
        else:
            print(f"[DEBUG save_password] 📝 Erstelle neuen Eintrag für {pdf_path}")

        passwords[pdf_path] = {
            "password": encrypted,
            "pdf_id": pdf_id,
            "sha256": file_hash,
            "last_path": pdf_path,
        }
        print(f"[DEBUG save_password] DB enthält jetzt {len(passwords)} Einträge")
        PDFPasswordManager.save_passwords(passwords)
        print("[DEBUG save_password] ✅ Erfolgreich gespeichert.")
        return True

    @staticmethod
    def get_saved_password(pdf_path):
        print(f"\n{'='*60}")
        print(f"[DEBUG get_saved_password] START für: {pdf_path}")
        print(f"{'='*60}")

        passwords = PDFPasswordManager.load_passwords()
        print(f"[DEBUG get_saved_password] DB enthält {len(passwords)} Einträge")

        # ----- 1. Exakter Pfad -----
        entry = passwords.get(pdf_path)
        if entry:
            print(
                f"[DEBUG get_saved_password] 🔍 1. Pfadvergleich: EXAKTEN PFAD gefunden."
            )
            if isinstance(entry, dict):
                pwd = PDFPasswordManager.decrypt_password(entry["password"], None)
                if pwd:
                    print(
                        f"[DEBUG get_saved_password] ✅ PASSWORT über exakten Pfad (Dict) erhalten."
                    )
                    return pwd
                else:
                    print(
                        f"[DEBUG get_saved_password] ❌ Entschlüsselung des Dict-Eintrags fehlgeschlagen."
                    )
            elif isinstance(entry, str):
                pwd = PDFPasswordManager.decrypt_password(entry, None)
                if pwd:
                    print(
                        f"[DEBUG get_saved_password] ✅ PASSWORT über exakten Pfad (String) erhalten."
                    )
                    return pwd
        else:
            print(
                f"[DEBUG get_saved_password] 🔍 1. Pfadvergleich: Kein exakter Pfad-Eintrag."
            )

        # ----- 2. PDF-ID -----
        pdf_id = PDFPasswordManager.get_document_id(pdf_path)
        if pdf_id:
            print(
                f"[DEBUG get_saved_password] 🔍 2. ID-Vergleich: Suche nach ID {pdf_id[:30]}..."
            )
            found = False
            for path, data in passwords.items():
                if isinstance(data, dict) and data.get("pdf_id") == pdf_id:
                    found = True
                    pwd = PDFPasswordManager.decrypt_password(data["password"], None)
                    if pwd:
                        print(
                            f"[DEBUG get_saved_password] ✅ PASSWORT über PDF-ID gefunden (im Eintrag für {path})."
                        )
                        print(
                            f"[DEBUG get_saved_password] ➕ Erstelle neuen Eintrag für aktuellen Pfad {pdf_path}"
                        )
                        PDFPasswordManager.save_password(pdf_path, pwd)
                        return pwd
                    else:
                        print(
                            f"[DEBUG get_saved_password] ❌ Entschlüsselung des ID-Eintrags fehlgeschlagen."
                        )
                    break
            if not found:
                print(
                    f"[DEBUG get_saved_password] ❌ Kein Eintrag mit dieser PDF-ID gefunden."
                )
        else:
            print(
                f"[DEBUG get_saved_password] 🔍 2. ID-Vergleich: Keine PDF-ID extrahierbar."
            )

        # ----- 3. SHA-256 Hash -----
        file_hash = PDFPasswordManager.get_file_hash(pdf_path)
        if file_hash:
            print(
                f"[DEBUG get_saved_password] 🔍 3. Hash-Vergleich: Suche nach Hash {file_hash[:30]}..."
            )
            found = False
            for path, data in passwords.items():
                if isinstance(data, dict) and data.get("sha256") == file_hash:
                    found = True
                    pwd = PDFPasswordManager.decrypt_password(data["password"], None)
                    if pwd:
                        print(
                            f"[DEBUG get_saved_password] ✅ PASSWORT über SHA-256 gefunden (im Eintrag für {path})."
                        )
                        print(
                            f"[DEBUG get_saved_password] ➕ Erstelle neuen Eintrag für aktuellen Pfad {pdf_path}"
                        )
                        PDFPasswordManager.save_password(pdf_path, pwd)
                        return pwd
                    else:
                        print(
                            f"[DEBUG get_saved_password] ❌ Entschlüsselung des Hash-Eintrags fehlgeschlagen."
                        )
                    break
            if not found:
                print(
                    f"[DEBUG get_saved_password] ❌ Kein Eintrag mit diesem SHA-256 gefunden."
                )
        else:
            print(
                f"[DEBUG get_saved_password] 🔍 3. Hash-Vergleich: Kein SHA-256 berechnet."
            )

        print(f"[DEBUG get_saved_password] ❌❌❌ KEIN PASSWORT GEFUNDEN ❌❌❌")
        return None

    @staticmethod
    def delete_password(pdf_path):
        """Löscht Eintrag anhand des Pfades."""
        passwords = PDFPasswordManager.load_passwords()
        if pdf_path in passwords:
            del passwords[pdf_path]
            PDFPasswordManager.save_passwords(passwords)

    @staticmethod
    def delete_all_passwords():
        """Löscht alle gespeicherten Passwörter."""
        PDFPasswordManager.save_passwords({})

    @staticmethod
    def get_decrypted_passwords(master_password=None):
        """Holt alle gespeicherten Passwörter entschlüsselt (für Export/Anzeige)."""
        if PDFPasswordManager.is_master_password_set() and not master_password:
            raise PermissionError("Master-Passwort erforderlich")

        passwords = PDFPasswordManager.load_passwords()
        decrypted = {}
        for pdf_path, data in passwords.items():
            if isinstance(data, dict):
                encrypted = data.get("password")
            else:
                encrypted = data
            try:
                decrypted_pw = PDFPasswordManager.decrypt_password(
                    encrypted, master_password
                )
                if decrypted_pw:
                    decrypted[pdf_path] = decrypted_pw
                else:
                    decrypted[pdf_path] = "[Entschlüsselungsfehler]"
            except Exception as e:
                print(f"Fehler beim Entschlüsseln für {pdf_path}: {e}")
                decrypted[pdf_path] = "[Fehler]"
        return decrypted

    @staticmethod
    def export_passwords_to_file(filepath, master_password=None, format="json"):
        """Exportiert alle Passwörter in eine Datei"""
        decrypted = PDFPasswordManager.get_decrypted_passwords(master_password)

        if format.lower() == "json":
            with open(filepath, "w", encoding="utf-8") as f:
                json.dump(decrypted, f, ensure_ascii=False, indent=2)
        elif format.lower() == "csv":
            with open(filepath, "w", encoding="utf-8") as f:
                f.write("PDF Datei;Passwort\n")
                for pdf_path, password in decrypted.items():
                    filename = os.path.basename(pdf_path)
                    f.write(f'"{filename}";"{password}"\n')
        elif format.lower() == "txt":
            with open(filepath, "w", encoding="utf-8") as f:
                for pdf_path, password in decrypted.items():
                    filename = os.path.basename(pdf_path)
                    f.write(f"Datei: {filename}\n")
                    f.write(f"Pfad: {pdf_path}\n")
                    f.write(f"Passwort: {password}\n")
                    f.write("-" * 50 + "\n")

        return True

    @staticmethod
    def debug_print_settings():
        settings_path = os.path.join(Config.DATA_DIR, "master_password.json")
        print(f"DEBUG: Lese Einstellungen von {settings_path}")
        if os.path.exists(settings_path):
            with open(settings_path, "r") as f:
                print(f"DEBUG: Inhalt: {f.read()}")
        else:
            print("DEBUG: Datei existiert nicht")

    @staticmethod
    def clean_passwords_if_no_master():
        """Löscht alle gespeicherten Passwörter, wenn kein Master-PW existiert."""
        if not PDFPasswordManager.is_master_password_set():
            if os.path.exists(Config.PASSWORD_DB_PATH):
                os.remove(Config.PASSWORD_DB_PATH)
                print("Kein Master-PW – alle gespeicherten Passwörter gelöscht.")

    ### ================================================
