    SIGNATURE_AUTH_DISABLED = "signature_auth_disabled"

    @staticmethod
    def get_signature_auth_disabled():
        """Gibt zurück, ob die Passwortabfrage für Signaturen deaktiviert ist."""
        settings = PDFPasswordManager.load_master_password_settings()
        return settings.get(PDFPasswordManager.SIGNATURE_AUTH_DISABLED, False)

    @staticmethod
    def set_signature_auth_disabled(disabled):
        """Setzt den Zustand der Checkbox (True = Abfrage deaktiviert)."""
        settings = PDFPasswordManager.load_master_password_settings()
        settings[PDFPasswordManager.SIGNATURE_AUTH_DISABLED] = disabled
        PDFPasswordManager.save_master_password_settings(settings)

    ### ================================================
    ### PW für TEXTBAUSTEINE
    ### ================================================

    TEMPLATE_AUTH_DISABLED = "template_auth_disabled"

    @staticmethod
    def get_template_auth_disabled():
        """Gibt zurück, ob die Passwortabfrage für private Textbausteine deaktiviert ist."""
        settings = PDFPasswordManager.load_master_password_settings()
        return settings.get(PDFPasswordManager.TEMPLATE_AUTH_DISABLED, False)

    @staticmethod
    def set_template_auth_disabled(disabled):
        """Setzt den Zustand der Checkbox (True = Abfrage deaktiviert)."""
        settings = PDFPasswordManager.load_master_password_settings()
        settings[PDFPasswordManager.TEMPLATE_AUTH_DISABLED] = disabled
        PDFPasswordManager.save_master_password_settings(settings)


