    def _find_main_window(self, widget):
        """Findet das Hauptfenster (PDFViewer) in der Widget-Hierarchie"""
        if widget is None:
            return None

        print(f"DEBUG myUniversalDialog._find_main_window: Starte mit {widget}")
        current = widget

        while current is not None:
            if isinstance(current, QMainWindow) and hasattr(current, "voice_enabled"):
                return current
            if hasattr(current, "voice_enabled") and hasattr(current, "page_changed"):
                return current
            try:
                parent = current.parent()
                if parent == current:
                    break
                current = parent
            except:
                break

        app = QApplication.instance()
        if app:
            for widget in app.topLevelWidgets():
                if isinstance(widget, QMainWindow) and hasattr(widget, "voice_enabled"):
                    return widget

        return None

    def _get_voice_enabled(self):
        """Bestimmt ob Sprachausgabe aktiviert ist"""
        if self.main_window and hasattr(self.main_window, "voice_enabled"):
            return self.main_window.voice_enabled
        return False

    def toggle_password_visibility(self, state):
        """Schaltet die Sichtbarkeit der Passwortfelder um"""
        if self.mode == "verify":
            if state == Qt.Checked:
                self.password_input.setEchoMode(QLineEdit.Normal)
            else:
                self.password_input.setEchoMode(QLineEdit.Password)

        elif self.mode == "setup":
            sender = self.sender()
            if sender == self.show_password_check1:
                if state == Qt.Checked:
                    self.password_input.setEchoMode(QLineEdit.Normal)
                else:
                    self.password_input.setEchoMode(QLineEdit.Password)
            elif sender == self.show_password_check2:
                if state == Qt.Checked:
                    self.confirm_input.setEchoMode(QLineEdit.Normal)
                else:
                    self.confirm_input.setEchoMode(QLineEdit.Password)

        elif self.mode == "change":
            sender = self.sender()
            if sender == self.show_new_password_check:
                if state == Qt.Checked:
                    self.new_password_input.setEchoMode(QLineEdit.Normal)
                else:
                    self.new_password_input.setEchoMode(QLineEdit.Password)
            elif sender == self.show_confirm_check:
                if state == Qt.Checked:
                    self.confirm_input.setEchoMode(QLineEdit.Normal)
                else:
                    self.confirm_input.setEchoMode(QLineEdit.Password)

    def open_password_generator(self, target_field):
        """Öffnet den Passwort Generator und setzt das generierte Passwort"""
        try:
            generator_dialog = PasswordGeneratorDialog(
                self, main_window=self.main_window
            )
            if generator_dialog.exec_() == QDialog.Accepted:
                generated_password = generator_dialog.get_generated_password()
                if generated_password:
                    target_field.setText(generated_password)
                    self.check_password_strength()
                    target_field.setFocus()
                    target_field.selectAll()
        except Exception as e:
            self.open_simple_password_generator(target_field)

