    def _authenticate(self):
        """Authentifiziert den Benutzer mit dem Master-Passwort."""
        dialog = MasterPasswordDialog(self, mode="verify")
        if dialog.exec_() == QDialog.Accepted and dialog.password:
            if PDFPasswordManager.verify_master_auth(dialog.password):
                self.authenticated = True
                return True
            else:
                myUniversalDialog(
                    self,
                    title=self.lang.tr("password_wrong"),
                    message=self.lang.tr("password_wrong"),
                    buttons=[(self.lang.tr("btn_ok"), "danger", "ok")],
                    icon_type="error",
                    text_alignment=Qt.AlignLeft,
                ).exec_()
        return False

    def set_initial_focus(self):
        """Setzt den Fokus auf den ersten sichtbaren Button"""
        for button in self.button_widgets:
            if button.isVisible():
                button.setFocus()
                break

    def update_status_label(self):
        """Aktualisiert die Status-Anzeige"""
        if PDFPasswordManager.is_master_password_set():
            status = "✅ " + self.lang.tr("master_password_success")
            color = "#F0F0F0"
        else:
            status = self.lang.tr("master_password_required")
            color = "#DB4242"

        self.status_label.setText(status)
        self.status_label.setStyleSheet(f"""
            QLabel {{
                color: {color};
                font-weight: bold;
                font-size: 15px;
                padding: 12px;
                border-radius: 6px;
                background-color: #000000;
                text-align: center;
            }}
        """)

    def update_button_states(self):
        """Aktualisiert den Zustand der Buttons"""
        has_master = PDFPasswordManager.is_master_password_set()

        self.setup_button.setVisible(not has_master)
        self.change_button.setVisible(has_master)
        self.remove_button.setVisible(has_master)

    def setup_master_password(self):
        """Richtet ein neues Master-Passwort ein"""
        dialog = MasterPasswordDialog(self, mode="setup")
        if dialog.exec_() == QDialog.Accepted and dialog.password:
            PDFPasswordManager.set_master_password(dialog.password)

            dialog = myUniversalDialog(
                self,
                title=self.lang.tr("success"),
                message=self.lang.tr("master_password_success"),
                buttons=[(self.lang.tr("btn_ok"), "success", "ok")],
                icon_type="",
                voice_message=self.lang.tr("master_password_success"),
                text_alignment=Qt.AlignLeft,
            )
            dialog.exec_()

            self.update_status_label()
            self.update_button_states()

    def change_master_password(self):
        """Ändert das bestehende Master-Passwort"""
        verify_dialog = MasterPasswordDialog(self, mode="verify")
        if verify_dialog.exec_() == QDialog.Accepted and verify_dialog.password:
            if PDFPasswordManager.verify_master_auth(verify_dialog.password):
                new_dialog = MasterPasswordDialog(self, mode="change")
                if new_dialog.exec_() == QDialog.Accepted and new_dialog.new_password:
                    PDFPasswordManager.set_master_password(new_dialog.new_password)

                    dialog = myUniversalDialog(
                        self,
                        title=self.lang.tr("success"),
                        message=self.lang.tr("master_password_changed"),
                        buttons=[(self.lang.tr("btn_ok"), "success", "ok")],
                        icon_type="",
                        voice_message=self.lang.tr("master_password_changed"),
                        text_alignment=Qt.AlignLeft,
                    )
                    dialog.exec_()

                    self.update_status_label()
            else:
                dialog = myUniversalDialog(
                    self,
                    title=self.lang.tr("password_wrong"),
                    message=self.lang.tr("password_wrong")
                    + "\n\n"
                    + self.lang.tr("master_password_enter"),
                    buttons=[
                        (self.lang.tr("btn_retry"), "primary", "retry"),
                        (self.lang.tr("btn_cancel"), "danger", "cancel"),
                    ],
                    icon_type="",
                    voice_message=self.lang.tr("password_wrong"),
                    text_alignment=Qt.AlignLeft,
                )

                if (
                    dialog.exec_() == QDialog.Accepted
                    and dialog.result_value == "retry"
                ):
                    self.change_master_password()

    def remove_master_password(self):
        """Entfernt das Master-Passwort UND LÖSCHT alle Passwörter"""
        # Authentifizierung erforderlich
        auth_dialog = MasterPasswordDialog(self, mode="verify")

        if auth_dialog.exec_() == QDialog.Accepted and auth_dialog.password:
            if PDFPasswordManager.verify_master_auth(auth_dialog.password):
                # Warnung und Export-Option
                dialog = myUniversalDialog(
                    self,
                    title=self.lang.tr("master_password_remove"),
                    message=self.lang.tr("master_password_export_before"),
                    buttons=[
                        (
                            self.lang.tr("master_password_export_delete"),
                            "warning",
                            "export_delete",
                            250,
                        ),
                        (
                            self.lang.tr("master_password_delete_now"),
                            "danger",
                            "delete_now",
                            250,
                        ),
                        (self.lang.tr("btn_cancel"), "primary", "cancel"),
                    ],
                    icon_type="",
                    text_alignment=Qt.AlignLeft,
                )

                if dialog.exec_() == QDialog.Accepted:
                    success = False  # <-- Hier initialisieren!

                    if dialog.result_value == "export_delete":
                        success = self._export_before_deletion(auth_dialog.password)
                        if not success:
                            return  # Export fehlgeschlagen oder abgebrochen

                    if dialog.result_value == "delete_now" or success:
                        # Endgültige Bestätigung nur bei delete_now oder erfolgreichem Export
                        if dialog.result_value == "delete_now":
                            confirm_dialog = myUniversalDialog(
                                self,
                                title=self.lang.tr("master_password_remove"),
                                message=self.lang.tr("master_password_remove_confirm"),
                                buttons=[
                                    (
                                        self.lang.tr("confirm_yes"),
                                        "danger",
                                        "confirm_delete",
                                        250,
                                    ),
                                    (
                                        self.lang.tr("confirm_no"),
                                        "primary",
                                        "cancel",
                                        250,
                                    ),
                                ],
                                icon_type="error",
                                text_alignment=Qt.AlignLeft,
                            )

                            if (
                                confirm_dialog.exec_() == QDialog.Accepted
                                and confirm_dialog.result_value == "confirm_delete"
                            ):
                                success = (
                                    PDFPasswordManager.remove_master_password_and_data()
                                )
                            else:
                                success = False
                        else:
                            # Bei export_delete wurde bereits bestätigt
                            success = (
                                PDFPasswordManager.remove_master_password_and_data()
                            )

                        if success:
                            success_dialog = myUniversalDialog(
                                self,
                                title=self.lang.tr("success"),
                                message=self.lang.tr("master_password_removed"),
                                buttons=[(self.lang.tr("btn_ok"), "success", "ok")],
                                icon_type="",
                                text_alignment=Qt.AlignLeft,
                            )
                            self.close_password_manager_if_open()
                            success_dialog.exec_()

                            # Nach erfolgreichem Entfernen das Signatur- und privateTextBaustein-Setting zurücksetzen
                            PDFPasswordManager.set_signature_auth_disabled(False)
                            PDFPasswordManager.set_template_auth_disabled(False)

                            self.update_status_label()
                            self.update_button_states()
                            self.accept()  # Dialog schließen
                        else:
                            error_dialog = myUniversalDialog(
                                self,
                                title=self.lang.tr("error"),
                                message=self.lang.tr("error_occurred"),
                                buttons=[(self.lang.tr("btn_ok"), "danger", "ok")],
                                icon_type="error",
                                text_alignment=Qt.AlignLeft,
                            )
                            error_dialog.exec_()
                else:
                    # Benutzer hat im ersten Dialog "Abbrechen" gewählt
                    return
            else:
                # Falsches Passwort
                dialog = myUniversalDialog(
                    self,
                    title=self.lang.tr("password_wrong"),
                    message=self.lang.tr("password_wrong")
                    + "\n\n"
                    + self.lang.tr("master_password_enter"),
                    buttons=[
                        (self.lang.tr("btn_retry"), "primary", "retry"),
                        (self.lang.tr("btn_cancel"), "danger", "cancel"),
                    ],
                    icon_type="",
                    voice_message=self.lang.tr("password_wrong"),
                    text_alignment=Qt.AlignLeft,
                )

                if (
                    dialog.exec_() == QDialog.Accepted
                    and dialog.result_value == "retry"
                ):
                    self.remove_master_password()

    def close_password_manager_if_open(self):
        """Schließt den Passwortmanager, falls er vom selben Hauptfenster geöffnet wurde"""
        try:
            parent = self.parent()
            if parent and isinstance(parent, EnhancedPasswordManagerDialog):
                parent.accept()
                print("Passwortmanager wurde geschlossen")

            app = QApplication.instance()
            for widget in app.topLevelWidgets():
                if isinstance(widget, EnhancedPasswordManagerDialog):
                    widget.accept()
        except Exception as e:
            print(f"Fehler beim Schließen des Passwortmanagers: {e}")

    def _export_before_deletion(self, master_password):
        """Exportiert Passwörter vor dem Löschen - mit Format-Auswahl"""
        try:
            format_dialog = QDialog(self)
            format_dialog.setWindowTitle(self.lang.tr("btn_export"))
            format_dialog.setFixedSize(350, 200)
            format_dialog.setStyleSheet("""
                QDialog {
                    background-color: #222222;
                    color: white;
                }
                QLabel {
                    font-size: 14px;
                    padding: 10px;
                }
                QComboBox {
                    padding: 8px;
                    font-size: 14px;
                    background-color: #3D3D3D;
                    color: white;
                    border: 1px solid #555;
                    border-radius: 4px;
                }
            """)

            layout = QVBoxLayout()
            layout.addWidget(QLabel(self.lang.tr("btn_export") + ":"))

            format_combo = QComboBox()
            format_combo.addItems(["JSON", "CSV", "TXT"])
            layout.addWidget(format_combo)

            button_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
            button_box.setStyleSheet("""
                QPushButton {
                    min-width: 80px;
                    padding: 8px 16px;
                    border-radius: 4px;
                }
            """)
            button_box.accepted.connect(format_dialog.accept)
            button_box.rejected.connect(format_dialog.reject)
            layout.addWidget(button_box)

            format_dialog.setLayout(layout)

            if format_dialog.exec_() != QDialog.Accepted:
                return False

            format_name = format_combo.currentText()
            format_map = {"JSON": "json", "CSV": "csv", "TXT": "txt"}
            file_format = format_map.get(format_name, "json")

            default_name = f"pdf_passwords_backup_export.{file_format}"
            path, _ = QFileDialog.getSaveFileName(
                self,
                f"{self.lang.tr('btn_export')} {format_name}",
                os.path.join(os.path.expanduser("~/Desktop"), default_name),
                f"{format_name} {self.lang.tr('file_export')} (*.{file_format})",
            )

            if not path:
                return False

            if PDFPasswordManager.export_passwords_to_file(
                path, master_password, file_format
            ):
                dialog = myUniversalDialog(
                    self,
                    title=self.lang.tr("success"),
                    message=self.lang.tr("success_exported")
                    + f"\n{os.path.basename(path)}",
                    buttons=[(self.lang.tr("btn_ok"), "success", "ok")],
                    icon_type="",
                    voice_message=self.lang.tr("success_exported"),
                    text_alignment=Qt.AlignLeft,
                )
                dialog.exec_()
                return True
            else:
                dialog = myUniversalDialog(
                    self,
                    title=self.lang.tr("error"),
                    message=self.lang.tr("export_failed"),
                    buttons=[(self.lang.tr("btn_ok"), "danger", "ok")],
                    icon_type="",
                    voice_message=self.lang.tr("export_failed"),
                    text_alignment=Qt.AlignLeft,
                )
                dialog.exec_()
                return False

        except Exception as e:
            print(f"Export-Fehler: {e}")
            dialog = myUniversalDialog(
                self,
                title=self.lang.tr("error"),
                message=f"{self.lang.tr('error_occurred')}:\n{str(e)[:100]}",
                buttons=[(self.lang.tr("btn_ok"), "danger", "ok")],
                icon_type="",
                text_alignment=Qt.AlignLeft,
            )
            dialog.exec_()
            return False

    def _find_main_window(self, widget):
        """Findet das Hauptfenster (PDFViewer) in der Widget-Hierarchie"""
        if widget is None:
            return None

        current = widget

        while current is not None:
            if isinstance(current, QMainWindow) and hasattr(current, "voice_enabled"):
                return current
            if hasattr(current, "voice_enabled") and hasattr(current, "page_changed"):
                return current
            try:
                parent = current.parent()
                if parent == current:
                    break
                current = parent
            except:
                break

        app = QApplication.instance()
        if app:
            for widget in app.topLevelWidgets():
                if isinstance(widget, QMainWindow) and hasattr(widget, "voice_enabled"):
                    return widget

        return None

    def _get_voice_enabled(self):
        """Bestimmt ob Sprachausgabe aktiviert ist"""
        if self.main_window and hasattr(self.main_window, "voice_enabled"):
            return self.main_window.voice_enabled
        return False

    def _on_signature_auth_changed(self, state):
        """Speichert den Zustand der Checkbox sofort."""
        disabled = state == Qt.Checked
        PDFPasswordManager.set_signature_auth_disabled(disabled)
        if self.main_window and hasattr(self.main_window, "say"):
            self.main_window.say(
                self.lang.tr("signature_auth_disabled")
                + (
                    " " + self.lang.tr("voice_on")
                    if disabled
                    else " " + self.lang.tr("voice_off")
                )
            )

    def _on_template_auth_changed(self, state):
        disabled = state == Qt.Checked
        PDFPasswordManager.set_template_auth_disabled(disabled)
        if self.main_window and hasattr(self.main_window, "say"):
            self.main_window.say(
                self.lang.tr("template_auth_disabled")
                + (
                    " " + self.lang.tr("voice_on")
                    if disabled
                    else " " + self.lang.tr("voice_off")
                )
            )


