class OCRSettingsDialog(QDialog):
    """OCR-Einstellungsdialog mit ausführlichen Erklärungen zu jedem Parameter."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.parent = parent

        # Language-Instanz vom Hauptfenster übernehmen
        if parent and hasattr(parent, "lang"):
            self.lang = parent.lang
        else:

            self.lang = Language()

        self.settings = QSettings("BinhDiez", "PDFDarkView")

        # Aktuelle Einstellungen laden
        self.force_ocr = self.settings.value("ocr_force_ocr", True, type=bool)
        self.deskew = self.settings.value("ocr_deskew", True, type=bool)
        self.clean = self.settings.value("ocr_clean", True, type=bool)
        self.optimize = self.settings.value("ocr_optimize", 1, type=int)
        self.jobs = self.settings.value("ocr_jobs", 4, type=int)
        self.verbose = self.settings.value("ocr_verbose", 1, type=int)
        self.oversample = self.settings.value("ocr_oversample", 300, type=int)
        self.pagesegmode = self.settings.value("ocr_pagesegmode", 6, type=int)
        self.oem = self.settings.value("ocr_oem", 3, type=int)

        self.setWindowTitle(self.parent.tr("ocr_settings_title"))
