    def _add_checkbox_row(self, grid, row, label_key, info_key, checkbox):
        """Fügt eine Zeile mit Checkbox hinzu"""
        label = QLabel(self.parent.tr(label_key))
        label.setStyleSheet("font-size: 14px; font-weight: bold;")
        label.setMinimumWidth(160)
        label.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)

        container = QWidget()
        container_layout = QHBoxLayout(container)
        container_layout.setContentsMargins(0, 0, 0, 0)
        container_layout.addWidget(checkbox)
        container_layout.addStretch()
        checkbox.setMinimumHeight(28)

        info_btn = self._create_info_button(info_key)

        grid.addWidget(label, row, 0, Qt.AlignVCenter)
        grid.addWidget(container, row, 1, Qt.AlignVCenter)
        grid.addWidget(info_btn, row, 2, Qt.AlignRight | Qt.AlignVCenter)

        return row + 1

    def _add_combo_row(self, grid, row, label_key, info_key, combo):
        """Fügt eine Zeile mit ComboBox hinzu"""
        label = QLabel(self.parent.tr(label_key))
        label.setStyleSheet("font-size: 14px; font-weight: bold;")
        label.setMinimumWidth(160)
        label.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)

        container = QWidget()
        container_layout = QHBoxLayout(container)
        container_layout.setContentsMargins(0, 0, 0, 0)
        container_layout.addWidget(combo)
        container_layout.addStretch()
        combo.setMinimumHeight(30)
        combo.setMinimumWidth(240)
        combo.setMaximumWidth(300)

        info_btn = self._create_info_button(info_key)

        grid.addWidget(label, row, 0, Qt.AlignVCenter)
        grid.addWidget(container, row, 1, Qt.AlignVCenter)
        grid.addWidget(info_btn, row, 2, Qt.AlignRight | Qt.AlignVCenter)

        return row + 1

    def _add_slider_row(
        self, grid, row, label_key, info_key, slider, value_label, format_str
    ):
        """Fügt eine Zeile mit Slider hinzu"""
        label = QLabel(self.parent.tr(label_key))
        label.setStyleSheet("font-size: 14px; font-weight: bold;")
        label.setMinimumWidth(160)
        label.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)

        container = QWidget()
        container_layout = QHBoxLayout(container)
        container_layout.setContentsMargins(0, 0, 0, 0)
        container_layout.setSpacing(8)

        slider.setMinimumHeight(28)
        slider.setMinimumWidth(200)

        value_label.setMinimumWidth(60)
        value_label.setStyleSheet("font-size: 13px;")

        container_layout.addWidget(slider)
        container_layout.addWidget(value_label)
        container_layout.addStretch()

        info_btn = self._create_info_button(info_key)

        grid.addWidget(label, row, 0, Qt.AlignVCenter)
        grid.addWidget(container, row, 1, Qt.AlignVCenter)
        grid.addWidget(info_btn, row, 2, Qt.AlignRight | Qt.AlignVCenter)

        return row + 1

    def _create_info_button(self, info_key):
        """Erstellt einen schmalen Info-Button"""
        btn = QPushButton("?")
        btn.setFixedSize(28, 28)
        btn.setToolTip(self.parent.tr("info_tooltip"))
        btn.setStyleSheet("""
            QPushButton {
                background-color: #1565C0;
                color: white;
                border-radius: 14px;
                font-weight: bold;
                font-size: 14px;
            }
            QPushButton:hover {
                background-color: #0d47a1;
            }
        """)
        btn.clicked.connect(lambda: self._show_info_dialog(self.parent.tr(info_key)))
        return btn

    def update_language_display(self):
        """Aktualisiert die Anzeige der aktuellen OCR-Sprache"""
        current_lang = self.settings.value("ocr_language", "deu+eng+vie")

        # Hole die lesbaren Namen für die Anzeige
        display_parts = []
        for code in current_lang.split("+"):
            display_name = self.get_language_display_name(code)
            flag = self.get_language_flag(code)
            display_parts.append(f"{flag} {display_name}")

        # Zeige maximal 3 Sprachen an, sonst mit "..." abkürzen
        if len(display_parts) > 9:
            display_text = (
                " + ".join(display_parts[:9]) + f" + … (+{len(display_parts)-9})"
            )
        else:
            display_text = " + ".join(display_parts)

        self.current_lang_label.setText(display_text)
        self.current_lang_label.setToolTip(
            " + ".join(display_parts)
        )  # Tooltip mit allen Sprachen

