    def load_values(self):
        """Lädt die Metadaten in die Felder."""
        # Titel
        self.title_edit.setText(self.metadata.get("title", ""))

        # Autor
        self.author_edit.setText(self.metadata.get("author", ""))

        # Betreff
        self.subject_edit.setText(self.metadata.get("subject", ""))

        # Stichwörter
        self.keywords_edit.setText(self.metadata.get("keywords", ""))

        # Erzeuger
        self.creator_edit.setText(self.metadata.get("creator", ""))

        # Produzent
        self.producer_edit.setText(self.metadata.get("producer", ""))

        # Erstellungsdatum
        creation_date = self.metadata.get("creationDate", "")
        if creation_date:
            parsed_date = self.parse_pdf_date(creation_date)
            if parsed_date:
                self.creation_date_edit.setDateTime(parsed_date)
            else:
                self.creation_date_edit.setDateTime(QDateTime.currentDateTime())
        else:
            self.creation_date_edit.setDateTime(QDateTime.currentDateTime())

        # Änderungsdatum
        mod_date = self.metadata.get("modDate", "")
        if mod_date:
            parsed_date = self.parse_pdf_date(mod_date)
            if parsed_date:
                self.mod_date_edit.setDateTime(parsed_date)
            else:
                self.mod_date_edit.setDateTime(QDateTime.currentDateTime())
        else:
            self.mod_date_edit.setDateTime(QDateTime.currentDateTime())

    def parse_pdf_date(self, date_string):
        """
        Parst ein PDF-Datum im Format "D:YYYYMMDDHHmmSS" in ein QDateTime.
        """
        if not date_string or not date_string.startswith("D:"):
            return None

        date_str = date_string[2:].strip()

        # Grundformat: YYYYMMDDHHMMSS
        if len(date_str) >= 14:
            year = int(date_str[0:4])
            month = int(date_str[4:6])
            day = int(date_str[6:8])
            hour = int(date_str[8:10])
            minute = int(date_str[10:12])
            second = int(date_str[12:14])

            return QDateTime(QDate(year, month, day), QTime(hour, minute, second))

        return None

    def format_pdf_date(self, date_time):
        """
        Formatiert ein QDateTime in das PDF-Datum-Format "D:YYYYMMDDHHMMSS".
        """
        return date_time.toString("'D:'yyyyMMddHHmmss")

    def update_pdf_info(self):
        """Aktualisiert die PDF-Informationen (Seitenzahl, Größe, etc.)."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            return

        # Dateigröße
        file_size = os.path.getsize(self.pdf_path)
        if file_size < 1024:
            size_str = f"{file_size} Bytes"
        elif file_size < 1024 * 1024:
            size_str = f"{file_size / 1024:.1f} KB"
        else:
            size_str = f"{file_size / (1024 * 1024):.1f} MB"
        self.size_value.setText(size_str)

        if self.current_doc:
            # Seitenzahl
            self.pages_value.setText(str(self.current_doc.page_count))

            # PDF-Version - Korrekte Methode für PyMuPDF
            try:
                # Version aus den Metadaten oder direkt aus dem Dokument
                if (
                    hasattr(self.current_doc, "metadata")
                    and "format" in self.current_doc.metadata
                ):
                    pdf_version = self.current_doc.metadata.get("format", "Unknown")
                elif hasattr(self.current_doc, "pdf_version"):
                    pdf_version = self.current_doc.pdf_version
                else:
                    # Alternative: Versuche die Version aus der Datei zu lesen
                    import struct

                    with open(self.pdf_path, "rb") as f:
                        header = f.read(8)
                        if header.startswith(b"%PDF-"):
                            version_str = header[5:8].decode("ascii", errors="ignore")
                            pdf_version = f"PDF {version_str}"
                        else:
                            pdf_version = "PDF (unbekannt)"
            except Exception as e:
                print(f"Fehler beim Lesen der PDF-Version: {e}")
                pdf_version = "PDF (unbekannt)"

            self.version_value.setText(pdf_version)

            # Verschlüsselungsstatus
            if self.current_doc.is_encrypted:
                self.encrypted_value.setText(self.parent.tr("metadata_encrypted_yes"))
            else:
                self.encrypted_value.setText(self.parent.tr("metadata_encrypted_no"))

    def reload_from_pdf(self):
        """Lädt die Metadaten neu aus der PDF (verwirft Änderungen)."""
        # Dokument neu öffnen
        if self.current_doc:
            self.current_doc.close()

        self.load_metadata_from_pdf()
        self.load_values()
        self.update_pdf_info()

        self.parent.say(self.parent.tr("metadata_reloaded"))

    def reset_to_defaults(self):
        """Setzt alle Metadaten-Felder auf leere Werte zurück."""
        self.title_edit.clear()
        self.author_edit.clear()
        self.subject_edit.clear()
        self.keywords_edit.clear()
        self.creator_edit.clear()
        self.producer_edit.clear()
        self.creation_date_edit.setDateTime(QDateTime.currentDateTime())
        self.mod_date_edit.setDateTime(QDateTime.currentDateTime())

        self.parent.say(self.parent.tr("metadata_reset_done"))

    def save_metadata(self):
        """Speichert die bearbeiteten Metadaten in der PDF."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            QMessageBox.warning(
                self, self.parent.tr("error"), self.parent.tr("metadata_no_file")
            )
            return

        try:
            # Backup erstellen (wenn aktiviert)
            if hasattr(self.parent, "create_backup") and self.parent.create_backup:
                self.parent.create_backup_if_enabled(self.pdf_path)

            # Dokument schließen, falls noch offen
            if self.current_doc:
                self.current_doc.close()
                self.current_doc = None

            # Dokument neu öffnen
            doc = fitz.open(self.pdf_path)

            # Metadaten aktualisieren
            metadata = {}

            if self.title_edit.text().strip():
                metadata["title"] = self.title_edit.text().strip()

            if self.author_edit.text().strip():
                metadata["author"] = self.author_edit.text().strip()

            if self.subject_edit.text().strip():
                metadata["subject"] = self.subject_edit.text().strip()

            if self.keywords_edit.text().strip():
                metadata["keywords"] = self.keywords_edit.text().strip()

            if self.creator_edit.text().strip():
                metadata["creator"] = self.creator_edit.text().strip()

            if self.producer_edit.text().strip():
                metadata["producer"] = self.producer_edit.text().strip()

            # Datumsfelder
            metadata["creationDate"] = self.format_pdf_date(
                self.creation_date_edit.dateTime()
            )
            metadata["modDate"] = self.format_pdf_date(self.mod_date_edit.dateTime())

            # Metadaten setzen
            doc.set_metadata(metadata)

            # In temporäre Datei speichern, dann ersetzen
            import tempfile
            import shutil

            fd, temp_path = tempfile.mkstemp(suffix=".pdf", prefix="metadata_")
            os.close(fd)

            doc.save(temp_path, garbage=4, deflate=True)
            doc.close()

            shutil.move(temp_path, self.pdf_path)

            # Dokument neu öffnen für die Anzeige
            self.current_doc = fitz.open(self.pdf_path)
            self.metadata = self.current_doc.metadata or {}

            # Erfolgsmeldung
            self.parent.say(self.parent.tr("metadata_saved"))
            self.accept()

            dialog = myUniversalDialog(
                self,
                title=self.parent.tr("success"),
                message=self.parent.tr("metadata_saved"),
                icon_type="",
            )
            dialog.exec_()
            return

        except Exception as e:
            QMessageBox.critical(
                self,
                self.parent.tr("error"),
                f"{self.parent.tr('metadata_save_error')}: {str(e)}",
            )

    def closeEvent(self, event):
        """Schließt das Dokument beim Schließen des Dialogs."""
        if self.current_doc:
            self.current_doc.close()
        event.accept()


