    def get_pdf_bookmark_key(self):
        """Erstellt einen eindeutigen Schlüssel für die PDF-Lesezeichen."""
        if not self.pdf_path:
            return None

        norm_path = os.path.normpath(self.pdf_path)
        import hashlib

        path_hash = hashlib.md5(norm_path.encode("utf-8")).hexdigest()[:16]
        return f"bookmarks_{path_hash}"

    def load_bookmarks(self):
        """Lädt die Lesezeichen für die aktuelle PDF aus den Einstellungen."""
        bookmark_key = self.get_pdf_bookmark_key()
        if not bookmark_key:
            return []

        bookmarks_json = self.settings.value(bookmark_key, "[]")

        try:
            bookmarks = json.loads(bookmarks_json)
            bookmarks.sort(key=lambda x: x.get("page", 0))
            return bookmarks
        except:
            return []

    def save_bookmarks(self):
        """Speichert die Lesezeichen in den Einstellungen."""
        bookmark_key = self.get_pdf_bookmark_key()
        if not bookmark_key:
            return

        bookmarks_json = json.dumps(self.bookmarks)
        self.settings.setValue(bookmark_key, bookmarks_json)
        self.settings.sync()

    def focus_search(self):
        """Fokussiert das Suchfeld."""
        self.search_input.setFocus()
        self.search_input.selectAll()

    def clear_search(self):
        """Löscht die Suche und zeigt alle Lesezeichen an."""
        self.search_input.clear()
        self.clear_search_btn.setVisible(False)
        self.search_result_label.setVisible(False)
        self.load_bookmarks_list()
        self.bookmarks_list.setFocus()  # Fokus zurück auf die Liste

    def clear_search_and_focus(self):
        """Löscht die Suche und fokussiert die Liste."""
        if self.search_input.text():
            self.clear_search()
        else:
            self.bookmarks_list.setFocus()

    def filter_bookmarks(self, search_text):
        """Filtert die Lesezeichen basierend auf dem Suchtext."""
        search_text = search_text.strip()

        if not search_text:
            self.clear_search()
            return

        self.clear_search_btn.setVisible(True)

        # Alle aktuellen Items ausblenden/entfernen
        self.bookmarks_list.clear()

        # Nach Übereinstimmungen suchen
        matches = []
        search_lower = search_text.lower()

        for i, bookmark in enumerate(self.bookmarks):
            name = bookmark.get("name", "").lower()
            page_num = bookmark.get("page", 0) + 1

            # Suche im Namen und in der Seitennummer
            if search_lower in name or str(page_num) == search_text:
                matches.append((i, bookmark))

        # Gefilterte Liste anzeigen
        if matches:
            for i, bookmark in matches:
                page_num = bookmark.get("page", 0) + 1
                name = bookmark.get(
                    "name", self.parent.tr("bookmark_name_default", page_num)
                )

                # Name für die Anzeige kürzen (max. 50 Zeichen)
                display_name = self.truncate_text(name, 50)
                # Hier funktioniert kein qta Icon deshalb UTF-8 🔖
                display_text = f"🔖 {self.parent.tr('bookmark_page_display', page_num)}: {display_name}"

                item = QListWidgetItem(display_text)
                item.setData(Qt.UserRole, i)
                item.setToolTip(self.parent.tr("bookmark_item_tooltip", name, page_num))
                self.bookmarks_list.addItem(item)

            # Suchergebnis-Info anzeigen
            self.search_result_label.setText(
                self.parent.tr("bookmark_search_results", len(matches), search_text)
            )
            self.search_result_label.setVisible(False)  # True um es anzuzeigen

            # Buttons aktivieren/deaktivieren basierend auf gefilterter Liste
            has_items = len(matches) > 0
            self.edit_btn.setEnabled(has_items)
            self.remove_btn.setEnabled(has_items)
            self.jump_btn.setEnabled(has_items)
            self.remove_all_btn.setEnabled(len(self.bookmarks) > 0)

            # Erstes Suchergebnis automatisch auswählen für Tabulator-Navigation
            if self.bookmarks_list.count() > 0:
                self.bookmarks_list.setCurrentRow(0)
        else:
            # Keine Ergebnisse
            no_results_item = QListWidgetItem(
                self.parent.tr("bookmark_no_search_results", search_text)
            )
            no_results_item.setFlags(Qt.NoItemFlags)
            no_results_item.setTextAlignment(Qt.AlignCenter)
            self.bookmarks_list.addItem(no_results_item)

            self.search_result_label.setText(
                self.parent.tr("bookmark_no_search_results_label", search_text)
            )
            self.search_result_label.setVisible(False)  # True um es anzuzeigen

            self.edit_btn.setEnabled(False)
            self.remove_btn.setEnabled(False)
            self.jump_btn.setEnabled(False)

    def load_bookmarks_list(self):
        """Füllt die Liste mit den Lesezeichen (Original, ohne Filter)."""
        self.bookmarks_list.clear()
        self.clear_search_btn.setVisible(False)
        self.search_result_label.setVisible(False)
        self.search_input.clear()

        if not self.bookmarks:
            placeholder = QListWidgetItem(self.parent.tr("bookmark_no_bookmarks"))
            placeholder.setFlags(Qt.NoItemFlags)
            placeholder.setTextAlignment(Qt.AlignCenter)
            self.bookmarks_list.addItem(placeholder)
            self.edit_btn.setEnabled(False)
            self.remove_btn.setEnabled(False)
            self.remove_all_btn.setEnabled(False)
            self.jump_btn.setEnabled(False)
            return

        self.edit_btn.setEnabled(True)
        self.remove_btn.setEnabled(True)
        self.remove_all_btn.setEnabled(True)
        self.jump_btn.setEnabled(True)

        for i, bookmark in enumerate(self.bookmarks):
            page_num = bookmark.get("page", 0) + 1
            name = bookmark.get(
                "name", self.parent.tr("bookmark_name_default", page_num)
            )

            # Name für die Anzeige kürzen (max. 50 Zeichen)
            display_name = self.truncate_text(name, 50)

            # Formatierte Anzeige
            # Hier funktioniert kein qta Icon deshalb UTF-8 🔖
            display_text = f"🔖 {self.parent.tr('bookmark_page_display', page_num)}: {display_name}"

            item = QListWidgetItem(display_text)
            item.setData(Qt.UserRole, i)
            # Im Tooltip den vollständigen Namen anzeigen
            item.setToolTip(self.parent.tr("bookmark_item_tooltip", name, page_num))
            self.bookmarks_list.addItem(item)

        # Nach dem Laden das erste Item auswählen für bessere Tabulator-Navigation
        if self.bookmarks_list.count() > 0:
            self.bookmarks_list.setCurrentRow(0)

    def get_current_bookmark_index(self):
        """Gibt den Index des aktuell ausgewählten Lesezeichens zurück (im gefilterten Zustand)."""
        current_item = self.bookmarks_list.currentItem()
        if not current_item:
            return None

        index = current_item.data(Qt.UserRole)
        if index is None or index >= len(self.bookmarks):
            return None

        return index

    def rename_bookmark(self):
        """Benennt ein Lesezeichen um."""
        index = self.get_current_bookmark_index()
        if index is None:
            dialog = myUniversalDialog(
                self,
                title=self.parent.tr("info"),
                message=self.parent.tr("bookmark_select_first"),
                buttons=[(self.parent.tr("btn_ok"), "primary", "ok")],
                icon_type="",
            )
            dialog.exec_()
            return

        bookmark = self.bookmarks[index]
        old_name = bookmark.get("name", "")
        page_num = bookmark.get("page", 0) + 1

        dialog = myUniversalDialog(
            self,
            title=self.parent.tr("bookmark_rename_title"),
            message=self.parent.tr("bookmark_rename_prompt", page_num),
            text_alignment=Qt.AlignLeft,
            buttons=[
                (self.parent.tr("btn_ok"), "primary", "ok"),
                (self.parent.tr("btn_cancel"), "dark", "cancel"),
            ],
            icon_type="",
            default_button="ok",
            input_fields=[
                {
                    "type": "text",
                    "name": "bookmark_name",
                    "label": "",
                    "default": old_name,
                    "placeholder": self.parent.tr("bookmark_rename_prompt", page_num),
                    "max_length": 10,
                }  # Maximale Eingabelänge
            ],
        )

        if dialog.exec_() != QDialog.Accepted:
            return

        new_name = dialog.get_input_value("bookmark_name")
        if not new_name or not new_name.strip():
            return

        # Name auf max. 50 Zeichen begrenzen
        new_name = new_name.strip()[:50]

        for i, b in enumerate(self.bookmarks):
            if (
                i != index
                and b.get("name") == new_name
                and b.get("page") == bookmark.get("page")
            ):
                confirm_dialog = myUniversalDialog(
                    self,
                    title=self.parent.tr("confirm"),
                    message=self.parent.tr("bookmark_name_exists_question", new_name),
                    buttons=[
                        (self.parent.tr("btn_yes"), "success", "yes"),
                        (self.parent.tr("btn_no"), "danger", "no"),
                    ],
                    icon_type="",
                    default_button="no",
                )
                result = confirm_dialog.exec_()
                if result != QDialog.Accepted or confirm_dialog.result_value != "yes":
                    return
                break

        self.bookmarks[index]["name"] = new_name
        self.save_bookmarks()
        self.load_bookmarks_list()

        for i in range(self.bookmarks_list.count()):
            item = self.bookmarks_list.item(i)
            if item.data(Qt.UserRole) == index:
                self.bookmarks_list.setCurrentItem(item)
                break

        self.parent.say(self.parent.tr("bookmark_renamed", old_name, new_name))

    def add_bookmark(self):
        """Fügt ein Lesezeichen mit der letzten Mausklick-Position hinzu."""
        if not self.parent or not hasattr(self.parent, "current_page"):
            return

        current_page = self.parent.current_page
        page_display = current_page + 1

        # Verwende vorhandene Methode, um die Position zu bekommen
        local_pos, target_page = self.parent._get_insertion_position()

        # Falls keine gültige Position gefunden wurde, verwende Seitenmitte
        if local_pos is None:
            # Fallback: Seitenmitte
            if hasattr(self.parent, "page_items") and current_page < len(
                self.parent.page_items
            ):
                page_item = self.parent.page_items[current_page]
                page_rect = page_item.boundingRect()
                local_pos = QPointF(page_rect.width() / 2, page_rect.height() / 2)
                target_page = current_page
                print(
                    f"DEBUG: Fallback zur Seitenmitte: ({local_pos.x():.1f}, {local_pos.y():.1f})"
                )
        else:
            print(
                f"DEBUG: Verwende Mausklick-Position: Seite {target_page + 1}, Lokale Position: ({local_pos.x():.1f}, {local_pos.y():.1f})"
            )

        default_name = self.parent.tr("bookmark_name_default", page_display)
        # Standardname auch kürzen
        default_name = self.truncate_text(default_name, 40)

        dialog = myUniversalDialog(
            self,
            title=self.parent.tr("bookmark_name_prompt_title"),
            message=self.parent.tr("bookmark_name_prompt"),
            text_alignment=Qt.AlignLeft,
            buttons=[
                (self.parent.tr("btn_ok"), "primary", "ok"),
                (self.parent.tr("btn_cancel"), "danger", "cancel"),
            ],
            icon_type="",
            default_button="ok",
            input_fields=[
                {
                    "type": "text",
                    "name": "bookmark_name",
                    "label": "",
                    "default": default_name,
                    "placeholder": self.parent.tr("bookmark_name_prompt"),
                    "max_length": 50,
                }  # Maximale Eingabelänge
            ],
        )

        if dialog.exec_() != QDialog.Accepted:
            return

        name = dialog.get_input_value("bookmark_name")
        if not name or not name.strip():
            name = default_name

        # Name auf max. 50 Zeichen begrenzen
        name = name.strip()[:50]

        # Prüfen ob Lesezeichen bereits existiert
        for bookmark in self.bookmarks:
            if bookmark.get("page") == target_page and bookmark.get("name") == name:
                info_dialog = myUniversalDialog(
                    self,
                    title=self.parent.tr("info"),
                    message=self.parent.tr("bookmark_exists"),
                    buttons=[(self.parent.tr("btn_ok"), "primary", "ok")],
                    icon_type="",
                )
                info_dialog.exec_()
                return

        # Lesezeichen mit lokaler Position speichern
        new_bookmark = {
            "page": target_page,
            "name": name,
            "local_pos_x": local_pos.x() if local_pos else 0,
            "local_pos_y": local_pos.y() if local_pos else 0,
            "created": QDateTime.currentDateTime().toString(Qt.ISODate),
        }

        print(
            f"DEBUG: Gespeicherte lokale Position: ({new_bookmark['local_pos_x']:.1f}, {new_bookmark['local_pos_y']:.1f}) auf Seite {target_page + 1}"
        )

        self.bookmarks.append(new_bookmark)
        self.bookmarks.sort(key=lambda x: x.get("page", 0))
        self.save_bookmarks()
        self.load_bookmarks_list()

        # Gefügtes Lesezeichen auswählen
        for i in range(self.bookmarks_list.count()):
            item = self.bookmarks_list.item(i)
            if item.data(Qt.UserRole) == len(self.bookmarks) - 1:
                self.bookmarks_list.setCurrentItem(item)
                break

        self.parent.say(self.parent.tr("bookmark_added", page_display, name))

    def truncate_text(self, text, max_length=30):
        """Kürzt einen Text auf die maximale Länge und fügt '...' hinzu."""
        if len(text) <= max_length:
            return text
        return text[: max_length - 3] + "..."

    def jump_to_bookmark(self):
        """Springt zum ausgewählten Lesezeichen mit gespeicherter Position."""
        index = self.get_current_bookmark_index()
        if index is None:
            return

        # Wenn in Zoom-Modus: Erst zurück zur Standardansicht
        if self.parent.zoom_mode != "page":
            self.parent.set_zoom_mode("page")

        bookmark = self.bookmarks[index]
        page = bookmark.get("page", 0)
        name = bookmark.get("name", "")
        local_pos_x = bookmark.get("local_pos_x", 0)
        local_pos_y = bookmark.get("local_pos_y", 0)

        print(f"\n=== SPRINGE ZU LESEZEICHEN ===")
        print(f"Seite: {page + 1}, Name: {name}")
        print(f"Lokale Position: ({local_pos_x:.1f}, {local_pos_y:.1f})")

        # Prüfen ob eine gültige Position gespeichert ist
        has_valid_position = local_pos_x != 0 or local_pos_y != 0

        # Zur Seite springen
        self.parent.go_to_page(page + 1)

        if (
            has_valid_position
            and hasattr(self.parent, "page_items")
            and page < len(self.parent.page_items)
        ):
            # Warten bis die Seite geladen ist, dann zur Position scrollen
            QTimer.singleShot(
                300,
                lambda: self._scroll_to_local_position(
                    page, QPointF(local_pos_x, local_pos_y)
                ),
            )

        self.parent.say(self.parent.tr("bookmark_jumped_to", name, page + 1))

    def _scroll_to_local_position(self, page, local_pos):
        """Scrollt zu einer lokalen Position auf einer Seite (mit Offset für Seitenbreite)."""
        try:
            if not hasattr(self.parent, "page_items") or page >= len(
                self.parent.page_items
            ):
                # print(f"DEBUG: Seite {page + 1} nicht verfügbar")
                return

            page_item = self.parent.page_items[page]

            # Lokale Position in Scene-Position umwandeln
            scene_pos = page_item.mapToScene(local_pos)

            # OFFSET für Seitenbreite-Darstellung
            viewport_height = self.parent.graphics_view.viewport().height()
            offset_y = (
                viewport_height * 0.45
            )  # 45% Offset (bringt das Lesezeichen an den oberen Bildschirmrand)

            # Scene-Position mit Offset (nach unten verschieben)
            scene_pos_with_offset = QPointF(scene_pos.x(), scene_pos.y() + offset_y)

            # print(f"DEBUG: Ursprüngliche Scene-Position: ({scene_pos.x():.1f}, {scene_pos.y():.1f})")
            # print(f"DEBUG: Viewport-Höhe: {viewport_height}, Offset: {offset_y:.1f}")
            # print(f"DEBUG: Angepasste Scene-Position: ({scene_pos_with_offset.x():.1f}, {scene_pos_with_offset.y():.1f})")

            # Ihre vorhandene Scroll-Methode mit der angepassten Position verwenden
            if hasattr(self.parent, "_scroll_to_position"):
                self.parent._scroll_to_position(scene_pos_with_offset)
            else:
                # Fallback: centerOn verwenden
                self.parent.graphics_view.centerOn(scene_pos_with_offset)

            # print(f"DEBUG: Zur Position mit Offset gescrollt")

        except Exception as e:
            print(f"DEBUG: Fehler beim Scrollen: {e}")

    def migrate_old_bookmarks(self):
        """Migriert alte Lesezeichen ohne lokale Position."""
        migrated = 0
        for bookmark in self.bookmarks:
            if "local_pos_x" not in bookmark:
                # Setze Standardposition: Seitenmitte
                bookmark["local_pos_x"] = 0
                bookmark["local_pos_y"] = 0
                migrated += 1

        if migrated > 0:
            self.save_bookmarks()
            print(f"DEBUG: {migrated} Lesezeichen wurden migriert")

    def remove_bookmark(self):
        """Entfernt das ausgewählte Lesezeichen."""
        index = self.get_current_bookmark_index()
        if index is None:
            dialog = myUniversalDialog(
                self,
                title=self.parent.tr("info"),
                message=self.parent.tr("bookmark_select_first"),
                buttons=[(self.parent.tr("btn_ok"), "primary", "ok")],
                icon_type="",
            )
            dialog.exec_()
            return

        bookmark = self.bookmarks[index]
        page_display = bookmark.get("page", 0) + 1
        name = bookmark.get("name", "")

        confirm_dialog = myUniversalDialog(
            self,
            title=self.parent.tr("confirm"),
            message=self.parent.tr("bookmark_confirm_remove", page_display, name),
            buttons=[
                (self.parent.tr("btn_yes"), "danger", "yes"),
                (self.parent.tr("btn_no"), "primary", "no"),
            ],
            icon_type="",
            default_button="no",
        )

        result = confirm_dialog.exec_()
        if result == QDialog.Accepted and confirm_dialog.result_value == "yes":
            del self.bookmarks[index]
            self.save_bookmarks()
            self.load_bookmarks_list()
            self.parent.say(self.parent.tr("bookmark_removed", name))
            self.parent.update_bookmark_menu()

    def remove_all_bookmarks(self):
        """Entfernt alle Lesezeichen."""
        if not self.bookmarks:
            return

        confirm_dialog = myUniversalDialog(
            self,
            title=self.parent.tr("confirm"),
            message=self.parent.tr("bookmark_confirm_remove_all", len(self.bookmarks)),
            buttons=[
                (self.parent.tr("btn_yes"), "danger", "yes"),
                (self.parent.tr("btn_no"), "primary", "no"),
            ],
            icon_type="",
            default_button="no",
        )

        result = confirm_dialog.exec_()
        if result == QDialog.Accepted and confirm_dialog.result_value == "yes":
            self.bookmarks = []
            self.save_bookmarks()
            self.load_bookmarks_list()
            self.parent.say(self.parent.tr("bookmark_all_removed"))
            self.parent.update_bookmark_menu()

    def handle_escape(self):
        """Behandelt Escape-Taste: Erst Suche löschen, dann Dialog schließen."""
        if self.search_input.text():
            # Erster Escape: Suche löschen
            self.clear_search()
            self.search_input.clear()
            self.bookmarks_list.setFocus()
        else:
            # Zweiter Escape: Dialog schließen
            self.reject()

    def keyPressEvent(self, event):
        """Ermöglicht Navigation mit Pfeiltasten in der gefilterten Liste."""
        if event.key() == Qt.Key_Down and self.bookmarks_list.hasFocus():
            current_row = self.bookmarks_list.currentRow()
            if current_row < self.bookmarks_list.count() - 1:
                self.bookmarks_list.setCurrentRow(current_row + 1)
        elif event.key() == Qt.Key_Up and self.bookmarks_list.hasFocus():
            current_row = self.bookmarks_list.currentRow()
            if current_row > 0:
                self.bookmarks_list.setCurrentRow(current_row - 1)
        elif event.key() == Qt.Key_Return or event.key() == Qt.Key_Enter:
            if self.bookmarks_list.hasFocus() and self.bookmarks_list.currentItem():
                self.jump_to_bookmark()
        else:
            super().keyPressEvent(event)

    def show_context_menu(self, position):
        """Zeigt das Kontextmenü für ein Lesezeichen an."""
        item = self.bookmarks_list.itemAt(position)
        if not item:
            return

        index = item.data(Qt.UserRole)
        if index is None or index >= len(self.bookmarks):
            return

        bookmark = self.bookmarks[index]
        page_num = bookmark.get("page", 0) + 1
        name = bookmark.get("name", "")

        # Kontextmenü erstellen
        context_menu = QMenu(self)

        # Zum Lesezeichen gehen
        goto_action = QAction(
            qta.icon("fa5s.location-arrow"), self.parent.tr("bookmark_jump"), self
        )
        goto_action.triggered.connect(self.jump_to_bookmark)
        context_menu.addAction(goto_action)

        context_menu.addSeparator()

        # Umbenennen
        rename_action = QAction(
            qta.icon("fa5s.edit"), self.parent.tr("bookmark_rename"), self
        )
        rename_action.triggered.connect(self.rename_bookmark)
        context_menu.addAction(rename_action)

        context_menu.addSeparator()

        # Löschen
        delete_action = QAction(
            qta.icon("fa5s.trash", color="red"), self.parent.tr("bookmark_remove"), self
        )
        delete_action.triggered.connect(self.remove_bookmark)
        context_menu.addAction(delete_action)

        # Alle löschen (nur wenn mehrere vorhanden)
        if len(self.bookmarks) > 1:
            context_menu.addSeparator()
            delete_all_action = QAction(
                qta.icon("fa5s.trash-alt", color="red"),
                self.parent.tr("bookmark_remove_all"),
                self,
            )
            delete_all_action.triggered.connect(self.remove_all_bookmarks)
            context_menu.addAction(delete_all_action)

        # Kontextmenü anzeigen
        context_menu.exec_(self.bookmarks_list.viewport().mapToGlobal(position))


