        header_layout.addStretch(1)
        main_layout.addWidget(header)

        # Optionen Gruppe
        self.option_group = QGroupBox(self.lang.tr("pages_delete_options"))
        self.option_group.setStyleSheet("""
            QGroupBox {
                font-size: 14px;
                font-weight: bold;
            }
            QGroupBox::title {
                subcontrol-origin: margin;
                left: 10px;
                padding: 0 5px 0 5px;
            }
        """)
