class ExtractPagesDialog(QDialog):
    """Dialog zum Aufteilen und Extrahieren von PDF-Seiten (barrierefrei)."""

    def __init__(self, parent=None, input_path=None):
        super().__init__(parent)
        self.parent = parent
        self.input_path = input_path

        # Language-Instanz vom Hauptfenster übernehmen
        if parent and hasattr(parent, "lang"):
            self.lang = parent.lang
        else:

            self.lang = Language()

        # Falls ein PDF-Pfad übergeben wurde, diesen verwenden
        if not self.input_path and parent and hasattr(parent, "pdf_path"):
            self.input_path = parent.pdf_path

        self.total_pages = 0
        self.init_ui()
        if self.input_path and os.path.exists(self.input_path):
            self.check_pdf_pages()
            self.btn_split.setEnabled(True)

        # Dark Mode vom Hauptfenster übernehmen
        if parent and hasattr(parent, "dark_mode"):
            self.dark_mode = parent.dark_mode
        else:
            self.dark_mode = True
        self.apply_styles()

    def init_ui(self):
        """Erstellt die Benutzeroberfläche des Splitter-Dialogs mit großer Schrift und Vorschau."""
