        base_font.setPointSize(14)
        self.setFont(base_font)

        # Hauptlayout mit Abständen
        main_layout = QVBoxLayout()
        main_layout.setSpacing(20)  # Abstand zwischen den Elementen
        main_layout.setContentsMargins(25, 25, 25, 25)

