### Seiten einfügen
### -------------------------------------------------


class InsertPagesDialog(QDialog):
    def __init__(self, total_pages, parent=None):
        super().__init__(parent)
        self.parent = parent
        self.total_pages = total_pages
        self.pdf_to_insert = None

        # Language-Instanz vom Hauptfenster übernehmen
        if parent and hasattr(parent, "lang"):
            self.lang = parent.lang
        else:

            self.lang = Language()

        self.init_ui()
        self.setup_keyboard_navigation()

    def init_ui(self):
        self.setWindowTitle(
            "PDFDarkView by BinhDiez - " + self.lang.tr("pages_insert")
        )  # Original: "Seiten einfügen"
        self.setMinimumWidth(450)
        self.setMinimumHeight(450)

        # Hauptlayout
        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(10, 5, 10, 10)
        self.setLayout(main_layout)

        # Kopfzeile (wie in anderen Dialogen)
        header = QWidget()
        header_layout = QHBoxLayout(header)
        header_layout.setContentsMargins(0, 0, 0, 15)
        header_layout.setSpacing(10)

        # linker Stretch → zieht alles zur Mitte
        header_layout.addStretch(1)

        if os.path.exists(Config.IMAGE_PATH):
            self.logo_label = QLabel()
            logo_pixmap = QPixmap(Config.IMAGE_PATH).scaled(
                80, 80, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            self.logo_label.setPixmap(logo_pixmap)
            self.logo_label.setAlignment(Qt.AlignVCenter)
            header_layout.addWidget(self.logo_label)

            header_layout.addStretch(1)

        self.title_label = QLabel(
            self.lang.tr("pages_insert")
        )  # Original: "Seiten einfügen"
        self.title_label.setStyleSheet("""
            QLabel {
                color: white;
                font-size: 20px;
                font-weight: bold;
                padding: 5px;
            }
        """)
        self.title_label.setAlignment(Qt.AlignCenter)
        header_layout.addWidget(self.title_label)
        header_layout.addStretch(1)

        if os.path.exists(Config.APP_ICON_PATH):
            self.icon_label = QLabel()
            icon_pixmap = QPixmap(Config.APP_ICON_PATH).scaled(
                50, 50, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            self.icon_label.setPixmap(icon_pixmap)
            self.icon_label.setAlignment(Qt.AlignVCenter)
            header_layout.addWidget(self.icon_label)

        # rechter Stretch → hält die Gruppe zentriert
        header_layout.addStretch(1)

        main_layout.addWidget(header)

        # Eingabegruppe
        input_group = QGroupBox(
            self.lang.tr("pages_insert_position")
        )  # Original: "Einfügeposition und PDF-Auswahl"
        input_group.setStyleSheet("""
            QGroupBox {
                font-size: 14px;
                font-weight: bold;
            }
            QGroupBox::title {
                subcontrol-origin: margin;
                left: 10px;
                padding: 0 5px 0 5px;
            }
        """)
        input_layout = QVBoxLayout()

        # Positionseingabe
        pos_layout = QHBoxLayout()
        pos_label = QLabel(
            self.lang.tr("pages_insert_before") + ":"
        )  # Original: "Einfügen vor Seite:"
        pos_label.setStyleSheet("font-size: 14px;")
        pos_layout.addWidget(pos_label)

        self.position_spin = QSpinBox()
        self.position_spin.setRange(1, self.total_pages + 1)
        self.position_spin.setValue(1)
        self.position_spin.setFocusPolicy(Qt.StrongFocus)
        self.position_spin.setStyleSheet("font-size: 14px;")

        pos_layout.addWidget(self.position_spin)

        input_layout.addLayout(pos_layout)

        # PDF-Auswahl
        self.pdf_label = QLabel(
            self.lang.tr("pages_insert_none")
        )  # Original: "Keine PDF ausgewählt"
        self.pdf_label.setStyleSheet(
            "color: #AAAAAA; font-style: italic; font-size: 14px;"
        )

        select_label = QLabel(
            self.lang.tr("pages_insert_select") + ":"
        )  # Original: "Aus PDF:"
        select_label.setStyleSheet("font-size: 14px;")
        input_layout.addWidget(select_label)
        input_layout.addWidget(self.pdf_label)

        input_group.setLayout(input_layout)
        main_layout.addWidget(input_group)

        # Buttons
        button_box = QHBoxLayout()

        # Original: "PDF auswählen"
        self.btn_choose = QPushButton(self.lang.tr("pages_insert_select"))
        self.parent.style_button(self.btn_choose, "primary", (160, 25))
        self.btn_choose.clicked.connect(self.choose_pdf)
        self.btn_choose.setFocusPolicy(Qt.StrongFocus)
        input_layout.addWidget(self.btn_choose)

        self.btn_cancel = QPushButton(
            self.lang.tr("btn_cancel")
        )  # Original: "Abbrechen"
        self.parent.style_button(self.btn_cancel, "danger", (160, 25))
        self.btn_cancel.clicked.connect(self.reject)
        self.btn_cancel.setFocusPolicy(Qt.StrongFocus)

        self.btn_ok = QPushButton(
            self.lang.tr("pages_insert")
        )  # Original: "Seiten einfügen"
        self.parent.style_button(self.btn_ok, "primary", (160, 25))
        self.btn_ok.clicked.connect(self.validate)
        self.btn_ok.setFocusPolicy(Qt.StrongFocus)

        button_box.addWidget(self.btn_choose)
        button_box.addWidget(self.btn_cancel)
        button_box.addWidget(self.btn_ok)
        main_layout.addLayout(button_box)

    def setup_keyboard_navigation(self):
        """Richtet Tastatursteuerung ein"""
        # ✅ ESC schließt den Dialog
        self.escape_shortcut = QShortcut(QKeySequence("Esc"), self)
        self.escape_shortcut.activated.connect(self.reject)

        # ✅ Tab-Reihenfolge festlegen (zyklisch)
        self.setTabOrder(self.position_spin, self.btn_choose)
        self.setTabOrder(self.btn_choose, self.btn_cancel)
        self.setTabOrder(self.btn_cancel, self.btn_ok)
        self.setTabOrder(self.btn_ok, self.position_spin)  # Zyklisch

        # ✅ Fokus-Style für alle Buttons
        for btn in [self.btn_choose, self.btn_cancel, self.btn_ok]:
            current_style = btn.styleSheet()
            if "QPushButton:focus" not in current_style:
                focus_style = """
                    QPushButton:focus {
                        border: 2px solid white !important;
                        border-radius: 8px !important;
                    }
                """
                btn.setStyleSheet(current_style + focus_style)

    def keyPressEvent(self, event):
        """Tastaturnavigation"""
        # ✅ Pfeiltasten für horizontale Navigation zwischen Buttons
        if event.key() == Qt.Key_Left:
            current = self.focusWidget()
            if current == self.btn_ok:
                self.btn_cancel.setFocus()
                event.accept()
                return
            elif current == self.btn_cancel:
                self.btn_choose.setFocus()
                event.accept()
                return
            elif current == self.btn_choose:
                self.btn_ok.setFocus()  # Zyklisch
                event.accept()
                return

        elif event.key() == Qt.Key_Right:
            current = self.focusWidget()
            if current == self.btn_choose:
                self.btn_cancel.setFocus()
                event.accept()
                return
            elif current == self.btn_cancel:
                self.btn_ok.setFocus()
                event.accept()
                return
            elif current == self.btn_ok:
                self.btn_choose.setFocus()  # Zyklisch
                event.accept()
                return

        # ✅ Tab-Taste (vorwärts)
        elif event.key() == Qt.Key_Tab:
            current = self.focusWidget()
            widget_order = [
                self.position_spin,
                self.btn_choose,
                self.btn_cancel,
                self.btn_ok,
            ]

            try:
                index = widget_order.index(current)
                next_index = (index + 1) % len(widget_order)
                widget_order[next_index].setFocus()
                event.accept()
                return
            except (ValueError, AttributeError):
                pass

        # ✅ Shift+Tab (rückwärts)
        elif event.key() == Qt.Key_Backtab:
            current = self.focusWidget()
            widget_order = [
                self.position_spin,
                self.btn_choose,
                self.btn_cancel,
                self.btn_ok,
            ]

            try:
                index = widget_order.index(current)
                prev_index = (index - 1) % len(widget_order)
                widget_order[prev_index].setFocus()
                event.accept()
                return
            except (ValueError, AttributeError):
                pass

        # ✅ Enter aktiviert fokussierten Button
        elif event.key() in (Qt.Key_Return, Qt.Key_Enter):
            current = self.focusWidget()
            if current == self.btn_ok:
                self.btn_ok.click()
                event.accept()
                return
            elif current == self.btn_cancel:
                self.btn_cancel.click()
                event.accept()
                return
            elif current == self.btn_choose:
                self.btn_choose.click()
                event.accept()
                return

        super().keyPressEvent(event)

    def showEvent(self, event):
        """Wird aufgerufen wenn der Dialog angezeigt wird"""
        super().showEvent(event)

        # ✅ Sprachausgabe für Barrierefreiheit
        self.say(
            self.lang.tr("pages_insert") + " " + self.lang.tr("pages_insert_position")
        )

        # ✅ Ersten Fokus setzen
        QTimer.singleShot(100, self.set_initial_focus)

    def set_initial_focus(self):
        """Setzt den initialen Fokus"""
        self.position_spin.setFocus()

    def choose_pdf(self):
        path, _ = QFileDialog.getOpenFileName(
            self,
            self.lang.tr("pages_insert_select"),
            "",
            "PDF Dateien (*.pdf)",  # Original: "PDF auswählen"
        )
        if path:
            self.pdf_to_insert = path
            self.pdf_label.setText(os.path.basename(path))
            self.pdf_label.setStyleSheet("color: #E0E0E0; font-style: normal;")

    def say(self, message, force=False):
        """Verwendet die Sprachausgabe des Hauptfensters"""
        if hasattr(self, "parent") and self.parent:
            self.parent.say(message, force)

    def narrate_focus(self, message):
        """Verwendet die Fokusansage des Hauptfensters"""
        if hasattr(self, "parent") and self.parent:
            self.parent.narrate_focus(message)

    def validate(self):
        if not self.pdf_to_insert:
            dialog = myUniversalDialog(
                self.parent,
                title=self.lang.tr(
                    "pages_no_pdf_selected"
                ),  # Original: "Keine PDf geladen"
                message=self.lang.tr(
                    "pages_no_pdf_selected"
                ),  # Original: "Es ist keine PDf ausgewählt."
                buttons=[(self.lang.tr("btn_ok"), "success", "ok")],
                icon_type="",
                voice_message=self.lang.tr("pages_no_pdf_selected"),
                text_alignment=Qt.AlignLeft,
            )
            dialog.exec_()
            return
        self.accept()

    def get_selection(self):
        return {
            "position": self.position_spin.value() - 1,
            "pdf_path": self.pdf_to_insert,
        }


# ================================================
# MEHRERE PDFs ZUSAMMENFÜHREN (mit Sortierung)
# ================================================


class MergePDFsDialog(QDialog):
    """Dialog zum Zusammenführen mehrerer PDFs mit Sortierung"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.parent = parent
        self.pdf_files = []

        if parent and hasattr(parent, "lang"):
            self.lang = parent.lang
        else:
            self.lang = Language()

        self.init_ui()
        self.setup_drag_drop()

    def init_ui(self):
        self.setWindowTitle(self.lang.tr("merge_pdfs_title"))
        self.setMinimumWidth(750)
        self.setMinimumHeight(450)

        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(10, 5, 10, 10)
        self.setLayout(main_layout)

        # Kopfzeile
        header = self._create_header()
        main_layout.addWidget(header)

        # PDF-Liste
        list_group = QGroupBox(self.lang.tr("merge_pdfs_list"))
        list_group.setStyleSheet("QGroupBox { font-size: 14px; font-weight: bold; }")
        list_layout = QVBoxLayout()

        # Toolbar über der Liste
        toolbar = QHBoxLayout()

        self.btn_add = QPushButton(qta.icon("fa5s.plus"), self.lang.tr("merge_add_pdf"))
        self.parent.style_button(self.btn_add, "primary", (150, 25))
        self.btn_add.clicked.connect(self.add_pdfs)

        self.btn_remove = QPushButton(
            qta.icon("fa5s.trash"), self.lang.tr("merge_remove")
        )
        self.parent.style_button(self.btn_remove, "danger", (150, 25))
        self.btn_remove.clicked.connect(self.remove_selected)

        self.btn_move_up = QPushButton(
            qta.icon("fa5s.arrow-up"), self.lang.tr("merge_move_up")
        )
        self.parent.style_button(self.btn_move_up, "primary", (150, 25))
        self.btn_move_up.clicked.connect(self.move_up)

        self.btn_move_down = QPushButton(
            qta.icon("fa5s.arrow-down"), self.lang.tr("merge_move_down")
        )
        self.parent.style_button(self.btn_move_down, "primary", (150, 25))
        self.btn_move_down.clicked.connect(self.move_down)

        toolbar.addWidget(self.btn_add)
        toolbar.addWidget(self.btn_remove)
        toolbar.addSpacing(20)
        toolbar.addWidget(self.btn_move_up)
        toolbar.addWidget(self.btn_move_down)
