class FlattenPDFThread(QThread):
    """Thread für das Glätten (Flatten) von PDFs."""

    progress_updated = pyqtSignal(int, str)
    finished = pyqtSignal(bool, str, str)

    def __init__(self, input_path, output_path, settings):
        super().__init__()
        self.input_path = input_path
        self.output_path = output_path
        self.settings = settings
        self._is_cancelled = False

    def cancel(self):
        self._is_cancelled = True

    def run(self):
        try:
            import fitz

            self.progress_updated.emit(10, "PDF wird geladen...")

            doc = fitz.open(self.input_path)
            total_pages = doc.page_count

            self.progress_updated.emit(20, f"Glätte {total_pages} Seiten...")

            # Alle Seiten durchgehen
            for page_num in range(total_pages):
                if self._is_cancelled:
                    doc.close()
                    self.finished.emit(False, "Glätten abgebrochen", self.output_path)
                    return

                page = doc[page_num]

                # Formularfelder glätten
                if self.settings["flatten_forms"]:
                    try:
                        page._flatten_widgets()
                    except:
                        pass

                # Anmerkungen glätten
                if self.settings["flatten_annotations"]:
                    try:
                        # Alle Anmerkungen auf der Seite finden und glätten
                        annots = page.annots()
                        if annots:
                            # In eine Liste umwandeln, da wir während des Iterierens löschen
                            annot_list = list(annots)
                            for annot in annot_list:
                                try:
                                    page.add_redact_annot(annot.rect)
                                except:
                                    pass
                        # Anmerkungen in den Seiteninhalt einbetten
                        page.apply_redactions()
                    except:
                        pass

                # Overlays glätten (unsere eigenen Elemente)
                if self.settings["flatten_overlays"]:
                    try:
                        # Alle Overlays in den Seiteninhalt einbetten
                        page.apply_redactions()
                    except:
                        pass

                progress = 20 + int((page_num + 1) / total_pages * 70)
                self.progress_updated.emit(
                    progress, f"Seite {page_num + 1} wird geglättet..."
                )

            # PDF speichern
            self.progress_updated.emit(90, "PDF wird gespeichert...")
            doc.save(self.output_path, garbage=4, deflate=True)
            doc.close()

            if self._is_cancelled:
                if os.path.exists(self.output_path):
                    os.remove(self.output_path)
                self.finished.emit(False, "Glätten abgebrochen", self.output_path)
                return

            self.progress_updated.emit(100, "Glätten abgeschlossen!")
            self.finished.emit(True, "", self.output_path)

        except Exception as e:
            error_msg = str(e)
            if self._is_cancelled:
                error_msg = "Glätten abgebrochen"
            print(f"Flatten-Fehler: {error_msg}")
            import traceback

            traceback.print_exc()

            if os.path.exists(self.output_path):
                try:
                    os.remove(self.output_path)
                except:
                    pass
            self.finished.emit(False, error_msg, self.output_path)


