        self.line_width_spin.setValue(self.line_width)
        self.line_width_spin.setSuffix(" px")
        self.line_width_spin.setFixedWidth(INPUT_WIDTH)
        self.line_width_spin.setMinimumHeight(38)
        self.line_width_spin.valueChanged.connect(self.update_preview)
        settings_layout.addWidget(width_label, 1, 0)
