        offset_y_label = QLabel(self.lang.tr("cross_offset_y"))
        self.offset_y_combo = QComboBox()
        self.offset_y_combo.setEditable(True)
        self.offset_y_combo.setMinimumHeight(38)
        self.offset_y_combo.setFixedWidth(INPUT_WIDTH)  # Gleiche Breite
        for i in range(-40, 41):
            self.offset_y_combo.addItem(str(i))
        self.offset_y_combo.setCurrentText(str(self.offset_y))
        self.offset_y_combo.setToolTip(self.lang.tr("cross_offset_y_tooltip"))

        offset_layout.addWidget(offset_x_label, 0, 0)
        offset_layout.addWidget(self.offset_x_combo, 0, 2)
        offset_layout.addWidget(offset_y_label, 1, 0)
