        preview_group = QGroupBox(self.lang.tr("cross_preview"))
        preview_layout = QVBoxLayout()
        self.preview_label = QLabel()
        self.preview_label.setFixedSize(220, 170)
        self.preview_label.setAlignment(Qt.AlignCenter)
        self.preview_label.setStyleSheet(
            "background-color: #2D2D2D; border: 2px solid #666; border-radius: 6px;"
        )
