class PageNumberDialog(QDialog):
    """Dialog für das Einfügen von Seitenzahlen mit verschiedenen Formaten und Positionen."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.parent = parent

        # --- Bildschirmgröße für maximale Dialogmaße ermitteln ---
        screen = QApplication.primaryScreen()
        screen_geometry = screen.availableGeometry()
        max_dialog_height = int(screen_geometry.height() * 0.8)
        max_dialog_width = int(screen_geometry.width() * 0.9)

        self.setWindowTitle(parent.tr("page_numbers_title"))

        self.setMinimumSize(550, 700)
        self.setMaximumSize(max_dialog_width, max_dialog_height)
        self.setSizeGripEnabled(True)

        self.setup_ui()

    def setup_ui(self):
        # Haupt-Layout
        main_layout = QVBoxLayout(self)
        main_layout.setSpacing(0)
        main_layout.setContentsMargins(0, 0, 0, 0)

        # ========== 1. Kopfbereich (Header) ==========
        header = QWidget()
        header.setFixedHeight(120)
        header_layout = QHBoxLayout(header)
        header_layout.setContentsMargins(15, 10, 15, 10)
        header_layout.addStretch(1)

        if os.path.exists(Config.IMAGE_PATH):
            self.logo_label = QLabel()
            logo_pixmap = QPixmap(Config.IMAGE_PATH).scaled(
                80, 80, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            self.logo_label.setPixmap(logo_pixmap)
            header_layout.addWidget(self.logo_label)
            header_layout.addStretch(1)

        self.title_label = QLabel(self.parent.tr("page_numbers_title"))
        self.title_label.setAlignment(Qt.AlignCenter)
        self.title_label.setStyleSheet(
            "font-size: 20px; font-weight: bold; color: white;"
        )
        header_layout.addWidget(self.title_label)
        header_layout.addStretch(1)

        if os.path.exists(Config.APP_ICON_PATH):
            self.icon_label = QLabel()
