class PDFTextViewer(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.parent = parent
        BaseWindow.__init__(self)

        # Language-Instanz vom Hauptfenster übernehmen
        if parent and hasattr(parent, "lang"):
            self.lang = parent.lang
        else:

            self.lang = Language()

        # Übernehme Einstellungen vom Hauptfenster
        self.voice_enabled = parent.voice_enabled if parent else True
        self.total_pages = 0
        self.current_page = 0
        self.page_texts = []  # Wichtig: Liste für Seitentexte
        self.pdf_path = None

        # ToolTips für macOS
        if sys.platform == "darwin":
            try:
                from Foundation import NSUserDefaults

                defaults = NSUserDefaults.standardUserDefaults()
                defaults.setBool_forKey_(True, "NSAllowsDefaultLineBreakStrategy")
            except ImportError:
                print("PyObjC nicht installiert")

            self.setAttribute(Qt.WA_AlwaysShowToolTips, True)
            QToolTip.setPalette(QPalette(QColor("#3E3E3E")))
            QToolTip.setFont(QFont("Helvetica", 14))

        # Suche
        self.search_results = []
        self.current_search_index = -1
        self.last_search_term = ""

        self.init_ui()  # vor der Sprach und Schriftgrößeneinstellung
        self.setWindowTitle(self.lang.tr("ocr_text_window"))

        # OCR Sprache für Font
        settings = QSettings("BinhDiez", "PDFDarkView")
        ocr_lang = settings.value("ocr_language", "deu+eng+vie")
        self._set_font_for_language(ocr_lang)

        # Fensterzustand VOR der Schriftgröße wiederherstellen
        settings = QSettings("BinhDiez", "PDFDarkView")
        was_maximized = settings.value("text_viewer_maximized", False, type=bool)
        geometry = settings.value("text_viewer_geometry")

        if geometry and not was_maximized:
            self.restoreGeometry(geometry)
        else:
            self.center_on_screen()

        if was_maximized:
            self.showMaximized()

        # Jetzt Schriftgröße laden (nachdem der Fenstermodus steht)
        saved_size = settings.value("text_viewer_font_size", 24, type=int)
        index = self.font_combo.findText(str(saved_size))
        if index >= 0:
            self.font_combo.setCurrentIndex(index)
        else:
            self.font_combo.setCurrentText(str(saved_size))
        # change_font_size ruft adjust_window_for_font_size auf,
        # das bei saved_size >=140 korrekt maximieren wird.
        self.change_font_size(str(saved_size))

