class NumberToWords:
    """Wandelt Zahlen in Wörter der gewünschten Sprache um
    Um eine weitere Sprache hinzuzufügen (z.B. Französisch), musst du nur:

    1. Eine neue statische Methode _francais schreiben, die eine Zahl entgegennimmt und den französischen Text zurückgibt.
    2. Die Methode registrieren: NumberToWords._register('fr', NumberToWords._francais).
    """

    _converters = {}  # Dictionary für Sprach-Konverter

    # mit Fallback falls keine landesspezifische stattic Methode vorliegt
    @staticmethod
    def convert(number, language):
        """Wandelt eine Zahl in die angegebene Sprache um."""
        converter = NumberToWords._converters.get(language)
        if converter is None:
            # Fallback: Versuche Deutsch, dann Englisch, dann Notfall
            converter = NumberToWords._converters.get("de")
        if converter is None:
            converter = NumberToWords._converters.get("en")
        if converter is None:
            # Wenn gar nichts geht, gib die Zahl als String zurück
            return str(number)
        return converter(number)

    @staticmethod
    def convert(number, lang="de"):
        """Wandelt eine Zahl in Wörter um"""
        if lang not in NumberToWords._converters:
            # Fallback: Zahl als String zurückgeben
            return str(number)
        return NumberToWords._converters[lang](number)

    @staticmethod
    def _register(lang, func):
        """Registriert eine Konverterfunktion für eine Sprache"""
        NumberToWords._converters[lang] = staticmethod(func)

    # ---------- Afrikaans ----------
    @staticmethod
    def _afrikaans(n):
        """Skakel 'n getal om na Afrikaanse woorde."""
        if n == 0:
            return "nul"
        if n < 0:
            return "minus " + NumberToWords._afrikaans(-n)

        # Grondgetalle 1-19
        units = [
            "",
            "een",
            "twee",
            "drie",
            "vier",
            "vyf",
            "ses",
            "sewe",
            "agt",
            "nege",
            "tien",
            "elf",
            "twaalf",
            "dertien",
            "veertien",
            "vyftien",
            "sestien",
            "sewentien",
            "agtien",
            "negentien",
        ]

        # Tientalle 20-90
        tens = [
            "",
            "",
            "twintig",
            "dertig",
            "veertig",
            "vyftig",
            "sestig",
            "sewentig",
            "tagtig",
            "negentig",
        ]

        # Honderde
        def hundred_word(h):
            if h == 1:
                return "honderd"
            else:
                return units[h] + "honderd"

        # Duisende
        def thousand_word(th):
            if th == 1:
                return "duisend"
            else:
                return NumberToWords._afrikaans(th) + "duisend"

        # Miljoene
        def million_word(m):
            if m == 1:
                return "een miljoen"
            else:
                return NumberToWords._afrikaans(m) + " miljoen"

        if n < 20:
            return units[n]

        if n < 100:
            ten = n // 10
            unit = n % 10
            if unit == 0:
                return tens[ten]
            else:
                # In Afrikaans word dit aanmekaar geskryf: "een-en-twintig"
                return units[unit] + "-en-" + tens[ten]

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            h_word = hundred_word(hundred)
            if rest == 0:
                return h_word
            else:
                return h_word + " " + NumberToWords._afrikaans(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            t_word = thousand_word(thousand)
            if rest == 0:
                return t_word
            else:
                return t_word + " " + NumberToWords._afrikaans(rest)

        # Miljoene
        million = n // 1_000_000
        rest = n % 1_000_000
        m_word = million_word(million)
        if rest == 0:
            return m_word
        else:
            return m_word + " " + NumberToWords._afrikaans(rest)

    # ---------- Arabisch ----------
    @staticmethod
    def _arabic(n):
        """تحويل الأرقام إلى كلمات باللغة العربية."""
        if n == 0:
            return "صفر"
        if n < 0:
            return "ناقص " + NumberToWords._arabic(-n)

        # الأرقام الأساسية 1-19
        units = [
            "",
            "واحد",
            "اثنان",
            "ثلاثة",
            "أربعة",
            "خمسة",
            "ستة",
            "سبعة",
            "ثمانية",
            "تسعة",
            "عشرة",
            "أحد عشر",
            "اثنا عشر",
            "ثلاثة عشر",
            "أربعة عشر",
            "خمسة عشر",
            "ستة عشر",
            "سبعة عشر",
            "ثمانية عشر",
            "تسعة عشر",
        ]

        # العشرات 20-90
        tens = [
            "",
            "",
            "عشرون",
            "ثلاثون",
            "أربعون",
            "خمسون",
            "ستون",
            "سبعون",
            "ثمانون",
            "تسعون",
        ]

        # المئات
        def hundred_word(h):
            if h == 1:
                return "مائة"
            else:
                return units[h] + "مائة"

        # الآلاف
        def thousand_word(th):
            if th == 1:
                return "ألف"
            elif th == 2:
                return "ألفان"
            elif 3 <= th <= 10:
                return units[th] + " آلاف"
            else:
                return NumberToWords._arabic(th) + " ألف"

        # الملايين
        def million_word(m):
            if m == 1:
                return "مليون"
            elif m == 2:
                return "مليونان"
            elif 3 <= m <= 10:
                return units[m] + " ملايين"
            else:
                return NumberToWords._arabic(m) + " مليون"

        if n < 20:
            return units[n]

        if n < 100:
            ten = n // 10
            unit = n % 10
            if unit == 0:
                return tens[ten]
            else:
                # في العربية، يكتب "واحد وعشرون" (الآحاد ثم "و" ثم العشرات)
                return units[unit] + " و " + tens[ten]

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            h_word = hundred_word(hundred)
            if rest == 0:
                return h_word
            else:
                return h_word + " و " + NumberToWords._arabic(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            t_word = thousand_word(thousand)
            if rest == 0:
                return t_word
            else:
                return t_word + " و " + NumberToWords._arabic(rest)

        # الملايين
        million = n // 1_000_000
        rest = n % 1_000_000
        m_word = million_word(million)
        if rest == 0:
            return m_word
        else:
            return m_word + " و " + NumberToWords._arabic(rest)

    # ---------- Bosnian ----------
    @staticmethod
    def _bosnian(n):
        """Pretvara broj u riječi na bosanskom jeziku."""
        if n == 0:
            return "nula"
        if n < 0:
            return "minus " + NumberToWords._bosnian(-n)

        # Osnovni brojevi 1-19
