    @staticmethod
    def _luxembourgish(n):
        """Wandelt eng Zuel op Lëtzebuergesch ëm."""
        if n == 0:
            return "null"
        if n < 0:
            return "minus " + NumberToWords._luxembourgish(-n)

        # Grundzuelen 1-19
        units = [
            "",
            "een",
            "zwee",
            "dräi",
            "véier",
            "fënnef",
            "sechs",
            "siwen",
            "aacht",
            "néng",
            "zéng",
            "eelef",
            "zwielef",
            "dräizéng",
            "véierzéng",
            "fofzéng",
            "g sechzéng",
            "siwwenzéng",
            "uechtzéng",
            "nonzéng",
        ]

        # Zénger 20-90
        tens = [
            "",
            "",
            "zwanzeg",
            "drësseg",
            "véierzeg",
            "fofzeg",
            "sechzeg",
            "siwwenzeg",
            "achtzeg",
            "nonzeg",
        ]

        # Honnert 100-900
        def hundred_word(h):
            if h == 1:
                return "honnert"
            else:
                return units[h] + "honnert"

        # Dausend 1000-9000
        def thousand_word(th):
            if th == 1:
                return "dausend"
            else:
                return NumberToWords._luxembourgish(th) + "dausend"

        # Milliounen 1e6-...
        def million_word(m):
            if m == 1:
                return "eng Millioun"
            else:
                return NumberToWords._luxembourgish(m) + " Milliounen"

        if n < 20:
            return units[n]

        if n < 100:
            unit = n % 10
            ten = n // 10
            if unit == 0:
                return tens[ten]
            else:
                # z.B. "eenanzwanzeg" (21) – och "een a zwanzeg" méiglech, hei "eenanzwanzeg" (zougeschriwwen)
                return units[unit] + "an" + tens[ten]

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            h_word = hundred_word(hundred)
            if rest == 0:
                return h_word
            else:
                return h_word + NumberToWords._luxembourgish(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            t_word = thousand_word(thousand)
            if rest == 0:
                return t_word
            else:
                return t_word + NumberToWords._luxembourgish(rest)

        # Milliounen
        million = n // 1_000_000
        rest = n % 1_000_000
        m_word = million_word(million)
        if rest == 0:
            return m_word
        else:
            return m_word + " " + NumberToWords._luxembourgish(rest)

