    @staticmethod
    def _bulgarian(n):
        """Превръща число в думи на български език."""
        if n == 0:
            return "нула"
        if n < 0:
            return "минус " + NumberToWords._bulgarian(-n)

        # Числата от 1 до 19
        units = [
            "",
            "едно",
            "две",
            "три",
            "четири",
            "пет",
            "шест",
            "седем",
            "осем",
            "девет",
            "десет",
            "единадесет",
            "дванадесет",
            "тринадесет",
            "четиринадесет",
            "петнадесет",
            "шестнадесет",
            "седемнадесет",
            "осемнадесет",
            "деветнадесет",
        ]

        # Десетици 20-90
        tens = [
            "",
            "",
            "двадесет",
            "тридесет",
            "четиридесет",
            "петдесет",
            "шестдесет",
            "седемдесет",
            "осемдесет",
            "деветдесет",
        ]

        # Специални форми за мъжки род при числата 1 и 2 (за стотици, хиляди и т.н.)
        # Но за числата като цяло използваме формите по-горе.

        # Помощна функция за стотици
        def hundred_word(h):
            if h == 1:
                return "сто"
            elif h == 2:
                return "двеста"
            elif h == 3:
                return "триста"
            elif h == 4:
                return "четиристотин"
            else:
                # 500-900: число + "стотин"
                return units[h] + "стотин"

        # Помощна функция за хиляди
        def thousand_word(th):
            if th == 1:
                return "хиляда"
            elif th == 2:
                return "две хиляди"
            else:
                # 3-9 хиляди: число + " хиляди"
                return NumberToWords._bulgarian(th) + " хиляди"

        # Помощна функция за милиони
        def million_word(m):
            if m == 1:
                return "един милион"
            elif m == 2:
                return "два милиона"
            else:
                # 3-9 милиона: число + " милиона"
                # Забележка: за 3-9 се използва "три милиона", "четири милиона" и т.н.
                # Числото трябва да бъде в подходяща форма, но тук използваме стандартната.
                # За числа над 9 ще работи рекурсията.
                return NumberToWords._bulgarian(m) + " милиона"

        if n < 20:
            return units[n]

        if n < 100:
            ten = n // 10
            unit = n % 10
            if unit == 0:
                return tens[ten]
            else:
                # между десетици и единици се поставя "и"
                # Пример: 21 = "двадесет и едно"
                return tens[ten] + " и " + units[unit]

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            h_word = hundred_word(hundred)
            if rest == 0:
                return h_word
            else:
                return h_word + " и " + NumberToWords._bulgarian(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            t_word = thousand_word(thousand)
            if rest == 0:
                return t_word
            else:
                return t_word + " и " + NumberToWords._bulgarian(rest)

        # Милиони
        million = n // 1_000_000
        rest = n % 1_000_000
        m_word = million_word(million)
        if rest == 0:
            return m_word
        else:
            return m_word + " и " + NumberToWords._bulgarian(rest)

    # ---------- Polnisch ----------
    @staticmethod
    def _polish(n):
        """Wandelt eine Zahl in polnische Wörter um."""
        if n == 0:
            return "zero"
        if n < 0:
            return "minus " + NumberToWords._polish(-n)

        # Grundzahlen 0-19
        units = [
            "",
            "jeden",
            "dwa",
            "trzy",
            "cztery",
            "pięć",
            "sześć",
            "siedem",
            "osiem",
            "dziewięć",
            "dziesięć",
            "jedenaście",
            "dwanaście",
            "trzynaście",
            "czternaście",
            "piętnaście",
            "szesnaście",
            "siedemnaście",
            "osiemnaście",
            "dziewiętnaście",
        ]

        # Zehner 20-90
        tens = [
            "",
            "",
            "dwadzieścia",
            "trzydzieści",
            "czterdzieści",
            "pięćdziesiąt",
            "sześćdziesiąt",
            "siedemdziesiąt",
            "osiemdziesiąt",
            "dziewięćdziesiąt",
        ]

        # Hunderter 100-900
        hundreds = [
            "",
            "sto",
            "dwieście",
            "trzysta",
            "czterysta",
            "pięćset",
            "sześćset",
            "siedemset",
            "osiemset",
            "dziewięćset",
        ]

        # Tausender-Formen: 1000 = tysiąc, 2000-4000 = tysiące, 5000+ = tysięcy
        def thousand_word(num):
            if num == 1:
                return "tysiąc"
            elif 2 <= num <= 4:
                return NumberToWords._polish(num) + " tysiące"
            else:
                return NumberToWords._polish(num) + " tysięcy"

        # Millionen-Formen: 1 = milion, 2-4 = miliony, 5+ = milionów
        def million_word(num):
            if num == 1:
                return "milion"
            elif 2 <= num <= 4:
                return NumberToWords._polish(num) + " miliony"
            else:
                return NumberToWords._polish(num) + " milionów"

        if n < 20:
            return units[n]

        if n < 100:
            unit = n % 10
            ten = n // 10
            if unit == 0:
                return tens[ten]
            else:
                # z.B. dwadzieścia jeden, dwadzieścia dwa, ...
                return tens[ten] + " " + units[unit]

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            if rest == 0:
                return hundreds[hundred]
            else:
                return hundreds[hundred] + " " + NumberToWords._polish(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            t_word = thousand_word(thousand)
            if rest == 0:
                return t_word
            else:
                return t_word + " " + NumberToWords._polish(rest)

        # Millionen
        million = n // 1_000_000
        rest = n % 1_000_000
        m_word = million_word(million)
        if rest == 0:
            return m_word
        else:
            return m_word + " " + NumberToWords._polish(rest)

    # ---------- Ungarisch ----------
    @staticmethod
    def _hungarian(n):
        """Átalakít egy számot magyar szavakká."""
        if n == 0:
            return "nulla"
        if n < 0:
            return "mínusz " + NumberToWords._hungarian(-n)

        # Alap számok 1-19
        units = [
            "",
            "egy",
            "kettő",
            "három",
            "négy",
            "öt",
            "hat",
            "hét",
            "nyolc",
            "kilenc",
            "tíz",
            "tizenegy",
            "tizenkettő",
            "tizenhárom",
            "tizennégy",
            "tizenöt",
            "tizenhat",
            "tizenhét",
            "tizennyolc",
            "tizenkilenc",
        ]

        # Tízesek 20-90
        tens = [
            "",
            "",
            "húsz",
            "harminc",
            "negyven",
            "ötven",
            "hatvan",
            "hetven",
            "nyolcvan",
            "kilencven",
        ]

        # Segédfüggvény a "kettő" → "két" cseréhez ezer/millió előtt
        def replace_ketto(text):
            # Cseréljük a "kettő" szót "két"-re, ha ezer vagy millió következik
            # Egyszerű string csere, mivel a "kettő" csak a 2-es számot jelöli
            return text.replace("kettőezer", "kétezer").replace(
                "kettőmillió", "kétmillió"
            )

        if n < 20:
            return units[n]

        if n < 100:
            ten = n // 10
            unit = n % 10
            if unit == 0:
                return tens[ten]
            else:
                # 20-99: tízes + egyes (pl. huszonegy)
                if ten == 2:  # 20-asok: "huszon" + egyes
                    return "huszon" + units[unit]
                else:
                    return tens[ten] + units[unit]

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            # Százasok: 1: "száz", 2: "kétszáz", 3: "háromszáz", ...
            if hundred == 1:
                hundred_word = "száz"
            elif hundred == 2:
                hundred_word = "kétszáz"
            else:
                hundred_word = units[hundred] + "száz"
            if rest == 0:
                return hundred_word
            else:
                return hundred_word + NumberToWords._hungarian(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            # Ezresek
            if thousand == 1:
                thousand_word = "ezer"
            else:
                thousand_word = NumberToWords._hungarian(thousand) + "ezer"
                thousand_word = replace_ketto(thousand_word)
            if rest == 0:
                return thousand_word
            else:
                return thousand_word + NumberToWords._hungarian(rest)

        # Milliók
        million = n // 1_000_000
        rest = n % 1_000_000
        if million == 1:
            million_word = "egymillió"
        else:
            million_word = NumberToWords._hungarian(million) + "millió"
            million_word = replace_ketto(million_word)
        if rest == 0:
            return million_word
        else:
            return million_word + NumberToWords._hungarian(rest)

