    # ---------- Türkisch ----------
    @staticmethod
    def _turkish(n):
        if n == 0:
            return "sıfır"
        if n < 0:
            return "eksi " + NumberToWords._turkish(-n)

        # Grundzahlen 1-9
        units = [
            "",
            "bir",
            "iki",
            "üç",
            "dört",
            "beş",
            "altı",
            "yedi",
            "sekiz",
            "dokuz",
        ]

        # Zehner 10-90
        tens = [
            "",
            "on",
            "yirmi",
            "otuz",
            "kırk",
            "elli",
            "altmış",
            "yetmiş",
            "seksen",
            "doksan",
        ]

        # Hunderter
        hundreds = [
            "",
            "yüz",
            "iki yüz",
            "üç yüz",
            "dört yüz",
            "beş yüz",
            "altı yüz",
            "yedi yüz",
            "sekiz yüz",
            "dokuz yüz",
        ]

        def _from_1_to_99(num):
            if num < 10:
                return units[num]
            ten = num // 10
            unit = num % 10
            if unit == 0:
                return tens[ten]
            else:
                return tens[ten] + " " + units[unit]

        def _from_1_to_999(num):
            if num < 100:
                return _from_1_to_99(num)
            hundred = num // 100
            rest = num % 100
            hundred_word = "yüz" if hundred == 1 else units[hundred] + " yüz"
            if rest == 0:
                return hundred_word
            else:
                return hundred_word + " " + _from_1_to_99(rest)

        # Tausender, Millionen, Milliarden
        # Türkisch: bin, milyon, milyar
        billions = n // 1_000_000_000
        millions = (n % 1_000_000_000) // 1_000_000
        thousands = (n % 1_000_000) // 1000
        remainder = n % 1000

        parts = []
        if billions > 0:
            if billions == 1:
                parts.append("bir milyar")
            else:
                parts.append(_from_1_to_999(billions) + " milyar")
        if millions > 0:
            if millions == 1:
                parts.append("bir milyon")
            else:
                parts.append(_from_1_to_999(millions) + " milyon")
        if thousands > 0:
            if thousands == 1:
                parts.append("bin")
            else:
                # "bin" öncesinde sayı varsa "bir bin" denmez, direkt "bin" kullanılır.
                # Ama iki bin, üç bin vb. normal.
                parts.append(_from_1_to_999(thousands) + " bin")
        if remainder > 0:
            parts.append(_from_1_to_999(remainder))

        return " ".join(parts)

