    # ---------- Zulu ----------
    @staticmethod
    def _zulu(n):
        """Wandelt eine Zahl in Zulu-Wörter um."""
        if n == 0:
            return "uZiro"  # oder "iqanda"? "uZiro" ist gebräuchlich.
        if n < 0:
            return "kushiywe " + NumberToWords._zulu(-n)

        # Grundzahlen 1-9
        digits = [
            "",
            "kunye",
            "kubili",
            "kuthathu",
            "kune",
            "kuhlanu",
            "isithupha",
            "isikhombisa",
            "isishiyagalombili",
            "isishiyagalolunye",
        ]

        # Zehner 10-19
        teens = [
            "ishumi",
            "ishumi nanye",
            "ishumi nambili",
            "ishumi nantathu",
            "ishumi nane",
            "ishumi nanhlanu",
            "ishumi nesithupha",
            "ishumi nesikhombisa",
            "ishumi nesishiyagalombili",
            "ishumi nesishiyagalolunye",
        ]

        # Zehner 20-90
        tens = [
            "",
            "",
            "amashumi amabili",
            "amashumi amathathu",
            "amashumi amane",
            "amashumi amahlanu",
            "amashumi ayisithupha",
            "amashumi ayisikhombisa",
            "amashumi ayisishiyagalombili",
            "amashumi ayisishiyagalolunye",
        ]

        # Hunderter, Tausender, Millionen
        def hundred_word(h):
            if h == 1:
                return "ikhulu"
            return "amakhulu " + digits[h]  # z.B. amakhulu amabili = 200

        def thousand_word(th):
            if th == 1:
                return "inkulungwane"
            return "izinkulungwane " + NumberToWords._zulu(
                th
            )  # z.B. izinkulungwane ezimbili = 2000

        def million_word(m):
            if m == 1:
                return "isigidi"
            return "izigidi " + NumberToWords._zulu(m)

        # Hilfsfunktion für Zahlen unter 100
        def under_hundred(num):
            if num < 10:
                return digits[num]
            if num < 20:
                return teens[num - 10]
            if num < 100:
                ten = num // 10
                unit = num % 10
                if unit == 0:
                    return tens[ten]
                else:
                    # Zusammensetzung: Zehner + " " + Einer (z.B. amashumi amabili nanye = 21)
                    return (
                        tens[ten] + " nanye"
                        if unit == 1
                        else tens[ten] + " " + digits[unit]
                    )

        if n < 100:
            return under_hundred(n)

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            hword = hundred_word(hundred)
            if rest == 0:
                return hword
            else:
                return hword + " " + under_hundred(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            return thousand_word(thousand) + (
                " " + NumberToWords._zulu(rest) if rest else ""
            )

        # Millionen
        million = n // 1_000_000
        rest = n % 1_000_000
        return million_word(million) + (" " + NumberToWords._zulu(rest) if rest else "")

