    @staticmethod
    def _japanese(n):
        """
        数字を日本語の漢数字に変換します。
        Wandelt eine Zahl in japanische Kanji-Ziffern um.
        """
        if n == 0:
            return "零"
        if n < 0:
            return "マイナス" + NumberToWords._japanese(-n)

        # 基本の数字
        digits = ["", "一", "二", "三", "四", "五", "六", "七", "八", "九"]

        # 位取りの単位（万進法）
        units = [
            "",
            "万",
            "億",
            "兆",
            "京",
            "垓",
            "𥝱",
            "穣",
            "溝",
            "澗",
            "正",
            "載",
            "極",
        ]
        # 通常は兆までで十分ですが、念のため

        def convert_group(num):
            """0～9999の数字を日本語に変換"""
            if num == 0:
                return ""
            thousand = num // 1000
            hundred = (num % 1000) // 100
            ten = (num % 100) // 10
            one = num % 10

            parts = []
            if thousand > 0:
                parts.append(digits[thousand] + "千")
            if hundred > 0:
                parts.append(digits[hundred] + "百")
            if ten > 0:
                # 十の位が1で、千・百の位がない場合 → "十" (いちじゅう ではない)
                if ten == 1 and thousand == 0 and hundred == 0:
                    parts.append("十")
                else:
                    parts.append(digits[ten] + "十")
            if one > 0:
                parts.append(digits[one])

            return "".join(parts)

        if n == 0:
            return "零"

        # 数字を4桁ごとに分割 (下位から)
        groups = []
        num = abs(n)
        while num > 0:
            groups.append(num % 10000)
            num //= 10000

        result = []
        for i, group in enumerate(groups):
            if group == 0:
                continue
            group_str = convert_group(group)
            if i > 0:
                group_str += units[i]
            result.insert(0, group_str)

        final = "".join(result)
        # 先頭の「一」が付かない特殊ケース（例：10000 → 一万）
        # すでに convert_group で処理済みなのでそのままでOK
        return final

    @staticmethod
    def _korean(n):
        """
        숫자를 한국어 단어로 변환합니다 (한자어 계통).
        Wandelt eine Zahl in koreanische Wörter um (sino-koreanisches System).
        """
        if n == 0:
            return "영"
        if n < 0:
            return "마이너스 " + NumberToWords._korean(-n)

        # 한자어 숫자
        digits = ["", "일", "이", "삼", "사", "오", "육", "칠", "팔", "구"]
        units = ["", "십", "백", "천"]
        large_units = [
            "",
            "만",
            "억",
            "조",
            "경",
            "해",
            "자",
            "양",
            "구",
            "간",
            "정",
            "재",
            "극",
        ]

        # 0-9 처리
        if n < 10:
            return digits[n]

        # 4자리씩 끊어서 처리
        result = []
        chunk_index = 0
        while n > 0:
            chunk = n % 10000
            if chunk != 0:
                chunk_str = ""
                # 각 자리수 처리
                thousand = chunk // 1000
                hundred = (chunk % 1000) // 100
                ten = (chunk % 100) // 10
                one = chunk % 10

                if thousand > 0:
                    chunk_str += digits[thousand] + "천"
                if hundred > 0:
                    chunk_str += digits[hundred] + "백"
                if ten > 0:
                    chunk_str += digits[ten] + "십"
                if one > 0:
                    chunk_str += digits[one]

                if chunk_index > 0:
                    chunk_str += large_units[chunk_index]
                result.insert(0, chunk_str)
            n //= 10000
            chunk_index += 1

        return "".join(result)

