    @staticmethod
    def _hindi(n):
        """Wandelt eine Zahl in Hindi-Wörter um."""
        if n == 0:
            return "शून्य"
        if n < 0:
            return "ऋण " + NumberToWords._hindi(-n)

        # Einheiten 1-9
        units = ["", "एक", "दो", "तीन", "चार", "पाँच", "छह", "सात", "आठ", "नौ"]

        # Zehner 10-19
        teens = [
            "दस",
            "ग्यारह",
            "बारह",
            "तेरह",
            "चौदह",
            "पंद्रह",
            "सोलह",
            "सत्रह",
            "अठारह",
            "उन्नीस",
        ]

        # Zehner 20-90
        tens = ["", "", "बीस", "तीस", "चालीस", "पचास", "साठ", "सत्तर", "अस्सी", "नब्बे"]

        # Hunderter, Tausender, etc.
        def hundred_word(h):
            if h == 1:
                return "सौ"
            return units[h] + " सौ"

        def thousand_word(th):
            if th == 1:
                return "हज़ार"
            return NumberToWords._hindi(th) + " हज़ार"

        def lakh_word(l):
            # 1 Lakh = 100.000
            if l == 1:
                return "एक लाख"
            return NumberToWords._hindi(l) + " लाख"

        def crore_word(c):
            # 1 Crore = 10.000.000
            if c == 1:
                return "एक करोड़"
            return NumberToWords._hindi(c) + " करोड़"

        # Hilfsfunktion für Zahlen unter 1000 (speziell für Hindi)
        def under_thousand(num):
            if num < 10:
                return units[num]
            if num < 20:
                return teens[num - 10]
            if num < 100:
                ten = num // 10
                unit = num % 10
                if unit == 0:
                    return tens[ten]
                # Spezialfall: 21 = इक्कीस, 31 = इकतीस, etc.
                # Einfache Zusammensetzung: tens + units (mit Sandhi)
                # Wir verwenden eine vereinfachte Version: tens + units
                # Für eine korrekte Hindi-Aussprache müsste man die Sandhi-Regeln beachten.
                # Hier eine einfache Näherung:
                if ten == 2 and unit == 1:
                    return "इक्कीस"
                if ten == 3 and unit == 1:
                    return "इकतीस"
                if ten == 4 and unit == 1:
                    return "इकतालीस"
                if ten == 5 and unit == 1:
                    return "इक्यावन"
                if ten == 6 and unit == 1:
                    return "इकसठ"
                if ten == 7 and unit == 1:
                    return "इकहत्तर"
                if ten == 8 and unit == 1:
                    return "इक्यासी"
                if ten == 9 and unit == 1:
                    return "इक्यानवे"
                if ten == 2 and unit == 2:
                    return "बाईस"
                if ten == 3 and unit == 2:
                    return "बत्तीस"
                # ... viele weitere Sonderfälle
                # Für den Zweck dieser Demo: einfache Kombination
                return tens[ten] + " " + units[unit]
            if num < 1000:
                hundred = num // 100
                rest = num % 100
                hword = hundred_word(hundred)
                if rest == 0:
                    return hword
                else:
                    return hword + " " + under_thousand(rest)

    @staticmethod
    def _mongolian(n):
        """Wandelt eine Zahl in mongolische Wörter um (kyrillisch)."""
        if n == 0:
            return "тэг"
        if n < 0:
            return "хасах " + NumberToWords._mongolian(-n)

        # Grundzahlen 1-9
        digits = [
            "",
            "нэг",
            "хоёр",
            "гурав",
            "дөрөв",
            "тав",
            "зургаа",
            "долоо",
            "найм",
            "ес",
        ]

        # Zehner 10-19 (Sonderfälle)
        teens = [
            "арав",
            "арван нэг",
            "арван хоёр",
            "арван гурав",
            "арван дөрөв",
            "арван тав",
            "арван зургаа",
            "арван долоо",
            "арван найм",
            "арван ес",
        ]

        # Zehner 20-90
        tens = [
            "",
            "",
            "хорин",
            "гучин",
            "дөчин",
            "тавин",
            "жаран",
            "далан",
            "наян",
            "ерэн",
        ]

        # Hunderter, Tausender, Millionen, Milliarden
        def hundred_word(h):
            if h == 1:
                return "зуу"
            return digits[h] + " зуу"

        def thousand_word(th):
            if th == 1:
                return "мянга"
            return NumberToWords._mongolian(th) + " мянга"

        def million_word(m):
            if m == 1:
                return "сая"
            return NumberToWords._mongolian(m) + " сая"

        def billion_word(b):
            if b == 1:
                return "тэрбум"
            return NumberToWords._mongolian(b) + " тэрбум"

        # Hilfsfunktion für Zahlen unter 1000
        def under_thousand(num):
            if num < 10:
                return digits[num]
            if num < 20:
                return teens[num - 10]
            if num < 100:
                ten = num // 10
                unit = num % 10
                if unit == 0:
                    return tens[ten]
                else:
                    return tens[ten] + " " + digits[unit]
            if num < 1000:
                hundred = num // 100
                rest = num % 100
                hword = hundred_word(hundred)
                if rest == 0:
                    return hword
                else:
                    return hword + " " + under_thousand(rest)

        if n < 1000:
            return under_thousand(n)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            return thousand_word(thousand) + (
                " " + under_thousand(rest) if rest else ""
            )

        if n < 1_000_000_000:
            million = n // 1_000_000
            rest = n % 1_000_000
            return million_word(million) + (
                " " + NumberToWords._mongolian(rest) if rest else ""
            )

        # Milliarden
        billion = n // 1_000_000_000
        rest = n % 1_000_000_000
        return billion_word(billion) + (
            " " + NumberToWords._mongolian(rest) if rest else ""
        )

    @staticmethod
    def _malay(n):
        """Mengubah angka menjadi kata-kata dalam Bahasa Malaysia."""
        if n == 0:
            return "sifar"  # oder "kosong" – hier wurde die formelle Variante gewählt
        if n < 0:
            return "negatif " + NumberToWords._malay(-n)

        # Angka dasar 0–19
        units = [
            "",
            "satu",
            "dua",
            "tiga",
            "empat",
            "lima",
            "enam",
            "tujuh",
            "lapan",
            "sembilan",
            "sepuluh",
            "sebelas",
            "dua belas",
            "tiga belas",
            "empat belas",
            "lima belas",
            "enam belas",
            "tujuh belas",
            "lapan belas",
            "sembilan belas",
        ]

        # Puluhan 20–90
        tens = [
            "",
            "",
            "dua puluh",
            "tiga puluh",
            "empat puluh",
            "lima puluh",
            "enam puluh",
            "tujuh puluh",
            "lapan puluh",
            "sembilan puluh",
        ]

        # Hilfsfunktionen für Hunderter, Tausender, Millionen
        def hundred_word(h):
            if h == 1:
                return "seratus"
            return units[h] + " ratus"

        def thousand_word(th):
            if th == 1:
                return "seribu"
            return NumberToWords._malay(th) + " ribu"

        def million_word(m):
            if m == 1:
                return "satu juta"
            return NumberToWords._malay(m) + " juta"

        if n < 20:
            return units[n]

        if n < 100:
            ten = n // 10
            unit = n % 10
            if unit == 0:
                return tens[ten]
            return tens[ten] + " " + units[unit]

        if n < 1000:
            hundred = n // 100
            rest = n % 100
            h_word = hundred_word(hundred)
            if rest == 0:
                return h_word
            return h_word + " " + NumberToWords._malay(rest)

        if n < 1_000_000:
            thousand = n // 1000
            rest = n % 1000
            t_word = thousand_word(thousand)
            if rest == 0:
                return t_word
            return t_word + " " + NumberToWords._malay(rest)

        # Jutaan (bis 999 Mio.)
        million = n // 1_000_000
        rest = n % 1_000_000
        m_word = million_word(million)
        if rest == 0:
            return m_word
        return m_word + " " + NumberToWords._malay(rest)

    @staticmethod
    def _nepali(n):
        """Wandelt eine Zahl in nepalesische Wörter um (Devanagari)."""
        if n == 0:
            return "शून्य"
        if n < 0:
            return "ऋण " + NumberToWords._nepali(-n)

        # Grundzahlen 1-9
        digits = ["", "एक", "दुई", "तीन", "चार", "पाँच", "छ", "सात", "आठ", "नौ"]

        # Zehner 10-19
        teens = [
            "दस",
            "एघार",
            "बाह्र",
            "तेह्र",
            "चौध",
            "पन्ध्र",
            "सोह्र",
            "सत्र",
            "अठार",
            "उन्नाइस",
        ]

        # Zehner 20-90
        tens = ["", "", "बीस", "तीस", "चालीस", "पचास", "साठी", "सत्तरी", "असी", "नब्बे"]

        # Spezielle Zusammensetzungen für 21-99 (wie im Nepali üblich)
        # Vereinfachte Implementierung: tens + digits mit Bindewort
        # Für eine vollständige korrekte Wiedergabe müssten viele Sonderfälle berücksichtigt werden.
        # Hier eine vereinfachte Version, die für die meisten Zahlen funktioniert.

        # Hunderter, Tausender, Lakh, Crore
        def hundred_word(h):
            if h == 1:
                return "एक सय"
            return digits[h] + " सय"

        def thousand_word(th):
            if th == 1:
                return "एक हजार"
            return NumberToWords._nepali(th) + " हजार"

        def lakh_word(l):
            # 1 Lakh = 100,000
            if l == 1:
                return "एक लाख"
            return NumberToWords._nepali(l) + " लाख"

        def crore_word(c):
            # 1 Crore = 10,000,000
            if c == 1:
                return "एक करोड"
            return NumberToWords._nepali(c) + " करोड"

        # Hilfsfunktion für Zahlen unter 1000
        def under_thousand(num):
            if num < 10:
                return digits[num]
            if num < 20:
                return teens[num - 10]
            if num < 100:
                ten = num // 10
                unit = num % 10
                if unit == 0:
                    return tens[ten]
                # Vereinfachte Zusammensetzung: tens + unit (z.B. बीस + एक = बीस एक)
                # Im Nepali gibt es oft Verschmelzungen wie एक्काइस (21), बाइस (22), etc.
                # Für den Zweck dieser Demo nehmen wir eine einfache Zusammensetzung.
                return tens[ten] + " " + digits[unit]
            if num < 1000:
                hundred = num // 100
                rest = num % 100
                hword = hundred_word(hundred)
                if rest == 0:
                    return hword
                else:
                    return hword + " " + under_thousand(rest)

        # Nepali verwendet das Lakh-Crore-System
        if n < 1000:
            return under_thousand(n)

        if n < 100_000:
            thousand = n // 1000
            rest = n % 1000
            return thousand_word(thousand) + (
                " " + under_thousand(rest) if rest else ""
            )

        if n < 10_000_000:
            lakh = n // 100_000
            rest = n % 100_000
            return lakh_word(lakh) + (" " + NumberToWords._nepali(rest) if rest else "")

        # Crore
        crore = n // 10_000_000
        rest = n % 10_000_000
        return crore_word(crore) + (" " + NumberToWords._nepali(rest) if rest else "")

    @staticmethod
    def _khmer(n):
        """Wandelt eine Zahl in khmerische Wörter um."""
        if n == 0:
            return "សូន្យ"
        if n < 0:
            return "ដក " + NumberToWords._khmer(-n)

        # Grundzahlen 1-9
        digits = [
            "",
            "មួយ",
            "ពីរ",
            "បី",
            "បួន",
            "ប្រាំ",
            "ប្រាំមួយ",
            "ប្រាំពីរ",
            "ប្រាំបី",
            "ប្រាំបួន",
        ]

        # Zehner (20-90)
        tens = [
            "",
            "",
            "ម្ភៃ",
            "សាមសិប",
            "សែសិប",
            "ហាសិប",
            "ហុកសិប",
            "ចិតសិប",
            "ប៉ែតសិប",
            "កៅសិប",
        ]

        # Hilfsfunktionen für Hunderter, Tausender, Zehntausender, Hunderttausender, Millionen
        def hundred_word(h):
            if h == 1:
                return "មួយរយ"
            return digits[h] + "រយ"

        def thousand_word(th):
            if th == 1:
                return "មួយពាន់"
            return NumberToWords._khmer(th) + "ពាន់"

        def ten_thousand_word(tth):
            if tth == 1:
                return "មួយម៉ឺន"
            return NumberToWords._khmer(tth) + "ម៉ឺន"

        def hundred_thousand_word(hth):
            if hth == 1:
                return "មួយសែន"
            return NumberToWords._khmer(hth) + "សែន"

        def million_word(m):
            if m == 1:
                return "មួយលាន"
            return NumberToWords._khmer(m) + "លាន"

        # Hilfsfunktion für Zahlen unter 1000
        def under_thousand(num):
            if num < 10:
                return digits[num]
            if num < 20:
                # 10-19
                ten = num // 10
                unit = num % 10
                if ten == 1:
                    if unit == 1:
                        return "ដប់មួយ"
                    elif unit == 0:
                        return "ដប់"
                    else:
                        return "ដប់" + digits[unit]
            if num < 100:
                ten = num // 10
                unit = num % 10
                if ten == 2:
                    # Spezialfall 20-29
                    if unit == 0:
                        return tens[2]  # "ម្ភៃ"
                    elif unit == 1:
                        return "ម្ភៃមួយ"
                    else:
                        return "ម្ភៃ" + digits[unit]
                else:
                    result = tens[ten]
                    if unit == 1:
                        result += "មួយ"
                    elif unit > 0:
                        result += digits[unit]
                    return result
            if num < 1000:
                hundred = num // 100
                rest = num % 100
                hword = hundred_word(hundred)
                if rest == 0:
                    return hword
                else:
                    return hword + under_thousand(rest)

        if n < 1000:
            return under_thousand(n)

        if n < 1_000_000:
            # Tausender, Zehntausender, Hunderttausender
            thousand = n // 1000
            rest = n % 1000
            if thousand < 10:
                return thousand_word(thousand) + (under_thousand(rest) if rest else "")
            elif thousand < 100:
                # Zehntausender (10.000 - 99.999)
                ten_thousand = thousand // 10
                thousand_rest = thousand % 10
                if thousand_rest == 0:
                    return ten_thousand_word(ten_thousand) + (
                        under_thousand(rest) if rest else ""
                    )
                else:
                    return (
                        NumberToWords._khmer(thousand)
                        + "ពាន់"
                        + (under_thousand(rest) if rest else "")
                    )
            else:
                # Hunderttausender (100.000 - 999.999)
                hundred_thousand = thousand // 100
                thousand_rest = thousand % 100
                if thousand_rest == 0:
                    return hundred_thousand_word(hundred_thousand) + (
                        under_thousand(rest) if rest else ""
                    )
                else:
                    return (
                        NumberToWords._khmer(thousand)
                        + "ពាន់"
                        + (under_thousand(rest) if rest else "")
                    )

        # Millionen
        million = n // 1_000_000
        rest = n % 1_000_000
        mword = million_word(million)
        if rest == 0:
            return mword
        else:
            return mword + NumberToWords._khmer(rest)

