        if n < 0:
            return "منفي " + NumberToWords._pashto(-n)

        # Grundzahlen 1-9
        digits = ["", "یو", "دوه", "درې", "څلور", "پنځه", "شپږ", "اووه", "اته", "نهه"]

        # Zehner 10-19
        teens = [
            "لس",
            "یوولس",
            "دوولس",
            "دیارلس",
            "څوارلس",
            "پنځلس",
            "شپاړلس",
            "اووه لس",
            "اتلس",
            "نولس",
        ]

        # Zehner 20-90
        tens = ["", "", "شل", "دېرش", "څلوېښت", "پنځوس", "شپېته", "اویا", "اتیا", "نوي"]

        # Hunderter, Tausender, Lakh, Crore
        def hundred_word(h):
            if h == 1:
                return "سل"
            return digits[h] + " سل"

        def thousand_word(th):
            if th == 1:
                return "زر"
            return NumberToWords._pashto(th) + " زر"

        def lakh_word(l):
            # 1 Lakh = 100,000
            if l == 1:
                return "یو لک"
            return NumberToWords._pashto(l) + " لک"

        def crore_word(c):
            # 1 Crore = 10,000,000
            if c == 1:
                return "یو کروړ"
            return NumberToWords._pashto(c) + " کروړ"

        # Hilfsfunktion für Zahlen unter 1000
        def under_thousand(num):
            if num < 10:
                return digits[num]
            if num < 20:
                return teens[num - 10]
            if num < 100:
                ten = num // 10
                unit = num % 10
                if unit == 0:
                    return tens[ten]
                # Zusammensetzung: ten + unit (z.B. شل + یو = شل یو)
                # Im Paschtu gibt es oft Verschmelzungen, aber wir bleiben einfach.
                return tens[ten] + " " + digits[unit]
            if num < 1000:
                hundred = num // 100
                rest = num % 100
                hword = hundred_word(hundred)
                if rest == 0:
                    return hword
                else:
                    return hword + " " + under_thousand(rest)

        # Paschtu verwendet wie Hindi/Urdu das Lakh-Crore-System
        if n < 1000:
            return under_thousand(n)

        if n < 100_000:
            thousand = n // 1000
            rest = n % 1000
            return thousand_word(thousand) + (
                " " + under_thousand(rest) if rest else ""
            )

        if n < 10_000_000:
            lakh = n // 100_000
            rest = n % 100_000
            return lakh_word(lakh) + (" " + NumberToWords._pashto(rest) if rest else "")

        # Crore
        crore = n // 10_000_000
        rest = n % 10_000_000
        return crore_word(crore) + (" " + NumberToWords._pashto(rest) if rest else "")

