# ============================================
# OCR-Sprachauswahl
# ============================================

# Hauptdialog (Combobox + Benutzerdefiniert)

class OCRLanguageDialog(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle(
            parent.tr("ocr_language_title") if parent else "OCR Language"
        )
        self.setModal(True)
        self.setFixedSize(550, 600)

        self.parent = parent
        self.settings = QSettings("BinhDiez", "PDFDarkView")
        default_lang = self.get_default_ocr_language()
        self.current_lang = self.settings.value("ocr_language", default_lang)

        # Verfügbare Sprachen ermitteln
        self.available_langs = get_available_tesseract_languages()
        self.predefined_options, self.available_set, self.names_map = (
            get_predefined_ocr_options()
        )

        layout = QVBoxLayout()
        layout.setSpacing(10)

        # Kopfzeile (wie gehabt)
        header = QWidget()
        header_layout = QHBoxLayout(header)
        header_layout.setContentsMargins(20, 5, 20, 5)
        header_layout.setSpacing(15)

        if os.path.exists(Config.IMAGE_PATH):
            logo = QLabel()
            logo.setPixmap(
                QPixmap(Config.IMAGE_PATH).scaled(
                    80, 80, Qt.KeepAspectRatio, Qt.SmoothTransformation
                )
            )
            header_layout.addWidget(logo, 1, Qt.AlignCenter | Qt.AlignVCenter)

        title_label = QLabel(self.parent.tr("ocr_language_title"))
        title_label.setStyleSheet("font-size: 22px; font-weight: bold; color: #E0E0E0;")
        header_layout.addWidget(title_label, 1, Qt.AlignCenter)

        if os.path.exists(Config.APP_ICON_PATH):
            icon = QLabel()
            icon.setPixmap(
                QPixmap(Config.APP_ICON_PATH).scaled(
                    60, 60, Qt.KeepAspectRatio, Qt.SmoothTransformation
                )
            )
            header_layout.addWidget(icon, 1, Qt.AlignCenter | Qt.AlignVCenter)

        layout.addWidget(header)

        # Info-Label
        info_label = QLabel(parent.tr("ocr_language_instruction"))
        info_label.setWordWrap(True)
        layout.addWidget(info_label)

        # Combobox für vordefinierte Optionen
        layout.addWidget(QLabel(parent.tr("ocr_language_predefined")))
        self.combo = QComboBox()
        self.combo.addItem(parent.tr("ocr_language_custom"), "custom")
        for display_name, code in self.predefined_options:
            self.combo.addItem(display_name, code)

        index = self.combo.findData(self.current_lang)
        if index >= 0:
            self.combo.setCurrentIndex(index)
        else:
            self.combo.setCurrentIndex(0)
        self.combo.currentIndexChanged.connect(self.on_combo_changed)
        layout.addWidget(self.combo)

        # Container für benutzerdefinierte Anzeige
        self.custom_container = QGroupBox()
        self.custom_container.setStyleSheet("""
            QGroupBox {
                font-weight: bold;
                margin-top: 10px;
            }
            QGroupBox::title {
                subcontrol-origin: margin;
                left: 10px;
                padding: 0 5px 0 5px;
            }
        """)
        self.custom_container.setTitle(f"{self.parent.tr('ocr_language_selected')} (0)")
        custom_layout = QVBoxLayout(self.custom_container)
        custom_layout.setContentsMargins(5, 5, 5, 5)

        # ========== WICHTIG: Feste maximale Höhe für die ScrollArea ==========
        custom_scroll = QScrollArea()
        custom_scroll.setWidgetResizable(True)
        custom_scroll.setMaximumHeight(600)
        custom_scroll.setMinimumHeight(100)  # Minimale Höhe
        custom_scroll.setSizePolicy(
            QSizePolicy.Expanding, QSizePolicy.Fixed
        )  # Vertikal fix
        custom_scroll.setStyleSheet(
            "QScrollArea { border: 1px solid #555; background: #2D2D2D; border-radius: 4px; }"
        )

        scroll_content = QWidget()
        scroll_layout = QVBoxLayout(scroll_content)
        scroll_layout.setContentsMargins(5, 5, 5, 5)

        # Label mit lesbaren Namen
        self.custom_label = QLabel()
        self.custom_label.setWordWrap(True)
        self.custom_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        self.custom_label.setStyleSheet("""
            QLabel {
                background-color: #2D2D2D;
                padding: 8px;
                font-size: 12px;
                color: #E0E0E0;
            }
        """)

        # Wichtig: Label oben ausrichten
        self.custom_label.setAlignment(Qt.AlignTop)

        scroll_layout.addWidget(self.custom_label)
        scroll_layout.addStretch()  # Stretch am Ende, damit Inhalt nach oben rutscht
        custom_scroll.setWidget(scroll_content)
        custom_layout.addWidget(custom_scroll)

        layout.addWidget(self.custom_container)

        # Button für benutzerdefinierte Auswahl
        self.custom_btn = QPushButton(parent.tr("ocr_language_custom"))
        self.parent.style_button(self.custom_btn, "primary", (480, 25))
        self.custom_btn.clicked.connect(self.open_custom_dialog)
        self.custom_btn.setFocusPolicy(Qt.StrongFocus)
        layout.addWidget(self.custom_btn)

        # Reset-Button
        reset_btn = QPushButton(parent.tr("ocr_language_reset"))
        self.parent.style_button(reset_btn, "primary", (480, 25))
        reset_btn.clicked.connect(self.reset_to_default)
        reset_btn.setFocusPolicy(Qt.StrongFocus)
        layout.addWidget(reset_btn)

        # OK/Cancel
        btn_box = QHBoxLayout()
        btn_box.addStretch()

        ok_btn = QPushButton(parent.tr("btn_ok"))
        self.parent.style_button(ok_btn, "success", (120, 25))
        ok_btn.clicked.connect(self.accept)
        ok_btn.setFocusPolicy(Qt.StrongFocus)
        btn_box.addWidget(ok_btn)
        btn_box.addStretch()

        cancel_btn = QPushButton(parent.tr("btn_cancel"))
        self.parent.style_button(cancel_btn, "danger", (120, 25))
        cancel_btn.clicked.connect(self.reject)
        cancel_btn.setFocusPolicy(Qt.StrongFocus)
        btn_box.addWidget(cancel_btn)
        btn_box.addStretch()

        layout.addLayout(btn_box)

        self.setLayout(layout)

        # Initiale Anzeige
        self.update_custom_label()
        self.update_combo_from_current_lang()

    def update_combo_from_current_lang(self):
        """Setzt die Combobox basierend auf dem aktuellen Sprachwert"""
        # Prüfe ob current_lang in den vordefinierten Optionen ist
        found = False
        for display_name, code in self.predefined_options:
            if code == self.current_lang:
                index = self.combo.findData(code)
                if index >= 0:
                    self.combo.setCurrentIndex(index)
                    found = True
                break

        if not found:
            self.combo.setCurrentIndex(0)  # "Benutzerdefiniert"
            self.custom_btn.setEnabled(True)
        # else:
        #     self.custom_btn.setEnabled(False)

    def on_combo_changed(self, index):
        data = self.combo.currentData()
        if data == "custom":
            self.custom_btn.setEnabled(True)
            self.update_custom_label()
        else:
            # self.custom_btn.setEnabled(False)
            # Bei vordefinierter Auswahl die aktuelle Sprache aktualisieren
            self.current_lang = data
            self.update_custom_label()

    def update_custom_label(self):
        """Aktualisiert das Label mit lesbaren Sprachnamen"""
        codes = self.current_lang.split("+")

        # Konvertiere Codes zu lesbaren Namen mit Flaggen
        display_names = []
        for code in codes:
            if code.strip():
                name = self.get_language_display_name(code)
                flag = self.get_language_flag(code)
                display_names.append(f"{flag} {name}")

        lang_count = len(display_names)

        # ========== GroupBox Titel aktualisieren ==========
        self.custom_container.setTitle(
            f"{self.parent.tr('ocr_language_selected')} ({lang_count})"
        )

        if lang_count == 0:
            self.custom_label.setText(
                f"🏳️ {self.parent.tr('ocr_no_language_selected')}"
            )
            return

        # Anzeige mit Zeilenumbruch nach jeder 3. Sprache
        lines = []
        for i in range(0, len(display_names), 4):
            chunk = display_names[i : i + 4]
            lines.append(", ".join(chunk))

        display_text = "<br>".join(lines)

        # HTML OHNE Zähler (nur die Sprachen)
        html_text = f"""
        <html>
        <body style="background-color:#2D2D2D; color:#E0E0E0;">
        {display_text}
        </body>
        </html>
        """
        self.custom_label.setText(html_text)

