    # mit QtAwesome Icons
    def init_menu_bar(self):
        """Initialisiert die Menüleiste mit Übersetzungen"""
        menubar = self.menuBar()

        # Stylesheet für einheitliche Shortcut-Ausrichtung
        menubar.setStyleSheet("""
            QMenu {
                font-family: system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
                font-size: 13px;
                background-color: #3D3D3D;
                color: #E0E0E0;
                border: 1px solid #555555;
                min-width: 450px;
            }
            QMenu::item {
                padding-right: 50px;
            }
            QMenu::item:selected {
                background-color: #1565C0;
                color: white;
            }
        """)

        # ==========================================
        # Datei-Menü - Dokumentenverwaltung
        # ==========================================
        file_menu = menubar.addMenu(self.tr("menu_file"))

        # Tastatur-Shortcut zum Fokussieren des Datei-Menüs
        focus_menu_action = QAction(self)
        focus_menu_action.setShortcut("F1")
        focus_menu_action.triggered.connect(
            lambda: menubar.setActiveAction(file_menu.menuAction())
        )
        self.addAction(focus_menu_action)

        # --- Dokument öffnen/schließen ---
        open_action = QAction(qta.icon("fa5s.folder-open"), self.tr("file_open"), self)
        open_action.setShortcut("Ctrl+O")
        open_action.triggered.connect(self.open_file_dialog)
        file_menu.addAction(open_action)

        close_action = QAction(qta.icon("fa5s.times"), self.tr("file_close"), self)
        close_action.setShortcut("Ctrl+W")
        close_action.triggered.connect(self.close_current_pdf)
        file_menu.addAction(close_action)

