        # Vorhandene Lesezeichen
        bookmarks = self.load_current_bookmarks()
        if bookmarks:
            header_action = QAction(self.tr("context_bookmarks_jump"), self)
            header_action.setEnabled(False)
            bookmark_menu.addAction(header_action)

            max_display = 20
            for i, bm in enumerate(bookmarks):
                if i >= max_display:
                    more_action = QAction(
                        qta.icon("fa5s.ellipsis-h"), self.tr("bookmark_more"), self
                    )
                    more_action.triggered.connect(self.open_bookmark_manager)
                    bookmark_menu.addAction(more_action)
                    break

                page_num = bm.get("page", 0) + 1
                name = bm.get("name", self.tr("bookmark_name_default", page_num))
                display_name = name[:32] + "..." if len(name) > 35 else name
                display_text = (
                    f"{self.tr('bookmark_page_display', page_num)}: {display_name}"
                )
                if len(display_text) > 50:
                    display_text = display_text[:47] + "..."

                bookmark_action = QAction(qta.icon("fa5s.bookmark"), display_text, self)
                bookmark_action.triggered.connect(
                    lambda checked, b=bm: self.jump_to_bookmark_from_context(b)
                )
                bookmark_menu.addAction(bookmark_action)

            bookmark_menu.addSeparator()

