    def _delayed_init_menu_bar(self):
        """Wird nach dem Start aufgerufen, um die Menüleiste zu initialisieren."""
        if self._menu_initialized:
            return
        try:
            # Sicherstellen, dass die Menüleiste existiert
            if not self.menuBar():
                # Falls noch nicht vorhanden, versuche es später erneut
                QTimer.singleShot(200, self._delayed_init_menu_bar)
                return
            # Menüleiste aufbauen
            t0 = time.time()
            self.init_menu_bar()
            self._menu_initialized = True
            print(f"[TIMING] init_menu_bar: {time.time()-t0:.3f}s")
            # Menü-Zustände aktualisieren
            t1 = time.time()
            self.update_menu_states()
            print(f"[TIMING] update_menu_states: {time.time()-t1:.3f}s")
            print(f"[TIMING] Verzögertes Laden der Menüleiste (nachdem die GUI sichtbar ist): {time.time()-t0:.3f}s")

        except Exception as e:
            print(f"Fehler beim verzögerten Laden der Menüleiste: {e}")
            # Im Fehlerfall: Versuche es später noch einmal
            QTimer.singleShot(500, self._delayed_init_menu_bar)

    def show_shortcuts(self):
        """Zeigt eine Übersicht aller Tastaturkürzel in einem Dialog an"""
        shortcuts_text = self.tr("show_shortcuts_text")

        # Falls die Übersetzung den Platzhalter {0} enthält, ersetzen wir ihn mit der App-Namen
        try:
            shortcuts_text = shortcuts_text.format(self.tr("app_name"))
        except:
            pass

        dialog = myUniversalDialog(
            self,
            title=self.tr("shortcuts_dialog_title"),
            message=shortcuts_text,
            buttons=[(self.tr("btn_close"), "primary", "close")],
            text_alignment=Qt.AlignLeft,
            icon_type="",
        )
        dialog.exec_()

    def update_menu_states(self):
        """Aktualisiert die Menü-Zustände basierend auf aktiven Modi und vorhandenen Elementen.
        Setzt dynamische Texte mit Pluralisierung und aktualisiert Sichtbarkeit."""

        if not hasattr(self, '_menu_initialized') or not self._menu_initialized:
            return

        # ===== Bedingungen für inkompatible Modi =====
        # Ein Modus ist aktiv, wenn einer der anderen Modi aktiv ist
        any_mode_active = (
            self.text_mode or self.image_mode or self.signature_mode or self.form_mode
        )

        # Ein bestimmter Modus kann nur aktiv sein, wenn KEIN anderer Modus aktiv ist
        text_allowed = not (self.image_mode or self.signature_mode or self.form_mode)
        image_allowed = not (self.text_mode or self.signature_mode or self.form_mode)
        signature_allowed = not (self.text_mode or self.image_mode or self.form_mode)
        form_allowed = not (self.text_mode or self.image_mode or self.signature_mode)

        # ===== TEXTE UND KREUZE =====
        # Anzahl der Elemente ermitteln
        text_count = sum(
            1
            for item in self.all_text_items
            if not getattr(item, "item_type", None) == "cross"
        )
        cross_count = sum(
            1
            for item in self.all_text_items
            if getattr(item, "item_type", None) == "cross"
        )
        total_texts = len(self.all_text_items)

        # Prüfe ob aktuelles Item ein Text oder Kreuz ist
        text_selected = False
        cross_selected = False
        if self.text_mode and self.current_text_item is not None:
            if (
                hasattr(self.current_text_item, "item_type")
                and self.current_text_item.item_type == "cross"
            ):
                cross_selected = True
            else:
                text_selected = True

        # ----- Text-Menü-Einträge -----
        if hasattr(self, "text_insert_action"):
            # "Text einfügen" nur erlaubt, wenn kein anderer Modus aktiv
            self.text_insert_action.setEnabled(text_allowed)

        if hasattr(self, "cross_insert_action"):
            # "Kreuz einfügen" nur erlaubt, wenn kein anderer Modus aktiv
            self.cross_insert_action.setEnabled(text_allowed)

        # "Text anpassen" (für ausgewählten Text)
        if hasattr(self, "text_customize_action"):
            self.text_customize_action.setVisible(text_selected)
            # Text für Kreuz anpassen (wird in der Menüzeile angezeigt, daher eigener Text)
            if cross_selected:
                # "✏️ Dieses Kreuz anpassen" -> Icon bereits über qta, also nur Text
                self.text_customize_action.setText(self.tr("cross_customize"))
            else:
                # "✏️ Diesen Text anpassen"
                self.text_customize_action.setText(self.tr("text_customize"))

        # "Alle Kreuze anpassen" – immer sichtbar, wenn Text-Modus aktiv, aber dynamischer Text mit Anzahl
        if hasattr(self, "cross_customize_all_action"):
            visible = self.text_mode and cross_count > 0
            self.cross_customize_all_action.setVisible(visible)
            if visible:
                if cross_count == 1:
                    # "Alle Kreuze anpassen" (Plural im Deutschen gleich?)
                    # Besser: "1 Kreuz anpassen" oder "Alle 1 Kreuze"? Wir sagen "Alle Kreuze anpassen" auch bei 1? Egal.
                    # Wir verwenden einen speziellen Schlüssel mit Platzhalter
                    text = self.tr("cross_customize", cross_count)
                else:
                    text = self.tr("cross_customize_all", cross_count)
                self.cross_customize_all_action.setText(text)

        # "Diesen Text / Kreuz verwerfen"
        if hasattr(self, "text_discard_action"):
            visible = text_selected or cross_selected
            self.text_discard_action.setVisible(visible)
            if visible:
                if cross_selected:
                    self.text_discard_action.setText(self.tr("cross_discard"))
                else:
                    self.text_discard_action.setText(self.tr("text_discard"))

        # "Alle Texte und Kreuze speichern" – dynamischer Text
        if hasattr(self, "text_save_all_action"):
            visible = total_texts > 0
            self.text_save_all_action.setVisible(visible)
            if visible:
                if text_count > 0 and cross_count > 0:
                    # Gemischt
                    text_word = self.tr(
                        "text_word_plural" if text_count != 1 else "text_word_singular"
                    )
                    cross_word = self.tr(
                        "cross_word_plural"
                        if cross_count != 1
                        else "cross_word_singular"
                    )
                    save_text = self.tr(
                        "save_mixed", text_count, text_word, cross_count, cross_word
                    )
                elif text_count > 0:
                    save_text = self.tr(
                        "save_texts",
                        text_count,
                        self.tr(
                            "text_word_plural"
                            if text_count != 1
                            else "text_word_singular"
                        ),
                    )
                elif cross_count > 0:
                    save_text = self.tr(
                        "save_crosses",
                        cross_count,
                        self.tr(
                            "cross_word_plural"
                            if cross_count != 1
                            else "cross_word_singular"
                        ),
                    )
                else:
                    save_text = self.tr("save_all", self.tr("text_menu"))  # Fallback
                self.text_save_all_action.setText(save_text)

        # "Alle Texte und Kreuze verwerfen" – dynamischer Text
        if hasattr(self, "text_discard_all_action"):
            visible = total_texts > 0
            self.text_discard_all_action.setVisible(visible)
            if visible:
                if text_count > 0 and cross_count > 0:
                    text_word = self.tr(
                        "text_word_plural" if text_count != 1 else "text_word_singular"
                    )
                    cross_word = self.tr(
                        "cross_word_plural"
                        if cross_count != 1
                        else "cross_word_singular"
                    )
                    discard_text = self.tr(
                        "discard_mixed", text_count, text_word, cross_count, cross_word
                    )
                elif text_count > 0:
                    discard_text = self.tr(
                        "discard_texts",
                        text_count,
                        self.tr(
                            "text_word_plural"
                            if text_count != 1
                            else "text_word_singular"
                        ),
                    )
                elif cross_count > 0:
                    discard_text = self.tr(
                        "discard_crosses",
                        cross_count,
                        self.tr(
                            "cross_word_plural"
                            if cross_count != 1
                            else "cross_word_singular"
                        ),
                    )
                else:
                    discard_text = self.tr("text_discard_all")
                self.text_discard_all_action.setText(discard_text)

        # "Anleitung" – immer sichtbar
        if hasattr(self, "text_guide_action"):
            self.text_guide_action.setVisible(True)

        # ===== SIGNATUREN =====
        if hasattr(self, "signature1_insert_action"):
            self.signature1_insert_action.setEnabled(signature_allowed)
        if hasattr(self, "signature2_insert_action"):
            self.signature2_insert_action.setEnabled(signature_allowed)

        sig_count = len(self.all_signature_items)
        sig_selected = self.signature_mode and self.current_signature_item is not None

        if hasattr(self, "signature_customize_action"):
            self.signature_customize_action.setVisible(sig_selected)
        if hasattr(self, "signature_discard_action"):
            self.signature_discard_action.setVisible(sig_selected)

        # "Alle Signaturen speichern" – dynamisch
        if hasattr(self, "signature_save_all_action"):
            visible = sig_count > 0
            self.signature_save_all_action.setVisible(visible)
            if visible:
                if sig_count == 1:
                    self.signature_save_all_action.setText(
                        self.tr("save_signature_single")
                    )
                else:
                    self.signature_save_all_action.setText(
                        self.tr("save_signatures", sig_count)
                    )

        # "Alle Signaturen verwerfen" – dynamisch
        if hasattr(self, "signature_discard_all_action"):
            visible = sig_count > 1
            self.signature_discard_all_action.setVisible(visible)
            if visible:
                self.signature_discard_all_action.setText(
                    self.tr("discard_signatures", sig_count)
                )

        if hasattr(self, "signature_guide_action"):
            self.signature_guide_action.setVisible(True)
        if hasattr(self, "signature_settings_action"):
            self.signature_settings_action.setVisible(True)

        # ===== BILDER =====
        if hasattr(self, "image_insert_action"):
            self.image_insert_action.setEnabled(image_allowed)

        img_count = len(self.all_image_items)
        img_selected = self.image_mode and self.current_image_item is not None

        if hasattr(self, "image_customize_action"):
            self.image_customize_action.setVisible(img_selected)
        if hasattr(self, "image_aspect_action"):
            self.image_aspect_action.setVisible(img_selected)
            if img_selected and hasattr(self.current_image_item, "aspect_ratio_mode"):
                self.image_aspect_action.setChecked(
                    self.current_image_item.aspect_ratio_mode
                )
        if hasattr(self, "image_discard_action"):
            self.image_discard_action.setVisible(img_selected)

        # "Alle Bilder speichern" – dynamisch
        if hasattr(self, "image_save_all_action"):
            visible = img_count > 0
            self.image_save_all_action.setVisible(visible)
            if visible:
                if img_count == 1:
                    self.image_save_all_action.setText(self.tr("save_image_single"))
                else:
                    self.image_save_all_action.setText(
                        self.tr("save_images", img_count)
                    )

        # "Alle Bilder verwerfen" – dynamisch
        if hasattr(self, "image_discard_all_action"):
            visible = img_count > 1
            self.image_discard_all_action.setVisible(visible)
            if visible:
                self.image_discard_all_action.setText(
                    self.tr("discard_images", img_count)
                )

        if hasattr(self, "image_guide_action"):
            self.image_guide_action.setVisible(True)

        # ===== FORMEN =====
        if hasattr(self, "form_rectangle_action"):
            self.form_rectangle_action.setEnabled(form_allowed)
        if hasattr(self, "form_ellipse_action"):
            self.form_ellipse_action.setEnabled(form_allowed)
        if hasattr(self, "form_line_action"):
            self.form_line_action.setEnabled(form_allowed)
        if hasattr(self, "form_arrow_action"):
            self.form_arrow_action.setEnabled(form_allowed)

        form_count = len(self.all_form_items)
        form_selected = self.form_mode and self.current_form_item is not None

        # "Form anpassen" - nur sichtbar wenn eine Form ausgewählt ist
        if hasattr(self, "form_customize_action"):
            self.form_customize_action.setVisible(form_selected)

        # "Transparenter Hintergrund" - nur sichtbar wenn eine Form ausgewählt ist
        if hasattr(self, "form_transparent_action"):
            self.form_transparent_action.setVisible(form_selected)
            if form_selected and hasattr(self.current_form_item, "transparent_bg"):
                self.form_transparent_action.setChecked(
                    not self.current_form_item.transparent_bg
                )

        # "Diese Form verwerfen" - nur sichtbar wenn eine Form ausgewählt ist
        if hasattr(self, "form_discard_action"):
            self.form_discard_action.setVisible(form_selected)

        # "Alle Formen speichern" – dynamischer Text
        if hasattr(self, "form_save_all_action"):
            visible = form_count > 0
            self.form_save_all_action.setVisible(visible)
            if visible:
                if form_count == 1:
                    self.form_save_all_action.setText(self.tr("save_form_single"))
                else:
                    self.form_save_all_action.setText(self.tr("save_forms", form_count))

        # "Alle Formen verwerfen" – dynamischer Text
        if hasattr(self, "form_discard_all_action"):
            visible = form_count > 1
            self.form_discard_all_action.setVisible(visible)
            if visible:
                self.form_discard_all_action.setText(
                    self.tr("discard_forms", form_count)
                )

        # ===== REDACTION (Schwärzen) =====
        redact_count = len(self.all_redaction_items)
        redact_selected = (
            self.redaction_mode and self.current_redaction_item is not None
        )
        if hasattr(self, "redact_discard_action"):
            self.redact_discard_action.setVisible(redact_selected)

        # "Einstellungen..." – IMMER sichtbar (für globale Einstellungen)
        if hasattr(self, "form_settings_action"):
            self.form_settings_action.setVisible(True)

        # "Anleitung..." – IMMER sichtbar
        if hasattr(self, "form_guide_action"):
            self.form_guide_action.setVisible(True)

        # ===== TRENNLINIEN IN DEN MENÜS AKTUALISIEREN =====
        for menu in [
            self.text_menu,
            self.image_menu,
            self.signature_menu,
            self.form_menu,
        ]:
            if menu is not None:
                self._update_menu_separators(menu)

        # ===== ZOOM-MENÜ AKTUALISIEREN (abhängig von Suche) =====
        self.update_zoom_menu()

    def _update_menu_separators(self, menu):
        """Versteckt Trennlinien wenn keine Aktionen sichtbar sind"""
        actions = menu.actions()
        for i, action in enumerate(actions):
            if action.isSeparator():
                # Prüfe ob es sichtbare Aktionen vor und nach der Trennlinie gibt
                has_visible_before = False
                for j in range(i - 1, -1, -1):
                    if actions[j].isVisible() and not actions[j].isSeparator():
                        has_visible_before = True
                        break

                has_visible_after = False
                for j in range(i + 1, len(actions)):
                    if actions[j].isVisible() and not actions[j].isSeparator():
                        has_visible_after = True
                        break

                # Trennlinie nur anzeigen wenn es sowohl davor als auch danach sichtbare Aktionen gibt
                action.setVisible(has_visible_before and has_visible_after)

