    def rebuild_menus(self):
        """Baut alle Menüs komplett neu auf - wird nach Sprachwechsel aufgerufen"""
        print(f"DEBUG: Baue Menüs neu auf für Sprache: {self.lang.current_lang}")

        # Alte Menüleiste leeren
        self.menuBar().clear()

        # Menüs komplett neu erstellen
        self.init_menu_bar()

        # Menü-Zustände aktualisieren
        self.update_menu_states()

        # Kurze Verzögerung für die Aktualisierung
        QApplication.processEvents()

    def update_bookmark_menu(self):
        """Aktualisiert das Lesezeichen-Menü (wird nach Änderungen aufgerufen)."""
        # Finde das Lesezeichen-Menü in der Menüleiste
        for action in self.menuBar().actions():
            if action.text() == self.tr("menu_edit"):
                edit_menu = action.menu()
                for sub_action in edit_menu.actions():
                    if sub_action.text() == self.tr("menu_bookmarks"):
                        bookmark_menu = sub_action.menu()
                        # Lösche alle Aktionen außer den ersten (Hinzufügen) und den Manager
                        actions_to_keep = []
                        for act in bookmark_menu.actions():
                            if act.text() in [
                                self.tr("bookmark_add"),
                                self.tr("bookmark_manage"),
                                self.tr("bookmark_next"),
                                self.tr("bookmark_prev"),
                            ]:
                                actions_to_keep.append(act)
                            elif act.text() == self.tr("bookmark_existing"):
                                actions_to_keep.append(act)

                        # Entferne alle Aktionen
                        bookmark_menu.clear()

                        # Füge die zu behaltenden Aktionen wieder hinzu
                        for act in actions_to_keep:
                            bookmark_menu.addAction(act)

                        # Füge die Trennlinie und die aktuellen Lesezeichen hinzu
                        bookmark_menu.addSeparator()

                        # Lade aktuelle Lesezeichen
                        bookmarks = self.load_current_bookmarks()

                        if bookmarks:
                            header_action = QAction(
                                self.tr("context_bookmarks_jump"), self
                            )
                            header_action.setEnabled(False)
                            bookmark_menu.addAction(header_action)

                            for i, bm in enumerate(bookmarks[:20]):
                                page_num = bm.get("page", 0) + 1
                                name = bm.get(
                                    "name", self.tr("bookmark_name_default", page_num)
                                )

                                # Name für die Menüanzeige kürzen (max. 35 Zeichen)
                                display_name = (
                                    name[:32] + "..." if len(name) > 35 else name
                                )
                                display_text = f"{self.tr('bookmark_page_display', page_num)}: {display_name}"

                                bookmark_action = QAction(
                                    qta.icon("fa5s.bookmark"), display_text, self
                                )
                                bookmark_action.triggered.connect(
                                    lambda checked, b=bm: self.jump_to_bookmark_from_context(
                                        b
                                    )
                                )
                                bookmark_menu.addAction(bookmark_action)

                            bookmark_menu.addSeparator()

                        # Füge die Navigation wieder hinzu
                        next_action = QAction(
                            qta.icon("fa5s.arrow-down"), self.tr("bookmark_next"), self
                        )
                        next_action.triggered.connect(self.next_bookmark)
                        bookmark_menu.addAction(next_action)

                        prev_action = QAction(
                            qta.icon("fa5s.arrow-up"), self.tr("bookmark_prev"), self
                        )
                        prev_action.triggered.connect(self.prev_bookmark)
                        bookmark_menu.addAction(prev_action)

                        break

