    def style_button(self, button, style_type, custom_size=None):
        style = self.button_styles.get(style_type, self.button_styles["primary"])

        # Automatische Breite berechnen (nur wenn nötig)
        if custom_size:
            final_width = custom_size[0]
            final_height = custom_size[1]
        else:
            button.adjustSize()
            final_width = button.sizeHint().width() + 20
            final_height = button.sizeHint().height()

        # Stylesheet mit fester Höhe bei custom_size
        if custom_size:
            height_css = f"min-height: {final_height}px; max-height: {final_height}px;"
        else:
            height_css = "min-height: 15px;"

        style_sheet = f"""
        QPushButton {{
            font-weight: bold;
            color: white;
            background-color: {style['bg']};
            border-radius: 8px;
            padding: 6px 12px;
            {height_css}
            min-width: {final_width}px;
            max-width: {final_width}px;
            border: none;
            margin: 2px;
        }}
        QPushButton:hover {{ background-color: {style['hover']}; }}
        QPushButton:pressed {{
            background-color: {style['hover']};
            padding-top: 7px;
            padding-left: 7px;
        }}
        QPushButton:disabled {{
            background-color: #cccccc;
            color: #666666;
        }}
        QPushButton:focus {{
            border: 2px solid #ffd700;
            border-radius: 8px;
            background-color: {style['hover']};
        }}
        """
        button.setStyleSheet(style_sheet)

        # Festsetzen der Größe (zusätzlich zu CSS)
        if custom_size:
            button.setFixedSize(final_width, final_height)
        else:
            button.setFixedHeight(final_height)

        button.setAccessibleName(button.text())

