    def setup_scroll_behavior(self):
        """Konfiguriert das Scrollverhalten für horizontale Sperre in Normalansicht"""
        # Horizontalen Scrollbalken komplett deaktivieren
        self.graphics_view.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)

        # Horizontal Scrollen in der View unterbinden
        self.graphics_view.setDragMode(QGraphicsView.ScrollHandDrag)

        # Event-Filter für zusätzliche Kontrolle
        self.graphics_view.viewport().installEventFilter(self)

    def setup_macos_specific_fixes(self):
        """macOS-spezifische Optimierungen"""
        if platform.system() == "Darwin":
            # Verhindert Probleme mit Qt internals auf macOS
            self.setAttribute(Qt.WA_MacFrameworkScaled, True)

            # Verhindert Crashes beim Schließen von Child-Windows
            self.setAttribute(Qt.WA_DeleteOnClose, False)

            # Weitere macOS-Optimierungen
            try:
                # Verhindert "already deleted" Crashes
                import objc

                # Setze ObjC Exception Handling
                objc.options.verbose = True
            except ImportError:
                pass

    def _get_safe_font(self, size=10):
        """Liefert eine Schriftart, die unter Windows zuverlässig funktioniert"""
        if sys.platform == "win32":
            # Windows: Systemschriftarten verwenden
            return QFont("Segoe UI", size)
        elif sys.platform == "darwin":
            return QFont("Helvetica", size)
        else:
            return QFont("Arial", size)

