    ### BACKUPS
    ###---------------------------------------

    def toggle_backup_setting(self):
        """Schaltet die Backup-Einstellung um und zeigt einmalig einen Info-Dialog."""
        # Aktuellen Zustand vor dem Umschalten merken
        old_state = self.create_backup

        # Umschalten
        self.create_backup = not self.create_backup
        self.settings.setValue("create_backup", self.create_backup)
        self.settings.sync()

        # Menü-Haken aktualisieren
        if hasattr(self, "backup_action"):
            self.backup_action.setChecked(self.create_backup)

        # Einstellung speichern
        self.save_app_settings()

        # Statusleiste aktualisieren
        status = self.tr("backup_on") if self.create_backup else self.tr("backup_off")
        self.statusBar().showMessage(self.tr("backup_status", status), 3000)

        status_msg = (
            self.tr("backup_activated")
            if self.create_backup
            else self.tr("backup_deactivated")
        )
        self.say(status_msg)

        print(f"Backup-Einstellung geändert: {self.create_backup}")

        # Nur wenn der Zustand sich tatsächlich geändert hat, und noch nicht dauerhaft ausgeblendet
        if old_state != self.create_backup:
            self._show_backup_info_dialog()

    def on_backup_setting_changed(self):
        """Wird vom FilenameSettingsDialog aufgerufen, wenn sich die Backup-Einstellung geändert hat."""
        settings = QSettings("BinhDiez", "PDFDarkView")
        self.create_backup = settings.value("create_backup", True, type=bool)
        if hasattr(self, "backup_action"):
            self.backup_action.setChecked(self.create_backup)
        # Kein Info-Dialog hier, da Benutzer bereits im Dialog war.

    def _show_backup_info_dialog(self):
        """Zeigt einmalig einen informativen Dialog über das Backup-Verhalten (HTML aus Wörterbuch)."""
        settings = QSettings("BinhDiez", "PDFDarkView")
        # Wenn bereits dauerhaft ausgeblendet, nichts tun
        if settings.value("backup_info_dialog_hidden", False, type=bool):
            return

        dialog = myUniversalDialog(
            self,
            title=self.tr("backup_info_title"),
            message=self.tr("backup_info_html"),
            buttons=[
                (self.tr("btn_ok"), "primary", "ok"),
                (self.tr("backup_do_not_show"), "dark", "hide", 300),
            ],
            icon_type="",
            voice_message=self.tr("backup_info_voice"),
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()

        if dialog.result_value == "hide":
            settings.setValue("backup_info_dialog_hidden", True)
            settings.sync()

    def show_and_reset_backup_info_dialog(self):
        """Setzt die 'Nicht mehr anzeigen'-Einstellung für den Backup-Info-Dialog zurück."""
        settings = QSettings("BinhDiez", "PDFDarkView")
        settings.remove("backup_info_dialog_hidden")
        settings.sync()

        self._show_backup_info_dialog()

    def get_backup_filename(self, original_path=None):
        """Erstellt einen Backup-Dateinamen mit Zeitstempel."""
        return self.generate_custom_filename(suffixes=["_backup"], force_new_file=True)

    def create_backup_if_enabled(self, original_pdf_path):
        """Erstellt ein Backup der PDF, wenn Backup-Einstellung aktiv ist"""
        if not self.create_backup:
            print("Backup ist deaktiviert - überspringe Backup-Erstellung")
            return None

        try:
            backup_path = self.get_backup_filename(original_pdf_path)

            # Prüfe ob Backup bereits existiert (unwahrscheinlich wegen Zeitstempel)
            if os.path.exists(backup_path):
                # Falls doch, sekundengenauen Zeitstempel hinzufügen
                import time

                micro_timestamp = time.strftime("%Y%m%d_%H%M%S_%f")[:-3]
                base_name = os.path.splitext(os.path.basename(original_pdf_path))[0]
                backup_path = os.path.join(
                    os.path.dirname(original_pdf_path),
                    f"{base_name}_backup_{micro_timestamp}.pdf",
                )

            # Backup erstellen
            shutil.copy2(original_pdf_path, backup_path)

            print(f"Backup erstellt: {backup_path}")
            return backup_path

        except Exception as e:
            print(f"Fehler bei Backup-Erstellung: {e}")
            return None

    def _prepare_overwrite_target(self, target_path):
        """
        print("_prepare_overwrite_target called")
        Bereitet das Überschreiben vor:
        - Wenn target_path das Original ist und Backup aktiv, wird ein Backup erstellt.
        - Bei neuer Datei wird eine Nummerierung bei Namenskonflikt durchgeführt.
        Gibt den endgültigen Pfad zurück.
        """
        if target_path == self.pdf_path:
            # Überschreiben des Originals
            if self.create_backup:
                backup_dir = os.path.dirname(self.pdf_path)
                base_name = os.path.splitext(os.path.basename(self.pdf_path))[0]
                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                backup_path = os.path.join(
                    backup_dir, f"{base_name}_backup_{timestamp}.pdf"
                )
                # Prüfen, ob bereits ein Backup mit diesem Zeitstempel existiert
                if not os.path.exists(backup_path):
                    shutil.copy2(self.pdf_path, backup_path)
                    print(f"Backup vor Überschreiben erstellt: {backup_path}")
                else:
                    # Falls es schon existiert (z.B. durch zweiten Aufruf), Nummer anhängen
                    counter = 1
                    while os.path.exists(backup_path):
                        backup_path = os.path.join(
                            backup_dir, f"{base_name}_backup_{timestamp}_{counter}.pdf"
                        )
                        counter += 1
                    shutil.copy2(self.pdf_path, backup_path)
                    print(
                        f"Backup vor Überschreiben erstellt (alternative): {backup_path}"
                    )
            return self.pdf_path
        else:
            # Neue Datei: Namenskonflikte vermeiden
            counter = 1
            base, ext = os.path.splitext(target_path)
            while os.path.exists(target_path):
                target_path = f"{base}_{counter}{ext}"
                counter += 1
            return target_path

    ###---------------------------------------
    ### SPRACHAUSGABE und Barrierefreiheit
    ###---------------------------------------

    def toggle_voice(self, checked=None):
        """Schaltet Sprachausgabe global um"""
        if checked is None:
            self.voice_enabled = not self.voice_enabled
        else:
            self.voice_enabled = checked

        # Sprachansage des neuen Status
        status = self.tr("voice_on") if self.voice_enabled else self.tr("voice_off")
        # "Sprachausgabe {0}"
        self.narrate_focus(self.tr("voice_toggle", status))

        # Einstellung speichern
        self.save_app_settings()

    def say(self, message, force=False, convert_numbers=False):
        """Erweiterte Sprachausgabe mit optionaler Zahlenkonvertierung"""
        if getattr(self, "_is_closing", False):
            return
        if not force and not self.voice_enabled:
            return

        try:
            if convert_numbers and hasattr(self, "lang"):
                import re

                def replace_number(match):
                    num = int(match.group())
                    return NumberToWords.convert(num, self.lang.current_lang)

                message = re.sub(r"\b\d+\b", replace_number, message)

            if platform.system() == "Darwin":
                # macOS: originaler say-Befehl
                os.system("pkill -f say")
                speed = getattr(self, "voice_speed", 1.0)
                os.system(f'say -r {int(175 * speed)} "{message}" &')
            else:
                # Windows/Linux: pyttsx3 (bereits installiert)
                import pyttsx3

                engine = pyttsx3.init()
                engine.setProperty("rate", int(175 * getattr(self, "voice_speed", 1.0)))
                engine.say(message)
                engine.runAndWait()
        except Exception as e:
            print(f"Fehler bei Sprachausgabe: {str(e)}")

    def narrate_focus(self, message):
        """Ansage für Fokuswechsel, unabhängig von VOICE_ENABLED"""
        self.say(message, force=True)

    def update_accessibility(self):
        """Aktiviert/Deaktiviert alle Barrierefreiheits-Features"""
        # Für alle Widgets
        for widget in self.findChildren(QWidget):
            if isinstance(widget, (QPushButton, QSpinBox, QComboBox, QLineEdit)):
                widget.setAccessibleName(widget.text() if self.voice_enabled else "")
                widget.setAccessibleDescription(
                    "" if not self.voice_enabled else widget.toolTip()
                )

            # ToolTips nur bei aktiver Sprachausgabe
            widget.setToolTip(
                "" if not self.voice_enabled else widget.property("tooltip_text")
            )

