    def check_shortcut_conflicts(self):
        from PyQt5.QtGui import QKeySequence

        print("Belegte Shortcuts:")
        for shortcut in self.findChildren(QShortcut):
            print(f"{shortcut.key().toString()} -> {shortcut.parent()}")

    ### neu mit Ergänzung für Signatur Mausklick Formen und Bildauswahl
    def eventFilter(self, obj, event):
        try:
            # === macOS Close Event Handling ===
            if (
                event.type() == QEvent.Close
                and platform.system() == "Darwin"
                and obj == self
            ):

                self.safe_quit()
                return True  # Event wurde behandelt

            # === BESTEHENDE EVENT HANDLING LOGIK ===

            # 0. Escape-Taste behandeln wenn Suche aktiv ist
            if (
                event.type() == QEvent.KeyPress
                and event.key() == Qt.Key_Escape
                and hasattr(self, "search_active")
                and self.search_active
            ):

                self.close_search()
                return True

            # 1. Zoom-Shortcuts während Suche KOMPLETT blockieren
            if (
                event.type() == QEvent.KeyPress
                and self._is_in_search_mode
                and event.modifiers() == Qt.ControlModifier
                and event.key() in [Qt.Key_1, Qt.Key_2, Qt.Key_3]
            ):

                print("Zoom shortcut blocked during search")
                self.say("Zoom während Suche nicht möglich")
                return True  # Event komplett blockieren

            # 2. Such-Shortcut während Zoom blockieren
            if (
                event.type() == QEvent.KeyPress
                and self._is_in_zoom_mode
                and event.modifiers() == Qt.ControlModifier
                and event.key() == Qt.Key_S
            ):

                print("Search shortcut blocked during zoom")
                self.say("Bitte zuerst Zoom beenden")
                return True  # Event komplett blockieren

            # 3. Tastendrücke in GraphicsView abfangen während Suche aktiv
            if (
                event.type() == QEvent.KeyPress
                and obj in [self.graphics_view, self.graphics_view.viewport()]
                and hasattr(self, "search_active")
                and self.search_active
            ):

                # Tastendruck an Suchleiste weiterleiten
                QApplication.sendEvent(self.search_bar, event)
                return True  # Event behandeln

            # 4. Existierende Tastendruck-Umleitung
            if (
                event.type() == QEvent.KeyPress
                and obj in [self.graphics_view, self.graphics_view.viewport()]
                and self._is_in_search_mode
            ):

                QApplication.sendEvent(self.search_bar, event)
                return True

            # 5. Existierende Navigation
            if (
                hasattr(self, "page_spin")
                and obj == self.page_spin
                and event.type() == QEvent.KeyPress
                and event.key() in (Qt.Key_Return, Qt.Key_Enter)
            ):

                self.go_to_page(self.page_spin.value())
                return True

            #  6. Blockiere horizontales Scrollen in allen Zoom-Modi
            if event.type() == QEvent.Wheel and obj in [
                self.graphics_view.viewport(),
                self.graphics_view,
            ]:

                wheel_event = event
                # Horizontales Scrollen komplett blockieren
                if wheel_event.angleDelta().x() != 0:
                    return True  # Event blockieren

            # 7. Klick auf leere Fläche im Signatur-Modus bewegt Signatur
            if (
                self.signature_mode
                and obj in [self.graphics_view, self.graphics_view.viewport()]
                and event.type() == QEvent.MouseButtonPress
                and event.button() == Qt.LeftButton
            ):

                # In Scene-Koordinaten umwandeln
                scene_pos = self.graphics_view.mapToScene(event.pos())

                # Prüfen ob auf Signatur geklickt wurde
                items_at_pos = self.scene.items(scene_pos)
                clicked_on_signature = False

                for item in items_at_pos:
                    if item == self.current_signature_item:
                        clicked_on_signature = True
                        break

                # Wenn NICHT auf Signatur geklickt
                if not clicked_on_signature and self.current_signature_item:
                    print(f"Klick auf leere Fläche: {scene_pos} - ignoriere")
                    # Hier die Position speichern, dann return
                    self.last_mouse_scene_pos = scene_pos

                    # Option 1: Nichts tun - einfach ignorieren (empfohlen)
                    event.ignore()
                    return False  # Lässt Event weiterverarbeiten

            # 8. Enter-Taste im Signatur-Modus
            if (
                event.type() == QEvent.KeyPress
                and event.key() in (Qt.Key_Return, Qt.Key_Enter)
                and self.signature_mode
            ):

                self.save_current_signature()
                return True

            # 9. ESC im Signatur-Modus
            if (
                event.type() == QEvent.KeyPress
                and event.key() == Qt.Key_Escape
                and self.signature_mode
            ):

                self.cancel_current_signature()
                return True

            # 10. Zweiter Klick für Linien/Pfeile im Form-Modus
            if (
                self.form_draw_mode
                and obj in [self.graphics_view, self.graphics_view.viewport()]
                and event.type() == QEvent.MouseButtonPress
                and event.button() == Qt.LeftButton
            ):

                # In Scene-Koordinaten umwandeln
                scene_pos = self.graphics_view.mapToScene(event.pos())

                # Prüfen auf welcher Seite geklickt wurde
                for i, page_item in enumerate(self.page_items):
                    if page_item.contains(scene_pos - page_item.pos()):
                        clicked_page = i
                        break
                else:
                    clicked_page = self.current_page

                # Zweiten Klick behandeln
                self.handle_form_second_click(scene_pos, clicked_page)
                return True

            # 11. Mausklicks speichern (und Bildauswahl aktualisieren)
            if (
                event.type() == QEvent.MouseButtonPress
                and event.button() == Qt.LeftButton
                and obj in [self.graphics_view, self.graphics_view.viewport()]
            ):

                # Mausposition in Scene-Koordinaten speichern
                self.last_mouse_scene_pos = self.graphics_view.mapToScene(event.pos())

                # Prüfen auf welcher Seite geklickt wurde
                for i, page_item in enumerate(self.page_items):
                    if page_item.contains(self.last_mouse_scene_pos - page_item.pos()):
                        self.last_mouse_page = i
                        break
                else:
                    self.last_mouse_page = self.current_page

                # print(f"DEBUG: Mausposition gespeichert - Seite: {self.last_mouse_page + 1}, "
                #     f"Position: ({self.last_mouse_scene_pos.x():.1f}, {self.last_mouse_scene_pos.y():.1f})")

                # --- Zusätzlich: Prüfe, ob auf ein Bild geklickt wurde ---
                items = self.scene.items(self.last_mouse_scene_pos)
                clicked_image = None
                for item in items:
                    if isinstance(item, ImageItem):
                        clicked_image = item
                        break

                if clicked_image:
                    # Alle anderen Bilder deselektieren
                    for other in self.all_image_items:
                        if other != clicked_image:
                            other.setSelected(False)
                    clicked_image.setSelected(True)
                    self.current_image_item = clicked_image
                    self.image_mode = True
                    print(
                        f"DEBUG: Bild {id(clicked_image)} über eventFilter als current gesetzt"
                    )
                # --- Ende der Bildauswahl ---

                # --- Zusätzlich: Prüfe, ob auf eine Form geklickt wurde ---
                items = self.scene.items(self.last_mouse_scene_pos)
                clicked_form = None
                for item in items:
                    if isinstance(item, FormItem):
                        clicked_form = item
                        break

                if clicked_form:
                    for other in self.all_form_items:
                        if other != clicked_form:
                            other.setSelected(False)
                    clicked_form.setSelected(True)
                    self.current_form_item = clicked_form
                    self.form_mode = True
                    print(
                        f"DEBUG: Form {id(clicked_form)} über eventFilter als current gesetzt"
                    )
                # --- Ende der Formauswahl ---

            # 12.

        except Exception as e:
            print(f"EventFilter Fehler: {str(e)}")

        return super().eventFilter(obj, event)

    def event(self, event):
        """Handle all application events"""
        # 1. macOS FileOpen events from Finder
        if sys.platform == "darwin" and event.type() == QEvent.FileOpen:
            self.handle_new_pdf(event.url().toLocalFile())
            return True

        # 2. Shortcut handling
        if event.type() == QEvent.ShortcutOverride:
            if event.modifiers() == Qt.ControlModifier:
                ### if event.key() == Qt.Key_S:
                ### Cmd+S hier nicht behandeln
                ### sonst wird er doppelt ausgeführt was die Suche wieder beendet
                if event.key() == Qt.Key_T:
                    self.force_text_window()
                    return True

        # 3. Fallback to default handling
        return super().event(event)

    def customEvent(self, event):
        """Behandelt Thread-Events sicher"""
        if event.type() == QEvent.User:
            self._cleanup_dialog()
        elif event.type() == QEvent.User + 1:
            print("Thread error occurred")

    def showEvent(self, event):
        """Erzwingt Vollbild und Style-Aktualisierung beim Anzeigen"""
        super().showEvent(event)

        # Verzögert Vollbild erzwingen
        QTimer.singleShot(50, self._ensure_fullscreen)

        self.apply_styles()  # Styles neu anwenden
        QTimer.singleShot(100, self.apply_styles)  # Sicherheitsupdate nach 100ms

    def showMaximized(self):
        """Erzwingt absolut maximierte Bildschirmfüllung"""
        super().showMaximized()

        # Zusätzlich: Maximieren erzwingen
        self.setWindowState(self.windowState() | Qt.WindowMaximized)

        # Für macOS: Vollbild erzwingen
        # if platform.system() == 'Darwin':
        # wurde wieder entfernt wegen Bildschirmflackern auf älteren Mac
        # funktioniert auch so

        # Für Windows/Linux: Maximieren
        # nur bei Bedarf aktivieren
        # QTimer.singleShot(100, lambda: self.showMaximized())

    def _ensure_fullscreen(self):
        """Stellt sicher dass Fenster maximaliert ist"""
        if not self.isMaximized():
            self.showMaximized()

        # Für macOS zusätzliche Optimierung
        if platform.system() == "Darwin":
            self.setWindowState(self.windowState() | Qt.WindowMaximized)

    def suppress_qt_warnings():
        """Redirects Qt warnings to devnull"""
        import warnings
        from PyQt5.QtCore import qInstallMessageHandler

        def qt_message_handler(mode, context, message):
            if "font" in message.lower():
                return
            warnings.warn(message)

        qInstallMessageHandler(qt_message_handler)

    # ShortCut`s
    def keyPressEvent(self, event):
        """Tastatursteuerung für Suche, Drag & Drop und alle Shortcuts"""

        # ----- 1. Escape für Drag & Drop (unverändert) -----
        if event.key() == Qt.Key_Escape and self.drag_enabled:
            self.drag_enabled = False
            self._remove_drop_zones()
            self.update_drag_menu()
            self.say(self.tr("drag_disabled"))
            self.set_zoom_mode("overview")
            return

        # ----- 2. Enter auf fokussiertem Button (unverändert) -----
        if event.key() in (Qt.Key_Return, Qt.Key_Enter):
            focused = QApplication.focusWidget()
            if isinstance(focused, QPushButton):
                focused.click()
                return

        # ----- 3. Spezielle Enter-Behandlung für die Suchleiste -----
        if event.key() in (Qt.Key_Return, Qt.Key_Enter):
            if self.search_bar.hasFocus():
                if event.modifiers() & Qt.ShiftModifier:
                    self.move_to_previous_result()
                else:
                    if (
                        not hasattr(self, "last_search_term")
                        or self.search_bar.text() != self.last_search_term
                    ):
                        self.execute_search()
                    else:
                        self.move_to_next_result()
                return

        # ----- 4. Alle anderen Shortcuts (nur wenn kein Eingabefeld fokussiert) -----
        focused_widget = QApplication.focusWidget()
        if isinstance(focused_widget, (QLineEdit, QSpinBox, QTextEdit)):
            super().keyPressEvent(event)
            return

        modifiers = event.modifiers()
        key = event.key()

        # ---------- Ctrl + Buchstabe ----------
        if modifiers == Qt.ControlModifier:
            if key == Qt.Key_F:
                self.toggle_search()
            elif key == Qt.Key_T:
                self.force_text_window()
            elif key == Qt.Key_O:
                self.open_file_dialog()
            elif key == Qt.Key_W:
                self.close_current_pdf()
            elif key == Qt.Key_Q:
                self.safe_quit()
            elif key == Qt.Key_P:
                self.print_pdf()
            elif key == Qt.Key_B:
                self.add_bookmark_current_page()
            elif key == Qt.Key_R:
                self.perform_ocr()
            elif key == Qt.Key_C:
                self._handle_copy()
            elif key == Qt.Key_V:
                self._handle_paste()
            elif key == Qt.Key_1:
                self.set_zoom_mode("page")
            elif key == Qt.Key_2:
                self.set_zoom_mode("two_pages")
            elif key == Qt.Key_3:
                self.set_zoom_mode("overview")
            else:
                super().keyPressEvent(event)
            return

        # ---------- Ctrl + Shift + Buchstabe ----------
        if modifiers == (Qt.ControlModifier | Qt.ShiftModifier):
            if key == Qt.Key_S:
                self.save_as()
            elif key == Qt.Key_P:
                self.protect_pdf()
            elif key == Qt.Key_B:
                self.open_bookmark_manager()
            elif key == Qt.Key_D:
                self.delete_pages()
            elif key == Qt.Key_E:
                self.extract_pages()
            elif key == Qt.Key_I:
                self.insert_pages()
            elif key == Qt.Key_M:
                self.move_pages()
            elif key == Qt.Key_J:
                self.merge_pdfs()
            elif key == Qt.Key_R:
                self.rotate_current_page()
            elif key == Qt.Key_T:
                self._insert_text_from_menu()
            elif key == Qt.Key_X:
                self._insert_cross_from_menu()
            elif key == Qt.Key_1:
                self._insert_signature_from_menu(1)
            elif key == Qt.Key_2:
                self._insert_signature_from_menu(2)
            elif key == Qt.Key_L:
                self._insert_form_from_menu("line")
            elif key == Qt.Key_A:
                self._insert_form_from_menu("arrow")
            elif key == Qt.Key_W:
                self._add_fullpage_text_watermark()
            elif key == Qt.Key_Num:  # Num für Seitenzahlen
                self._add_page_numbers()
            elif key == Qt.Key_Down:
                self.next_bookmark()
            elif key == Qt.Key_Up:
                self.prev_bookmark()
            elif key == Qt.Key_0:
                self.normalize_current_page()
            elif key == Qt.Key_D:
                self.toggle_dark_mode()
            else:
                super().keyPressEvent(event)
            return

        # ---------- Ctrl + Alt + Buchstabe ----------
        if modifiers == (Qt.ControlModifier | Qt.AltModifier):
            if key == Qt.Key_K:
                self._open_password_manager()
            elif key == Qt.Key_P:
                self.print_now()
            elif key == Qt.Key_R:
                self.rotate_all_pages()
            elif key == Qt.Key_I:
                self.open_metadata_dialog()
            elif key == Qt.Key_E:
                self.export_to_pages()
            elif key == Qt.Key_W:
                self.export_to_word()
            elif key == Qt.Key_T:
                self.export_to_text()
            elif key == Qt.Key_X:
                self.extract_images()
            elif key == Qt.Key_N:
                self.nup_pdf()
            elif key == Qt.Key_A:
                if sys.platform == "darwin":
                    self.convert_to_pdfa()
            elif key == Qt.Key_F:
                self.flatten_pdf()
            elif key == Qt.Key_L:
                self.overlay_pdf()
            elif key == Qt.Key_O:
                self.optimize_pdf()
            elif key == Qt.Key_C:
                self.crop_pdf()
            elif key == Qt.Key_S:
                self.change_page_size()
            elif key == Qt.Key_0:
                self.normalize_all_pages()
            else:
                super().keyPressEvent(event)
            return

        # ---------- Ctrl + Alt + Shift + Buchstabe ----------
        if modifiers == (Qt.ControlModifier | Qt.AltModifier | Qt.ShiftModifier):
            if key == Qt.Key_O:
                self.open_ocr_settings_dialog()
            elif key == Qt.Key_S:
                self.open_signature_settings()
            elif key == Qt.Key_F:
                self.open_filename_settings()
            elif key == Qt.Key_E:
                self.export_all_settings()
            elif key == Qt.Key_I:
                self.import_all_settings()
            elif key == Qt.Key_W:
                self._add_fullpage_image_watermark()
            else:
                super().keyPressEvent(event)
            return

        # ---------- Funktionstasten ----------
        if modifiers == Qt.NoModifier:
            if key == Qt.Key_F1:
                menubar = self.menuBar()
                if menubar:
                    menubar.setActiveAction(menubar.actions()[0])
                return
            elif key == Qt.Key_F2:
                self.toggle_voice()
                return

        # ---------- Alles andere ----------
        super().keyPressEvent(event)

    def add_temp_file(self, file_path):
        """Delegiert an base_window"""
        return self.base_window.add_temp_file(file_path)

    def remove_temp_file(self, file_path):
        """Delegiert an base_window"""
        return self.base_window.remove_temp_file(file_path)

    def cleanup_temp_files(self):
        """Delegiert an base_window"""
        return self.base_window.cleanup_temp_files()

    def open_user_data_folder(self):
        """
        Öffnet den User Data Ordner im Datei-Explorer / Finder.
        Zeigt den Pfad in der Statusleiste an.
        """
        # User Data Ordner ermitteln
        if getattr(sys, "frozen", False):
            user_base = Config.get_user_data_dir()
        else:
            user_base = os.path.join(os.path.dirname(__file__), "test_user_data")
            os.makedirs(user_base, exist_ok=True)

        if not user_base or not os.path.exists(user_base):
            self.statusBar().showMessage("⚠️ User data folder not found", 3000)
            return

        # Pfad in der Statusleiste anzeigen
        self.statusBar().showMessage(f"📂 {user_base}", 5000)

        # Ordner im Datei-Explorer öffnen
        try:
            if platform.system() == "Windows":
                os.startfile(user_base)
            elif platform.system() == "Darwin":  # macOS
                subprocess.Popen(["open", user_base])
            else:  # Linux
                subprocess.Popen(["xdg-open", user_base])
        except Exception as e:
            # Fallback: Pfad in Statusleiste anzeigen
            self.statusBar().showMessage(
                f"📂 {user_base} (Could not open folder)", 5000
            )
            print(f"📂 User Data Folder: {user_base}")

