    def clear_recent_paths(self):
        """Löscht alle gespeicherten Pfade nach Bestätigung"""
        if self.recent_paths.is_empty():
            self.say(self.tr("recent_empty"))
            return

        dialog = myUniversalDialog(
            self,
            title=self.tr("recent_clear_title"),
            message=self.tr("recent_clear_confirm"),
            buttons=[
                (self.tr("btn_clear"), "danger", "clear"),
                (self.tr("btn_cancel"), "secondary", "cancel"),
            ],
            icon_type="",
            voice_message=self.tr("recent_clear_confirm"),
        )
        dialog.exec_()

        if dialog.result_value == "clear":
            self.recent_paths.clear()
            self.update_recent_menu()
            self.say(self.tr("recent_cleared"))

    def get_recent_start_directory(self, default=None):
        """Gibt das Startverzeichnis für Dateidialoge zurück"""
        return self.recent_paths.get_start_directory(default)

    # ===== METHODEN FÜR DIE UNTERMENÜS =====

    def show_recent_dirs_submenu(self):
        """Zeigt das Untermenü für Verzeichnisse"""
        # Dynamisches Menü erstellen
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #3D3D3D;
                color: #E0E0E0;
                border: 1px solid #555555;
                min-width: 300px;
            }
            QMenu::item:selected {
                background-color: #1565C0;
            }
        """)

        if not self.recent_paths.is_enabled():
            action = QAction(self.tr("recent_tracking_disabled"), self)
            action.setEnabled(False)
            menu.addAction(action)
        else:
            dirs = self.recent_paths.get_directories_with_display_names(max_items=10)
            if dirs:
                for path, display_name, index in dirs:
                    action = QAction(
                        qta.icon("fa5s.folder"), f"{index}. {display_name}", self
                    )
                    action.setToolTip(path)
                    action.triggered.connect(
                        lambda checked, p=path: self.open_recent_directory(p)
                    )
                    menu.addAction(action)

                menu.addSeparator()

                # Standard-Verzeichnis anzeigen
                default_dir = self.recent_paths.get_default_directory()
                if default_dir:
                    default_action = QAction(
                        qta.icon("fa5s.check-circle", color="#4CAF50"),
                        self.tr(
                            "recent_default_current", os.path.basename(default_dir)
                        ),
                        self,
                    )
                    default_action.setEnabled(False)
                    default_action.setToolTip(default_dir)
                    menu.addAction(default_action)
            else:
                empty_action = QAction(self.tr("recent_no_directories"), self)
                empty_action.setEnabled(False)
                menu.addAction(empty_action)

        # Menü an der Position des Actions anzeigen
        menu.exec_(QCursor.pos())

    def show_recent_files_submenu(self):
        """Zeigt das Untermenü für Dateien"""
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #3D3D3D;
                color: #E0E0E0;
                border: 1px solid #555555;
                min-width: 300px;
            }
            QMenu::item:selected {
                background-color: #1565C0;
            }
        """)

        if not self.recent_paths.is_enabled():
            action = QAction(self.tr("recent_tracking_disabled"), self)
            action.setEnabled(False)
            menu.addAction(action)
        else:
            files = self.recent_paths.get_files_with_display_names(max_items=10)
            if files:
                for path, display_name, index in files:
                    action = QAction(
                        qta.icon("fa5s.file-pdf"), f"{index}. {display_name}", self
                    )
                    action.setToolTip(path)
                    action.triggered.connect(
                        lambda checked, p=path: self.open_recent_file(p)
                    )
                    menu.addAction(action)
            else:
                empty_action = QAction(self.tr("recent_no_files"), self)
                empty_action.setEnabled(False)
                menu.addAction(empty_action)

        # Menü an der Position des Actions anzeigen
        menu.exec_(QCursor.pos())

    def update_recent_menu(self):
        """Aktualisiert die Recent-Menüs (für Kompatibilität)"""
        # Die Untermenüs werden dynamisch erstellt, daher nichts zu tun
        pass

    def open_recent_directory(self, directory):
        """
        Öffnet den Dateidialog mit einem bestimmten Verzeichnis
        """
        if not os.path.exists(directory):
            self.recent_paths.remove_directory(directory)
            self.say(self.tr("recent_directory_not_found"))
            return

        # Dateidialog mit diesem Verzeichnis öffnen
        if not self.check_for_unsaved_changes("open_new_pdf"):
            return

        path, _ = QFileDialog.getOpenFileName(
            self,
            self.tr("btn_open"),
            directory,
            "PDF Dateien (*.pdf)",
            options=(
                QFileDialog.Options()
                if sys.platform == "darwin"
                else QFileDialog.DontUseNativeDialog
            ),
        )

        if path:
            self.recent_paths.add_both(path)
            self._load_pdf_safely(path)

    def open_recent_file(self, filepath):
        """
        Öffnet eine PDF-Datei direkt aus der Recent-Liste
        """
        if not os.path.exists(filepath):
            self.recent_paths.remove_file(filepath)
            self.say(self.tr("recent_file_not_found"))
            return

        if not filepath.lower().endswith(".pdf"):
            # Nicht-PDF-Datei: Nachfragen
            reply = QMessageBox.question(
                self,
                self.tr("recent_open_file"),
                self.tr("recent_open_file_question", os.path.basename(filepath)),
                QMessageBox.Yes | QMessageBox.No,
            )
            if reply != QMessageBox.Yes:
                return

        self.recent_paths.add_both(filepath)
        self._load_pdf_safely(filepath)

    def show_recent_paths_dialog(self):
        """Zeigt den Dialog zur Verwaltung der Recent Paths"""
        dialog = RecentPathsDialog(self, self.recent_paths)

        # Dialog modal anzeigen
        if dialog.exec_() == QDialog.Accepted:
            selected_path = dialog.get_selected_path()
            if selected_path:
                if os.path.isdir(selected_path):
                    # Verzeichnis: Dateidialog öffnen
                    self.open_recent_directory(selected_path)
                elif os.path.isfile(selected_path) and selected_path.lower().endswith(
                    ".pdf"
                ):
                    # PDF-Datei: direkt laden
                    self.recent_paths.add_both(selected_path)
                    self._load_pdf_safely(selected_path)
                elif os.path.isfile(selected_path):
                    # Andere Datei: Nachfragen
                    reply = QMessageBox.question(
                        self,
                        self.tr("recent_open_file"),
                        self.tr(
                            "recent_open_file_question", os.path.basename(selected_path)
                        ),
                        QMessageBox.Yes | QMessageBox.No,
                    )
                    if reply == QMessageBox.Yes:
                        self.recent_paths.add_both(selected_path)
                        self._load_pdf_safely(selected_path)

    ###=======================================
    ### Aktionen im Menü Datei - übersetzt
    ###=======================================

    def open_file_dialog(self):
        """Verwendet den nativen Dateidialog mit korrektem Startpfad"""
        if not self.check_for_unsaved_changes("open_new_pdf"):
            return

        # Startverzeichnis bestimmen (nur Verzeichnisse, keine Dateien)
        start_dir = self.recent_paths.get_start_directory()

        # Wenn kein Verzeichnis in Recent, Standard verwenden
        if not start_dir or not os.path.exists(start_dir):
            start_dir = os.path.expanduser("~/Documents")

        # Nativen Dialog anzeigen
        path, _ = QFileDialog.getOpenFileName(
            self,
            self.tr("btn_open"),
            start_dir,
            "PDF Dateien (*.pdf)",
            options=(
                QFileDialog.Options()
                if sys.platform == "darwin"
                else QFileDialog.DontUseNativeDialog
            ),
        )

        if path:
            # Beides speichern: Verzeichnis für später, Datei für Recent-Dialog
            self.recent_paths.add_both(path)
            self.update_recent_menu()
            self._load_pdf_safely(path)

    def handle_new_pdf(self, pdf_path):
        """Zentrale PDF-Behandlung für alle Öffnen-Methoden"""
        if not self.check_for_unsaved_changes("open_new_pdf"):
            return

        self.pdf_path = pdf_path
        self.current_page = 0

        # Sicherstellen, dass Hauptfenster bereit ist
        self.show()
        self.raise_()
        self.activateWindow()
        QApplication.processEvents()

        # Ladevorgang starten
        self.load_pdf()

    ### PDF Laden mit Fortschrittsanzeige
    ### und Passwortfunktion
    def load_pdf(self, pdf_path=None, password=None):
        """Lädt PDF mit optionalem Passwort (vermeidet temporäre Kopie)"""
        if not pdf_path:
            pdf_path = self.pdf_path

        if not pdf_path or not os.path.exists(pdf_path):
            self.handle_pdf_error(self.tr("pdf_not_found_format", pdf_path))
            return False

        self._clear_all_overlays()

        try:
            doc = fitz.open(pdf_path)

            if doc.is_encrypted or doc.needs_pass:
                if password:
                    if doc.authenticate(password):
                        return self._load_pdf_from_doc(doc, pdf_path, password)
                    else:
                        doc.close()
                        return self._handle_password_protected(pdf_path, None)
                else:
                    doc.close()
                    saved_password = PDFPasswordManager.get_saved_password(pdf_path)
                    return self._handle_password_protected(pdf_path, saved_password)

            doc.close()
            return self._load_pdf_direct(pdf_path)

        except Exception as e:
            self.handle_pdf_error(self.tr("error_pdf_load_format", str(e)))
            return False

    def _create_loading_dialog(self):
        """Erstellt einen einheitlichen Lade-Dialog"""
        dialog = QDialog(self)
        dialog.setWindowTitle(self.tr("progress_loading"))
        dialog.setWindowModality(Qt.WindowModal)
        dialog.setFixedSize(400, 200)
        dialog.setStyleSheet("background-color: #222222;")
        dialog.setWindowFlags(
            Qt.Window
            | Qt.CustomizeWindowHint
            | Qt.WindowTitleHint
            | Qt.WindowStaysOnTopHint
        )

        layout = QVBoxLayout()
        layout.setContentsMargins(15, 15, 15, 15)

        header = QWidget()
        header_layout = QHBoxLayout(header)
        header_layout.setContentsMargins(0, 0, 0, 15)

        if os.path.exists(Config.IMAGE_PATH):
            logo_label = QLabel()
            logo_pixmap = QPixmap(Config.IMAGE_PATH).scaled(
                100, 100, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            logo_label.setPixmap(logo_pixmap)
            header_layout.addWidget(logo_label)

        title_label = QLabel(self.tr("app_name"))
        title_label.setStyleSheet(
            "QLabel { color: white; font-size: 20px; font-weight: bold; padding: 5px; }"
        )
        header_layout.addWidget(title_label, 1, Qt.AlignCenter)

        if os.path.exists(Config.APP_ICON_PATH):
            icon_label = QLabel()
            icon_pixmap = QPixmap(Config.APP_ICON_PATH).scaled(
                50, 50, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            icon_label.setPixmap(icon_pixmap)
            header_layout.addWidget(icon_label)

        layout.addWidget(header)

        progress_bar = QProgressBar()
        progress_bar.setRange(0, 100)
        progress_bar.setValue(0)
        progress_bar.setTextVisible(False)
        progress_bar.setFixedHeight(10)
        progress_bar.setStyleSheet("""
            QProgressBar {
                border: 1px solid #444;
                border-radius: 2px;
                background: #000;
                height: 6px;
            }
            QProgressBar::chunk {
                background-color: #1976D2;
                border-radius: 1px;
                width: 4px;
            }
        """)
        layout.addWidget(progress_bar)

        loading_label = QLabel(self.tr("progress_preparing"))
        loading_label.setAlignment(Qt.AlignCenter)
        loading_label.setStyleSheet("color: white; font-size: 12px;")
        layout.addWidget(loading_label)

        dialog.setLayout(layout)
        return dialog, progress_bar, loading_label

    def _load_pdf_from_doc(self, doc, pdf_path, password):
        """Lädt PDF direkt aus authentifiziertem Dokument (keine temporäre Datei)"""
        try:
            self.pdf_path = pdf_path
            self.current_password = password
            self.current_doc = doc  # Dokument speichern
            self.total_pages = doc.page_count
            self.page_pixmaps = []
            self.page_rects = []

            # Lade-Dialog anzeigen
            loading_dialog, progress_bar, loading_label = self._create_loading_dialog()
            loading_dialog.show()
            QApplication.processEvents()

            # Zoom-Faktor wie im PDFLoaderThread berechnen
            viewer_width = self.graphics_view.viewport().width()
            first_page = doc[0]
            zoom_x = viewer_width / first_page.rect.width
            zoom_y = zoom_x
            mat = fitz.Matrix(zoom_x, zoom_y)

            for i in range(self.total_pages):
                page = doc.load_page(i)
                pix = page.get_pixmap(matrix=mat)

                # QImage erstellen (wie im Thread)
                img = QImage(
                    pix.samples, pix.width, pix.height, pix.stride, QImage.Format_RGB888
                ).convertToFormat(QImage.Format_ARGB32)

                # Dark Mode anwenden (exakt die Logik aus dem Thread)
                if self.dark_mode:
                    if self.invert_mode == "classic":
                        img.invertPixels(QImage.InvertRgb)
                    else:  # 'smart'
                        img = SMART_INVERT_FUNCTION(img, self.gray_threshold)

                pixmap = QPixmap.fromImage(img)
                self.page_pixmaps.append(pixmap)
                self.page_rects.append(page.rect)

                # Fortschritt aktualisieren
                progress = int((i + 1) / self.total_pages * 100)
                loading_label.setText(f"Seite {i+1}/{self.total_pages}")
                progress_bar.setValue(progress)
                QApplication.processEvents()

            loading_dialog.accept()

            # Ergebnis an die Anzeige übergeben
            self._display_pdf(
                {
                    "page_pixmaps": self.page_pixmaps,
                    "page_rects": self.page_rects,
                    "total_pages": self.total_pages,
                    "zoom_x": zoom_x,
                    "zoom_y": zoom_y,
                }
            )

            filename = os.path.basename(pdf_path)
            self.setWindowTitle(f"{self.tr('app_title')} - {filename}")

            return True

        except Exception as e:
            if doc:
                doc.close()
            self.current_doc = None
            self.handle_pdf_error(self.tr("error_pdf_load_format", str(e)))
            return False

    def _load_pdf_direct(self, pdf_path):
        """Lädt PDF ohne Passwortprüfung"""
        t0 = time.time()
        try:
            # PDF-Pfad sofort aktualisieren
            self.pdf_path = pdf_path
            # Alte Ressourcen bereinigen
            self._cleanup_loading_resources()

            # Lade-Dialog erstellen
            self.loading_dialog = QDialog(self)
            # "PDF wird geladen..."
            self.loading_dialog.setWindowTitle(self.tr("progress_loading"))
            self.loading_dialog.setWindowModality(Qt.WindowModal)
            self.loading_dialog.setFixedSize(400, 200)
            self.loading_dialog.setStyleSheet("background-color: #222222;")

            flags = (
                Qt.Window
                | Qt.CustomizeWindowHint
                | Qt.WindowTitleHint
                | Qt.WindowStaysOnTopHint
            )
            self.loading_dialog.setWindowFlags(flags)

            # Layout mit Header und Progress-Bar
            layout = QVBoxLayout()
            layout.setContentsMargins(15, 15, 15, 15)

            # Header Bereich
            header = QWidget()
            header_layout = QHBoxLayout(header)
            header_layout.setContentsMargins(0, 0, 0, 15)

            # Logo (links)
            if os.path.exists(Config.IMAGE_PATH):
                self.logo_label = QLabel()
                logo_pixmap = QPixmap(Config.IMAGE_PATH).scaled(
                    100, 100, Qt.KeepAspectRatio, Qt.SmoothTransformation
                )
                self.logo_label.setPixmap(logo_pixmap)
                header_layout.addWidget(self.logo_label)

            # App Name (zentriert)
            self.title_label = QLabel(self.tr("app_name"))
            self.title_label.setStyleSheet("""
                QLabel {
                    color: white;
                    font-size: 20px;
                    font-weight: bold;
                    padding: 5px;
                }
            """)
            header_layout.addWidget(self.title_label, 1, Qt.AlignCenter)

            # App Icon (rechts)
            if os.path.exists(Config.APP_ICON_PATH):
                self.icon_label = QLabel()
                icon_pixmap = QPixmap(Config.APP_ICON_PATH).scaled(
                    50, 50, Qt.KeepAspectRatio, Qt.SmoothTransformation
                )
                self.icon_label.setPixmap(icon_pixmap)
                header_layout.addWidget(self.icon_label)

            layout.addWidget(header)

            # Progress-Bar
            self.progress_bar = QProgressBar()
            self.progress_bar.setRange(0, 100)
            self.progress_bar.setValue(0)
            self.progress_bar.setTextVisible(False)
            self.progress_bar.setStyleSheet("""
                QProgressBar {
                    border: 1px solid #444444;
                    border-radius: 2px;
                    background: #000000;
                    height: 6px;
                }
                QProgressBar::chunk {
                    background-color: #1976D2;
                    border-radius: 1px;
                    width: 4px;
                }
            """)
            self.progress_bar.setFixedHeight(10)
            layout.addWidget(self.progress_bar)

            # Status Label
            # "Vorbereitung..."
            self.loading_label = QLabel(self.tr("progress_preparing"))
            self.loading_label.setAlignment(Qt.AlignCenter)
            self.loading_label.setStyleSheet("color: white; font-size: 12px;")
            layout.addWidget(self.loading_label)

            self.loading_dialog.setLayout(layout)

            # Anzeigen
            if sys.platform == "darwin":
                self.loading_dialog.show()
                QApplication.processEvents()  # Event-Loop aktualisieren
            else:
                self.loading_dialog.show()

            # Lade-Thread starten
            self.pdf_loader = PDFLoaderThread(
                pdf_path,
                self.dark_mode,
                self.width(),
                self.invert_mode,
                self.gray_threshold,
            )
            self.pdf_loader.progress_updated.connect(self._update_loading_progress)
            self.pdf_loader.finished.connect(self._handle_loading_finished)

            self.pdf_loader.start()
            self.current_doc = None  # Wichtig: kein dauerhaftes Dokument
            self.current_password = None

            print(f"PDF geladen: {self.pdf_path}")
            print(f"[TIMING] Zeit für das Laden der PDF: {time.time()-t0:.3f}s")
            return True

        except Exception as e:
            # "Fehler beim Laden der PDF: {0}"
            self.handle_pdf_error(self.tr("error_pdf_load_format", str(e)))
            return False

    def handle_pdf_error(self, error_msg):
        """Behandelt PDF-Fehler einheitlich"""
        print(f"PDF Error: {error_msg}")

        dialog = myUniversalDialog(
            self,
            # "Fehler"
            title=self.tr("error"),
            message=error_msg,
            buttons=[(self.tr("btn_ok"), "primary", "ok")],
            icon_type="error",
            # "Es ist ein Fehler aufgetreten"
            voice_message=self.tr("error_occurred"),
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()

        # Zurücksetzen des Lade-Dialogs falls vorhanden
        self._cleanup_loading_resources()

    def _handle_password_protected(self, pdf_path, saved_password=None):
        dialog = PasswordDialog(self, pdf_path, saved_password)
        result = dialog.exec_()

        if result == QDialog.Accepted:
            if dialog.action == "open":
                return self._open_encrypted_directly(
                    pdf_path, dialog.password, dialog.save_checkbox.isChecked()
                )
            elif dialog.action == "remove":
                return self._remove_password_and_open(pdf_path, dialog.password)
            elif dialog.action == "use_saved":
                return self._open_encrypted_directly(
                    pdf_path, dialog.password, save_password=False
                )
            elif dialog.action == "manage":
                enhanced_dialog = EnhancedPasswordManagerDialog(self)
                enhanced_dialog.exec_()
                return False
            return False
        else:
            self._reset_after_password_cancel(pdf_path)
            return False

    def _reset_after_password_cancel(self, pdf_path):
        """Setzt den Zustand zurück, wenn Passwort-Dialog abgebrochen wurde"""
        # Wichtig: pdf_path zurücksetzen, damit Export-Prüfung greift
        if hasattr(self, "pdf_path") and self.pdf_path == pdf_path:
            self.pdf_path = None

        # Eventuelle temporäre Dateien bereinigen
        if hasattr(self, "temp_pdf_path") and self.temp_pdf_path:
            try:
                if os.path.exists(self.temp_pdf_path):
                    os.unlink(self.temp_pdf_path)
                self.remove_temp_file(self.temp_pdf_path)
            except:
                pass
            self.temp_pdf_path = None

        # Original-Pfad zurücksetzen
        self.original_pdf_path = None

        # Fenstertitel zurücksetzen
        self.setWindowTitle(self.tr("app_title"))

    def _open_encrypted_directly(self, pdf_path, password, save_password=False):
        """Öffnet eine verschlüsselte PDF direkt ohne temporäre Datei."""
        try:
            doc = fitz.open(pdf_path)
            if doc.is_encrypted or doc.needs_pass:
                if not doc.authenticate(password):
                    QMessageBox.critical(
                        self, self.tr("error"), self.tr("password_wrong")
                    )
                    doc.close()
                    return False

            # Setze die Pfade und Passwort
            self.pdf_path = pdf_path
            self.original_pdf_path = pdf_path
            self.current_password = password  # <-- Wichtig
            self.temp_pdf_path = None

            if save_password:
                PDFPasswordManager.save_password(pdf_path, password)

            # Lade direkt aus dem authentifizierten Dokument
            success = self._load_pdf_from_doc(doc, pdf_path, password)
            if not success:
                doc.close()
            return success

        except Exception as e:
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('error_occurred')}: {str(e)}"
            )
            return False

    def _open_with_password(self, pdf_path, password, save_password=False):
        """Öffnet PDF mit Passwort"""
        try:
            # Passwort speichern wenn gewünscht
            if save_password:
                PDFPasswordManager.save_password(pdf_path, password)

            # Temporäre entschlüsselte Kopie erstellen
            return self._create_temp_decrypted_copy(pdf_path, password)

        except Exception as e:
            # "Fehler beim Öffnen: {0}"
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('error_occurred')}: {str(e)}"
            )
            return False

    def _create_temp_decrypted_copy(self, pdf_path, password):
        """Erstellt temporäre entschlüsselte Kopie"""
        try:
            # Öffne das verschlüsselte PDF
            doc = fitz.open(pdf_path)

            # Prüfe ob Passwort benötigt wird
            if doc.needs_pass:
                if not doc.authenticate(password):
                    # "Falsches Passwort."
                    QMessageBox.critical(
                        self, self.tr("error"), self.tr("password_wrong")
                    )
                    doc.close()
                    return False

            # Temporäre Datei erstellen
            temp_file = tempfile.NamedTemporaryFile(suffix=".pdf", delete=False)
            temp_filename = temp_file.name
            temp_file.close()

            # Temporäre Datei zur Verwaltung hinzufügen (wird von BaseWindow geerbt)
            self.add_temp_file(temp_filename)

            # Unverschlüsselt speichern
            doc.save(
                temp_filename, encryption=fitz.PDF_ENCRYPT_NONE, garbage=4, deflate=True
            )
            doc.close()

            # Teste ob die temporäre Datei geöffnet werden kann
            test_doc = fitz.open(temp_filename)
            if test_doc.is_encrypted or test_doc.needs_pass:
                test_doc.close()
                self.remove_temp_file(temp_filename)
                os.unlink(temp_filename)
                # "Entschlüsselung fehlgeschlagen."
                QMessageBox.critical(
                    self, self.tr("error"), self.tr("decryption_failed")
                )
                return False
            test_doc.close()

            # Speichere den temporären Pfad
            self.temp_pdf_path = temp_filename
            self.original_pdf_path = pdf_path

            # Temporäre Datei laden
            self.pdf_path = temp_filename

            # Titel aktualisieren
            filename = os.path.basename(pdf_path)
            # "{0} (entschlüsselt)"
            self.setWindowTitle(
                f"{self.tr('app_title')} - {filename} {self.tr('decrypted_suffix')}"
            )

            # PDF normal laden
            return self._load_pdf_direct(temp_filename)

        except Exception as e:
            # "Fehler beim Entschlüsseln: {0}"
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('decryption_error')}: {str(e)}"
            )
            return False

    def _remove_password_and_open(self, pdf_path, password):
        """Entfernt Passwort und speichert unverschlüsselte Kopie"""
        try:
            # Backup erstellen wenn aktiviert
            if self.create_backup:
                backup_path = self.get_backup_filename(pdf_path)
                shutil.copy2(pdf_path, backup_path)
                print(f"Backup der verschlüsselten Datei erstellt: {backup_path}")

            # Speicherort für unverschlüsselte Kopie abfragen
            # Original: default_path = os.path.splitext(pdf_path)[0] + "_unencrypted.pdf"
            default_path = (
                os.path.splitext(pdf_path)[0] + "_unencrypted.pdf"
            )  # bewusst englisch
            path, _ = QFileDialog.getSaveFileName(
                self,
                # "Unverschlüsselte PDF speichern unter"
                self.tr("save_unencrypted"),
                default_path,
                "PDF Dateien (*.pdf)",
            )

            if not path:
                return False

            # Öffne das verschlüsselte PDF
            doc = fitz.open(pdf_path)

            # Prüfe ob Passwort benötigt wird
            if doc.needs_pass:
                if not doc.authenticate(password):
                    # "Falsches Passwort."
                    QMessageBox.critical(
                        self, self.tr("error"), self.tr("password_wrong")
                    )
                    doc.close()
                    return False

            # Unverschlüsselt speichern
            doc.save(path, encryption=fitz.PDF_ENCRYPT_NONE, garbage=4, deflate=True)
            doc.close()

            # Gespeichertes Passwort löschen
            PDFPasswordManager.delete_password(pdf_path)

            # Unverschlüsselte Kopie laden
            self.pdf_path = path
            self.setWindowTitle(f"{self.tr('app_title')} - {os.path.basename(path)}")

            dialog = myUniversalDialog(
                self,
                # "Erfolgreich entschlüsselt"
                title=self.tr("decryption_success"),
                # "PDF wurde entschlüsselt und gespeichert unter:\n\n{0}"
                message=self.tr("decryption_success_message", path),
                # Keine buttons = Default "OK" Button
                icon_type="",
                # "PDF wurde entschlüsselt und gespeichert."
                voice_message=self.tr("decryption_success_voice"),
                text_alignment=Qt.AlignLeft,
            )
            dialog.exec_()
            return self._load_pdf_direct(path)

        except Exception as e:
            # "Fehler beim Entfernen des Passworts: {0}"
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('password_remove_error')}: {str(e)}"
            )
            return False

    def _open_password_manager(self):
        """Öffnet Passwortverwaltung"""
        dialog = EnhancedPasswordManagerDialog(self)
        dialog.exec_()

        # Optional: Nach dem Schließen des Managers können Sie das aktuelle PDF neu laden
        # falls das Passwort für das aktuelle PDF geändert wurde
        if (
            hasattr(self, "original_pdf_path")
            and self.original_pdf_path
            and os.path.exists(self.original_pdf_path)
        ):
            # Prüfen ob Passwort für aktuelles PDF gelöscht wurde
            saved_pw = PDFPasswordManager.get_saved_password(self.original_pdf_path)
            if not saved_pw and hasattr(self, "temp_pdf_path") and self.temp_pdf_path:
                # Wenn Passwort gelöscht wurde und wir eine temporäre Datei haben,
                # könnten wir fragen ob der Benutzer das Original neu laden möchte
                pass  # Optional implementieren

    def _display_pdf(self, result):
        """Lädt PDF in die QGraphicsScene mit Zoom-Optionen"""
        try:
            self.scene.clear()
            self.page_pixmaps = result["page_pixmaps"]
            self.page_rects = result["page_rects"]
            self.total_pages = result["total_pages"]
            self.zoom_x = result["zoom_x"]
            self.zoom_y = result["zoom_y"]

            self.page_items = []

            # Seiten basierend auf Zoom-Modus anordnen
            if self.zoom_mode == "two_pages":
                self._arrange_two_pages()
            elif self.zoom_mode == "overview":
                self._arrange_overview()
            else:
                self._arrange_single_pages()  # Standard (eine Seite unter der anderen)

            # Navigation aktualisieren
            with QSignalBlocker(self.page_spin):
                self.page_spin.setMaximum(self.total_pages)
                self.page_spin.setValue(1)
            # "von {0}"
            self.page_count_label.setText(self.tr("page_count", self.total_pages))

            # Gespeicherte Overlays wiederherstellen
            restored = self._restore_overlay_items()
            if not restored:
                # Keine Overlays – auf erste Seite springen
                self.current_page = 0
                self.apply_zoom()  # Zoom anwenden
                self.scroll_to_page(announce=False)

            # ===== Seiteninfo in Statusleiste anzeigen =====
            QTimer.singleShot(100, self.update_page_info)

            # ------------------------------------------
            # Ausstehenden Sprung zur Position ausführen
            # ------------------------------------------
            if (
                hasattr(self, "_pending_scroll_target")
                and self._pending_scroll_target is not None
            ):
                target_page, target_scene_pos = self._pending_scroll_target
                if target_page < self.total_pages:
                    self.current_page = target_page
                    with QSignalBlocker(self.page_spin):
                        self.page_spin.setValue(target_page + 1)
                    # Kurze Verzögerung, damit die Seite auch wirklich sichtbar ist
                    QTimer.singleShot(
                        100, lambda: self._scroll_to_position(target_scene_pos)
                    )
                self._pending_scroll_target = None
            # -------------------------------------------------------

            # MENÜ-HAKEN AKTUALISIEREN BEIM NEUEN PDF
            self.update_zoom_menu_checks()

            # ---- Automatisches Öffnen des Textfensters, wenn gewünscht ----
            if self._open_text_window_next:
                self._open_text_window_next = False
                # Kurze Verzögerung, damit die GUI sich beruhigt
                QTimer.singleShot(200, self._show_text_window_directly)

        except Exception as e:
            print(f"Display error: {str(e)}")
            raise

    def _update_loading_progress(self, value, message=None):
        """Sicherer Fortschrittsupdate mit optionalem message-Parameter"""
        try:
            if hasattr(self, "progress_bar") and self.progress_bar:
                self.progress_bar.setValue(value)
            if hasattr(self, "loading_label") and self.loading_label:
                if message:
                    self.loading_label.setText(message)
        except RuntimeError:
            pass  # Ignoriere Fehler bei zerstörten Objekten

    def _handle_loading_finished(self, result, success, error_message):
        """Behandelt Ladeabschluss"""
        try:
            self._cleanup_loading_resources()
            if success:
                self._display_pdf(result)
                # Fenstertitel aktualisieren
                if self.pdf_path:
                    filename = os.path.basename(self.pdf_path)
                    self.setWindowTitle(f"{self.tr('app_title')} -- {filename}")
                    self.update_bookmark_menu()

            else:
                # "Laden fehlgeschlagen:\n{0}"
                QMessageBox.critical(
                    self, self.tr("error"), self.tr("load_failed_format", error_message)
                )
        except Exception as e:
            print(f"Fehler beim loading finished: {e}")
            traceback.print_exc()

    def _cleanup_loading_resources(self):
        """Robuste Ressourcenfreigabe mit vollständiger Bereinigung"""
        try:
            # Signalverbindungen trennen
            if hasattr(self, "pdf_loader") and self.pdf_loader:
                try:
                    self.pdf_loader.progress_updated.disconnect()
                    self.pdf_loader.finished.disconnect()
                except:
                    pass

                if self.pdf_loader.isRunning():
                    self.pdf_loader.quit()
                    self.pdf_loader.wait(300)

            # Dialog bereinigen
            if hasattr(self, "loading_dialog") and self.loading_dialog:
                try:
                    if not sip.isdeleted(self.loading_dialog):
                        self.loading_dialog.hide()
                        self.loading_dialog.deleteLater()
                except:
                    pass

            # Status zurücksetzen
            if hasattr(self, "_loading_dialog_visible"):
                self._loading_dialog_visible = False

            # Kopierdaten zurücksetzen
            self.copied_text_data = None
            self.copied_signature_data = None
            self.copied_image_data = None
            self.copied_form_data = None
            # Kreuze haben keine Kopierfunktion

        except Exception as e:
            print(f"Fehler beim Clean up: {e}")
            traceback.print_exc()
        finally:
            # Variablen bereinigen
            for attr in ["pdf_loader", "loading_dialog", "_loading_dialog_ref"]:
                if hasattr(self, attr):
                    delattr(self, attr)

    def _load_pdf_safely(self, pdf_path):
        """Thread-sicheres PDF-Laden"""
        self.pdf_path = pdf_path
        self.current_page = 0

        # Sicherstellen, dass Hauptfenster bereit ist
        self.show()
        self.raise_()
        QApplication.processEvents()

        # Alte Referenzen bereinigen
        if hasattr(self, "pdf_loader") and self.pdf_loader:
            self.pdf_loader.quit()
            self.pdf_loader.wait()

        # Neuen Ladevorgang starten
        self.load_pdf()

    def check_page_visibility(self):
        """Überprüft die Sichtbarkeit aller Seiten"""
        for i in range(self.total_pages):
            page_top = sum(self.page_heights[:i])
            page_bottom = page_top + self.page_heights[i]
            print(f"Page {i+1} - Top: {page_top}, Bottom: {page_bottom}")

    def _get_page_format(self, width_pt, height_pt):
        """
        Erkennt das Seitenformat anhand der Maße in Punkten.
        Verwendet eine großzügige Toleranz für abweichende Größen.
        """
        # Standardformate in Punkten (Breite, Höhe)
        # Sortiert nach Größe für bessere Erkennung
        formats = {
            "A0": (2384, 3370),
            "A1": (1684, 2384),
            "A2": (1191, 1684),
            "A3": (842, 1191),
            "A4": (595, 842),
            "A5": (420, 595),
            "A6": (298, 420),
            "A7": (210, 298),
            "A8": (147, 210),
            "Legal": (612, 1008),
            "Letter": (612, 792),
            "Tabloid": (792, 1224),
            "Executive": (522, 756),
            "Statement": (396, 612),
        }

        # Toleranz in Punkten (großzügig für abweichende Größen)
        tolerance = 20

        # Prüfe ob die Größe einem bekannten Format entspricht
        for name, (w, h) in formats.items():
            # Prüfe beide Ausrichtungen (Hoch- und Querformat)
            if (abs(width_pt - w) < tolerance and abs(height_pt - h) < tolerance) or (
                abs(width_pt - h) < tolerance and abs(height_pt - w) < tolerance
            ):
                # Bei Querformat den Namen mit "(quer)" kennzeichnen
                if abs(width_pt - h) < tolerance and abs(height_pt - w) < tolerance:
                    return f"{name} (quer)"
                return name

        # Wenn kein Standardformat erkannt wurde, benutzerdefiniert
        # Aber prüfe ob es nahe an einem Standardformat liegt (größere Toleranz)
        for name, (w, h) in formats.items():
            if (abs(width_pt - w) < 50 and abs(height_pt - h) < 50) or (
                abs(width_pt - h) < 50 and abs(height_pt - w) < 50
            ):
                # Bei Querformat
                if abs(width_pt - h) < 50 and abs(height_pt - w) < 50:
                    return f"{name} (quer) ≈"
                return f"{name} ≈"  # ≈ für "ungefähr"

        return "Benutzerdefiniert"

    ### -----------------------
    ### PDF Info für Statusliste Navbar und Dialog
    ### ----------------------

    def update_page_info(self):
        """Aktualisiert die Statusleiste mit Seiteninformationen (anhängend)."""
        if (
            not self.pdf_path
            or not self.page_items
            or self.current_page >= len(self.page_items)
        ):
            return

        try:
            # Aktuelle Seite
            current = self.current_page + 1
            total = len(self.page_items)

            # Seitengröße aus dem Dokument holen
            doc = fitz.open(self.pdf_path)
            if self.current_page < len(doc):
                page = doc[self.current_page]
                width_pt = page.rect.width
                height_pt = page.rect.height

                # In mm umrechnen (1 pt = 0.352778 mm)
                width_mm = width_pt * 0.352778
                height_mm = height_pt * 0.352778

                # Format erkennen
                format_name = self._get_page_format(width_pt, height_pt)

                # Seiteninfo-String
                page_info = f" | {format_name} ({width_mm:.1f} x {height_mm:.1f} mm)"

                # Bestehenden Statusleisten-Text holen (ohne unsere Info)
                current_text = self.statusBar().currentMessage()

                # Wenn bereits eine Seiteninfo vorhanden ist, diese entfernen
                # Suche nach " | " am Ende
                if " | " in current_text:
                    # Prüfen ob es unsere Seiteninfo ist (enthält "mm")
                    parts = current_text.rsplit(" | ", 1)
                    if len(parts) == 2 and "mm" in parts[1]:
                        current_text = parts[0]

                # Neue Statusleisten-Nachricht
                new_text = f"{current_text}{page_info}"
                self.statusBar().showMessage(new_text)

            doc.close()
        except Exception as e:
            print(f"Fehler beim Aktualisieren der Seiteninfo: {e}")

    def show_pdf_info(self):
        """Zeigt Informationen über die aktuelle PDF an."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            self._show_no_pdf_dialog()
            return

        try:
            import fitz

            doc = fitz.open(self.pdf_path)

            # Basis-Info als sauberer Block (ohne doppelte \n)
            info_lines = [
                f"Datei: {os.path.basename(self.pdf_path)}",
                f"Seiten: {len(doc)}",
                f"Dateigröße: {self._format_size(os.path.getsize(self.pdf_path))}",
                "",
                "Seitengrößen:",
                "-" * 40,
            ]

            # Seitengrößen sammeln (wie gehabt)
            page_sizes = {}
            for i, page in enumerate(doc):
                width = page.rect.width
                height = page.rect.height
                key = f"{width:.0f}x{height:.0f}"
                if key not in page_sizes:
                    format_name = self._get_page_format(width, height)
                    page_sizes[key] = {
                        "count": 0,
                        "format": format_name,
                        "width": width,
                        "height": height,
                    }
                page_sizes[key]["count"] += 1

            # Größen-Infos anhängen (mit Einrückung)
            for key, data in page_sizes.items():
                info_lines.append(
                    f"  {data['format']} ({data['width']:.0f} x {data['height']:.0f} pt)"
                    f" - {data['count']} Seite(n)"
                )

            doc.close()

            # Alles mit genau EINEM \n verbinden
            info_text = "\n".join(info_lines)

            myUniversalDialog(
                self,
                title=self.tr("pdf_info_title"),
                message=info_text,
                buttons=[(self.tr("btn_ok"), "primary", "ok")],
                icon_type="",
                text_alignment=Qt.AlignLeft,
                selectable_text=True,
                voice_message=self.tr("pdf_info_voice"),
            ).exec_()

        except Exception as e:
            print(f"Fehler beim Anzeigen der PDF-Info: {e}")
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=self.tr("pdf_info_error", str(e)),
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()

