    def save_as(self):
        """Speichert das PDF unter neuem Namen mit optionaler Verschlüsselung"""
        if not self.pdf_path:
            myUniversalDialog(
                self,
                title=self.tr("no_pdf_loaded"),
                message=self.tr("no_pdf_message"),
                icon_type="",
                voice_message=self.tr("no_pdf_loaded"),
            ).exec_()
            return

        # Dateiname
        default_path = self.generate_custom_filename(
            suffixes=[self.tr("filename_copy_suffix")]
        )

        # Auswahldialog
        path, _ = QFileDialog.getSaveFileName(
            self, self.tr("save_as"), default_path, "PDF Dateien (*.pdf)"
        )
        if not path:
            return
        if not path.lower().endswith(".pdf"):
            path += ".pdf"

        has_current_password = (
            hasattr(self, "current_password") and self.current_password
        )
        print(
            f"DEBUG: has_current_password = {has_current_password}, password = {getattr(self, 'current_password', None)}"
        )

        if has_current_password:
            msg = self.tr("password_save_question")
            buttons = [
                (self.tr("password_save_choice_keep"), "primary", "keep", 280),
                (self.tr("password_save_choice_change"), "warning", "change", 250),
                (self.tr("password_save_choice_none"), "danger", "none", 250),
            ]
            dialog = myUniversalDialog(
                self,
                title=self.tr("password_options_title"),
                message=msg,
                buttons=buttons,
                icon_type="",
                text_alignment=Qt.AlignLeft,
                default_button="keep",
            )
            if dialog.exec_() != QDialog.Accepted:
                return
            choice = dialog.result_value
            print(f"DEBUG: choice = {choice}")

            if choice == "keep":
                password = self.current_password
                save_pw = True
                encrypt = True
            elif choice == "change":
                pass_dialog = ProtectPDFDialog(self, self.pdf_path)
                if pass_dialog.exec_() != QDialog.Accepted or not pass_dialog.password:
                    self.say(self.tr("password_cancel"))
                    return
                password = pass_dialog.password
                save_pw = pass_dialog.save_checkbox.isChecked()
                encrypt = True
            else:  # 'none'
                encrypt = False
        else:
            # Kein bestehendes Passwort
            dialog = myUniversalDialog(
                self,
                title=self.tr("encryption_question"),
                message=self.tr("encryption_question"),
                buttons=[
                    (self.tr("encryption_yes"), "success", "yes", 120),
                    (self.tr("encryption_no"), "primary", "no", 120),
                    (self.tr("encryption_cancel"), "danger", "cancel", 120),
                ],
                default_button="no",
                icon_type="",
                text_alignment=Qt.AlignLeft,
                voice_message=self.tr("encryption_question"),
            )
            if dialog.exec_() != QDialog.Accepted:
                self.say(self.tr("save_cancel"))
                return
            choice = dialog.result_value
            if choice == "cancel":
                return
            elif choice == "yes":
                pass_dialog = ProtectPDFDialog(self, self.pdf_path)
                if pass_dialog.exec_() != QDialog.Accepted or not pass_dialog.password:
                    self.say(self.tr("password_cancel"))
                    return
                password = pass_dialog.password
                save_pw = pass_dialog.save_checkbox.isChecked()
                encrypt = True
            else:  # 'no'
                encrypt = False

        try:
            if encrypt:
                if self._protect_pdf_with_password(self.pdf_path, path, password):
                    if save_pw:
                        PDFPasswordManager.save_password(path, password)

                    myUniversalDialog(
                        self,
                        title=self.tr("success"),
                        message=self.tr("save_encrypted", os.path.basename(path)),
                        buttons=[(self.tr("btn_ok"), "success", "ok")],
                        icon_type="",
                        voice_message=self.tr("save_encrypted_voice"),
                        text_alignment=Qt.AlignLeft,
                    ).exec_()

                    # Frage nach Öffnen
                    open_dialog = myUniversalDialog(
                        self,
                        title=self.tr("open_saved_dialog_title"),
                        message=self.tr("open_saved_question"),
                        buttons=[
                            (self.tr("confirm_yes"), "primary", "yes", 120),
                            (self.tr("confirm_no"), "danger", "no", 120),
                        ],
                        icon_type="",
                        text_alignment=Qt.AlignLeft,
                        default_button="yes",
                    )
                    open_dialog.exec_()
                    if open_dialog.result_value == "yes":
                        self.load_pdf(path, password=password)
                else:
                    raise Exception("Verschlüsselung fehlgeschlagen")
            else:
                # Unverschlüsselt speichern
                if has_current_password and choice == "none":
                    # Entschlüsselte Version aus der passwortgeschützten Originaldatei speichern
                    doc = fitz.open(self.pdf_path)
                    doc.authenticate(self.current_password)
                    doc.save(path, encryption=fitz.PDF_ENCRYPT_NONE)
                    doc.close()
                else:
                    shutil.copy2(self.pdf_path, path)
                myUniversalDialog(
                    self,
                    title=self.tr("success"),
                    message=self.tr("save_success", os.path.basename(path)),
                    buttons=[(self.tr("btn_ok"), "success", "ok")],
                    icon_type="",
                    voice_message=self.tr("save_success_voice"),
                    text_alignment=Qt.AlignLeft,
                ).exec_()

            size_kb = os.path.getsize(path) / 1024
            encrypted_str = "Yes" if encrypt else "No"
            print(
                f"PDF gespeichert unter: {path} | original: {self.pdf_path} | Größe: {size_kb:.1f} KB | verschlüsselt: {encrypted_str}"
            )

        except Exception as e:
            error_msg = self.tr("save_error_format", str(e))
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                buttons=[(self.tr("btn_ok"), "success", "ok")],
                icon_type="",
                voice_message=self.tr("save_error"),
            ).exec_()
            print(f"Fehler beim Speichern unter: {e}")
            traceback.print_exc()

    def protect_pdf(self):
        """Schützt das aktuelle PDF mit einem Passwort"""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            myUniversalDialog(
                self,
                title=self.tr("no_pdf_loaded"),
                message=self.tr("no_pdf_message"),
                icon_type="",
                voice_message=self.tr("no_pdf_loaded"),
            ).exec_()
            return

        pw_dialog = ProtectPDFDialog(self, self.pdf_path)
        if pw_dialog.exec_() == QDialog.Accepted and pw_dialog.password:
            try:
                # Dateiname
                output_path = self.generate_custom_filename(
                    is_protected=True, force_new_file=True
                )

                # Falls die Datei bereits existiert, Nummer anhängen (einfache Lösung)
                counter = 1
                base, ext = os.path.splitext(output_path)
                while os.path.exists(output_path):
                    output_path = f"{base}_{counter}{ext}"
                    counter += 1

                password = pw_dialog.password
                save_pw = pw_dialog.save_checkbox.isChecked()

                if self._protect_pdf_with_password(
                    self.pdf_path, output_path, password
                ):
                    if save_pw:
                        PDFPasswordManager.save_password(output_path, password)

                    confirm_dialog = myUniversalDialog(
                        self,
                        title=self.tr("protect_open_title"),
                        message=self.tr(
                            "protect_success", output_path, "*" * len(password)
                        ),
                        buttons=[
                            (self.tr("protect_open"), "danger", "yes"),
                            (self.tr("protect_skip"), "primary", "no"),
                        ],
                        icon_type="",
                        text_alignment=Qt.AlignLeft,
                        voice_message=self.tr("protect_question"),
                        default_button="no",
                    )
                    confirm_dialog.exec_()
                    if confirm_dialog.result_value == "yes":
                        self.close_current_pdf()
                        self.load_pdf(output_path, password=password)
            except Exception as e:
                QMessageBox.critical(
                    self, self.tr("error"), f"{self.tr('protect_error')}: {str(e)}"
                )

    def _protect_pdf_with_password(self, input_path, output_path, password):
        """Verschlüsselt eine PDF mit einem Passwort (input_path kann verschlüsselt sein)"""
        try:
            # Öffne die Eingabedatei – ggf. mit Passwort authentifizieren
            doc = fitz.open(input_path)
            if doc.is_encrypted or doc.needs_pass:
                if not doc.authenticate(password):
                    doc.close()
                    raise Exception(self.tr("password_wrong"))

            # Verschlüsselt speichern (AES-256)
            doc.save(
                output_path,
                encryption=fitz.PDF_ENCRYPT_AES_256,
                user_pw=password,
                owner_pw=None,
                permissions=fitz.PDF_PERM_PRINT | fitz.PDF_PERM_COPY,
                garbage=4,
                deflate=True,
            )
            doc.close()
            return True

        except Exception as e:
            print(f"Fehler beim Verschlüsseln: {str(e)}")
            # Aufräumen, falls teilweise gespeichert
            if os.path.exists(output_path):
                try:
                    os.unlink(output_path)
                except:
                    pass
            raise e

    ### -----------------------------------------
    ### EXPORT (Pages, Word, TXT)
    ### -----------------------------------------
    def export_to_pages(self):
        """Exportiert nach Apple Pages (.rtf) – mit OCR falls nötig."""
        if not self.pdf_path:
            self._show_no_pdf_dialog()
            return
        base_name = os.path.splitext(self.pdf_path)[0]  # ohne Erweiterung
        if self.check_pdf_has_text():
            self._execute_pages_export(self.pdf_path, base_name)
        else:
            self._offer_ocr_and_export("Pages", base_name, self._execute_pages_export)

    def export_to_word(self):
        """Exportiert nach Microsoft Word (.docx) – mit OCR falls nötig."""
        if not self.pdf_path:
            self._show_no_pdf_dialog()
            return
        base_name = os.path.splitext(self.pdf_path)[0]
        if self.check_pdf_has_text():
            self._execute_word_export(self.pdf_path, base_name)
        else:
            self._offer_ocr_and_export("Word", base_name, self._execute_word_export)

    def export_to_text(self):
        """Exportiert als reine Textdatei (.txt) – mit OCR falls nötig."""
        if not self.pdf_path:
            self._show_no_pdf_dialog()
            return
        base_name = os.path.splitext(self.pdf_path)[0]
        if self.check_pdf_has_text():
            self._execute_text_export(self.pdf_path, base_name)
        else:
            self._offer_ocr_and_export("TXT", base_name, self._execute_text_export)

    def _execute_pages_export(self, pdf_path, base_name):
        """Exportiert die PDF (original oder OCR-verbessert) als RTF."""
        try:
            doc = fitz.open(pdf_path)
            output_path = base_name + ".rtf"
            print(f"Starte Pages-Export nach: {output_path}")

            with open(output_path, "w", encoding="utf-8") as f:
                f.write("{\\rtf1\\ansi\\ansicpg1252\n")
                f.write("{\\fonttbl\\f0\\fswiss Helvetica;}\n")
                f.write("\\f0\\fs24\n")
                for page in doc:
                    text = page.get_text("text").replace("\n", "\\par\n")
                    f.write(f"{text}\\par\\par\n")
                f.write("}")

            doc.close()
            self._open_exported_file(output_path, "Pages")
            self.say(self.tr("export_pages_success"))
            # ????????
            print(f"Export nach Pages")

        except Exception as e:
            self.say(self.tr("export_pages_error_format", str(e)))
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('export_pages_error')}:\n{str(e)}"
            )
            print("Export nach Pages fehlgeschlagen")

    def _execute_word_export(self, pdf_path, base_name):
        """Exportiert die PDF (original oder OCR-verbessert) als DOCX."""
        try:
            doc = fitz.open(pdf_path)
            output_path = base_name + ".docx"
            print(f"Starte Word-Export nach: {output_path}")

            from docx import Document

            document = Document()
            for page in doc:
                text = page.get_text("text")
                document.add_paragraph(text)
            document.save(output_path)
            doc.close()

            self._open_exported_file(output_path, "Microsoft Word")
            self.say(self.tr("export_word_success"))
            print(f"Export nach Word erfolgreich")

        except Exception as e:
            self.say(self.tr("export_word_error_format", str(e)))
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('export_word_error')}:\n{str(e)}"
            )
            print(f"Export nach Word fehlgeschlagen")

    def _execute_text_export(self, pdf_path, base_name):
        """Exportiert die PDF (original oder OCR-verbessert) als TXT."""
        try:
            doc = fitz.open(pdf_path)
            output_path = base_name + ".txt"
            print(f"Starte Text-Export nach: {output_path}")

            with open(output_path, "w", encoding="utf-8") as f:
                for page in doc:
                    f.write(page.get_text("text") + "\n\n")
            doc.close()

            self._open_exported_file(output_path, "TextEdit")
            self.say(self.tr("export_text_success"))
            print(f"Export nach TXT erfolgreich")

        except Exception as e:
            self.say(self.tr("export_text_error_format", str(e)))
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('export_text_error')}:\n{str(e)}"
            )
            print(f"Export nach TXT fehlgeschlagen")

    # Gemeinsame 4 Hilfsmethoden für Export
    def _offer_ocr_and_export(self, export_format, base_name, export_callback):
        """
        Zeigt Dialog an und startet OCR, falls gewünscht.
        export_format: "Pages", "Word", "TXT" (für Anzeige)
        base_name: gewünschter Basisname für die Exportdatei (ohne Extension)
        export_callback: Funktion, die (pdf_path, base_name) erwartet
        """
        dialog = myUniversalDialog(
            self,
            title=self.tr("ocr_required"),
            message=self.tr("export_ocr_question_html", export_format),
            buttons=[
                (self.tr("ocr_perform"), "primary", "ocr", 180),
                (self.tr("ocr_later"), "dark", "later", 180),
                (self.tr("btn_cancel"), "danger", "cancel", 180),
            ],
            icon_type="",
            voice_message=self.tr("export_ocr_voice", export_format),
            default_button="ocr",
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()
        if dialog.result_value == "ocr":
            self._run_ocr_for_export(base_name, export_callback)
        elif dialog.result_value == "later":
            self.say(self.tr("export_no_ocr_possible"))

    def _run_ocr_for_export(self, base_name, export_callback):
        """Startet OCR und ruft nach Erfolg export_callback mit temporärer PDF auf."""
        temp_ocr_path = self.generate_custom_filename(
            suffixes="_ocr_temp", update_timestamp=False
        )
        self.ocr_thread = OCRThread(self.pdf_path, temp_ocr_path, self.dark_mode)
        # WICHTIG: Verbindung VOR dem Start
        self.ocr_thread.progress_updated.connect(self._update_ocr_progress)
        self.ocr_thread.finished.connect(
            lambda success, msg: self._on_ocr_for_export_finished(
                success, temp_ocr_path, base_name, export_callback
            )
        )
        # print("DEBUG: progress_updated verbunden")
        self.ocr_thread.start()
        self.show_ocr_progress_dialog()

    def _on_ocr_for_export_finished(
        self, success, ocr_pdf_path, base_name, export_callback
    ):
        """Callback nach OCR: Bei Erfolg Export mit temporärer PDF, dann löschen."""
        self.ocr_in_progress = False
        self._close_progress_dialog()

        if success and os.path.exists(ocr_pdf_path):
            try:
                export_callback(ocr_pdf_path, base_name)
            except Exception as e:
                print(f"Fehler beim Export nach OCR: {e}")
            finally:
                # Temporäre OCR-Datei löschen
                try:
                    os.remove(ocr_pdf_path)
                    self.remove_temp_file(ocr_pdf_path)
                except:
                    pass
        else:
            self.say(self.tr("ocr_failed_export_not_possible"))

    def _open_exported_file(self, file_path, preferred_app=None):
        """Öffnet eine Datei mit einer bevorzugten App (falls vorhanden) oder mit der Standard-App."""
        if not os.path.exists(file_path):
            return

        if sys.platform == "darwin":
            if preferred_app:
                try:
                    subprocess.run(["open", "-a", preferred_app, file_path])
                    return
                except:
                    pass
            subprocess.run(["open", file_path])
        elif sys.platform == "win32":
            if preferred_app == "Microsoft Word" and file_path.endswith(".docx"):
                os.startfile(file_path)
            else:
                os.startfile(file_path)
        else:  # Linux
            subprocess.run(["xdg-open", file_path])

    def export_images(self):
        """Exportiert alle Seiten als PNG/JPEG mit pdf2image."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            self._show_no_pdf_dialog()
            return

        # Prüfen ob pdf2image installiert ist
        try:
            import pdf2image
        except ImportError:
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=self.tr("export_images_pdf2image_missing"),
                text_alignment=Qt.AlignLeft,
                buttons=[(self.tr("btn_ok"), "primary", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()
            return

        dialog = ExportImagesDialog(self)
        if dialog.exec_() != QDialog.Accepted:
            self.say(self.tr("export_images_cancel"))
            return

        settings = dialog.get_data()
        self.say(self.tr("export_images_start"))

        try:
            # Zielordner erstellen
            target_folder = settings["target_folder"]
            if settings["subfolder"]:
                base_name = os.path.splitext(os.path.basename(self.pdf_path))[0]
                target_folder = os.path.join(target_folder, f"{base_name}_bilder")
                os.makedirs(target_folder, exist_ok=True)

            # Fortschritts-Dialog
            total_pages = settings["end_page"] - settings["start_page"] + 1
            progress_dialog = QProgressDialog(
                self.tr("export_images_progress"),
                self.tr("btn_cancel"),
                0,
                total_pages,
                self,
            )
            progress_dialog.setWindowModality(Qt.WindowModal)
            progress_dialog.setMinimumWidth(400)
            progress_dialog.setStyleSheet("""
                QProgressDialog {
                    background-color: #2D2D2D;
                    color: #E0E0E0;
                }
            """)

            # pdf2image Konvertierung
            from pdf2image import convert_from_path

            # Poppler-Pfad für Windows setzen
            poppler_path = None
            if sys.platform == "win32":
                # Versuche Poppler im Script-Verzeichnis zu finden
                poppler_path = os.path.join(Config.SCRIPT_DIR, "poppler", "bin")
                if not os.path.exists(poppler_path):
                    poppler_path = None

            # Seiten konvertieren
            first_page = settings["start_page"]
            last_page = settings["end_page"]

            print(
                f"Konvertiere Seiten {first_page} bis {last_page} mit {settings['dpi']} DPI"
            )

            images = convert_from_path(
                self.pdf_path,
                dpi=settings["dpi"],
                first_page=first_page,
                last_page=last_page,
                poppler_path=poppler_path,
                fmt=settings["format"],
            )

            # Bilder speichern
            for i, image in enumerate(images):
                if progress_dialog.wasCanceled():
                    self.say(self.tr("export_images_cancel"))
                    return

                page_num = first_page + i
                progress_dialog.setLabelText(
                    self.tr("export_images_saving", page_num, total_pages)
                )

                # Dateinamen generieren
                if settings["single_files"]:
                    # Mit führenden Nullen für sortierte Reihenfolge
                    digits = len(str(total_pages))
                    filename = (
                        f"seite_{str(page_num).zfill(digits)}.{settings['format_name']}"
                    )
                else:
                    filename = f"alle_seiten.{settings['format_name']}"

                filepath = os.path.join(target_folder, filename)

                # Bei mehreren Seiten in einer Datei: überschreiben vermeiden
                if not settings["single_files"] and i > 0:
                    base, ext = os.path.splitext(filename)
                    filename = f"{base}_{page_num}{ext}"
                    filepath = os.path.join(target_folder, filename)

                # Qualität für JPEG setzen
                if settings["format"] == "jpeg":
                    image.save(filepath, "JPEG", quality=settings["quality"])
                else:
                    image.save(filepath, settings["format"].upper())

                progress_dialog.setValue(i + 1)
                QApplication.processEvents()

            progress_dialog.close()

            # Erfolgsmeldung
            success_message = self.tr(
                "export_images_success", total_pages, target_folder
            )

            # Hier verwenden wir myUniversalDialog für die Erfolgsmeldung
            result_dialog = myUniversalDialog(
                self,
                title=self.tr("success"),
                message=success_message,
                text_alignment=Qt.AlignLeft,
                buttons=[
                    (self.tr("export_images_open_folder"), "primary", "open"),
                    (self.tr("btn_ok"), "success", "ok"),
                ],
                icon_type="",
                voice_message=self.tr("export_images_complete"),
                default_button="open",
            )
            result_dialog.exec_()

            # Ordner öffnen, wenn der Benutzer "open" gewählt hat
            if result_dialog.result_value == "open":
                if sys.platform == "darwin":
                    subprocess.run(["open", target_folder])
                elif sys.platform == "win32":
                    os.startfile(target_folder)
                else:
                    subprocess.run(["xdg-open", target_folder])

        except Exception as e:
            error_msg = self.tr("export_images_error_format", str(e))
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                text_alignment=Qt.AlignLeft,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()
            print(f"Fehler beim Exportieren der Bilder: {e}")
            traceback.print_exc()

