    def convert_to_pdfa(self):
        """Konvertiert die PDF zu PDF/A (ohne integrierte OCR)."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            self._show_no_pdf_dialog()
            return

        # Prüfen ob ocrmypdf installiert ist
        try:
            import ocrmypdf
        except ImportError:
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=self.tr("pdfa_ocrmypdf_missing"),
                buttons=[(self.tr("btn_ok"), "primary", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()
            return

        dialog = PdfAConvertDialog(self)
        if dialog.exec_() != QDialog.Accepted:
            self.say(self.tr("pdfa_cancel"))
            return

        settings = dialog.get_data()
        self.say(self.tr("pdfa_start"))

        try:
            # Suffix basierend auf dem gewählten Standard
            standard = settings["standard"]  # z.B. "pdfa-2"
            if standard == "pdfa-1":
                suffix = self.tr("filename_pdfa1_suffix")
            elif standard == "pdfa-2":
                suffix = self.tr("filename_pdfa2_suffix")
            elif standard == "pdfa-3":
                suffix = self.tr("filename_pdfa3_suffix")
            else:
                suffix = "_PDFA"  # Fallback

            # Zielpfad mit generate_custom_filename erstellen
            output_path = self.generate_custom_filename(
                suffixes=[suffix], force_new_file=True
            )

            # PDF/A-Konvertierung ohne OCR
            self.pdfa_thread = PDFAThread(self.pdf_path, output_path, settings)
            self.pdfa_thread.progress_updated.connect(self._update_pdfa_progress)
            self.pdfa_thread.finished.connect(self._on_pdfa_finished)

            # Fortschritts-Dialog
            self.pdfa_progress_dialog = QProgressDialog(
                self.tr("pdfa_progress"), self.tr("btn_cancel"), 0, 100, self
            )
            self.pdfa_progress_dialog.setWindowModality(Qt.WindowModal)
            self.pdfa_progress_dialog.setMinimumWidth(400)
            self.pdfa_progress_dialog.setStyleSheet("""
                QProgressDialog {
                    background-color: #2D2D2D;
                    color: #E0E0E0;
                }
            """)
            self.pdfa_progress_dialog.canceled.connect(self._cancel_pdfa_conversion)
            self.pdfa_progress_dialog.show()

            self.pdfa_thread.start()

        except Exception as e:
            error_msg = self.tr("pdfa_error_format", str(e))
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()
            print(f"Fehler bei PDF/A-Konvertierung: {e}")
            traceback.print_exc()

    def _update_pdfa_progress(self, progress, message):
        """Aktualisiert den Fortschritts-Dialog für PDF/A."""
        if hasattr(self, "pdfa_progress_dialog") and self.pdfa_progress_dialog:
            self.pdfa_progress_dialog.setValue(progress)
            if message:
                self.pdfa_progress_dialog.setLabelText(message)

    def _cancel_pdfa_conversion(self):
        """Bricht die PDF/A-Konvertierung ab."""
        if hasattr(self, "pdfa_thread") and self.pdfa_thread:
            self.pdfa_thread.cancel()
            self.say(self.tr("pdfa_cancel"))

    def _on_pdfa_finished(self, success, message, output_path):
        """Behandelt das Ende der PDF/A-Konvertierung."""
        # Fehler immer im Terminal ausgeben
        if not success:
            print(f"PDF/A-Fehler: {message}")
            import traceback

            traceback.print_exc()

        if hasattr(self, "pdfa_progress_dialog") and self.pdfa_progress_dialog:
            self.pdfa_progress_dialog.close()

        if success:
            success_message = self.tr("pdfa_success", output_path)
            confirm_dialog = myUniversalDialog(
                self,
                title=self.tr("success"),
                message=success_message,
                text_alignment=Qt.AlignLeft,
                buttons=[
                    (self.tr("confirm_yes"), "primary", "yes"),
                    (self.tr("confirm_no"), "danger", "no"),
                ],
                icon_type="",
                voice_message=self.tr("pdfa_complete"),
                default_button="yes",
            )
            confirm_dialog.exec_()

            if confirm_dialog.result_value == "yes":
                self.close_current_pdf()
                self.load_pdf(output_path)
        else:
            error_msg = self.tr("pdfa_error_format", message)
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                text_alignment=Qt.AlignLeft,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()

