    ### ------------------------
    ### DRUCKEN
    ### ------------------------

    def print_now(self):
        """Direkt drucken (ohne Dialog) – Windows: Acrobat/Foxit mit /t"""
        if not self.pdf_path:
            dialog = myUniversalDialog(
                self,
                # "kein PDF geladen"
                title=self.tr("no_pdf_loaded"),
                # "Es ist kein PDF geladen"
                message=self.tr("no_pdf_message"),
                icon_type="",
                # "kein PDF geladen"
                voice_message=self.tr("no_pdf_loaded"),
            )
            dialog.exec_()
            return

        try:
            # "Starte Sofort-Druck"
            self.say(self.tr("print_now"))

            if sys.platform == "darwin":  # macOS
                # Lösung mit os.system
                os.system(f'lpr "{self.pdf_path}"')
                # "Druckauftrag gesendet"
                self.say(self.tr("print_sent"))
                print(f"Druckauftrag an Drucker gesendet")

            elif sys.platform == "win32":
                app_list = [
                    ("AcroRd32.exe", [
                        r"C:\Program Files\Adobe\Acrobat Reader DC\Reader",
                        r"C:\Program Files (x86)\Adobe\Acrobat Reader DC\Reader"
                    ]),
                    ("FoxitReader.exe", [
                        r"C:\Program Files\Foxit Software\Foxit Reader",
                        r"C:\Program Files (x86)\Foxit Software\Foxit Reader"
                    ]),
                ]
                app_path = self._find_windows_app(app_list)
                if app_path:
                    try:
                        subprocess.Popen([app_path, "/t", self.pdf_path])
                        print(f"PDF an {os.path.basename(app_path)} zum stillen Druck übergeben")
                        self.say(self.tr("print_sent"))
                    except Exception as e:
                        print(f"Fehler beim Drucken mit {app_path}: {e}")
                        QMessageBox.critical(self, self.tr("error"),
                                            f"{self.tr('print_error')}:\n{str(e)}")
                else:
                    msg = "Keine unterstützte Druckanwendung (Acrobat Reader oder Foxit) gefunden. Bitte installieren Sie eine davon."
                    print(msg)
                    QMessageBox.critical(self, self.tr("error"), msg)
            else:  # Linux
                os.system(f'lp "{self.pdf_path}"')
                self.say(self.tr("print_sent"))

        except Exception as e:
            self.say(self.tr("print_error_format", str(e)))
            QMessageBox.critical(...)

    def print_pdf(self):
        """Öffnet die PDF in der Standardanwendung (Vorschau) und simuliert den Druckdialog.
        Der Benutzer muss den Druckvorgang manuell bestätigen."""
        if not self.pdf_path:
            dialog = myUniversalDialog(
                self,
                title=self.tr("no_pdf_loaded"),
                message=self.tr("no_pdf_message"),
                icon_type="",
                voice_message=self.tr("no_pdf_loaded"),
            )
            dialog.exec_()
            return

        # Sprachausgabe: Hinweis, dass die Vorschau geöffnet wird
        self.say(self.tr("print_preview_start"))

        if sys.platform == "darwin":  # macOS
            # PDF in der Vorschau öffnen
            subprocess.run(["open", "-a", "Preview", self.pdf_path])
            # Nach einer Sekunde das Druckmenü simulieren
            QTimer.singleShot(1000, self._send_print_command_to_preview)
            self.say(self.tr("print_preview_manual"))
            print(f"PDF mit Vorschau-App geöffnet – bitte manuell drucken")

        elif sys.platform == "win32":
            # Zuerst Apps mit Druckdialog-Parameter
            dialog_apps = [
                ("AcroRd32.exe", [
                    r"C:\Program Files\Adobe\Acrobat Reader DC\Reader",
                    r"C:\Program Files (x86)\Adobe\Acrobat Reader DC\Reader"
                ]),
                ("FoxitReader.exe", [
                    r"C:\Program Files\Foxit Software\Foxit Reader",
                    r"C:\Program Files (x86)\Foxit Software\Foxit Reader"
                ]),
            ]
            app_path = self._find_windows_app(dialog_apps)
            if app_path:
                try:
                    subprocess.Popen([app_path, "/p", self.pdf_path])
                    print(f"PDF an {os.path.basename(app_path)} mit Druckdialog übergeben")
                    self.say(self.tr("print_preview_start") + f" ({os.path.basename(app_path)})")
                except Exception as e:
                    print(f"Fehler beim Öffnen von {app_path}: {e}")
                    self._open_with_browser_fallback()   # Fallback zu Browser
            else:
                # Keine Dialog-App → Browser versuchen
                self._open_with_browser_fallback()

        else:  # Linux
            subprocess.run(["xdg-open", self.pdf_path])
            self.say(self.tr("print_preview_manual"))

    def _send_print_command_to_preview(self):
        """Sendet Cmd+P an die Vorschau (falls aktiv)."""

        # Aktiviert die Vorschau und sendet Cmd+P
        subprocess.run(
            [
                "osascript",
                "-e",
                'tell application "Preview" to activate',
                "-e",
                "delay 0.2",
                "-e",
                'tell application "System Events" to keystroke "p" using command down',
            ]
        )

    def _find_windows_app(self, app_list):
        for name, paths in app_list:
            found = shutil.which(name)
            if found:
                return found
            for base in paths:
                full = os.path.join(base, name)
                if os.path.isfile(full):
                    return full
        return None

    def _open_with_browser_fallback(self):
        """Versucht, die PDF mit einem Browser zu öffnen (Edge, Firefox, Chrome)."""
        browser_apps = [
            ("msedge.exe", [
                r"C:\Program Files (x86)\Microsoft\Edge\Application",
                r"C:\Program Files\Microsoft\Edge\Application"
            ]),
            ("firefox.exe", [
                r"C:\Program Files\Mozilla Firefox",
                r"C:\Program Files (x86)\Mozilla Firefox"
            ]),
            ("chrome.exe", [
                r"C:\Program Files\Google\Chrome\Application",
                r"C:\Program Files (x86)\Google\Chrome\Application"
            ]),
        ]
        browser_path = self._find_windows_app(browser_apps)
        if browser_path:
            try:
                subprocess.Popen([browser_path, self.pdf_path])
                print(f"PDF an {os.path.basename(browser_path)} zur Ansicht übergeben – bitte manuell Strg+P drücken")
                self.say(self.tr("print_preview_manual") + f" ({os.path.basename(browser_path)})")
            except Exception as e:
                print(f"Fehler beim Öffnen des Browsers: {e}")
                QMessageBox.critical(self, self.tr("error"),
                                    f"{self.tr('print_error')}:\n{str(e)}")
        else:
            msg = "Keine unterstützte Anwendung zum Anzeigen der PDF gefunden. Bitte installieren Sie Edge, Firefox oder Chrome."
            print(msg)
            QMessageBox.critical(self, self.tr("error"), msg)

    ### ------------------------
    ### SCHLIESSEN
    ### ------------------------
    def close_current_pdf(self):
        """Schließt die aktuell geöffnete PDF und setzt die Anzeige vollständig zurück"""
        # Prüfen, ob ungespeicherte Änderungen vorhanden sind
        if not self.check_for_unsaved_changes("close_pdf"):
            return

        if (
            hasattr(self, "current_doc")
            and self.current_doc
            and not self.current_doc.is_closed
        ):
            self.current_doc.close()
            self.current_doc = None
        self.current_password = None

        # Falls OCR läuft, Thread warten lassen
        if (
            hasattr(self, "ocr_thread")
            and self.ocr_thread
            and self.ocr_thread.isRunning()
        ):
            print("Warte auf OCR-Thread...")
            self.ocr_thread.cancel()
            self.ocr_thread.wait(5000)  # Max. 5 Sekunden warten
            if self.ocr_thread.isRunning():
                self.ocr_thread.terminate()
                self.ocr_thread.wait()

        # 1. Temporäre entschlüsselte Datei bereinigen (wichtig!)
        self._cleanup_temp_pdf()

        # 2. PDF-Pfad zurücksetzen
        if self.pdf_path:
            # Sprachausgabe vor dem Schließen
            pdf_name = os.path.basename(self.pdf_path)
            self.say(self.tr("close_pdf", pdf_name))

        self.pdf_path = None
        self.original_pdf_path = None
        self.current_password = None
        self.current_page = 0
        self.total_pages = 0

        # 3. Kopierdaten zurücksetzen
        self.copied_text_data = None
        self.copied_signature_data = None
        self.copied_image_data = None
        self.copied_form_data = None

        # 4. Anzeige löschen (WICHTIG!)
        if hasattr(self, "scene") and self.scene:
            self.scene.clear()

        # 5. Seitenzahlen zurücksetzen
        if hasattr(self, "page_spin"):
            self.page_spin.setValue(0)
            self.page_spin.setMaximum(0)

        if hasattr(self, "page_count_label"):
            self.page_count_label.setText(self.tr("page_count", 0))

        # 6. Fenstertitel zurücksetzen
        self.setWindowTitle(self.tr("app_title"))

        # 7. Suchfunktion schließen falls aktiv
        if (
            hasattr(self, "search_bar")
            and self.search_bar
            and self.search_bar.isVisible()
        ):
            self.close_search()

        # 8. Eventuelle Lade-Threads abbrechen
        self._cleanup_loading_resources()

        # 9. Force Update der GUI
        QApplication.processEvents()

    def _cleanup_temp_pdf(self):
        """Bereinigt temporäre entschlüsselte PDF-Dateien"""
        if hasattr(self, "temp_pdf_path") and self.temp_pdf_path:
            try:
                if os.path.exists(self.temp_pdf_path):
                    os.unlink(self.temp_pdf_path)
                self.remove_temp_file(self.temp_pdf_path)
            except Exception as e:
                print(f"Fehler beim Löschen temporärer PDF: {e}")
                traceback.print_exc()
            finally:
                self.temp_pdf_path = None

    def _cleanup_overlays(self):
        """
        Entfernt alle Overlay-Elemente (Texte, Kreuze, Signaturen, Bilder, Formen)
        aus der Szene, um Signalverbindungen zu trennen und den Destruktor sauber ablaufen zu lassen.
        """
        # Texte und Kreuze
        for item in list(self.all_text_items):
            if item and item.scene():
                item.setSelected(False)
                self.scene.removeItem(item)
        self.all_text_items.clear()
        self.current_text_item = None

        # Signaturen
        for item in list(self.all_signature_items):
            if item and item.scene():
                item.setSelected(False)
                self.scene.removeItem(item)
                item.deleteLater()
        self.all_signature_items.clear()
        self.current_signature_item = None

        # Bilder
        for item in list(self.all_image_items):
            if item and item.scene():
                item.setSelected(False)
                self.scene.removeItem(item)
                item.deleteLater()
        self.all_image_items.clear()
        self.current_image_item = None

        # Formen
        for item in list(self.all_form_items):
            if item and item.scene():
                item.setSelected(False)
                self.scene.removeItem(item)
                item.deleteLater()
        self.all_form_items.clear()
        self.current_form_item = None

        # Falls es noch weitere QGraphicsItem-Objekte in der Szene gibt,
        # die nicht in den Listen sind, können hier auch alle Items außer
        # den Seiten-Items gelöscht werden. Das ist optional, erhöht aber die Sicherheit.
        # (Die Seiten-Items werden später automatisch mit der Szene gelöscht.)

    def check_for_unsaved_changes(self, action_key):
        """
        Prüft, ob ungespeicherte Änderungen vorliegen.
        action_key: Einer der Keys: 'close_window', 'open_new_pdf', 'close_pdf', 'quit_app'
        Returns: True – fortfahren, False – abgebrochen
        """
        if not (
            self.text_mode
            or self.signature_mode
            or self.image_mode
            or self.form_mode
            or self.redaction_mode
        ):
            return True

        # Beschreibung aus dem Wörterbuch holen
        action_desc = self.tr(f"action_{action_key}")
        return self._prompt_save_before_close(
            keep_open=False, action_description=action_desc
        )

    def closeEvent(self, event):
        print("\n=== PDFViewer closeEvent aufgerufen ===")

        # Prüfen, ob ungespeicherte Änderungen vorhanden sind
        if not self.check_for_unsaved_changes("close_window"):
            event.ignore()
            return

        self._is_closing = True

        # ALLE Fehler im closeEvent abfangen
        try:
            # 0. Wichtig: Zuerst den Sprachausgabe-Versuch sichern
            try:
                self.say(self.tr("app_quitting"))
            except Exception as e:
                print(f"Fehler bei Sprachausgabe im closeEvent: {e}")
                import traceback

                traceback.print_exc()

            # 1. Signalblockierung für Scrollbalken (verhindert rangeChanged etc.)
            try:
                vscroll = self.graphics_view.verticalScrollBar()
                if vscroll:
                    vscroll.blockSignals(True)
                hscroll = self.graphics_view.horizontalScrollBar()
                if hscroll:
                    hscroll.blockSignals(True)
            except Exception as e:
                print(f"Fehler bei Scrollbar-Blockierung: {e}")

            # 2. Overlays aus der Szene entfernen
            try:
                self._cleanup_overlays()
            except Exception as e:
                print(f"Fehler bei Overlay-Cleanup: {e}")

            # 3. GraphicsView von der Scene trennen
            try:
                self.graphics_view.setScene(None)
            except Exception as e:
                print(f"Fehler beim Trennen der Scene: {e}")

            # 4. Scene löschen (Qt plant die Zerstörung)
            try:
                if self.scene:
                    self.scene.deleteLater()
                    self.scene = None
            except Exception as e:
                print(f"Fehler beim Löschen der Scene: {e}")

            # 5. Temporäre Dateien bereinigen
            try:
                self.cleanup_temp_files()
            except Exception as e:
                print(f"Fehler bei Temp-File-Cleanup: {e}")

            # 6. BaseWindow-Ressourcen freigeben
            try:
                if hasattr(self, "base_window") and self.base_window:
                    self.base_window.safe_close()
            except Exception as e:
                print(f"Fehler bei base_window.safe_close(): {e}")

            # 7. Einstellungen speichern
            try:
                self.save_app_settings()
            except Exception as e:
                print(f"Fehler beim Speichern der Einstellungen: {e}")

            # Event akzeptieren
            event.accept()

        except Exception as e:
            # Fängt alle anderen, unerwarteten Fehler ab
            print(f"KRITISCHER FEHLER in closeEvent: {e}")
            import traceback

            traceback.print_exc()
            # In jedem Fall das Event akzeptieren, damit die App beendet wird
            event.accept()

        finally:
            self._is_closing = False
            # 8. Event an die Elternklasse weitergeben (jetzt außerhalb des try)
            try:
                super().closeEvent(event)
            except Exception as e:
                print(f"Fehler in super().closeEvent(): {e}")

    def safe_close(self):
        """Sicheres Schließen mit Ressourcenbereinigung"""
        try:
            # BaseWindow safe_close aufrufen
            if hasattr(self, "base_window"):
                self.base_window.safe_close()

            # Eigene Ressourcen bereinigen
            if hasattr(self, "scene") and self.scene:
                self.scene.clear()

            if hasattr(self, "page_pixmaps"):
                self.page_pixmaps.clear()

        except Exception as e:
            print(f"Fehler in PDFViewer safe_close: {str(e)}")

    def safe_quit(self):
        """Sicheres Beenden der gesamten Anwendung"""
        try:
            self.tee.close()
            print("safe_quit aufgerufen")
            self.close()  # löst closeEvent aus
        except Exception as e:
            print(f"Fehler in safe_quit: {str(e)}")
            QApplication.quit()

    ###=======================================
    ### Aktionen im Menü Bearbeiten
    ###=======================================
    ###---------------------------------------
    ### SUCHE CMD+S weiter mit Enter
    ###-----------------------------

    def force_search(self):
        """Suchfunktion mit korrekter Statusverwaltung"""
        if self._block_search_changes:
            return

        if not self.pdf_path:
            self.say(self.tr("no_pdf_loaded"))
            return

        # Wenn in Zoom-Modus: Erst zurück zur Standardansicht
        if self.zoom_mode != "page":
            print("In zoom mode - resetting to standard view first")
            self._prepare_for_search()
            QTimer.singleShot(150, self._delayed_search_activation)
            return

        self._activate_search()

    def _delayed_search_activation(self):
        """Verzögerte Suchaktivierung"""
        if self.zoom_mode == "page":  # Nur wenn wirklich zurückgesetzt
            self._activate_search()

    def _activate_search(self):
        """Aktiviert die Suche"""
        if self.is_native_pdf():
            if self.search_bar.isVisible():
                self.close_search()
            else:
                self.open_search()
        else:
            # Logik für nicht-native PDFs
            pass

    def toggle_native_search(self):
        """Handhabung der nativen Suche"""
        if self._is_in_zoom_mode:
            # Bitte zuerst Zoom beenden
            self.say(self.tr("zoom_exit_first"))
            return

        if self.search_bar.isVisible():
            self.close_search()
        else:
            self.open_search()

    def toggle_search(self):
        """Schaltet die Suche ein/aus mit Zoom-Handling"""
        if self.search_container.isVisible():
            self.close_search()
            # Zurück zum vorherigen Zoom-Modus wenn nötig
            if hasattr(self, "last_zoom_mode") and self.zoom_mode == "page":
                QTimer.singleShot(300, lambda: self.set_zoom_mode(self.last_zoom_mode))
        else:
            # Für Suche vorbereiten
            self._prepare_for_search()
            self.open_search()

    """Echte native PDF (eingebetteter Text) True Native Suche
        macOS OCRmyPDF (Text‑Spans vorhanden) True Native Suche
        Windows OCR (Overlay, Markierung im Producer) False Umleitung ins Textfenster
        PDF ohne Text (Scans) False Umleitung ins Textfenster

        Damit wird nur bei Windows‑OCR‑PDFs und bei reinen Bild‑PDFs das Textfenster geöffnet.
        Auf macOS erzeugte OCR‑PDFs bleiben für die native Suche nutzbar """

    def open_search(self):
        """Aktiviert die Suchleiste mit vollständigem Status-Update"""
        if not self.pdf_path or self._block_search_changes:
            return

        # ins Textfenster umleiten, wenn die PDF KEINEN nativen Text enthält
        if not self.is_native_pdf():
            self.force_text_window()
            return

        print("Opening search...")
        self.search_active = True
        self._is_in_search_mode = True
        self._block_zoom_changes = True  # Zoom während Suche blockieren
        self.update_zoom_menu()

        self.search_container.show()
        self.search_bar.setFocus()
        self.search_bar.selectAll()

        self.say("Suchfeld aktiviert")

    def _restore_graphics_focus(self):
        """Stellt die Fokus-Policy für GraphicsView nach ShortCut für Suche wieder her"""
        if hasattr(self, "graphics_view"):
            self.graphics_view.setFocusPolicy(Qt.ClickFocus)
            self.graphics_view.viewport().setFocusPolicy(Qt.ClickFocus)

    def _ensure_search_focus(self):
        """Stellt sicher dass die Suchleiste fokussiert bleibt"""
        if hasattr(self, "search_active") and self.search_active:
            self.search_bar.setFocus()
            self.search_bar.selectAll()

    def _restore_search_focus(self):
        """Stellt den Fokus auf die Suchleiste wieder her"""
        if (
            hasattr(self, "search_active")
            and self.search_active
            and hasattr(self, "search_bar")
            and self.search_bar.isVisible()
        ):

            print("Restoring focus to search bar")
            self.search_bar.setFocus()
            self.search_bar.selectAll()

    ### Suchvorgang
    def _prepare_for_search(self):
        """Bereitet Zoom-Reset für Suche vor"""
        self._block_zoom_changes = True  # Weitere Zoom-Änderungen blockieren
        self.set_zoom_mode("page")  # Zur Standardansicht wechseln
        self._block_zoom_changes = False  # Zoom wieder erlauben nach Reset

    def execute_search(self):
        """Startet Suche mit automatischem Zoom-Wechsel"""
        # Zur Standardansicht wechseln für korrekte Suchmarkierungen
        was_zoomed = self._prepare_for_search()

        search_term = self.search_bar.text().strip()
        if not search_term:
            self.close_search()
            return

        try:
            # Vorherige Markierungen entfernen
            self.clear_search_marks()

            # Neue Suche initialisieren
            self.search_results = []
            self.last_search_term = search_term
            doc = fitz.open(self.pdf_path)

            # Suche durchführen
            for page_num in range(len(doc)):
                page = doc.load_page(page_num)
                text_instances = page.search_for(search_term)  # Ohne Flags

                for rect in text_instances:
                    self.search_results.append(
                        {
                            "page": page_num,
                            "rect": rect,
                            "text": page.get_textbox(rect),
                            "page_rect": page.rect,
                        }
                    )

            doc.close()

            if not self.search_results:
                self.search_status_label.setText(self.tr("search_no_results"))
                self.say(self.tr("search_no_results"))
                if was_zoomed:
                    QTimer.singleShot(
                        1000, lambda: self.set_zoom_mode(self.last_zoom_mode)
                    )
                return

            self.current_search_index = 0

            # Wichtig: Erst die Seite wechseln, dann scrollen
            first_result = self.search_results[0]

            # Zur Seite des ersten Treffers wechseln
            if first_result["page"] != self.current_page:
                self.current_page = first_result["page"]
                with QSignalBlocker(self.page_spin):
                    self.page_spin.setValue(self.current_page + 1)

            # Dann zur genauen Position scrollen
            self._scroll_to_search_result(first_result)

            # Status aktualisieren und Markierungen zeichnen
            self.highlight_result()

        except Exception as e:
            import traceback

            traceback.print_exc()  # Ausgabe in die Konsole
            error_msg = str(e)
            self.search_status_label.setText(f"Fehler: {error_msg[:50]}...")
            self.say(self.tr("search_error"))
            print(f"Suchfehler: {error_msg}")  # zusätzliche Ausgabe
            if was_zoomed:
                QTimer.singleShot(1000, lambda: self.set_zoom_mode(self.last_zoom_mode))

    def highlight_result(self):
        """Markiert das aktuelle Suchergebnis und scrollt dorthin"""
        if not hasattr(self, "search_results") or not self.search_results:
            return

        result = self.search_results[self.current_search_index]

        # Zur richtigen Seite wechseln, falls nötig
        if result["page"] != self.current_page:
            self.current_page = result["page"]
            with QSignalBlocker(self.page_spin):
                self.page_spin.setValue(self.current_page + 1)

        # Wichtig: Zuerst die Seite laden/sichtbar machen
        if not self.page_items or self.current_page >= len(self.page_items):
            return

        # Dann zur genauen Position des Treffers scrollen
        self._scroll_to_search_result(result)

        # Text-Status aktualisieren
        rel_pos = result["rect"].y0 / result["page_rect"].height

        if rel_pos < 0.2:
            position_key = "search_pos_top"
        elif rel_pos < 0.4:
            position_key = "search_pos_upper"
        elif rel_pos < 0.6:
            position_key = "search_pos_middle"
        elif rel_pos < 0.8:
            position_key = "search_pos_lower"
        else:
            position_key = "search_pos_bottom"

        position_text = self.tr(position_key)

        status_text = self.tr(
            "search_results", self.current_search_index + 1, len(self.search_results)
        )
        status_text += (
            f" ({self.tr('search_position', result['page'] + 1, position_text)})"
        )

        self.search_status_label.setText(status_text)
        self.say(status_text, convert_numbers=True)

        # Markierungen neu zeichnen (nach dem Scrollen)
        QTimer.singleShot(50, self.draw_search_marks)

    def _scroll_to_search_result(self, result):
        """Scrollt zur Position eines Suchergebnisses - sorgt dafür, dass es im sichtbaren Bereich ist"""
        if not self.page_items or self.current_page >= len(self.page_items):
            return

        try:
            page_item = self.page_items[self.current_page]

            # Zoom-Faktor berechnen (wie in draw_search_marks)
            zoom_y = page_item.boundingRect().height() / result["page_rect"].height

            # Y-Position des Treffers in Scene-Koordinaten
            target_y = page_item.y() + (result["rect"].y0 * zoom_y)

            # Höhe des Treffers
            target_height = (result["rect"].y1 - result["rect"].y0) * zoom_y

            # Viewport-Höhe
            view_height = self.graphics_view.viewport().height()
            current_scroll = self.graphics_view.verticalScrollBar().value()

            # Zielposition so berechnen, dass der Treffer im sichtbaren Bereich liegt
            # Wir wollen den Treffer im oberen Drittel des Bildschirms haben (für bessere Lesbarkeit)
            ideal_position = target_y - (view_height * 0.3)  # 30% vom oberen Rand

            # Begrenzen auf gültigen Bereich
            max_scroll = self.graphics_view.verticalScrollBar().maximum()
            new_scroll = max(0, min(max_scroll, int(ideal_position)))

            # Sanft scrollen (für besseres Benutzererlebnis)
            self._smooth_scroll_to(new_scroll)

            print(
                f"DEBUG: Scroll zu Treffer - Y: {target_y:.1f}, Scroll: {new_scroll}, ViewHeight: {view_height}"
            )

        except Exception as e:
            print(f"Fehler beim Scrollen zum Suchergebnis: {str(e)}")
            import traceback

            traceback.print_exc()

    def _smooth_scroll_to(self, target_position, duration=150):
        """Sanftes Scrollen zu einer Position"""
        scroll_bar = self.graphics_view.verticalScrollBar()
        current_pos = scroll_bar.value()

        if current_pos == target_position:
            return

        # Animation für sanftes Scrollen
        self._scroll_animation = QPropertyAnimation(scroll_bar, b"value")
        self._scroll_animation.setDuration(duration)
        self._scroll_animation.setStartValue(current_pos)
        self._scroll_animation.setEndValue(target_position)
        self._scroll_animation.setEasingCurve(QEasingCurve.OutCubic)
        self._scroll_animation.start()

    def draw_search_marks(self):
        """Zeichnet Suchmarkierungen mit aktueller Treffer-Hervorhebung"""
        if not hasattr(self, "search_results") or not self.search_results:
            return

        try:
            # Zuerst alle Seiten zurücksetzen (ohne Markierungen)
            for i, item in enumerate(self.page_items):
                if i < len(self.page_pixmaps):
                    item.setPixmap(self.page_pixmaps[i])

            # Nur sichtbare Seiten aktualisieren
            scroll_pos = self.graphics_view.verticalScrollBar().value()
            viewport_height = self.graphics_view.viewport().height()
            viewport_bottom = scroll_pos + viewport_height

            for page_num, item in enumerate(self.page_items):
                item_top = item.y()
                item_bottom = item_top + item.boundingRect().height()

                # Nur sichtbare oder teilweise sichtbare Seiten bearbeiten
                if item_bottom > scroll_pos and item_top < viewport_bottom:
                    original_pixmap = self.page_pixmaps[page_num]
                    marked_pixmap = original_pixmap.copy()
                    painter = QPainter(marked_pixmap)
                    painter.setRenderHint(QPainter.Antialiasing)

                    for i, result in enumerate(self.search_results):
                        if result["page"] == page_num:
                            rect = result["rect"]
                            zoom_y = marked_pixmap.height() / result["page_rect"].height
                            zoom_x = marked_pixmap.width() / result["page_rect"].width

                            x = rect.x0 * zoom_x
                            y = rect.y0 * zoom_y
                            width = (rect.x1 - rect.x0) * zoom_x
                            height = (rect.y1 - rect.y0) * zoom_y

                            # Aktuelles Ergebnis hervorheben
                            if i == self.current_search_index:
                                bg_color = QColor(255, 69, 0, 200)  # Orange
                                border_width = 3

                                # Ergebnisnummer über dem Treffer anzeigen
                                painter.setPen(QPen(Qt.white, 1))
                                painter.setFont(QFont("Arial", 10, QFont.Bold))

                                # Nummer oberhalb des Treffers platzieren (oder rechts wenn oben kein Platz)
                                number_y = y - 15
                                if number_y < 0:
                                    number_y = (
                                        y + height + 2
                                    )  # Unterhalb wenn kein Platz oben

                                painter.drawText(
                                    QRectF(x, number_y, width, 15),
                                    Qt.AlignCenter,
                                    f"{i+1}/{len(self.search_results)}",
                                )
                            else:
                                bg_color = QColor(255, 255, 0, 150)  # Gelb
                                border_width = 2

                            painter.setPen(QPen(bg_color, border_width))
                            painter.setBrush(QBrush(bg_color))
                            painter.drawRect(QRectF(x, y, width, height))

                    painter.end()
                    item.setPixmap(marked_pixmap)

        except Exception as e:
            print(f"Fehler beim Zeichnen: {str(e)}")

    def move_to_next_result(self):
        """Springt zum nächsten Treffer"""
        if hasattr(self, "search_results") and self.search_results:
            self.current_search_index = (self.current_search_index + 1) % len(
                self.search_results
            )
            self.highlight_result()  # highlight_result macht jetzt das Scrollen

    def move_to_previous_result(self):
        """Springt zum vorherigen Treffer"""
        if hasattr(self, "search_results") and self.search_results:
            self.current_search_index = (self.current_search_index - 1) % len(
                self.search_results
            )
            self.highlight_result()  # highlight_result macht jetzt das Scrollen

    ### Suche schließen
    def close_search(self):
        """Schließt die Suche oder Zoom mit vollständigem Status-Reset"""
        if not self.zoom_mode == "page":
            self.set_zoom_mode("page")
            print("Closing Zoom")
            return

        print("Closing search...")

        self.search_active = False
        self._is_in_search_mode = False
        self._block_zoom_changes = False
        self.update_zoom_menu()

        was_active = self.search_container.isVisible()
        self.search_bar.clear()
        self.search_results = []
        self.current_search_index = -1
        self.last_search_term = ""
        self.search_status_label.setText(self.tr("search_results", 0, 0))

        # Markierungen entfernen
        self.clear_search_marks()

        self.search_container.hide()

        if was_active and self.voice_enabled:
            self.say("Suche beendet")

    def clear_search_marks(self):
        """Entfernt alle Suchmarkierungen durch Neuladen der Original-Pixmaps"""
        if hasattr(self, "page_items") and hasattr(self, "page_pixmaps"):
            for i, item in enumerate(self.page_items):
                if i < len(self.page_pixmaps):
                    item.setPixmap(self.page_pixmaps[i])

    # für Suche und/oder Textfenster schließen
    def close_search_or_text_window(self):
        """Schließt Suche oder Textfenster mit Escape"""
        if hasattr(self, "search_bar") and self.search_bar.isVisible():
            self.close_search()
        elif (
            hasattr(self, "text_viewer")
            and self.text_viewer
            and self.text_viewer.isVisible()
        ):
            self.text_viewer.close()

    ### -------------------------------------
    ### LESEZEICHEN BOOKMARKS
    ### -------------------------------------

    def add_bookmark_current_page(self):
        """Fügt ein Lesezeichen für die aktuelle Seite hinzu (mit Position)."""
        if not self.pdf_path:
            self._show_no_pdf_dialog()
            return

        current_page = self.current_page
        page_display = current_page + 1

        # Position ermitteln (verwende _get_insertion_position)
        local_pos, target_page = self._get_insertion_position()

        if local_pos is None:
            # Fallback: Seitenmitte
            if hasattr(self, "page_items") and current_page < len(self.page_items):
                page_item = self.page_items[current_page]
                page_rect = page_item.boundingRect()
                local_pos = QPointF(page_rect.width() / 2, page_rect.height() / 2)
                target_page = current_page
                print(
                    f"DEBUG: Fallback zur Seitenmitte: ({local_pos.x():.1f}, {local_pos.y():.1f})"
                )
        else:
            print(
                f"DEBUG: Mausklick-Position: Seite {target_page + 1}, Lokale Position: ({local_pos.x():.1f}, {local_pos.y():.1f})"
            )

        default_name = self.tr("bookmark_name_default", page_display)

        dialog = myUniversalDialog(
            self,
            title=self.tr("bookmark_name_prompt_title"),
            message=self.tr("bookmark_name_prompt"),
            text_alignment=Qt.AlignLeft,
            buttons=[
                (self.tr("btn_ok"), "primary", "ok"),
                (self.tr("btn_cancel"), "danger", "cancel"),
            ],
            icon_type="",
            voice_message=self.tr("bookmark_name_prompt"),
            default_button="ok",
            input_fields=[
                {
                    "type": "text",
                    "name": "bookmark_name",
                    "label": "",
                    "default": default_name,
                    "placeholder": self.tr("bookmark_name_prompt"),
                }
            ],
        )

        if dialog.exec_() != QDialog.Accepted:
            return

        name = dialog.get_input_value("bookmark_name")
        if not name or not name.strip():
            name = default_name

        bookmark_key = self.get_pdf_bookmark_key()
        settings = QSettings("BinhDiez", "PDFDarkView")
        bookmarks_json = settings.value(bookmark_key, "[]")

        try:
            bookmarks = json.loads(bookmarks_json)
        except:
            bookmarks = []

        for bookmark in bookmarks:
            if (
                bookmark.get("page") == target_page
                and bookmark.get("name") == name.strip()
            ):
                self.say(self.tr("bookmark_exists"))
                return

        # Lesezeichen mit Position speichern
        bookmarks.append(
            {
                "page": target_page,
                "name": name.strip(),
                "local_pos_x": local_pos.x() if local_pos else 0,
                "local_pos_y": local_pos.y() if local_pos else 0,
                "created": QDateTime.currentDateTime().toString(Qt.ISODate),
            }
        )

        bookmarks.sort(key=lambda x: x.get("page", 0))
        settings.setValue(bookmark_key, json.dumps(bookmarks))
        settings.sync()

        print(
            f"DEBUG: Gespeicherte Position: ({local_pos.x() if local_pos else 0:.1f}, {local_pos.y() if local_pos else 0:.1f}) auf Seite {target_page + 1}"
        )
        self.say(self.tr("bookmark_added", page_display, name.strip()))
        self.update_bookmark_menu()

    def jump_to_bookmark_from_context(self, bookmark):
        """Springt zu einem Lesezeichen aus dem Kontextmenü."""
        if not self.pdf_path:
            return

        # Wenn in Zoom-Modus: Erst zurück zur Standardansicht
        if self.zoom_mode != "page":
            self.set_zoom_mode("page")

        page = bookmark.get("page", 0)
        name = bookmark.get("name", "")
        local_pos_x = bookmark.get("local_pos_x", 0)
        local_pos_y = bookmark.get("local_pos_y", 0)

        print(f"\n=== SPRINGE ZU LESEZEICHEN (Kontextmenü) ===")
        print(f"Seite: {page + 1}, Name: {name}")

        # Zur Seite springen
        self.go_to_page(page + 1)

        # Zur Position scrollen (falls vorhanden)
        has_valid_position = local_pos_x != 0 or local_pos_y != 0
        if (
            has_valid_position
            and hasattr(self, "page_items")
            and page < len(self.page_items)
        ):
            # Warten bis die Seite geladen ist, dann zur Position scrollen
            QTimer.singleShot(
                300,
                lambda: self._scroll_to_local_position_from_context(
                    page, QPointF(local_pos_x, local_pos_y)
                ),
            )

        self.say(self.tr("bookmark_jumped_to", name, page + 1))

    def _scroll_to_local_position_from_context(self, page, local_pos):
        """Scrollt zu einer lokalen Position auf einer Seite (für Kontextmenü)."""
        try:
            if not hasattr(self, "page_items") or page >= len(self.page_items):
                print(f"DEBUG: Seite {page + 1} nicht verfügbar")
                return

            page_item = self.page_items[page]

            # Lokale Position in Scene-Position umwandeln
            scene_pos = page_item.mapToScene(local_pos)

            # OFFSET für Seitenbreite-Darstellung (wie im Dialog)
            viewport_height = self.graphics_view.viewport().height()
            offset_y = viewport_height * 0.45  # 45% Offset

            # Scene-Position mit Offset (nach unten verschieben)
            scene_pos_with_offset = QPointF(scene_pos.x(), scene_pos.y() + offset_y)

            print(
                f"DEBUG: Kontextmenü - Scene-Position mit Offset: ({scene_pos_with_offset.x():.1f}, {scene_pos_with_offset.y():.1f})"
            )

            # Ihre vorhandene Scroll-Methode verwenden
            self._scroll_to_position(scene_pos_with_offset)

        except Exception as e:
            print(f"DEBUG: Fehler beim Scrollen (Kontextmenü): {e}")

    def get_pdf_bookmark_key(self):
        """Erstellt einen eindeutigen Schlüssel für die PDF-Lesezeichen."""
        if not self.pdf_path:
            return None

        norm_path = os.path.normpath(self.pdf_path)
        import hashlib

        path_hash = hashlib.md5(norm_path.encode("utf-8")).hexdigest()[:16]
        # Nur den Hash verwenden, nicht den Dateinamen (der könnte sich ändern)
        return f"bookmarks_{path_hash}"

    def migrate_old_bookmarks_to_position(self):
        """Migriert alte Lesezeichen ohne Position."""
        bookmark_key = self.get_pdf_bookmark_key()
        if not bookmark_key:
            return

        settings = QSettings("BinhDiez", "PDFDarkView")
        bookmarks_json = settings.value(bookmark_key, "[]")

        try:
            bookmarks = json.loads(bookmarks_json)
            migrated = False

            for bookmark in bookmarks:
                if "local_pos_x" not in bookmark:
                    # Setze Standardposition: Seitenmitte
                    bookmark["local_pos_x"] = 0
                    bookmark["local_pos_y"] = 0
                    migrated = True

            if migrated:
                settings.setValue(bookmark_key, json.dumps(bookmarks))
                settings.sync()
                print(f"DEBUG: {len(bookmarks)} Lesezeichen migriert")

        except Exception as e:
            print(f"DEBUG: Fehler bei Migration: {e}")

    def open_bookmark_manager(self):
        """Öffnet den Lesezeichen-Manager-Dialog."""
        if not self.pdf_path:
            self._show_no_pdf_dialog()
            return
        # self.debug_show_all_bookmarks()
        self.migrate_old_bookmarks_to_position()
        dialog = BookmarkManagerDialog(self, self.pdf_path)
        dialog.exec_()

    def next_bookmark(self):
        """Springt zum nächsten Lesezeichen."""
        if not self.pdf_path:
            return

        bookmarks = self.load_current_bookmarks()
        if not bookmarks:
            self.say(self.tr("bookmark_no_bookmarks"))
            return

        current_page = self.current_page

        # Nächstes Lesezeichen finden
        next_bookmark = None
        for bookmark in bookmarks:
            if bookmark.get("page", 0) > current_page:
                next_bookmark = bookmark
                break

        if next_bookmark:
            page = next_bookmark.get("page", 0)
            name = next_bookmark.get("name", "")
            self.go_to_page(page + 1)
            self.say(self.tr("bookmark_jumped_to", name, page + 1))
        else:
            # Zum ersten Lesezeichen gehen
            first = bookmarks[0]
            page = first.get("page", 0)
            name = first.get("name", "")
            self.go_to_page(page + 1)
            self.say(self.tr("bookmark_jumped_to", name, page + 1))

    def prev_bookmark(self):
        """Springt zum vorherigen Lesezeichen."""
        if not self.pdf_path:
            return

        bookmarks = self.load_current_bookmarks()
        if not bookmarks:
            self.say(self.tr("bookmark_no_bookmarks"))
            return

        current_page = self.current_page

        # Vorheriges Lesezeichen finden
        prev_bookmark = None
        for bookmark in reversed(bookmarks):
            if bookmark.get("page", 0) < current_page:
                prev_bookmark = bookmark
                break

        if prev_bookmark:
            page = prev_bookmark.get("page", 0)
            name = prev_bookmark.get("name", "")
            self.go_to_page(page + 1)
            self.say(self.tr("bookmark_jumped_to", name, page + 1))

    def load_current_bookmarks(self):
        """Lädt die Lesezeichen für die aktuelle PDF."""
        bookmark_key = self.get_pdf_bookmark_key()
        if not bookmark_key:
            # print(f"DEBUG: Kein Bookmark-Key für {self.pdf_path}")
            return []

        settings = QSettings("BinhDiez", "PDFDarkView")
        bookmarks_json = settings.value(bookmark_key, "[]")

        try:
            bookmarks = json.loads(bookmarks_json)
            bookmarks.sort(key=lambda x: x.get("page", 0))

            print(f"\n{len(bookmarks)} Lesezeichen geladen für Key {bookmark_key}")
            return bookmarks
        except Exception as e:
            print(f"DEBUG: Fehler beim Laden: {e}")
            return []

    def debug_show_all_bookmarks(self):
        """Zeigt alle gespeicherten Lesezeichen-Keys in den Einstellungen."""
        settings = QSettings("BinhDiez", "PDFDarkView")
        print("\n=== ALLE GESPEICHERTEN LESEZEICHEN ===")
        for key in settings.allKeys():
            if key.startswith("bookmarks_"):
                value = settings.value(key)
                print(f"Key: {key}")
                print(f"Value: {value}")
                print("-" * 50)

    # Methoden für das Kontextmenü im Hauptfenster (5 Methoden)
    def add_bookmark_current_page_with_name(self, page, position=None):
        """Fügt ein Lesezeichen für die angegebene Seite hinzu (mit Position)."""
        if not self.pdf_path:
            self._show_no_pdf_dialog()
            return

        current_page = page if page is not None else self.current_page
        page_display = current_page + 1

        # Position ermitteln
        local_pos = None
        target_page = current_page

        if position is not None:
            # Position aus dem Kontextmenü (Mausklick)
            local_pos = position
            print(
                f"DEBUG: Kontextmenü-Position: Seite {target_page + 1}, Lokale Position: ({local_pos.x():.1f}, {local_pos.y():.1f})"
            )
        else:
            # Verwende die vorhandene _get_insertion_position Methode
            local_pos, target_page = self._get_insertion_position()
            if local_pos is None:
                # Fallback: Seitenmitte
                if hasattr(self, "page_items") and current_page < len(self.page_items):
                    page_item = self.page_items[current_page]
                    page_rect = page_item.boundingRect()
                    local_pos = QPointF(page_rect.width() / 2, page_rect.height() / 2)
                    target_page = current_page
                    print(
                        f"DEBUG: Fallback zur Seitenmitte: ({local_pos.x():.1f}, {local_pos.y():.1f})"
                    )
            else:
                print(
                    f"DEBUG: Mausklick-Position: Seite {target_page + 1}, Lokale Position: ({local_pos.x():.1f}, {local_pos.y():.1f})"
                )

        default_name = self.tr("bookmark_name_default", page_display)

        dialog = myUniversalDialog(
            self,
            title=self.tr("bookmark_name_prompt_title"),
            message=self.tr("bookmark_name_prompt"),
            text_alignment=Qt.AlignLeft,
            buttons=[
                (self.tr("btn_ok"), "primary", "ok"),
                (self.tr("btn_cancel"), "danger", "cancel"),
            ],
            icon_type="",
            voice_message=self.tr("bookmark_name_prompt"),
            default_button="ok",
            input_fields=[
                {
                    "type": "text",
                    "name": "bookmark_name",
                    "label": "",
                    "default": default_name,
                    "placeholder": self.tr("bookmark_name_prompt"),
                }
            ],
        )

        if dialog.exec_() != QDialog.Accepted:
            return

        name = dialog.get_input_value("bookmark_name")
        if not name or not name.strip():
            name = default_name

        bookmark_key = self.get_pdf_bookmark_key()
        settings = QSettings("BinhDiez", "PDFDarkView")
        bookmarks_json = settings.value(bookmark_key, "[]")

        try:
            bookmarks = json.loads(bookmarks_json)
        except:
            bookmarks = []

        for bookmark in bookmarks:
            if (
                bookmark.get("page") == target_page
                and bookmark.get("name") == name.strip()
            ):
                self.say(self.tr("bookmark_exists"))
                return

        # Lesezeichen mit Position speichern
        bookmarks.append(
            {
                "page": target_page,
                "name": name.strip(),
                "local_pos_x": local_pos.x() if local_pos else 0,
                "local_pos_y": local_pos.y() if local_pos else 0,
                "created": QDateTime.currentDateTime().toString(Qt.ISODate),
            }
        )

        bookmarks.sort(key=lambda x: x.get("page", 0))
        settings.setValue(bookmark_key, json.dumps(bookmarks))
        settings.sync()

        print(
            f"DEBUG: Gespeicherte Position: ({local_pos.x() if local_pos else 0:.1f}, {local_pos.y() if local_pos else 0:.1f}) auf Seite {target_page + 1}"
        )
        self.say(self.tr("bookmark_added", page_display, name.strip()))
        self.update_bookmark_menu()

    def create_bookmark_submenu(self, bookmark, index):
        """Erstellt ein Untermenü für ein Lesezeichen (für das Kontextmenü)."""
        submenu = QMenu()

        # Umbenennen
        rename_action = submenu.addAction(
            qta.icon("fa5s.edit"), self.tr("bookmark_rename")
        )
        rename_action.triggered.connect(
            lambda: self.rename_bookmark_from_context(bookmark, index)
        )

        submenu.addSeparator()

        # Löschen
        delete_action = submenu.addAction(
            qta.icon("fa5s.trash", color="red"), self.tr("bookmark_remove")
        )
        delete_action.triggered.connect(
            lambda: self.remove_bookmark_from_context(bookmark, index)
        )

        return submenu

    def rename_bookmark_from_context(self, bookmark, index):
        """Benennt ein Lesezeichen über das Kontextmenü um."""
        bookmark_key = self.get_pdf_bookmark_key()
        settings = QSettings("BinhDiez", "PDFDarkView")
        bookmarks_json = settings.value(bookmark_key, "[]")

        try:
            bookmarks = json.loads(bookmarks_json)
        except:
            return

        if index >= len(bookmarks):
            return

        old_name = bookmark.get("name", "")
        page_num = bookmark.get("page", 0) + 1

        dialog = myUniversalDialog(
            self,
            title=self.tr("bookmark_rename_title"),
            message=self.tr("bookmark_rename_prompt", page_num),
            buttons=[
                (self.tr("btn_ok"), "primary", "ok"),
                (self.tr("btn_cancel"), "dark", "cancel"),
            ],
            icon_type="",
            voice_message=self.tr("bookmark_rename_prompt", page_num),
            default_button="ok",
            input_fields=[
                {
                    "type": "text",
                    "name": "bookmark_name",
                    "label": "",
                    "default": old_name,
                    "placeholder": self.tr("bookmark_rename_prompt", page_num),
                }
            ],
        )

        if dialog.exec_() != QDialog.Accepted:
            return

        new_name = dialog.get_input_value("bookmark_name")
        if not new_name or not new_name.strip():
            return

        bookmarks[index]["name"] = new_name.strip()
        settings.setValue(bookmark_key, json.dumps(bookmarks))
        settings.sync()

        self.say(self.tr("bookmark_renamed", old_name, new_name.strip()))

    def remove_bookmark_from_context(self, bookmark, index):
        """Entfernt ein Lesezeichen über das Kontextmenü."""
        bookmark_key = self.get_pdf_bookmark_key()
        settings = QSettings("BinhDiez", "PDFDarkView")
        bookmarks_json = settings.value(bookmark_key, "[]")

        try:
            bookmarks = json.loads(bookmarks_json)
        except:
            return

        if index >= len(bookmarks):
            return

        name = bookmark.get("name", "")
        page_num = bookmark.get("page", 0) + 1

        dialog = myUniversalDialog(
            self,
            title=self.tr("confirm"),
            message=self.tr("bookmark_confirm_remove", page_num, name),
            buttons=[
                (self.tr("btn_yes"), "danger", "yes"),
                (self.tr("btn_no"), "primary", "no"),
            ],
            icon_type="",
            voice_message=self.tr("bookmark_confirm_remove", page_num, name),
            default_button="no",
        )

        result = dialog.exec_()
        if result == QDialog.Accepted and dialog.result_value == "yes":
            del bookmarks[index]
            settings.setValue(bookmark_key, json.dumps(bookmarks))
            settings.sync()
            self.say(self.tr("bookmark_removed", name))
            self.update_bookmark_menu()

    def confirm_clear_all_bookmarks(self):
        """Bestätigungsdialog zum Löschen aller Lesezeichen."""
        bookmarks = self.load_current_bookmarks()
        if not bookmarks:
            return

        dialog = myUniversalDialog(
            self,
            title=self.tr("confirm"),
            message=self.tr("bookmark_confirm_remove_all", len(bookmarks)),
            buttons=[
                (self.tr("btn_yes"), "danger", "yes"),
                (self.tr("btn_no"), "primary", "no"),
            ],
            icon_type="",
            voice_message=self.tr("bookmark_confirm_remove_all", len(bookmarks)),
            default_button="no",
        )

        result = dialog.exec_()
        if result == QDialog.Accepted and dialog.result_value == "yes":
            bookmark_key = self.get_pdf_bookmark_key()
            settings = QSettings("BinhDiez", "PDFDarkView")
            settings.setValue(bookmark_key, "[]")
            settings.sync()
            self.say(self.tr("bookmark_all_removed"))
            self.update_bookmark_menu()

    ###------------------------------------
    ### OCR Cmd+R
    ###-----------------------------------

    # 1. perform_ocr() - Hauptmethode
    def perform_ocr(self, action_name="OCR"):
        if not self.pdf_path:
            dialog = myUniversalDialog(
                self,
                # "kein PDF geladen"
                title=self.tr("no_pdf_loaded"),
                # "Es ist kein PDF geladen"
                message=self.tr("no_pdf_message"),
                icon_type="",
                # "kein PDF geladen"
                voice_message=self.tr("no_pdf_loaded"),
            )
            dialog.exec_()
            return

        if not hasattr(self, "ocr_available") or not self.ocr_available:
            dialog = myUniversalDialog(
                self,
                # "OCR fehlgeschlagen"
                title=self.tr("ocr_failed"),
                # OCR-Tools fehlen ...
                message=self.tr("ocr_install_message"),
                icon_type="",
                voice_message=self.tr("ocr_failed"),
            )
            dialog.exec_()
            return

        response = None  # Initialisierung (wichtig!)

        if hasattr(self, "has_rotated_pages") and self.has_rotated_pages(self.pdf_path):
            # Frage Benutzer, ob er ausrichten möchte (falls Methode existiert)
            if hasattr(self, "ask_rotate_before_ocr"):
                response = self.ask_rotate_before_ocr()
            else:
                # Fallback: keine Abfrage, einfach normalisieren (optional)
                response = "yes"  # oder "no", je nach Wunsch

            if response == "cancel":
                return
            elif response == "yes":
                if hasattr(self, "create_normalized_temp_copy"):
                    temp_normalized = self.create_normalized_temp_copy(self.pdf_path)
                    if temp_normalized and os.path.exists(temp_normalized):
                        self._run_guaranteed_ocr_simple(
                            action_name, input_path=temp_normalized
                        )
                        return
                    else:
                        self.say(self.tr("ocr_normalize_failed"))
                        # Fallthrough – weitermachen mit Original
                else:
                    # Methode nicht vorhanden – trotzdem OCR starten
                    pass
            # Bei "no" einfach weitermachen

        # Normaler OCR-Aufruf (ohne Normalisierung)
        self._run_guaranteed_ocr_simple(action_name)

    # 2. _run_guaranteed_ocr_simple() - Startet OCR
    def _run_guaranteed_ocr_simple(self, action_name, input_path=None):
        if input_path is None:
            input_path = self.pdf_path

        # Vor dem Start die Sprache prüfen (nur auf macOS/Linux, auf Windows überspringen)
        if platform.system() != "Windows":
            settings = QSettings("BinhDiez", "PDFDarkView")
            ocr_lang = settings.value("ocr_language", "deu+eng+vie")
            if not self.check_ocr_languages_available(ocr_lang):
                self.say(self.tr("ocr_cancelled_due_to_missing_languages"))
                return

        try:
            self.show_ocr_progress_dialog()
            self.loading_label.setText(self.tr("ocr_starting"))
            QApplication.processEvents()

            temp_path = self.generate_custom_filename(
                suffixes="_ocr", update_timestamp=False
            )

            print(f"\n🔧 Starte OCR")
            print(f"📥 Input: {input_path}")
            print(f"📤 Output: {temp_path}")

            self.ocr_thread = OCRThread(input_path, temp_path, self.dark_mode)
            self.ocr_thread.real_ocr_done = False  # ← Sicherheitshalber
            self.ocr_thread.progress_updated.connect(self._update_ocr_progress)
            self.ocr_thread.finished.connect(
                lambda success, msg: self.ocr_completed(
                    success, msg, temp_path, action_name
                )
            )
            self.ocr_thread.start()

        except Exception as e:
            print(f"💥 OCR-Start fehlgeschlagen: {str(e)}")
            self._close_progress_dialog()

    # 3. ocr_completed() - Verarbeitet Ergebnis
    def ocr_completed(self, success, msg, temp_path, action_name):

        try:
            self.ocr_in_progress = False
            self._close_progress_dialog()

            # Plattformspezifische Erfolgsprüfung
            if platform.system() == "Windows":
                # Unter Windows vertrauen wir allein der Existenz der Datei
                real_success = (
                    os.path.exists(temp_path) and os.path.getsize(temp_path) > 0
                )
            else:
                real_success = (
                    success
                    and os.path.exists(temp_path)
                    and getattr(self.ocr_thread, "real_ocr_done", False)
                )

            if real_success:
                # Erfolg: Datei verschieben, Dialog anzeigen, neu laden
                try:
                    original_size = (
                        os.path.getsize(self.pdf_path)
                        if os.path.exists(self.pdf_path)
                        else 0
                    )
                    new_size = os.path.getsize(temp_path)
                    original_size_str = self._format_file_size(original_size)
                    new_size_str = self._format_file_size(new_size)
                    diff = new_size - original_size
                    diff_abs = abs(diff)
                    diff_sign = "+" if diff > 0 else "-" if diff < 0 else ""
                    diff_str = (
                        self._format_file_size(diff_abs) if diff_abs > 0 else "0 Bytes"
                    )

                    target_path = self.generate_custom_filename(
                        suffixes=["_ocr"], update_timestamp=False
                    )
                    final_path = self._prepare_overwrite_target(target_path)

                    shutil.move(temp_path, final_path)

                    original_name = os.path.basename(self.pdf_path)
                    ocr_name = os.path.basename(final_path)

                    # Marker für Textfenster
                    self.ocr_performed = True
                    self.last_ocr_pdf = final_path

                    # ggf. temporäre gedrehte PDF löschen
                    if hasattr(self, "_current_normalized_temp") and os.path.exists(
                        self._current_normalized_temp
                    ):
                        os.unlink(self._current_normalized_temp)
                        self.remove_temp_file(self._current_normalized_temp)
                        self._current_normalized_temp = None

                    message_lines = [
                        self.tr("ocr_success"),
                        "",
                        self.tr("original_file"),
                        f"{original_name}",
                        "",
                        self.tr("old_size", original_size_str),
                        self.tr("new_size", new_size_str),
                        "",
                        self.tr("size_change", diff_sign, diff_str),
                        "",
                        self.tr("ocr_new_file_question", ocr_name),
                    ]
                    message_text = "\n".join(message_lines)
                    self.say(self.tr("ocr_success_voice"), convert_numbers=True)

                    dialog = myUniversalDialog(
                        self,
                        title=self.tr("ocr_success_title"),
                        message=message_text,
                        buttons=[
                            (self.tr("ocr_open_new"), "success", "open", 330),
                            (self.tr("ocr_keep_original"), "primary", "keep", 330),
                        ],
                        icon_type="",
                        voice_message="",
                        text_alignment=Qt.AlignLeft,
                    )
                    dialog.exec_()

                    if dialog.result_value == "open":
                        self._cleanup_all_modes()
                        if self._open_text_window_on_ocr_success:
                            self._open_text_window_next = True
                            self._open_text_window_on_ocr_success = False
                        self.load_pdf(final_path)
                        self._cached_native = None
                        self._cached_native_path = None
                    else:
                        self._open_text_window_on_ocr_success = False
                        self.say(self.tr("ocr_original_kept"))

                except Exception as e:
                    print(f"💥 Fehler nach erfolgreicher OCR: {str(e)}")
                    error_message = self.tr("ocr_partial_success", temp_path, str(e))
                    QMessageBox.critical(self, self.tr("error"), error_message)

                pass
            else:
                # Fehler: Aufräumen, Fehlermeldung anzeigen
                if os.path.exists(temp_path):
                    os.remove(temp_path)

                # Detaillierte Fehlermeldung aufbereiten
                error_detail = msg if msg else self.tr("ocr_unknown_error")
                # Begrenze die Länge für den Dialog (optional, aber sinnvoll)
                if len(error_detail) > 2000:
                    error_detail = error_detail[:2000] + "\n... (Nachricht gekürzt)"

                dialog = myUniversalDialog(
                    self,
                    title=self.tr("ocr_failed"),
                    message=f"{error_detail}",
                    buttons=[(self.tr("btn_ok"), "primary", "ok")],
                    icon_type="error",
                    voice_message=self.tr("ocr_failed"),
                    text_alignment=Qt.AlignLeft,
                )
                dialog.exec_()

        except Exception as e:
            import traceback

            traceback.print_exc()
            # Zeige Fehler im Dialog an (damit du ihn siehst)
            QMessageBox.critical(
                self,
                "Interner Fehler",
                f"Fehler in ocr_completed:\n{str(e)}\n\nSiehe Konsole für Details.",
            )
            # Aufräumen nicht vergessen
            if os.path.exists(temp_path):
                os.remove(temp_path)
            self.ocr_in_progress = False
            self._close_progress_dialog()

    def _format_file_size(self, size_bytes):
        """
        Formatiert eine Dateigröße in Bytes in eine lesbare Form mit passender Einheit.

        Args:
            size_bytes: Größe in Bytes

        Returns:
            String mit formatierter Größe und Einheit (z.B. "1.234 KB" oder "12,3 MB")
        """
        if size_bytes < 1024:
            return f"{size_bytes} Bytes"
        elif size_bytes < 1024 * 1024:
            kb = size_bytes / 1024
            # Bei KB: Ganzzahlen oder eine Nachkommastelle
            if kb < 10:
                return f"{kb:.1f} KB"
            else:
                return f"{int(kb)} KB"
        else:
            mb = size_bytes / (1024 * 1024)
            # Bei MB: Eine oder zwei Nachkommastellen
            if mb < 10:
                return f"{mb:.1f} MB"
            elif mb < 100:
                return f"{mb:.1f} MB"
            else:
                return f"{int(mb)} MB"

    # 4. get_backup_filename() - Backup Dateiname
    def get_backup_filename(self, original_path=None):
        """Erstellt einen Backup-Dateinamen für die aktuell geöffnete PDF."""
        # -backup mit Übersetzung
        # return self.generate_custom_filename(suffixes=[self.tr('filename_backup_suffix')])
        # _backup ohne Übersetzung
        return self.generate_custom_filename(suffixes="_backup")

    # 5. _close_progress_dialog() - Dialog schließen
    def _close_progress_dialog(self):
        """Schließt Fortschrittsdialog"""
        if hasattr(self, "loading_dialog") and self.loading_dialog:
            try:
                self.loading_dialog.hide()
                self.loading_dialog.deleteLater()
                self.loading_dialog = None
            except:
                pass

    # 6. _open_pdf_in_new_window() - Fenster öffnen
    def _open_pdf_in_new_window(self, pdf_path):
        """Öffnet PDF in neuem Fenster"""
        try:
            if os.path.exists(pdf_path):
                # Kurze Verzögerung für Stabilität
                QTimer.singleShot(300, lambda: self._open_pdf_window(pdf_path))
        except Exception as e:
            print(f"❌ Öffnen fehlgeschlagen: {str(e)}")

    # 7. _open_pdf_window() - Fenster öffnen (Hilfe)
    def _open_pdf_window(self, pdf_path):
        """Öffnet tatsächlich das Fenster"""
        try:
            new_viewer = PDFViewer(pdf_path)
            new_viewer.showMaximized()
        except:
            pass

    # 8. perform_ocr_request() - OCR-Abfrage Dialog
    def perform_ocr_request(self, action_name):
        """Existierende OCR-Abfrage - angepasst für myUniversalDialog"""
        if self.ocr_in_progress and self.pdf_path:
            return False

        if self.ocr_declined and self.last_ocr_pdf == self.pdf_path:
            return False

        # Logo für Dialog vorbereiten
        logo_path = Config.IMAGE_PATH if os.path.exists(Config.IMAGE_PATH) else None

        # Dialog erstellen
        dialog = myUniversalDialog(
            parent=self,
            # "OCR erforderlich"
            title=self.tr("ocr_required"),
            # "<p>Das PDF enthält keinen durchsuchbaren Text.<p>Möchten Sie OCR durchführen, um <b>{0}</b> zu ermöglichen?</p>"
            message=self.tr("ocr_question_html", action_name),
            buttons=[
                # "OCR durchführen"
                (self.tr("ocr_perform"), "primary", "ocr", 180),
                # "Später"
                (self.tr("ocr_later"), "dark", "later", 180),
                # "Abbrechen"
                (self.tr("btn_cancel"), "danger", "cancel", 180),
            ],
            icon_type="",
            # "OCR erforderlich. Das PDF enthält keinen durchsuchbaren Text. Möchten Sie OCR durchführen, um {0} zu ermöglichen?"
            voice_message=self.tr("ocr_question_voice", action_name),
            default_button="ocr",
            text_alignment=Qt.AlignLeft,
        )

        # Dialog ausführen und Ergebnis verarbeiten
        result = dialog.exec_()

        if result == QDialog.Accepted:
            if dialog.result_value == "ocr":
                self.perform_ocr(action_name)
                return True
            elif dialog.result_value == "later":
                return False
            else:
                # Für den Fall, dass ein anderer Button gedrückt wurde
                return False
        else:  # QDialog.Rejected (Abbrechen oder ESC)
            self.ocr_declined = True
            self.last_ocr_pdf = self.pdf_path
            return False

