    # 10. _update_ocr_progress() - Fortschritt aktualisieren
    def _update_ocr_progress(self, value):
        """Aktualisiert die OCR-Fortschrittsanzeige (nur Prozentwert)"""
        # print(f"DEBUG: _update_ocr_progress called with value={value}")
        # print(f"DEBUG: self.progress_bar = {self.progress_bar}")
        # print(f"DEBUG: self.loading_label = {self.loading_label}")

        try:
            if hasattr(self, "progress_bar") and self.progress_bar:
                self.progress_bar.setValue(value)

            # Statusmeldungen basierend auf Fortschritt
            if value < 20:
                # Original: status = "PDF wird analysiert..."
                status = self.tr("ocr_status_analyzing")
            elif value < 40:
                # Original: status = "Bildoptimierung läuft..."
                status = self.tr("ocr_status_optimizing")
            elif value < 60:
                # Original: status = "Texterkennung in Arbeit..."
                status = self.tr("ocr_status_recognizing")
            elif value < 80:
                # Original: status = "Text wird eingebettet..."
                status = self.tr("ocr_status_embedding")
            else:
                # Original: status = "Finalisierung der PDF..."
                status = self.tr("ocr_status_finalizing")

            if hasattr(self, "loading_label") and self.loading_label:
                self.loading_label.setText(status)

        except RuntimeError:
            pass  # Ignoriere Fehler bei zerstörten Objekten

    ### 11. Prüfung ob OCR erforderlich ist
    ### Achtung beide Methoden werden verwendet
    def is_native_pdf(self):
        if not self.pdf_path:
            return False

        # Cache-Verwaltung (wie bisher)
        if (
            hasattr(self, "_cached_native")
            and hasattr(self, "_cached_native_path")
            and self._cached_native_path == self.pdf_path
        ):
            return self._cached_native

        doc = None
        try:
            doc = fitz.open(self.pdf_path)

            # ===== NEU: Prüfe auf Windows-OCR-Markierung =====
            meta = doc.metadata
            producer = meta.get("producer", "")
            if "PDFDarkView_WindowsOCR" in producer:
                doc.close()
                self._cached_native = False
                self._cached_native_path = self.pdf_path
                return False

            # ===== BISHERIGE TEXT-SPAN-PRÜFUNG =====
            for page in doc:
                for block in page.get_text("dict").get("blocks", []):
                    for line in block.get("lines", []):
                        for span in line.get("spans", []):
                            if span.get("font") and span.get("text", "").strip():
                                doc.close()
                                self._cached_native = True
                                self._cached_native_path = self.pdf_path
                                return True
            doc.close()
            self._cached_native = False
            self._cached_native_path = self.pdf_path
            return False
        except Exception:
            return False
        finally:
            if doc:
                doc.close()

    ### 12. Prüfung ob OCR erforderlich pedantisch (streng)
    ### deutsch - englisch - vietnamesisch
    def check_pdf_has_text(self):
        """
        Prüft, ob die PDF bereits durchsuchbaren Text enthält.
        Sprachunabhängig durch Analyse von Satzzeichen und Wortlängen.
        """
        if not self.pdf_path:
            return False

        doc = fitz.open(self.pdf_path)
        try:
            # Maximal 10 Seiten analysieren (performant)
            max_pages = min(len(doc), 10)
            text_samples = []

            for i in range(max_pages):
                text = doc[i].get_text("text").strip()
                if text:
                    text_samples.append(text)

            if not text_samples:
                return False

            combined = " ".join(text_samples)

            # Entferne häufige Nicht-Text-Elemente (Seitenzahlen, kurze Zahlen)
            combined = re.sub(r"\b\d{1,3}\b", "", combined)
            # Entferne einzelne Buchstaben (könnten Rauschen sein)
            combined = re.sub(r"\b\w\b", "", combined)

            # Prüfe auf Satzzeichen (universelles Merkmal)
            has_punctuation = bool(re.search(r'[.,!?;:()"\'-]', combined))

            # Prüfe auf längere Wörter (mindestens 3 Zeichen)
            words = re.findall(r"\b\w{3,}\b", combined)
            word_count_condition = len(words) >= 5  # Weniger streng als vorher

            return has_punctuation and word_count_condition

        except Exception as e:
            print(f"Fehler in check_pdf_has_text: {e}")
            return False
        finally:
            doc.close()

    ### 13. Prüfe installierte OCR Sprachen

    def check_ocr_languages_available(self, lang_string):
        """Prüft, ob alle angegebenen Tesseract-Sprachen installiert sind."""

        available = get_available_tesseract_languages()
        required = [lang.strip() for lang in lang_string.split("+") if lang.strip()]
        missing = [lang for lang in required if lang not in available]

        if not missing:
            return True

        # Fehlende Sprachen formatieren (mit Namen, falls bekannt)
        missing_names = []
        for code in missing:
            # Versuche, einen lesbaren Namen zu bekommen
            iso = TESSERACT_TO_ISO.get(code, code)
            info = LANGUAGE_INFO.get(iso, {})
            name = info.get("name", code.upper())
            flag = info.get("flag", "🌐")
            missing_names.append(f"{flag} {name} ({code})")

        missing_text = "\n".join(missing_names)

        dialog = myUniversalDialog(
            self,
            title=self.tr("ocr_missing_languages"),
            message=self.tr("ocr_missing_languages_message", missing_text),
            buttons=[
                (self.tr("ocr_install_help_now"), "primary", "help", 200),
                (self.tr("ocr_continue_anyway"), "warning", "continue", 200),
                (self.tr("btn_cancel"), "danger", "cancel", 120),
            ],
            icon_type="",
            voice_message=self.tr("ocr_missing_languages_voice"),
            text_alignment=Qt.AlignLeft,
            default_button="help",
        )
        dialog.exec_()

        if dialog.result_value == "help":
            self.show_ocr_install_help()
            return False
        elif dialog.result_value == "continue":
            return True  # Benutzer will trotzdem versuchen (nicht empfohlen)
        else:
            return False

