    # 17. Prüfen, ob das PDF gedrehte Seiten enthält
    def has_rotated_pages(self, pdf_path):
        """Prüft, ob mindestens eine Seite eine Rotation ungleich 0° hat."""
        try:
            doc = fitz.open(pdf_path)
            for page in doc:
                # page.rotation gibt die aktuelle Rotation in Grad (0, 90, 180, 270)
                if page.rotation % 90 != 0 or page.rotation != 0:
                    doc.close()
                    return True
            doc.close()
            return False
        except Exception as e:
            print(f"Fehler beim Prüfen der Rotation: {e}")
            return False

    def create_normalized_temp_copy(self, pdf_path):
        """Erstellt eine temporäre PDF-Kopie, bei der alle Seiten auf 0° gedreht sind."""
        try:
            # Temporäre Datei anlegen
            fd, temp_path = tempfile.mkstemp(suffix=".pdf", prefix="normalized_")
            os.close(fd)
            self.add_temp_file(temp_path)  # falls vorhanden, sonst selbst verwalten

            # Original öffnen und normalisiert speichern
            src_doc = fitz.open(pdf_path)
            dst_doc = fitz.open()  # leeres Dokument

            for src_page in src_doc:
                # Rotation auf 0° setzen (physisch)
                src_page.set_rotation(0)
                # Seite in neues Dokument einfügen (behält die korrigierte Ausrichtung)
                dst_doc.insert_pdf(
                    src_doc, from_page=src_page.number, to_page=src_page.number
                )

            dst_doc.save(temp_path, garbage=4, deflate=True)
            dst_doc.close()
            src_doc.close()

            return temp_path
        except Exception as e:
            print(f"Fehler beim Erstellen der normalisierten Kopie: {e}")
            return None

