    def _update_delete_progress(self, percent, message, details):
        """Aktualisiert die Fortschrittsanzeige beim Löschen"""
        try:
            self.delete_progress_bar.setValue(percent)
            self.delete_status_label.setText(message)
            self.delete_details_label.setText(details)
        except:
            pass

    def _handle_delete_finished(self, result):
        """Behandelt das Ende des Löschvorgangs"""
        try:
            self.delete_progress_dialog.accept()

            if result.get("success", False):
                deleted_count = result.get("deleted_count", 0)
                if deleted_count > 0:
                    # PDF neu laden
                    self.pdf_path = result.get("edited_path", self.pdf_path)
                    self.load_pdf()

                    # Erfolgsmeldung
                    if self.create_backup:
                        info_msg = self.tr(
                            "pages_deleted_with_backup",
                            deleted_count,
                            os.path.basename(result.get("backup_path", "")),
                        )
                        voice_msg = self.tr("pages_deleted_voice", deleted_count)
                    else:
                        new_filename = os.path.basename(result.get("edited_path", ""))
                        info_msg = self.tr(
                            "pages_deleted_new_file", deleted_count, new_filename
                        )
                        voice_msg = self.tr(
                            "pages_deleted_new_file_voice", deleted_count, new_filename
                        )

                    dialog = myUniversalDialog(
                        self,
                        title=self.tr("success"),
                        message=info_msg,  # ← Korrektur
                        icon_type="",
                        voice_message=voice_msg,
                        text_alignment=Qt.AlignLeft,
                    )
                    dialog.exec_()
                else:
                    self.say(self.tr("pages_deleted_none"))
                    dialog = myUniversalDialog(
                        self,
                        title=self.tr("info"),
                        message=self.tr("pages_deleted_none"),
                        icon_type="",
                        voice_message=self.tr("pages_deleted_none"),
                        text_alignment=Qt.AlignLeft,
                    )
                    dialog.exec_()
            else:
                QMessageBox.critical(
                    self,
                    self.tr("error"),
                    result.get("error", self.tr("error_unknown")),
                )
        finally:
            self._cleanup_delete_resources()

    def _handle_delete_error(self, error_msg):
        """Behandelt Fehler beim Löschen"""
        try:
            self.delete_progress_dialog.reject()
            QMessageBox.critical(self, self.tr("error"), error_msg)
        finally:
            self._cleanup_delete_resources()

    def _cleanup_delete_resources(self):
        """Räumt Ressourcen des Löschvorgangs auf"""
        try:
            if hasattr(self, "delete_worker"):
                self.delete_worker.quit()
                self.delete_worker.wait(500)
            if hasattr(self, "delete_progress_dialog"):
                self.delete_progress_dialog.deleteLater()
        except:
            pass

