    def _handle_move_finished(self, result):
        try:
            if hasattr(self, "move_progress_dialog") and self.move_progress_dialog:
                self.move_progress_dialog.accept()

            if result.get("success", False):
                moved_count = result.get("moved_count", 0)
                self.pdf_path = result.get("edited_path", self.pdf_path)
                current_mode = self.zoom_mode
                self.load_pdf()
                self.set_zoom_mode(current_mode)

                if self.create_backup:
                    # Backup war aktiv -> Original überschrieben
                    info_msg = self.tr(
                        "pages_moved_with_backup",
                        moved_count,
                        os.path.basename(result.get("backup_path", "")),
                    )
                    voice_msg = self.tr("pages_moved_voice", moved_count)
                else:
                    # Backup war inaktiv -> neue Datei erstellt
                    new_filename = os.path.basename(result.get("edited_path", ""))
                    info_msg = self.tr(
                        "pages_moved_new_file", moved_count, new_filename
                    )
                    voice_msg = self.tr(
                        "pages_moved_new_file_voice", moved_count, new_filename
                    )

                dialog = myUniversalDialog(
                    self,
                    title=self.tr("move_success_title"),
                    message=info_msg,
                    icon_type="",
                    voice_message=voice_msg,
                    text_alignment=Qt.AlignLeft,
                )
                dialog.exec_()
            else:
                QMessageBox.critical(
                    self,
                    self.tr("error"),
                    result.get("error", self.tr("error_unknown")),
                )

        except Exception as e:
            print(f"Fehler in _handle_move_finished: {str(e)}")
        finally:
            self._cleanup_move_resources()

    def _handle_move_error(self, error_msg):
        """Behandelt Fehler beim Verschieben"""
        try:
            self.move_progress_dialog.reject()
            QMessageBox.critical(self, self.tr("error"), error_msg)
        finally:
            self._cleanup_move_resources()

    def _cleanup_move_resources(self):
        """Ressourcen für Move-Operation aufräumen"""
        try:
            if hasattr(self, "move_worker"):
                if self.move_worker.isRunning():
                    self.move_worker.quit()
                    self.move_worker.wait(500)
                self.move_worker = None

            if hasattr(self, "move_progress_dialog"):
                try:
                    self.move_progress_dialog.close()
                    self.move_progress_dialog.deleteLater()
                except:
                    pass
                self.move_progress_dialog = None

        except Exception as e:
            print(f"Fehler in _cleanup_move_resources: {str(e)}")

    # ================================================
