    def merge_pdfs(self):
        """Öffnet den Dialog zum Zusammenführen mehrerer PDFs"""
        if not self.check_for_unsaved_changes("open_new_pdf"):
            return

        dialog = MergePDFsDialog(self)
        if dialog.exec_() == QDialog.Accepted:
            selection = dialog.get_selection()
            self.process_merge_pdfs(selection)

    def process_merge_pdfs(self, selection):
        """Verarbeitet das Zusammenführen von PDFs mit Fortschrittsdialog"""
        try:
            # Zielverzeichnis bestimmen
            pdf_files = selection["pdf_files"]

            if pdf_files:
                # Verzeichnis der ersten ausgewählten PDF verwenden
                first_pdf_path = pdf_files[0][0]
                target_dir = os.path.dirname(first_pdf_path)
            else:
                # Fallback: Downloads-Ordner
                target_dir = os.path.expanduser("~/Downloads")

            # Basisnamen aus erster PDF oder generischen Namen
            if pdf_files:
                base_name = os.path.splitext(os.path.basename(pdf_files[0][0]))[0]
            else:
                base_name = "zusammengefuehrte_pdfs"

            # Zentrale Dateinamen-Generierung verwenden
            # Erstelle einen temporären Pfad für die generate-Methode
            temp_pdf_path = os.path.join(target_dir, f"{base_name}.pdf")

            final_path = FilenameGenerator.generate(
                pdf_path=temp_pdf_path,
                base_name=base_name,
                suffixes=[self.tr("filename_merge_suffix")],
                is_protected=False,
                update_timestamp=True,
            )

            # Bei Namenskonflikt Nummer anhängen (zusätzliche Sicherheit)
            counter = 1
            base, ext = os.path.splitext(final_path)
            while os.path.exists(final_path):
                final_path = f"{base}_{counter}{ext}"
                counter += 1

            # Fortschrittsdialog erstellen
            self.merge_progress_dialog = self._create_merge_progress_dialog()
            self.merge_progress_dialog.show()
            QApplication.processEvents()

            # Worker-Thread starten
            self.merge_worker = MergePDFsWorker(
                selection, final_path, self.lang, self.create_backup
            )
            self.merge_worker.progress_updated.connect(self._update_merge_progress)
            self.merge_worker.finished.connect(self._handle_merge_finished)
            self.merge_worker.error_occurred.connect(self._handle_merge_error)

            if hasattr(self, "merge_cancel_btn"):
                self.merge_cancel_btn.clicked.connect(self.merge_worker.cancel)

            self.merge_worker.start()

        except Exception as e:
            self._cleanup_merge_resources()
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('error_dialog_creation')}:\n{str(e)}"
            )

