    def change_page_size(self):
        """Ändert die Seitengröße der PDF."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            self._show_no_pdf_dialog()
            return

        dialog = PageSizeDialog(self)
        if dialog.exec_() != QDialog.Accepted:
            self.say(self.tr("pagesize_cancel"))
            return

        settings = dialog.get_data()
        self.say(self.tr("pagesize_start"))

        try:
            suffix = self.tr("filename_pagesize_suffix")
            output_path = self.generate_custom_filename(
                suffixes=[suffix], force_new_file=True
            )

            self.pagesize_thread = PageSizeThread(self.pdf_path, output_path, settings)
            self.pagesize_thread.progress_updated.connect(
                self._update_pagesize_progress
            )
            self.pagesize_thread.finished.connect(self._on_pagesize_finished)

            self.pagesize_progress_dialog = QProgressDialog(
                self.tr("pagesize_progress"), self.tr("btn_cancel"), 0, 100, self
            )
            self.pagesize_progress_dialog.setWindowModality(Qt.WindowModal)
            self.pagesize_progress_dialog.setMinimumWidth(400)
            self.pagesize_progress_dialog.setStyleSheet("""
                QProgressDialog {
                    background-color: #2D2D2D;
                    color: #E0E0E0;
                }
            """)
            self.pagesize_progress_dialog.canceled.connect(self._cancel_pagesize)
            self.pagesize_progress_dialog.show()

            self.pagesize_thread.start()

        except Exception as e:
            error_msg = self.tr("pagesize_error_format", str(e))
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()
            print(f"Fehler beim Ändern der Seitengröße: {e}")
            traceback.print_exc()

    def _update_pagesize_progress(self, progress, message):
        """Aktualisiert den Fortschritts-Dialog."""
        if hasattr(self, "pagesize_progress_dialog") and self.pagesize_progress_dialog:
            self.pagesize_progress_dialog.setValue(progress)
            if message:
                self.pagesize_progress_dialog.setLabelText(message)

    def _cancel_pagesize(self):
        """Bricht das Ändern der Seitengröße ab."""
        if hasattr(self, "pagesize_thread") and self.pagesize_thread:
            self.pagesize_thread.cancel()
            self.say(self.tr("pagesize_cancel"))

    def _on_pagesize_finished(self, success, message, output_path):
        """Behandelt das Ende des Änderns der Seitengröße."""
        if hasattr(self, "pagesize_progress_dialog") and self.pagesize_progress_dialog:
            self.pagesize_progress_dialog.close()
            self.pagesize_progress_dialog = None

        if success:
            success_message = self.tr("pagesize_success", output_path)
            confirm_dialog = myUniversalDialog(
                self,
                title=self.tr("success"),
                message=success_message,
                buttons=[
                    (self.tr("confirm_yes"), "primary", "yes"),
                    (self.tr("confirm_no"), "danger", "no"),
                ],
                icon_type="",
                voice_message=self.tr("pagesize_complete"),
                default_button="yes",
                text_alignment=Qt.AlignLeft,
            )
            confirm_dialog.exec_()

            if confirm_dialog.result_value == "yes":
                self.close_current_pdf()
                self.load_pdf(output_path)
        else:
            error_msg = self.tr("pagesize_error_format", message)
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
                text_alignment=Qt.AlignLeft,
            ).exec_()

