    ### 1. Master PW Prüfung für Signaturen und private Textbausteine
    def ensure_master_authentication(self, on_success):
        """Prüft die Authentifizierungsbedingungen für Signaturen.
        Wenn alle Bedingungen erfüllt sind, wird on_success() aufgerufen.
        Andernfalls werden Dialoge angezeigt, die den Benutzer durch die
        Einrichtung/Authentifizierung führen, und bei Erfolg on_success aufgerufen.
        """
        if not PDFPasswordManager.is_master_password_set():
            # Kein Master-PW → Frage, ob eingerichtet werden soll
            dialog = myUniversalDialog(
                self,
                # "Master-Passwort erforderlich"
                title=self.tr("master_password_required"),
                # "Um Signaturen verwenden zu können, müssen Sie ein Master-Passwort einrichten.\n\nMöchten Sie jetzt ein Master-Passwort einrichten?"
                message=self.tr("master_password_for_signatures"),
                buttons=[
                    # "Ja"
                    (self.tr("confirm_yes"), "primary", "yes"),
                    # "Nein"
                    (self.tr("confirm_no"), "danger", "no"),
                ],
                icon_type="",
                text_alignment=Qt.AlignLeft,
            )
            if dialog.exec_() == QDialog.Accepted and dialog.result_value == "yes":
                setup_dialog = MasterPasswordDialog(self, mode="setup")
                if setup_dialog.exec_() == QDialog.Accepted:
                    # Passwort wurde bereits im Dialog gespeichert
                    self.master_authenticated = True
                    # Kein parent_window nötig – self ist bereits das Hauptfenster
                    on_success()
            return

        # Master-PW ist gesetzt
        if PDFPasswordManager.get_signature_auth_disabled():
            # Abfrage deaktiviert → sofort on_success
            on_success()
            return

        # Abfrage aktiviert
        if self.master_authenticated:
            on_success()
            return

        # Authentifizierung notwendig
        auth_dialog = MasterPasswordDialog(self, mode="verify")
        if auth_dialog.exec_() == QDialog.Accepted:
            self.master_authenticated = True
            on_success()

    ### 2. Einfügeposition bei Aufruf über ShortCut ohne vorherigen Mausklick
    def _get_insertion_position(self, default_y_ratio=0.5):
        """
        Ermittelt die Einfügeposition basierend auf letztem Mausklick oder Standard.
        Gibt ein Tupel (lokale Position als QPointF, Zielseite als int) zurück.
        Falls keine Seite verfügbar, wird (None, None) zurückgegeben.
        """
        if not self.page_items:
            return None, None

        # Wenn eine Mausposition gespeichert ist (z.B. durch vorherigen Klick)
        if (
            hasattr(self, "last_mouse_scene_pos")
            and self.last_mouse_scene_pos is not None
        ):
            # Prüfe, auf welcher Seite die Mausposition liegt (mit korrekter Umrechnung)
            for i, page_item in enumerate(self.page_items):
                # Scene-Position in lokale Koordinaten der Seite umwandeln
                local_pos_on_page = page_item.mapFromScene(self.last_mouse_scene_pos)
                # Prüfen, ob der Punkt innerhalb der Seite liegt
                if page_item.boundingRect().contains(local_pos_on_page):
                    return local_pos_on_page, i
            # Mausposition liegt auf keiner Seite (z.B. nach Seitenwechsel)
            # Fallback: aktuelle Seite, Standardposition (Mitte, aber etwas oberhalb)
            target_page = self.current_page
            page_item = self.page_items[target_page]
            page_rect = page_item.boundingRect()
            local_pos = QPointF(
                page_rect.width() / 2, page_rect.height() * default_y_ratio
            )
            return local_pos, target_page

        # Fallback: aktuelle Seite, Standardposition (Mitte)
        target_page = self.current_page
        page_item = self.page_items[target_page]
        page_rect = page_item.boundingRect()
        local_pos = QPointF(page_rect.width() / 2, page_rect.height() * default_y_ratio)
        return local_pos, target_page

    ### 3. Dateiname mit Zeitstempel und Zusatz (ersetzt alte Erweiterungen)
    def generate_custom_filename(
        self,
        base_name=None,
        suffixes=None,
        is_protected=None,
        update_timestamp=True,
        force_new_file=False,
    ):
        """
        Wrapper für FilenameGenerator.
        force_new_file=True: ignoriert die Überschreib-Einstellung, erzeugt immer eine neue Datei.
        """
        if is_protected is None:
            is_protected = bool(getattr(self, "current_password", None))

        if not force_new_file:
            settings = QSettings("BinhDiez", "PDFDarkView")
            behavior = settings.value("filename/behavior", "new_file", type=str)
            if behavior == "overwrite":
                # Original überschreiben: gebe aktuellen Pfad zurück (KEIN Backup hier!)
                return self.pdf_path

        return FilenameGenerator.generate(
            pdf_path=self.pdf_path,
            base_name=base_name,
            suffixes=suffixes,
            is_protected=is_protected,
            update_timestamp=update_timestamp,
        )

