    ### 5. Zentrale Methode zum Neuladen mit Zielseite und Position
    def _reload_pdf_after_save_with_position(
        self, pdf_path, target_page, target_scene_pos, password=None
    ):
        """Lädt PDF neu und scrollt zur Position – ohne Timer, mit Callback."""
        try:
            print(f"\n=== PDF NEU LADEN - ZIELSEITE: {target_page + 1} ===")
            self._cleanup_all_modes()
            self.pdf_path = pdf_path

            # Sprunginformationen für später merken (gesprungen wird dann in _display_pdf also nach dem neu laden)
            self._pending_scroll_target = (target_page, target_scene_pos)

            # PDF laden (asynchron, aber am Ende wird _display_pdf aufgerufen)
            self.load_pdf(pdf_path, password=password)

        except Exception as e:
            print(f"Fehler beim Neu laden des PDF: {str(e)}")

    ### 6. Methode zum Springen zur Position
    def _jump_to_target_position(self):
        """Springt zur gespeicherten Seite und Position"""
        if not hasattr(self, "_target_page_after_load") or not hasattr(
            self, "_target_pos_after_load"
        ):
            return

        target_page = self._target_page_after_load
        target_pos = self._target_pos_after_load

        print(f"\n=== SPRINGE ZUR POSITION ===")
        print(f"Zielseite: {target_page + 1}, Gesamtseiten: {self.total_pages}")
        print(f"Zielposition: ({target_pos.x():.1f}, {target_pos.y():.1f})")

        # letzte Position und dann Fertigmeldung
        if target_page < self.total_pages:
            # 1. Zuerst zur richtigen Seite springen
            print(f"DEBUG: Setze Seite auf {target_page + 1}")
            self.current_page = target_page
            with QSignalBlocker(self.page_spin):
                self.page_spin.setValue(target_page + 1)

            # 2. Kurz warten bis die Seite geladen ist
            QTimer.singleShot(100, lambda: self._scroll_to_position(target_pos))

            # 3. Erfolgsmeldung falls gewünscht
            if self._show_success_dialog:
                QTimer.singleShot(300, self._show_delayed_success_dialog)

    ### 7. Methode zum Scrollen zur Position
    def _scroll_to_position(self, target_scene_pos):
        """Scrollt die Ansicht zu einer bestimmten Scene-Position (für Seitenbreite optimiert)."""
        try:
            print(
                f"DEBUG: _scroll_to_position nach ({target_scene_pos.x():.1f}, {target_scene_pos.y():.1f})"
            )

            if self.current_page < len(self.page_items):
                page_item = self.page_items[self.current_page]

                # Hole die aktuelle Viewport-Position
                viewport_rect = self.graphics_view.viewport().rect()
                view_center = self.graphics_view.mapToScene(viewport_rect.center())

                # Berechne die Differenz
                dx = target_scene_pos.x() - view_center.x()
                dy = target_scene_pos.y() - view_center.y()

                print(
                    f"DEBUG: Aktuelle View-Mitte: ({view_center.x():.1f}, {view_center.y():.1f})"
                )
                print(f"DEBUG: Differenz: dx={dx:.1f}, dy={dy:.1f}")

                # Methode 1: Direktes Setzen der Scrollbar-Position (genauer)
                if hasattr(self, "scroll_area") and self.scroll_area:
                    scrollbar = self.scroll_area.verticalScrollBar()

                    # Berechne die relative Position innerhalb der Seite
                    page_rect = page_item.boundingRect()
                    page_top = page_item.scenePos().y()
                    page_height = page_rect.height()

                    # Zielposition relativ zur Seite (0..1)
                    relative_y = (target_scene_pos.y() - page_top) / page_height

                    # Scrollbar-Position berechnen
                    scroll_max = scrollbar.maximum()
                    target_scroll = int(relative_y * scroll_max)

                    print(
                        f"DEBUG: Relative Y: {relative_y:.3f}, Scroll-Ziel: {target_scroll}/{scroll_max}"
                    )

                    # Scrollen mit Animation
                    self.animate_scroll(scrollbar, target_scroll)
                else:
                    # Fallback: centerOn
                    self.graphics_view.centerOn(target_scene_pos)
                    self.graphics_view.ensureVisible(
                        target_scene_pos.x(), target_scene_pos.y(), 50, 50
                    )

                # Force update
                self.graphics_view.viewport().update()
                QApplication.processEvents()

        except Exception as e:
            print(f"DEBUG: Fehler beim Scrollen: {e}")

