    ### 9. Zentrale CleanUp Version
    def _cleanup_all_modes(self):
        """Räumt alle aktiven Modi auf – sicher."""
        self._cleaning_up_text = False  # Schutz zurücksetzen (falls vorher abgebrochen)
        self._cleaning_up_signature = False
        self._cleaning_up_image = False
        self._cleaning_up_form = False
        self._cleaning_up_cross = False
