    ### 11. Copy & Paste ShortCuts (5 Methoden)
    def _handle_copy(self):
        """Behandelt Strg+C: Kopiert das aktuell ausgewählte Element."""
        # Prüfe der Reihe nach, welches Element aktuell ausgewählt ist
        if self.text_mode and self.current_text_item:
            self._copy_text_item(self.current_text_item)
            # "Text kopiert"
            self.say(self.tr("copy_text"))
        elif self.image_mode and self.current_image_item:
            self._copy_image_item(self.current_image_item)
            # "Bild kopiert"
            self.say(self.tr("copy_image"))
        elif self.form_mode and self.current_form_item:
            self._copy_form_item(self.current_form_item)
            # "Form kopiert"
            self.say(self.tr("copy_form"))
        elif self.signature_mode and self.current_signature_item:
            self._copy_signature_item(self.current_signature_item)
            # "Signatur kopiert"
            self.say(self.tr("copy_signature"))
        elif self.redaction_mode and self.current_redaction_item:
            self._copy_redaction_item(self.current_redaction_item)
            self.say(self.tr("redact_copied"))
        else:
            # "Kein Element zum Kopieren ausgewählt"
            self.say(self.tr("no_element_to_copy"))

        # "Kopiert: {0}"
        self.statusBar().showMessage(self.tr("copied", self._get_element_type()), 2000)

    def check_target_page_rotation(self, page_num, action_name="einzufügen"):
        """
        Prüft ob die Zielseite gedreht ist.
        Gibt True zurück wenn OK (nicht gedreht).
        Gibt False zurück wenn abgebrochen (Warnung + Abbruch).
        """
        if page_num >= len(self.page_items):
            return True

        try:
            doc = fitz.open(self.pdf_path)
            if hasattr(self, "current_password") and self.current_password:
                doc.authenticate(self.current_password)
            page = doc[page_num]
            rotation = page.rotation
            doc.close()
        except Exception as e:
            print(f"Fehler beim Prüfen der Seitenrotation: {e}")
            return True

        if rotation == 0:
            return True

        # Warnung ohne Dreh-Option
        dialog = myUniversalDialog(
            self,
            title=self.tr("page_rotated_warning_title"),
            message=self.tr(
                "paste_on_rotated_page_simple_warning", page_num + 1, rotation
            ),
            buttons=[(self.tr("btn_ok"), "primary", "ok")],
            icon_type="",
            voice_message=self.tr("paste_on_rotated_page_voice", page_num + 1),
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()
        return False  # Immer abbrechen

    def _paste_from_context(self, local_pos, page_num):
        """
        Einfügen aus Kontextmenü mit expliziter Position und Seite.
        Vermeidet Probleme mit globalen last_mouse_* Variablen.
        """

        # Prüfe ob kopierte Daten vorhanden sind
        has_data = (
            self.copied_text_data is not None
            or self.copied_image_data is not None
            or self.copied_form_data is not None
            or self.copied_signature_data is not None
            or self.copied_redaction_data is not None
        )  # neu

        if not has_data:
            self.say(self.tr("no_copied_data"))
            return

        # Prüfung auf gedrehte Seite (nur für Text/Bild/Form/Signatur – Redaction benötigt keine Umrechnung)
        if self.copied_redaction_data is None:
            if not self.check_target_page_rotation(page_num):
                return

        # Einfügen basierend auf Typ
        if self.copied_text_data is not None:
            self._paste_text_at_position(local_pos, page_num)
        elif self.copied_image_data is not None:
            self._paste_image_at_position(local_pos, page_num)
        elif self.copied_form_data is not None:
            self._paste_form_at_position(local_pos, page_num)
        elif self.copied_signature_data is not None:
            self._paste_signature_at_position(local_pos, page_num)
        elif self.copied_redaction_data is not None:  # neu
            self._paste_redaction_at_position(local_pos, page_num)

    def _handle_paste_from_menu(self):
        """Behandelt Einfügen über Shortcut oder Kontextmenü mit Rotationsprüfung."""
        # Prüfe ob kopierte Daten vorhanden sind
        has_data = (
            self.copied_text_data is not None
            or self.copied_image_data is not None
            or self.copied_form_data is not None
            or self.copied_signature_data is not None
        )

        if not has_data:
            self.say(self.tr("no_copied_data"))
            return

        # Position ermitteln (letzter Mausklick oder Fallback)
        if (
            hasattr(self, "last_mouse_scene_pos")
            and self.last_mouse_scene_pos is not None
        ):
            scene_pos = self.last_mouse_scene_pos
            page_num = self.last_mouse_page
            if page_num < len(self.page_items):
                page_item = self.page_items[page_num]
                local_pos = page_item.mapFromScene(scene_pos)
            else:
                local_pos = scene_pos
        else:
            local_pos, page_num = self._get_insertion_position(default_y_ratio=0.5)

        if local_pos is None:
            self.say(self.tr("no_valid_position"))
            return

        # Prüfung auf gedrehte Seite (Warnung + Abbruch bei gedrehter Seite)
        if not self.check_target_page_rotation(page_num):
            return  # Hier wird die Methode verlassen - NICHTS wird eingefügt

        # Nur wenn wir hier ankommen, ist die Seite NICHT gedreht
        # Jetzt erst einfügen
        if self.copied_text_data is not None:
            self._paste_text_at_position(local_pos, page_num)
        elif self.copied_image_data is not None:
            self._paste_image_at_position(local_pos, page_num)
        elif self.copied_form_data is not None:
            self._paste_form_at_position(local_pos, page_num)
        elif self.copied_signature_data is not None:
            self._paste_signature_at_position(local_pos, page_num)

    def _handle_paste(self):
        """Behandelt Strg+V: Fügt an der letzten Klickposition auf der AKTUELLEN Seite ein."""
        # Prüfe ob kopierte Daten vorhanden sind
        has_data = (
            self.copied_text_data is not None
            or self.copied_image_data is not None
            or self.copied_form_data is not None
            or self.copied_signature_data is not None
            or self.copied_redaction_data is not None
        )

        if not has_data:
            self.say(self.tr("no_copied_data"))
            return

        # Verwende die aktuell angezeigte Seite
        page_num = self.current_page

        if page_num >= len(self.page_items):
            self.say(self.tr("no_valid_position"))
            return

        # Letzte Mausposition in Scene-Koordinaten holen
        if (
            hasattr(self, "last_mouse_scene_pos")
            and self.last_mouse_scene_pos is not None
        ):
            scene_pos = self.last_mouse_scene_pos
            # Konvertiere zu lokalen Koordinaten auf der aktuellen Seite
            page_item = self.page_items[page_num]
            local_pos = page_item.mapFromScene(scene_pos)
            # Prüfen, ob die Position innerhalb der Seite liegt, sonst Mitte
            if not page_item.boundingRect().contains(local_pos):
                page_rect = page_item.boundingRect()
                local_pos = QPointF(page_rect.width() / 2, page_rect.height() / 2)
        else:
            # Fallback: Mitte der Seite
            page_item = self.page_items[page_num]
            page_rect = page_item.boundingRect()
            local_pos = QPointF(page_rect.width() / 2, page_rect.height() / 2)

        print(
            f"DEBUG _handle_paste: Seite={page_num+1}, Position=({local_pos.x():.1f}, {local_pos.y():.1f})"
        )

        # Prüfung auf gedrehte Seite
        if not self.check_target_page_rotation(page_num):
            return

        # Einfügen basierend auf Typ
        if self.copied_text_data is not None:
            self._paste_text_at_position(local_pos, page_num)
        elif self.copied_image_data is not None:
            self._paste_image_at_position(local_pos, page_num)
        elif self.copied_form_data is not None:
            self._paste_form_at_position(local_pos, page_num)
        elif self.copied_signature_data is not None:
            self._paste_signature_at_position(local_pos, page_num)
        if self.copied_redaction_data is not None:
            self._paste_redaction_at_position(local_pos, page_num)

    def _get_element_type(self):
        """Hilfsfunktion für Statusmeldung."""
        if self.text_mode:
            # "Text"
            return self.tr("element_text")
        if self.image_mode:
            # "Bild"
            return self.tr("element_image")
        if self.form_mode:
            # "Form"
            return self.tr("element_form")
        if self.signature_mode:
            # "Signatur"
            return self.tr("element_signature")
        # "Element"
        return self.tr("element_unknown")

    ### 12 Behalten von Einfügungen beim Neuladen Wechsel Dark / Light Mode ...
    ### 3 zentrale Methoden und 5 dezentrale

    def _save_overlay_data(self):
        """
        Sammelt alle Overlay-Elemente (Texte, Kreuze, Signaturen, Bilder, Formen, Redactions)
        und speichert sie in self._saved_overlays als unabhängige Datenstruktur.

        WICHTIG:
        - Die Daten werden als Python-Dictionaries gespeichert, NICHT als Qt-Objekte
        - Dadurch sind sie unabhängig von der Qt-Szene und überleben das Neuladen
        - Jeder Eintrag enthält alle nötigen Informationen zur Wiederherstellung
        - Auch der Dark Mode-Status wird berücksichtigt (Farben werden entsprechend gespeichert)

        RÜCKGABE:
        - None (die Daten werden in self._saved_overlays gespeichert)
        """

        data = []

        # ===== 1. Metadaten: Aktuelle Seite speichern =====
        if self.page_items:
            data.append({"type": "meta", "current_page": self.current_page})
        else:
            data.append({"type": "meta", "current_page": 0})

        # ===== 2. Texte und Kreuze sammeln =====
        # Wichtig: Wir iterieren über eine Kopie der Liste, falls sich während des Sammelns etwas ändert
        for item in self.all_text_items[:]:
            try:
                # Prüfen ob das Item noch gültig ist (nicht gelöscht)
                if item and not sip.isdeleted(item):

                    # ===== Kreuz (X-Mark) =====
                    if hasattr(item, "item_type") and item.item_type == "cross":
                        d = {
                            "type": "cross",
                            "page": item.page,
                            "pos_x": item.pos().x(),
                            "pos_y": item.pos().y(),
                            "font_size": item.font_size,
                            "line_width": item.line_width,
                            "arm_length": item.arm_length,
                            "color": (
                                item.text_color.name()
                                if hasattr(item, "text_color")
                                else "#000000"
                            ),
                            "bold": item.bold if hasattr(item, "bold") else True,
                            "offset_x": getattr(item, "offset_x", 0),
                            "offset_y": getattr(item, "offset_y", 0),
                        }

                    # ===== Text =====
                    else:
                        if hasattr(item, "get_format_data"):
                            fd = item.get_format_data()
                            d = {
                                "type": "text",
                                "page": item.page,
                                "pos_x": item.pos().x(),
                                "pos_y": item.pos().y(),
                                "text": fd["text"],
                                "font_size": fd["font_size"],
                                "bold": fd["bold"],
                                "italic": fd.get("italic", False),
                                "underline": fd.get("underline", False),
                                "color": fd["color"].name(),
                                "alignment": fd["alignment"],
                                "opacity": fd.get("opacity", 100),
                                "word_wrap": fd.get("word_wrap", False),
                                "width_mode": fd.get("width_mode", "auto"),
                            }
                        else:
                            # Fallback für ältere Items
                            d = {
                                "type": "text",
                                "page": item.page,
                                "pos_x": item.pos().x(),
                                "pos_y": item.pos().y(),
                                "text": item.toPlainText(),
                                "font_size": getattr(item, "font_size", 16),
                                "bold": getattr(item, "bold", False),
                                "italic": getattr(item, "italic", False),
                                "underline": getattr(item, "underline", False),
                                "color": getattr(
                                    item, "text_color", QColor(0, 0, 0)
                                ).name(),
                                "alignment": getattr(item, "alignment", Qt.AlignLeft),
                                "opacity": getattr(item, "opacity", 100),
                                "word_wrap": getattr(item, "word_wrap", False),
                                "width_mode": getattr(item, "width_mode", "auto"),
                            }
                    data.append(d)

            except Exception as e:
                print(f"DEBUG: Fehler beim Sammeln von Text/Kreuz: {e}")

        # ===== 3. Signaturen sammeln =====
        for item in self.all_signature_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    # Absoluten Pfad verwenden (wichtig für Windows Bundle)
                    abs_path = (
                        os.path.abspath(item.original_path)
                        if item.original_path
                        else ""
                    )
                    d = {
                        "type": "signature",
                        "page": item.page_num,
                        "pos_x": item.pos().x(),
                        "pos_y": item.pos().y(),
                        "signature_number": item.signature_number,
                        "original_path": abs_path,  # Absoluter Pfad!
                        "size_percent": item.size_percent,
                        "has_timestamp": hasattr(item, "timestamp_item")
                        and item.timestamp_item is not None,
                        "timestamp_text": (
                            item.timestamp_item.toPlainText()
                            if (hasattr(item, "timestamp_item") and item.timestamp_item)
                            else ""
                        ),
                    }
                    data.append(d)
            except Exception as e:
                print(f"DEBUG: Fehler beim Sammeln von Signatur: {e}")

        # ===== 4. Bilder sammeln =====
        for item in self.all_image_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    abs_path = (
                        os.path.abspath(item.original_path)
                        if item.original_path
                        else ""
                    )
                    d = {
                        "type": "image",
                        "page": item.page_num,
                        "pos_x": item.pos().x(),
                        "pos_y": item.pos().y(),
                        "original_path": abs_path,  # Absoluter Pfad!
                        "aspect_ratio_mode": item.aspect_ratio_mode,
                        "current_scale": (
                            item.pixmap().width() / item.original_pixmap.width()
                            if item.original_pixmap.width() > 0
                            else 1.0
                        ),
                        "rotation": item.rotation(),
                    }
                    data.append(d)
            except Exception as e:
                print(f"DEBUG: Fehler beim Sammeln von Bild: {e}")

        # ===== 5. Formen sammeln =====
        for item in self.all_form_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if hasattr(item, "get_format_data"):
                        fd = item.get_format_data()
                        d = {
                            "type": "form",
                            "page": item.page_num,
                            "pos_x": item.pos().x(),
                            "pos_y": item.pos().y(),
                            "form_type": fd["form_type"],
                            "line_width": fd["line_width"],
                            "line_color": fd["line_color"].name(),
                            "fill_color": (
                                fd["fill_color"].name() if fd["fill_color"] else None
                            ),
                            "transparent_bg": fd["transparent_bg"],
                            "rect_x": fd.get("rect_x"),
                            "rect_y": fd.get("rect_y"),
                            "rect_w": fd.get("rect_w"),
                            "rect_h": fd.get("rect_h"),
                            "start_x": fd.get("start_x"),
                            "start_y": fd.get("start_y"),
                            "end_x": fd.get("end_x"),
                            "end_y": fd.get("end_y"),
                        }
                    else:
                        d = {
                            "type": "form",
                            "page": item.page_num,
                            "pos_x": item.pos().x(),
                            "pos_y": item.pos().y(),
                            "form_type": item.form_type,
                            "line_width": item.line_width,
                            "line_color": item.line_color.name(),
                            "fill_color": (
                                item.fill_color.name() if item.fill_color else None
                            ),
                            "transparent_bg": item.transparent_bg,
                            "rect_x": item.rect.x() if hasattr(item, "rect") else None,
                            "rect_y": item.rect.y() if hasattr(item, "rect") else None,
                            "rect_w": (
                                item.rect.width() if hasattr(item, "rect") else None
                            ),
                            "rect_h": (
                                item.rect.height() if hasattr(item, "rect") else None
                            ),
                            "start_x": (
                                item.start_point.x()
                                if hasattr(item, "start_point")
                                else None
                            ),
                            "start_y": (
                                item.start_point.y()
                                if hasattr(item, "start_point")
                                else None
                            ),
                            "end_x": (
                                item.end_point.x()
                                if hasattr(item, "end_point")
                                else None
                            ),
                            "end_y": (
                                item.end_point.y()
                                if hasattr(item, "end_point")
                                else None
                            ),
                        }
                    data.append(d)
            except Exception as e:
                print(f"DEBUG: Fehler beim Sammeln von Form: {e}")

        # ===== 6. Redactions (Schwärzungen) sammeln =====
        for item in self.all_redaction_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    d = {
                        "type": "redaction",
                        "page": item.page_num,
                        "rect_x": item.rect.x(),
                        "rect_y": item.rect.y(),
                        "rect_w": item.rect.width(),
                        "rect_h": item.rect.height(),
                    }
                    data.append(d)
            except Exception as e:
                print(f"DEBUG: Fehler beim Sammeln von Redaction: {e}")

        # ===== 7. Daten speichern =====
        self._saved_overlays = data
        print(f"DEBUG: {len(data)} Overlay-Elemente gesichert (nach Validierung)")

    def _clear_all_items_from_scene(self):
        """Entfernt ALLE Overlay-Items NUR aus der Szene, aber NICHT aus den Listen!"""
        print("\n=== CLEAR ALL ITEMS FROM SCENE ===")

        count = 0

        # 1. Texte und Kreuze - NUR aus der Szene entfernen, aber NICHT aus der Liste löschen!
        for item in self.all_text_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Text aus Szene: {e}")
        # WICHTIG: self.all_text_items wird NICHT geleert!
        # self.text_mode bleibt auch erhalten!

        # 2. Signaturen
        for item in self.all_signature_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Signatur aus Szene: {e}")
        # self.all_signature_items wird NICHT geleert!

        # 3. Bilder
        for item in self.all_image_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Bild aus Szene: {e}")
        # self.all_image_items wird NICHT geleert!

        # 4. Formen
        for item in self.all_form_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Form aus Szene: {e}")
        # self.all_form_items wird NICHT geleert!

        # 5. Redactions
        for item in self.all_redaction_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Redaction aus Szene: {e}")
        # self.all_redaction_items wird NICHT geleert!

        print(f"DEBUG: {count} Items aus der Szene entfernt (Listen bleiben erhalten)")

        # WICHTIG: NICHT self.text_mode = False setzen!
        # Die Modi bleiben erhalten, weil die Items ja noch in den Listen sind

        # Garbage Collection erzwingen
        import gc

        gc.collect()

        print("=== CLEAR ALL ITEMS FROM SCENE ABGESCHLOSSEN ===\n")

    def _clear_items_from_scene_only(self):
        """
        Entfernt ALLE Overlay-Items NUR aus der grafischen Szene.
        Die Daten in den Listen (all_text_items etc.) bleiben ERHALTEN!

        WARUM?
        - Die Qt-Objekte müssen aus der Szene entfernt werden, bevor die PDF neu geladen wird
        - Sonst gibt es "wrapped C/C++ object has been deleted" Fehler
        - Aber die Daten in den Listen werden für das nächste _save_overlay_data() benötigt
        - Deshalb: Nur aus der Szene entfernen, nicht aus den Listen

        WANN?
        - Wird beim Umschalten des Dark Mode aufgerufen
        - Wird beim Neuladen der PDF aufgerufen
        - Wird beim Schließen der App aufgerufen

        ACHTUNG:
        - Die Modi (text_mode, signature_mode, etc.) bleiben erhalten!
        - Die aktuellen Items (current_text_item, etc.) bleiben erhalten!
        - Nur die grafische Darstellung wird entfernt
        """

        print("\n=== CLEAR ITEMS FROM SCENE ONLY ===")

        removed_count = 0

        # ===== 1. Texte und Kreuze =====
        # Wir iterieren über eine Kopie der Liste, weil wir während der Iteration die Szene verändern
        for item in self.all_text_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    # Aus der Szene entfernen
                    if item.scene():
                        item.scene().removeItem(item)
                    # Parent entfernen (wichtig für Speicherfreigabe)
                    if item.parentItem():
                        item.setParentItem(None)
                    removed_count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Text aus Szene: {e}")
        # WICHTIG: self.all_text_items wird NICHT geleert!

        # ===== 2. Signaturen =====
        for item in self.all_signature_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    removed_count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Signatur aus Szene: {e}")
        # self.all_signature_items wird NICHT geleert!

        # ===== 3. Bilder =====
        for item in self.all_image_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    removed_count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Bild aus Szene: {e}")
        # self.all_image_items wird NICHT geleert!

        # ===== 4. Formen =====
        for item in self.all_form_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    removed_count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Form aus Szene: {e}")
        # self.all_form_items wird NICHT geleert!

        # ===== 5. Redactions =====
        for item in self.all_redaction_items[:]:
            try:
                if item and not sip.isdeleted(item):
                    if item.scene():
                        item.scene().removeItem(item)
                    if item.parentItem():
                        item.setParentItem(None)
                    removed_count += 1
            except Exception as e:
                print(f"DEBUG: Fehler beim Entfernen von Redaction aus Szene: {e}")
        # self.all_redaction_items wird NICHT geleert!

        print(
            f"DEBUG: {removed_count} Items aus der Szene entfernt (Listen bleiben erhalten)"
        )
        print(f"DEBUG: Texte in Liste: {len(self.all_text_items)}")
        print(f"DEBUG: Signaturen in Liste: {len(self.all_signature_items)}")
        print(f"DEBUG: Bilder in Liste: {len(self.all_image_items)}")
        print(f"DEBUG: Formen in Liste: {len(self.all_form_items)}")
        print(f"DEBUG: Redactions in Liste: {len(self.all_redaction_items)}")

        # Garbage Collection erzwingen (wichtig für Windows Bundle)
        import gc

        gc.collect()

        print("=== CLEAR ITEMS FROM SCENE ONLY ABGESCHLOSSEN ===\n")

    def _restore_overlay_items(self):
        """
        Stellt alle Overlay-Elemente aus self._saved_overlays wieder her.

        WICHTIG: Extrahiert die Scroll-Position aus den Daten,
        damit sie später wiederhergestellt werden kann.
        """

        print("\n=== RESTORE OVERLAY ITEMS ===")
        t0 = time.time()
        if not self._saved_overlays:
            print("DEBUG: Keine Overlay-Daten zum Wiederherstellen")
            return False

        print(f"DEBUG: Stelle {len(self._saved_overlays)} Elemente wieder her")

        # ===== Scroll-Position aus den Daten extrahieren =====
        scroll_position = None
        for d in self._saved_overlays:
            if d.get("type") == "scroll":
                scroll_position = {
                    "page": d.get("page", 0),
                    "relative_x": d.get("relative_x", 0.5),
                    "relative_y": d.get("relative_y", 0.5),
                }
                print(
                    f"DEBUG: Scroll-Position gefunden: Seite {scroll_position['page'] + 1}"
                )
                break

        # ===== Alle Listen leeren =====
        self.all_text_items.clear()
        self.all_signature_items.clear()
        self.all_image_items.clear()
        self.all_form_items.clear()
        self.all_redaction_items.clear()

        # ===== Metadaten extrahieren =====
        target_page = 0
        for d in self._saved_overlays:
            if d.get("type") == "meta":
                target_page = d.get("current_page", 0)
                break

        restored_count = 0

        # ===== Alle Elemente wiederherstellen (ohne scroll und meta) =====
        for d in self._saved_overlays:
            t = d.get("type")
            if t in ["scroll", "meta"]:
                continue  # Überspringe Meta-Daten

            try:
                if t == "cross":
                    item = self._restore_cross_item(d)
                    if item:
                        self.all_text_items.append(item)
                        restored_count += 1
                elif t == "text":
                    item = self._restore_text_item(d)
                    if item:
                        self.all_text_items.append(item)
                        restored_count += 1
                elif t == "signature":
                    item = self._restore_signature_item(d)
                    if item:
                        self.all_signature_items.append(item)
                        restored_count += 1
                elif t == "image":
                    item = self._restore_image_item(d)
                    if item:
                        self.all_image_items.append(item)
                        restored_count += 1
                elif t == "form":
                    item = self._restore_form_item(d)
                    if item:
                        self.all_form_items.append(item)
                        restored_count += 1
                elif t == "redaction":
                    item = self._restore_redaction_item(d)
                    if item:
                        self.all_redaction_items.append(item)
                        restored_count += 1
            except Exception as e:
                print(f"DEBUG: Fehler bei {t}: {e}")

        print(f"DEBUG: Wiederhergestellt: {restored_count} Elemente")

        # ===== Modi aktivieren =====
        self.text_mode = len(self.all_text_items) > 0
        self.signature_mode = len(self.all_signature_items) > 0
        self.image_mode = len(self.all_image_items) > 0
        self.form_mode = len(self.all_form_items) > 0
        self.redaction_mode = len(self.all_redaction_items) > 0

        # ===== Aktuelle Items setzen =====
        if self.text_mode:
            self.current_text_item = self.all_text_items[-1]
            self.current_text_item.setSelected(True)
            self._setup_text_movement_shortcuts()

        if self.signature_mode:
            self.current_signature_item = self.all_signature_items[-1]
            self.current_signature_item.setSelected(True)
            self._setup_movement_shortcuts()

        if self.image_mode:
            self.current_image_item = self.all_image_items[-1]
            self.current_image_item.setSelected(True)
            self._setup_image_shortcuts()

        if self.form_mode:
            self.current_form_item = self.all_form_items[-1]
            self.current_form_item.setSelected(True)
            self._setup_form_keyboard_shortcuts()

        if self.redaction_mode:
            self.current_redaction_item = self.all_redaction_items[-1]
            self.current_redaction_item.setSelected(True)
            self._setup_redaction_shortcuts()

        # ===== Zur Seite springen (nur wenn keine Scroll-Position) =====
        if scroll_position is None and target_page < self.total_pages:
            self.current_page = target_page
            with QSignalBlocker(self.page_spin):
                self.page_spin.setValue(target_page + 1)
            self.scroll_to_page(announce=False)

        # ===== UI aktualisieren =====
        self.update_menu_states()
        self.scene.update()
        self.graphics_view.viewport().update()
        QApplication.processEvents()

        # ===== Scroll-Position für später speichern =====
        if scroll_position:
            self._pending_scroll_position = scroll_position


        print(f"[TIMING] _restore_overlay_items: {time.time()-t0:.3f}s")

        return True

    def _restore_cross_item(self, data):
        """Stellt ein Kreuz-Item wieder her - MIT EXPLIZITER PRÜFUNG"""
        try:
            print(f"DEBUG: _restore_cross_item aufgerufen mit data: {data}")

            page_num = data.get("page", 0)
            print(
                f"DEBUG: page_num = {page_num}, len(page_items) = {len(self.page_items)}"
            )

            if page_num >= len(self.page_items):
                print(
                    f"DEBUG: ❌ Seite {page_num} existiert nicht (nur {len(self.page_items)} Seiten)"
                )
                return None

            page_item = self.page_items[page_num]
            if page_item is None:
                print(f"DEBUG: ❌ page_item ist None für Seite {page_num}")
                return None

            # Farbe basierend auf Dark Mode
            if self.dark_mode:
                display_color = QColor(255, 255, 255)
            else:
                display_color = QColor(data.get("color", "#000000"))

            print(f"DEBUG: Erstelle Kreuz mit Farbe {display_color.name()}")

            # Kreuz erstellen
            cross_item = CrossGraphicsItem(
                data.get("pos_x", 0),
                data.get("pos_y", 0),
                data.get("arm_length", 12),
                data.get("line_width", 4.8),
                display_color,
                data.get("bold", True),
                data.get("font_size", 48),
                page_item,
            )

            # Attribute setzen
            cross_item.viewer = self
            cross_item.page = page_num
            cross_item.text_color = QColor(data.get("color", "#000000"))
            cross_item.offset_x = data.get("offset_x", 0)
            cross_item.offset_y = data.get("offset_y", 0)
            cross_item.setZValue(1000)

            print(
                f"DEBUG: ✅ Kreuz erfolgreich erstellt bei ({data.get('pos_x')}, {data.get('pos_y')})"
            )
            return cross_item

        except Exception as e:
            print(f"DEBUG: ❌ Fehler in _restore_cross_item: {e}")
            import traceback

            traceback.print_exc()
            return None

    def _restore_text_item(self, data):
        page_num = data["page"]
        if page_num >= len(self.page_items):
            return
        page_item = self.page_items[page_num]

        text_item = CustomTextItem(
            text=data["text"],
            font_size=data["font_size"],
            bold=data["bold"],
            italic=data["italic"],
            underline=data["underline"],
            color=QColor(data["color"]),
            alignment=data["alignment"],
            opacity=data["opacity"],
            word_wrap=data["word_wrap"],
            width_mode=data["width_mode"],
        )
        text_item.viewer = self
        text_item.page = page_num
        text_item.setParentItem(page_item)
        text_item.setPos(data["pos_x"], data["pos_y"])
        text_item.apply_formatting()

        # hohen Z-Wert setzen, damit die Elemente über der PDF-Seite liegen
        text_item.setZValue(1000)

        self.all_text_items.append(text_item)

    def _restore_signature_item(self, data):
        page_num = data["page"]
        if page_num >= len(self.page_items):
            return
        page_item = self.page_items[page_num]

        display_pixmap, temp_path = self._prepare_signature_for_display(
            data["original_path"], data["size_percent"], self.dark_mode
        )
        if display_pixmap.isNull():
            return

        sig_item = SignatureItem(display_pixmap, page_num)
        sig_item.viewer = self
        sig_item.setParentItem(page_item)
        sig_item.signature_number = data["signature_number"]
        sig_item.original_path = data["original_path"]
        sig_item.temp_path = temp_path
        sig_item.size_percent = data["size_percent"]
        sig_item.setPos(data["pos_x"], data["pos_y"])

        # hohen Z-Wert setzen, damit die Elemente über der PDF-Seite liegen
        sig_item.setZValue(1000)

        if data["has_timestamp"] and data["timestamp_text"]:
            timestamp_item = QGraphicsTextItem(data["timestamp_text"], sig_item)
            font = QFont(
                "Arial", self.signature_settings.get("timestamp_font_size", 14)
            )
            font.setBold(True)
            timestamp_item.setFont(font)
            if self.dark_mode:
                timestamp_item.setDefaultTextColor(QColor(255, 255, 255))
            else:
                timestamp_item.setDefaultTextColor(QColor(0, 0, 0))
            timestamp_item.setPos(0, display_pixmap.height() + 10)
            sig_item.timestamp_item = timestamp_item

        self._setup_signature_event_handlers(sig_item)
        self.all_signature_items.append(sig_item)

    def _restore_image_item(self, data):
        page_num = data["page"]
        if page_num >= len(self.page_items):
            return
        page_item = self.page_items[page_num]

        # Original-Bild laden
        original_pixmap = QPixmap(data["original_path"])
        if original_pixmap.isNull():
            return

        # Skalierung aus gespeicherten Daten
        saved_scale = data.get("current_scale", 1.0)

        # Bild mit gespeicherter Größe skalieren
        if saved_scale != 1.0:
            new_width = int(original_pixmap.width() * saved_scale)
            new_height = int(original_pixmap.height() * saved_scale)
            display_pixmap = original_pixmap.scaled(
                new_width, new_height, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
        else:
            display_pixmap = original_pixmap

        # ImageItem erstellen
        img_item = ImageItem(display_pixmap, page_num)
        img_item.viewer = self
        img_item.setParentItem(page_item)
        img_item.original_path = data["original_path"]
        img_item.original_pixmap = original_pixmap
        img_item.aspect_ratio_mode = data["aspect_ratio_mode"]
        img_item.setPos(data["pos_x"], data["pos_y"])

        # Wichtig: Scale auf 1 setzen
        img_item.setScale(1.0)

        # Rotation wiederherstellen
        if "rotation" in data and data["rotation"] != 0:
            img_item.setRotation(data["rotation"])

        img_item.setZValue(1000)
        self._setup_image_event_handlers(img_item)
        self.all_image_items.append(img_item)

        print(f"DEBUG: Bild wiederhergestellt mit Skalierung: {saved_scale}")

    def _restore_form_item(self, data):
        page_num = data["page"]
        if page_num >= len(self.page_items):
            return
        page_item = self.page_items[page_num]

        line_color = QColor(data["line_color"])
        fill_color = QColor(data["fill_color"]) if data["fill_color"] else None

        if data["form_type"] in ["line", "arrow"]:
            start = QPointF(data["start_x"], data["start_y"])
            end = QPointF(data["end_x"], data["end_y"])
            form_item = FormItem(
                form_type=data["form_type"],
                page_num=page_num,
                start_point=start,
                end_point=end,
                line_width=data["line_width"],
                line_color=line_color,
                fill_color=fill_color,
                transparent_bg=data["transparent_bg"],
            )
            form_item.setPos(data["pos_x"], data["pos_y"])
        else:
            rect = QRectF(
                data["rect_x"], data["rect_y"], data["rect_w"], data["rect_h"]
            )
            form_item = FormItem(
                form_type=data["form_type"],
                page_num=page_num,
                rect=rect,
                line_width=data["line_width"],
                line_color=line_color,
                fill_color=fill_color,
                transparent_bg=data["transparent_bg"],
            )
            form_item.setPos(data["pos_x"], data["pos_y"])

        form_item.viewer = self
        form_item.setParentItem(page_item)
        if hasattr(form_item, "apply_dark_mode"):
            form_item.apply_dark_mode(self.dark_mode)

        # hohen Z-Wert setzen, damit die Elemente über der PDF-Seite liegen
        form_item.setZValue(1000)

        self.all_form_items.append(form_item)

        def _clear_all_overlays(self):
            """Entfernt alle Overlay-Elemente aus der Szene und leert die Listen."""
            for item in self.all_text_items:
                if item.scene():
                    item.scene().removeItem(item)
            self.all_text_items.clear()
            for item in self.all_signature_items:
                if item.scene():
                    item.scene().removeItem(item)
            self.all_signature_items.clear()
            for item in self.all_image_items:
                if item.scene():
                    item.scene().removeItem(item)
            self.all_image_items.clear()
            for item in self.all_form_items:
                if item.scene():
                    item.scene().removeItem(item)
            self.all_form_items.clear()

            # Modi zurücksetzen
            self.text_mode = False
            self.signature_mode = False
            self.image_mode = False
            self.form_mode = False
            self.current_text_item = None
            self.current_signature_item = None
            self.current_image_item = None
            self.current_form_item = None

            self._cleanup_text_movement_shortcuts()
            self._cleanup_movement_shortcuts()
            self._cleanup_image_shortcuts()
            self._cleanup_form_keyboard_shortcuts()
            self._saved_overlays = None

    def _restore_redaction_item(self, data):
        page_num = data["page"]
        if page_num >= len(self.page_items):
            return
        page_item = self.page_items[page_num]
        rect = QRectF(data["rect_x"], data["rect_y"], data["rect_w"], data["rect_h"])
        redact_item = RedactionItem(rect, page_num, self)
        redact_item.setParentItem(page_item)
        redact_item.setPos(rect.topLeft())
        self._setup_redaction_event_handlers(redact_item)
        self.all_redaction_items.append(redact_item)
        # Kein current setzen, weil das aus meta wiederhergestellt wird

    def _clear_all_overlays(self):
        """Entfernt alle Overlay-Elemente aus der Szene und leert die Listen."""
        for item in self.all_text_items:
            if item.scene():
                item.scene().removeItem(item)
        self.all_text_items.clear()
        for item in self.all_signature_items:
            if item.scene():
                item.scene().removeItem(item)
        self.all_signature_items.clear()
        for item in self.all_image_items:
            if item.scene():
                item.scene().removeItem(item)
        self.all_image_items.clear()
        for item in self.all_form_items:
            if item.scene():
                item.scene().removeItem(item)
        self.all_form_items.clear()

        # Modi zurücksetzen
        self.text_mode = False
        self.signature_mode = False
        self.image_mode = False
        self.form_mode = False
        self.current_text_item = None
        self.current_signature_item = None
        self.current_image_item = None
        self.current_form_item = None

        self._cleanup_text_movement_shortcuts()
        self._cleanup_movement_shortcuts()
        self._cleanup_image_shortcuts()
        self._cleanup_form_keyboard_shortcuts()

        # Redactions
        for item in self.all_redaction_items:
            if item.scene():
                item.scene().removeItem(item)
        self.all_redaction_items.clear()
        self.redaction_mode = False
        self.current_redaction_item = None
        self._cleanup_redaction_shortcuts()

    ### 13. KEIN Einfügen auf gedrehten Seiten
    def check_page_rotation(
        self, page_index=None, show_warning=True, callback=None, callback_args=None
    ):
        """
        Prüft, ob die aktuelle Seite gedreht ist.
        Returns:
            True  – Seite ist nicht gedreht (OK) oder wurde erfolgreich gedreht
            False – Seite ist gedreht und Benutzer hat abgebrochen

        callback: Funktion, die nach erfolgreichem Drehen aufgerufen wird
        callback_args: Argumente für die Callback-Funktion (als Liste oder Tupel)
        """
        if page_index is None:
            page_index = self.current_page

        if page_index >= len(self.page_items):
            if callback:
                if callback_args:
                    callback(*callback_args)
                else:
                    callback()
            return True

        try:
            doc = fitz.open(self.pdf_path)
            if hasattr(self, "current_password") and self.current_password:
                doc.authenticate(self.current_password)
            page = doc[page_index]
            rotation = page.rotation
            doc.close()
        except Exception as e:
            print(f"Fehler beim Prüfen der Seitenrotation: {e}")
            if callback:
                if callback_args:
                    callback(*callback_args)
                else:
                    callback()
            return True

        if rotation == 0:
            if callback:
                if callback_args:
                    callback(*callback_args)
                else:
                    callback()
            return True

        if show_warning:
            # Speichere Callback für später
            self._pending_action = callback
            self._pending_args = callback_args
            return self._show_rotation_warning(page_index, rotation)

        return False

    def _show_rotation_warning(self, page_index, rotation):
        """Zeigt eine Warnung für gedrehte Seiten an und bietet wiederholtes Drehen an."""
        settings = QSettings("BinhDiez", "PDFDarkView")

        if settings.value("page_rotated_warning_hidden", False, type=bool):
            success = self._rotate_until_upright(page_index)
            if success and self._pending_action:
                args = self._pending_args if self._pending_args else ()
                self._pending_action(*args)
                self._pending_action = None
                self._pending_args = None
            return success

        dialog = myUniversalDialog(
            self,
            title=self.tr("page_rotated_warning_title"),
            message=self.tr("page_rotated_warning_message", page_index + 1, rotation),
            buttons=[
                (
                    self.tr("page_rotated_rotate_until_upright"),
                    "success",
                    "rotate",
                    380,
                ),
                (self.tr("btn_help"), "primary", "help", 120),
                (self.tr("page_rotated_cancel"), "danger", "cancel", 200),
            ],
            icon_type="",
            voice_message=self.tr("page_rotated_warning_voice"),
            text_alignment=Qt.AlignLeft,
            default_button="rotate",
        )
        dialog.exec_()

        if dialog.result_value == "rotate":
            success = self._rotate_until_upright(page_index)
            if success and self._pending_action:
                args = self._pending_args if self._pending_args else ()
                self._pending_action(*args)
                self._pending_action = None
                self._pending_args = None
            return success

        elif dialog.result_value == "help":
            self.show_help_rotated_pages()
            return self.check_page_rotation(
                page_index, show_warning=True
            )  # Dialog erneut anzeigen

        else:
            # Bei Abbruch: Callback verwerfen
            self._pending_action = None
            self._pending_args = None
            return False

    def _rotate_page_silent(self, page_index):
        """
        Dreht eine Seite um 90 Grad OHNE Meldungen und OHNE Neuladen.
        Verwendet temporäre Datei und ersetzt die Originaldatei.
        """
        if not 0 <= page_index < len(self.page_pixmaps):
            return False

        try:
            # In temporäre Datei speichern
            temp_dir = tempfile.gettempdir()
            temp_path = os.path.join(
                temp_dir, f"temp_rotate_silent_{os.path.basename(self.pdf_path)}"
            )

            doc = fitz.open(self.pdf_path)
            page = doc[page_index]
            current_rotation = page.rotation
            new_rotation = (current_rotation + 90) % 360
            page.set_rotation(new_rotation)
            doc.save(temp_path, garbage=4, deflate=True)
            doc.close()

            # Original ersetzen
            shutil.move(temp_path, self.pdf_path)
            return True

        except Exception as e:
            print(f"Fehler beim stillen Drehen: {e}")
            return False

    def _rotate_until_upright(self, page_index):
        """
        Dreht die Seite wiederholt um 90°, bis sie aufrecht ist (Rotation == 0).
        Nach der Drehung wird die Szene neu geladen.
        """
        max_attempts = 4

        for attempt in range(max_attempts):
            try:
                doc = fitz.open(self.pdf_path)
                if hasattr(self, "current_password") and self.current_password:
                    doc.authenticate(self.current_password)
                page = doc[page_index]
                current_rotation = page.rotation
                doc.close()

                print(
                    f"DEBUG: Drehversuch {attempt+1}, aktuelle Rotation = {current_rotation}"
                )

                if current_rotation == 0:
                    # Seite ist jetzt aufrecht – lade die PDF neu
                    self.load_pdf()
                    self.say(self.tr("page_rotated_now_upright"))
                    return True

                if not self._rotate_page_silent(page_index):
                    return False

            except Exception as e:
                print(f"Fehler beim Drehen: {e}")
                return False

        self.say(self.tr("page_rotated_still_not_upright"))
        return False

    def show_help_rotated_pages(self):
        """Zeigt den Hilfedialog für gedrehte Seiten an."""
        dialog = myUniversalDialog(
            self,
            title=self.tr("help_rotated_pages_title"),
            message=self.tr("help_rotated_pages_html"),
            buttons=[(self.tr("btn_ok"), "primary", "ok")],
            icon_type="",
            voice_message=self.tr("help_rotated_pages_voice"),
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()

    ### 14. Hilfsmethode für verzögertes Einfügen (zentral)
    def _delayed_insert(self, insert_func, *args, delay=100):
        """Führt eine Einfüge-Funktion nach einer kurzen Verzögerung aus."""
        QTimer.singleShot(delay, lambda: insert_func(*args, True))

