    ### BILD EINFÜGEN
    ### ==============================================

    def _insert_image_from_menu(self):
        """Bild über Menü einfügen – mit intelligenter Positionierung."""
        print(f"\n{'='*60}")
        print(f"DEBUG: _insert_image_from_menu aufgerufen")
        print(f"{'='*60}")

        if not self.page_items or self.current_page >= len(self.page_items):
            print("DEBUG: Keine PDF geladen oder keine Seiten vorhanden")
            # "Keine PDF geladen"
            self.say(self.tr("no_pdf_loaded"))
            return

        # ========== Prüfung auf gedrehte Seite ==========
        if not self.check_page_rotation():
            return

        # Prüfe ob andere Modi aktiv sind (Text, Signatur, Form) – aber nicht Bild
        if self.text_mode or self.signature_mode or self.form_mode:
            active_modes = []
            if self.text_mode:
                # "Texteingabe"
                active_modes.append(self.tr("active_mode_text"))
            if self.signature_mode:
                # "Signatur"
                active_modes.append(self.tr("active_mode_signature"))
            if self.form_mode:
                # "Form"
                active_modes.append(self.tr("active_mode_form"))

            # " und "
            mode_text = self.tr("active_mode_and").join(active_modes)

            dialog = myUniversalDialog(
                self,
                # "Modus-Konflikt"
                title=self.tr("mode_conflict"),
                # "Es ist bereits der Modus '{0}' aktiv.\n\nMöchten Sie diesen beenden und {1}?"
                message=self.tr(
                    "mode_conflict_message", mode_text, self.tr("mode_replace_image")
                ),
                text_alignment=Qt.AlignLeft,
                buttons=[
                    # "Modus beenden und Bild einfügen"
                    (
                        self.tr("mode_replace", self.tr("mode_replace_image")),
                        "warning",
                        "replace",
                        300,
                    ),
                    # "Abbrechen"
                    (self.tr("mode_cancel"), "danger", "cancel", 200),
                ],
                icon_type="",
                # "{0} Modus ist aktiv. Beenden und Bild einfügen?"
                voice_message=self.tr("mode_conflict_voice_image", mode_text),
                default_button="cancel",
            )

            if dialog.exec_() == QDialog.Accepted:
                if dialog.result_value == "replace":
                    if self.text_mode:
                        self._cleanup_text_mode(speak=False)
                    if self.signature_mode:
                        self._cleanup_signature_mode()
                    if self.form_mode:
                        self._cleanup_form_mode()
                else:
                    return
            else:
                return

        # Position ermitteln
        local_pos, target_page = self._get_insertion_position(default_y_ratio=0.15)
        if local_pos is None:
            print("DEBUG: Keine gültige Position ermittelt")
            return

        print(f"DEBUG: Ziel-Seite: {target_page + 1}")
        print(f"DEBUG: Lokale Position: ({local_pos.x():.1f}, {local_pos.y():.1f})")

        self._place_image_at_position(local_pos, target_page)

    def load_image_settings(self):
        """Lädt Bildeinstellungen aus QSettings"""
        settings = QSettings("BinhDiez", "PDFDarkView")

        default_size_str = settings.value("image/default_size", "100%")
        try:
            default_size_percent = int(default_size_str.replace("%", "")) / 100.0
        except:
            default_size_percent = 1.0

        return {
            "keep_aspect_ratio": settings.value(
                "image/keep_aspect_ratio", True, type=bool
            ),
            "default_size": default_size_str,
            "default_size_percent": default_size_percent,
            "dark_mode_invert": settings.value(
                "image/dark_mode_invert", True, type=bool
            ),
        }

    def _insert_another_image(self, local_pos, page_num):
        """Fügt ein weiteres Bild ein, ohne den aktuellen Modus zu beenden."""
        self._place_image_at_position(local_pos, page_num)

    def _prepare_image_for_display(self, image_path, scale_factor, dark_mode):
        """Bereitet Bild für Anzeige vor - OHNE Invertierung"""
        try:
            original_pixmap = QPixmap(image_path)
            if original_pixmap.isNull():
                return QPixmap(), None

            # Größe berechnen
            original_size = original_pixmap.size()
            new_width = int(original_size.width() * scale_factor)
            new_height = int(original_size.height() * scale_factor)
            new_size = QSize(new_width, new_height)

            # NUR skalieren, KEINE Invertierung
            scaled_pixmap = original_pixmap.scaled(
                new_size, Qt.KeepAspectRatio, Qt.SmoothTransformation
            )
            return scaled_pixmap, None

        except Exception as e:
            print(f"Fehler in _prepare_image_for_display: {e}")
            return QPixmap(), None

    def insert_image_at_position(self, scene_position, page_num):
        """Fügt Bild an Klickposition ein - AKTUALISIERT"""
        print(f"=== BILD EINFÜGEN FÜR SEITE {page_num + 1} ===")

        # ========== Prüfung auf gedrehte Seite ==========
        if not self.check_page_rotation():
            return

        # Prüfe ob Signatur- oder Text-Modus aktiv ist
        if self.signature_mode or self.text_mode or self.form_mode:
            active_modes = []
            if self.signature_mode:
                # "Signatur"
                active_modes.append(self.tr("active_mode_signature"))
            if self.text_mode:
                # "Texteingabe"
                active_modes.append(self.tr("active_mode_text"))
            if self.form_mode:
                # "Form"
                active_modes.append(self.tr("active_mode_form"))

            # " und "
            mode_text = self.tr("active_mode_and").join(active_modes)

            dialog = myUniversalDialog(
                self,
                # "Modus-Konflikt"
                title=self.tr("mode_conflict"),
                # "Es ist bereits der Modus '{0}' aktiv.\n\nMöchten Sie diesen beenden und {1}?"
                message=self.tr(
                    "mode_conflict_message", mode_text, self.tr("mode_replace_image")
                ),
                text_alignment=Qt.AlignLeft,
                buttons=[
                    # "Modus beenden und Bild einfügen"
                    (
                        self.tr("mode_replace", self.tr("mode_replace_image")),
                        "warning",
                        "replace",
                        300,
                    ),
                    # "Abbrechen"
                    (self.tr("mode_cancel"), "danger", "cancel", 200),
                ],
                icon_type="",
                # "{0} Modus ist aktiv. Beenden und Bild einfügen?"
                voice_message=self.tr("mode_conflict_voice_image", mode_text),
                default_button="cancel",
            )

            if dialog.exec_() == QDialog.Accepted:
                if dialog.result_value == "replace":
                    if self.signature_mode:
                        self._cleanup_signature_mode()
                    if self.text_mode:
                        self._cleanup_text_mode(speak=False)
                    if self.form_mode:
                        self._cleanup_form_mode()
                else:
                    return
            else:
                return

        if self.image_mode and self.current_image_item:
            result = self._show_image_replace_dialog()
            if result == "replace":
                self._cleanup_image_mode()
                QTimer.singleShot(
                    100, lambda: self._place_image_at_position(scene_position, page_num)
                )
                return
            elif result == "cancel":
                return

        self._place_image_at_position(scene_position, page_num)

        # Menü-Zustände aktualisieren
        self.update_menu_states()

    def _show_image_replace_dialog(self):
        """Dialog für Bild-Ersetzung"""
        dialog = myUniversalDialog(
            self,
            # "Bild aktiv"
            title=self.tr("image_active_title"),
            # "Es ist bereits ein Bild aktiv.\n\nMöchten Sie das aktuelle Bild ersetzen?"
            message=self.tr("image_replace_question"),
            text_alignment=Qt.AlignLeft,
            buttons=[
                # "Bild ersetzen"
                (self.tr("image_replace"), "warning", "replace", 300),
                # "Abbrechen"
                (self.tr("mode_cancel"), "danger", "cancel", 300),
            ],
            icon_type="",
            # "Aktuelles Bild ersetzen oder abbrechen?"
            voice_message=self.tr("image_replace_voice"),
            default_button="cancel",
        )

        if dialog.exec_() == QDialog.Accepted:
            return dialog.result_value
        return "cancel"

    def _place_image_at_position(self, scene_position, target_page):
        """Platziert ein neues Bild an der angegebenen Position – ohne vorherige zu löschen."""
        print(f"=== BILD PLATZIEREN AUF SEITE {target_page + 1} ===")

        # Dateiauswahl
        # "Bilder (*.png *.jpg *.jpeg *.bmp *.tiff *.gif *.webp);;Alle Dateien (*.*)"
        file_filter = self.tr("image_filter_all")
        filepath, _ = QFileDialog.getOpenFileName(
            self,
            # "Bild auswählen"
            self.tr("image_select"),
            os.path.expanduser("~/Pictures"),
            file_filter,
        )

        if not filepath:
            print("Kein Bild ausgewählt")
            return

        try:
            from PIL import Image

            img = Image.open(filepath)
            img.verify()
            img.close()

            keep_aspect = self.image_settings.get("keep_aspect_ratio", True)
            default_size = self.image_settings.get("default_size_percent", 1.0)

            display_pixmap, temp_path = self._prepare_image_for_display(
                filepath, default_size, False  # dark_mode = False
            )

            if display_pixmap.isNull():
                print("FEHLER: Bild konnte nicht geladen werden")
                return

            if target_page >= len(self.page_items):
                print(f"FEHLER: Seite {target_page + 1} existiert nicht")
                return

            page_item = self.page_items[target_page]
            page_item.setVisible(True)

            # Bild-Item erstellen
            image_item = ImageItem(display_pixmap, target_page)
            image_item.viewer = self  # <-- WICHTIG
            print(f"DEBUG: Viewer für Bild {id(image_item)} gesetzt")
            image_item.setParentItem(page_item)
            image_item.setVisible(True)

            image_item.original_path = filepath
            image_item.temp_path = temp_path
            image_item.aspect_ratio_mode = keep_aspect
            image_item.setFlag(QGraphicsItem.ItemIsMovable, True)
            image_item.setFlag(QGraphicsItem.ItemIsSelectable, True)
            image_item.setZValue(500)

            # Wichtig: Scale auf 1 setzen, da Pixmap bereits die richtige Größe hat
            image_item.setScale(1.0)

            # Position berechnen (zentriert)
            pixmap_width = display_pixmap.width()
            pixmap_height = display_pixmap.height()
            pos_x = scene_position.x() - pixmap_width / 2
            pos_y = scene_position.y() - pixmap_height / 2

            page_rect = page_item.boundingRect()
            pos_x = max(0, min(pos_x, page_rect.width() - pixmap_width))
            pos_y = max(0, min(pos_y, page_rect.height() - pixmap_height))
            image_item.setPos(pos_x, pos_y)

            # Event-Handler einrichten
            self._setup_image_event_handlers(image_item)

            # Zur Liste hinzufügen
            self.all_image_items.append(image_item)

            # Als aktuelles Item setzen
            self.current_image_item = image_item
            self.image_mode = True
            image_item.setSelected(True)

            if temp_path:
                self.temp_image_files.append(temp_path)

            self._setup_image_shortcuts()
            # "Bild {0} auf Seite {1} eingefügt"
            self.say(
                self.tr("image_inserted", os.path.basename(filepath), target_page + 1)
            )
            self.update_menu_states()

        except Exception as e:
            print(f"Fehler beim Bild einfügen: {e}")
            import traceback

            traceback.print_exc()
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('image_invalid')}:\n{str(e)}"
            )

    def _setup_image_event_handlers(self, image_item):
        """Richtet Event-Handler für Bild-Item ein"""

        # Drag & Drop Zustand
        image_item._is_dragging = False
        image_item._is_resizing = False
        image_item.drag_start_offset = None
        image_item.resize_edge = None
        image_item.original_rect = None

        def mouse_press_event(event):
            if event.button() == Qt.LeftButton:
                pos = event.pos()

                # Prüfe ob auf einem Ziehpunkt geklickt wurde
                cursor = image_item._get_cursor_for_position(pos)

                if cursor and cursor in [
                    Qt.SizeFDiagCursor,
                    Qt.SizeBDiagCursor,
                    Qt.SizeHorCursor,
                    Qt.SizeVerCursor,
                ]:
                    # Größenänderung starten
                    image_item._is_resizing = True
                    image_item.resize_edge = image_item._get_edge_from_position(pos)
                    image_item.original_rect = QRectF(
                        image_item.pos().x(),
                        image_item.pos().y(),
                        image_item.pixmap().width(),
                        image_item.pixmap().height(),
                    )
                    image_item.setCursor(cursor)
                    image_item.is_resizing = True
                    event.accept()
                else:
                    # Bewegung starten
                    image_item.setCursor(Qt.ClosedHandCursor)
                    image_item._is_dragging = True

                    # Offset berechnen
                    parent_item = image_item.parentItem()
                    if parent_item:
                        scene_pos = event.scenePos()
                        mouse_local_pos = parent_item.mapFromScene(scene_pos)
                        image_item.drag_start_offset = (
                            mouse_local_pos - image_item.pos()
                        )

                    event.accept()
            else:
                event.ignore()

        def mouse_move_event(event):
            if image_item._is_resizing and image_item.resize_edge:
                # Größenänderung
                self._handle_image_resize(image_item, event)
                event.accept()
            elif image_item._is_dragging and image_item.drag_start_offset is not None:
                # Bewegung
                self._handle_image_move(image_item, event)
                event.accept()
            else:
                event.ignore()

        def mouse_release_event(event):
            if event.button() == Qt.LeftButton:
                image_item._is_dragging = False
                image_item._is_resizing = False
                image_item.drag_start_offset = None
                image_item.resize_edge = None
                image_item.original_rect = None
                image_item.is_resizing = False

                # Cursor zurücksetzen
                pos = event.pos()
                cursor = image_item._get_cursor_for_position(pos)
                if cursor:
                    image_item.setCursor(cursor)
                else:
                    image_item.setCursor(Qt.OpenHandCursor)

                event.accept()
            else:
                event.ignore()

        def hover_move_event(event):
            # Cursor basierend auf Position aktualisieren
            if not image_item._is_dragging and not image_item._is_resizing:
                cursor = image_item._get_cursor_for_position(event.pos())
                if cursor:
                    image_item.setCursor(cursor)
                else:
                    image_item.setCursor(Qt.OpenHandCursor)
            super(ImageItem, image_item).hoverMoveEvent(event)

        def key_press_event(event):
            if event.key() == Qt.Key_A:
                # [A] Taste für Seitenverhältnis umschalten
                image_item.aspect_ratio_mode = not image_item.aspect_ratio_mode
                status = (
                    self.tr("image_aspect_on")
                    if image_item.aspect_ratio_mode
                    else self.tr("image_aspect_off")
                )
                # "Seitenverhältnis beibehalten {0}"
                self.say(self.tr("image_aspect_toggle", status))
                event.accept()
            else:
                super(ImageItem, image_item).keyPressEvent(event)

        # Event-Handler zuweisen
        image_item.mousePressEvent = mouse_press_event
        image_item.mouseMoveEvent = mouse_move_event
        image_item.mouseReleaseEvent = mouse_release_event
        image_item.hoverMoveEvent = hover_move_event
        image_item.keyPressEvent = key_press_event

        image_item.setAcceptHoverEvents(True)
        image_item.setFlag(QGraphicsItem.ItemIsFocusable, True)

    def _handle_image_move(self, image_item, event):
        """Behandelt Bewegung des Bildes"""
        parent_item = image_item.parentItem()
        if not parent_item:
            return

        scene_pos = event.scenePos()
        mouse_local_pos = parent_item.mapFromScene(scene_pos)
        new_pos = mouse_local_pos - image_item.drag_start_offset

        # Auf Seitenbereich beschränken
        pixmap = image_item.pixmap()
        if pixmap:
            page_rect = parent_item.boundingRect()
            pixmap_width = pixmap.width()
            pixmap_height = pixmap.height()

            min_x = 0
            max_x = page_rect.width() - pixmap_width
            min_y = 0
            max_y = page_rect.height() - pixmap_height

            new_x = max(min_x, min(new_pos.x(), max_x))
            new_y = max(min_y, min(new_pos.y(), max_y))
            new_pos = QPointF(new_x, new_y)

        image_item.setPos(new_pos)

    def _handle_image_resize(self, image_item, event):
        """Behandelt Größenänderung des Bildes"""
        parent_item = image_item.parentItem()
        if not parent_item or not image_item.original_rect:
            return

        # Mausposition in lokalen Koordinaten des Parents
        scene_pos = event.scenePos()
        mouse_pos = parent_item.mapFromScene(scene_pos)

        # Original-Rechteck
        orig_rect = image_item.original_rect
        orig_x = orig_rect.x()
        orig_y = orig_rect.y()
        orig_w = orig_rect.width()
        orig_h = orig_rect.height()

        # Original-Bildgröße (für Seitenverhältnis)
        orig_pixmap = image_item.original_pixmap
        orig_pix_w = orig_pixmap.width()
        orig_pix_h = orig_pixmap.height()
        aspect_ratio = orig_pix_w / orig_pix_h if orig_pix_h > 0 else 1.0

        # Neue Größe basierend auf Ziehpunkt berechnen
        edge = image_item.resize_edge
        new_x, new_y, new_w, new_h = orig_x, orig_y, orig_w, orig_h

        if edge == "bottom-right" or edge == "right" or edge == "bottom":
            new_w = max(50, mouse_pos.x() - orig_x)
            if image_item.aspect_ratio_mode and edge in [
                "bottom-right",
                "bottom",
                "right",
            ]:
                new_h = new_w / aspect_ratio

        if edge == "bottom-left" or edge == "left" or edge == "bottom":
            new_w = max(50, (orig_x + orig_w) - mouse_pos.x())
            new_x = (orig_x + orig_w) - new_w
            if image_item.aspect_ratio_mode and edge in [
                "bottom-left",
                "bottom",
                "left",
            ]:
                new_h = new_w / aspect_ratio
                new_y = orig_y + (orig_h - new_h)

        if edge == "top-right" or edge == "right" or edge == "top":
            new_w = max(50, mouse_pos.x() - orig_x)
            new_h = max(50, (orig_y + orig_h) - mouse_pos.y())
            if image_item.aspect_ratio_mode and edge in ["top-right", "top", "right"]:
                new_h = new_w / aspect_ratio
                new_y = (orig_y + orig_h) - new_h

        if edge == "top-left" or edge == "left" or edge == "top":
            new_w = max(50, (orig_x + orig_w) - mouse_pos.x())
            new_x = (orig_x + orig_w) - new_w
            new_h = max(50, (orig_y + orig_h) - mouse_pos.y())
            if image_item.aspect_ratio_mode and edge in ["top-left", "top", "left"]:
                new_h = new_w / aspect_ratio
                new_y = (orig_y + orig_h) - new_h

        # Auf Seitenbereich beschränken
        page_rect = parent_item.boundingRect()
        new_x = max(0, min(new_x, page_rect.width() - new_w))
        new_y = max(0, min(new_y, page_rect.height() - new_h))

        # Bild skalieren
        if new_w > 0 and new_h > 0:
            scaled_pixmap = image_item.original_pixmap.scaled(
                int(new_w),
                int(new_h),
                (
                    Qt.KeepAspectRatio
                    if image_item.aspect_ratio_mode
                    else Qt.IgnoreAspectRatio
                ),
                Qt.SmoothTransformation,
            )

            image_item.setPixmap(scaled_pixmap)
            image_item.setPos(new_x, new_y)

            # Wichtig: scale auf 1 setzen, da Pixmap bereits skaliert ist
            image_item.setScale(1.0)

            print(f"DEBUG: Bild-Größe geändert auf {new_w}x{new_h}")

    def _get_edge_from_position(self, image_item, pos):
        """Bestimmt welcher Ziehpunkt angeklickt wurde"""
        pixmap = image_item.pixmap()
        if pixmap.isNull():
            return None

        x, y = pos.x(), pos.y()
        w, h = pixmap.width(), pixmap.height()
        margin = image_item.resize_handle_size

        if x <= margin and y <= margin:
            return "top-left"
        elif x >= w - margin and y <= margin:
            return "top-right"
        elif x <= margin and y >= h - margin:
            return "bottom-left"
        elif x >= w - margin and y >= h - margin:
            return "bottom-right"
        elif y <= margin:
            return "top"
        elif y >= h - margin:
            return "bottom"
        elif x <= margin:
            return "left"
        elif x >= w - margin:
            return "right"
        return None

    def _setup_image_keyboard_shortcuts(self):
        """Richtet Tastatur-Shortcuts für Bild-Modus ein"""
        # Alte Shortcuts entfernen
        if hasattr(self, "image_shortcuts"):
            for shortcut in self.image_shortcuts:
                try:
                    shortcut.setEnabled(False)
                    shortcut.deleteLater()
                except:
                    pass
            self.image_shortcuts.clear()
        else:
            self.image_shortcuts = []

        # Enter zum Speichern
        shortcut_save = QShortcut(QKeySequence("Return"), self.graphics_view)
        shortcut_save.activated.connect(self._show_image_save_dialog)
        self.image_shortcuts.append(shortcut_save)

        shortcut_save2 = QShortcut(QKeySequence("Enter"), self.graphics_view)
        shortcut_save2.activated.connect(self._show_image_save_dialog)
        self.image_shortcuts.append(shortcut_save2)

        # ESC zum Abbrechen
        shortcut_cancel = QShortcut(QKeySequence("Escape"), self.graphics_view)
        shortcut_cancel.activated.connect(self._cancel_image_esc_handler)
        self.image_shortcuts.append(shortcut_cancel)

        # [A] für Seitenverhältnis umschalten
        shortcut_aspect = QShortcut(QKeySequence("A"), self.graphics_view)
        shortcut_aspect.activated.connect(self._toggle_aspect_ratio)
        self.image_shortcuts.append(shortcut_aspect)

        # Pfeiltasten für Bewegung (wie bei Signatur)
        arrow_keys = [
            (Qt.Key_Up, 0, -1),
            (Qt.Key_Down, 0, 1),
            (Qt.Key_Left, -1, 0),
            (Qt.Key_Right, 1, 0),
        ]

        for key, dx, dy in arrow_keys:
            shortcut = QShortcut(QKeySequence(key), self.graphics_view)
            shortcut.activated.connect(lambda dx=dx, dy=dy: self._move_image(dx, dy))
            self.image_shortcuts.append(shortcut)

            # Strg für größere Schritte
            shortcut_ctrl = QShortcut(QKeySequence(f"Ctrl+{key}"), self.graphics_view)
            shortcut_ctrl.activated.connect(
                lambda dx=dx * 5, dy=dy * 5: self._move_image(dx, dy)
            )
            self.image_shortcuts.append(shortcut_ctrl)

            # Shift für mittlere Schritte
            shortcut_shift = QShortcut(QKeySequence(f"Shift+{key}"), self.graphics_view)
            shortcut_shift.activated.connect(
                lambda dx=dx * 10, dy=dy * 10: self._move_image(dx, dy)
            )
            self.image_shortcuts.append(shortcut_shift)

        print(f"{len(self.image_shortcuts)} Bild-Shortcuts eingerichtet")

    def _setup_image_shortcuts(self):
        """Richtet Tastatur-Shortcuts für Bild-Modus ein."""
        if hasattr(self, "image_shortcuts"):
            for sc in self.image_shortcuts:
                sc.setEnabled(False)
                sc.deleteLater()
        self.image_shortcuts = []

        # Enter zum Speichern
        sc_save = QShortcut(QKeySequence("Return"), self.graphics_view)
        sc_save.activated.connect(self._show_image_save_dialog)
        self.image_shortcuts.append(sc_save)

        sc_save2 = QShortcut(QKeySequence("Enter"), self.graphics_view)
        sc_save2.activated.connect(self._show_image_save_dialog)
        self.image_shortcuts.append(sc_save2)

        # ESC zum Abbrechen (verwirft aktuelles Bild)
        sc_cancel = QShortcut(QKeySequence("Escape"), self.graphics_view)
        sc_cancel.activated.connect(self._cleanup_image_mode)
        self.image_shortcuts.append(sc_cancel)

        # [A] für Seitenverhältnis
        sc_aspect = QShortcut(QKeySequence("A"), self.graphics_view)
        sc_aspect.activated.connect(self._toggle_aspect_ratio)
        self.image_shortcuts.append(sc_aspect)

        # Pfeiltasten für Bewegung (analog Signaturen)
        arrow_keys = [
            (Qt.Key_Up, 0, -1),
            (Qt.Key_Down, 0, 1),
            (Qt.Key_Left, -1, 0),
            (Qt.Key_Right, 1, 0),
        ]
        for key, dx, dy in arrow_keys:
            sc = QShortcut(QKeySequence(key), self.graphics_view)
            sc.activated.connect(lambda d=dx, ddy=dy: self._move_image(d, ddy))
            self.image_shortcuts.append(sc)

            sc_ctrl = QShortcut(QKeySequence(f"Ctrl+{key}"), self.graphics_view)
            sc_ctrl.activated.connect(
                lambda d=dx * 5, ddy=dy * 5: self._move_image(d, ddy)
            )
            self.image_shortcuts.append(sc_ctrl)

            sc_shift = QShortcut(QKeySequence(f"Shift+{key}"), self.graphics_view)
            sc_shift.activated.connect(
                lambda d=dx * 10, ddy=dy * 10: self._move_image(d, ddy)
            )
            self.image_shortcuts.append(sc_shift)

    def _move_image(self, dx, dy):
        """Bewegt Bild mit Tastatur"""
        if not self.image_mode or not self.current_image_item:
            return

        item = self.current_image_item
        new_pos = QPointF(item.pos().x() + dx, item.pos().y() + dy)

        # Auf Seite beschränken
        if self.page_items and item.page_num < len(self.page_items):
            page_item = self.page_items[item.page_num]
            page_rect = page_item.boundingRect()
            pixmap = item.pixmap()

            if pixmap:
                min_x = 0
                max_x = page_rect.width() - pixmap.width()
                min_y = 0
                max_y = page_rect.height() - pixmap.height()

                new_x = max(min_x, min(new_pos.x(), max_x))
                new_y = max(min_y, min(new_pos.y(), max_y))
                new_pos = QPointF(new_x, new_y)

        item.setPos(new_pos)

    def _copy_image_item(self, image_item):
        """Kopiert die Daten eines Bild-Items."""
        if not image_item:
            return
        self.copied_image_data = {
            "original_path": image_item.original_path,
            "pixmap": image_item.pixmap(),  # aktuell skaliertes Pixmap
            "width": image_item.pixmap().width(),
            "height": image_item.pixmap().height(),
            "aspect_ratio_mode": image_item.aspect_ratio_mode,
        }
        # "Bild kopiert"
        self.say(self.tr("image_copied"))

    def _paste_image_at_position(self, local_pos, page_num):
        """Fügt das kopierte Bild an der angegebenen Position ein – zentriert an Klickposition."""
        if self.copied_image_data is None:
            # "Kein kopiertes Bild vorhanden"
            self.say(self.tr("no_copied_image"))
            return False

        try:
            if page_num >= len(self.page_items):
                return False

            page_item = self.page_items[page_num]
            data = self.copied_image_data
            pixmap = data["pixmap"]

            image_item = ImageItem(pixmap, page_num)
            image_item.viewer = self
            image_item.setParentItem(page_item)
            image_item.original_path = data["original_path"]
            image_item.aspect_ratio_mode = data["aspect_ratio_mode"]
            image_item.setFlag(QGraphicsItem.ItemIsMovable, True)
            image_item.setFlag(QGraphicsItem.ItemIsSelectable, True)
            image_item.setZValue(500)

            # Position zentriert an Klickposition
            pos_x = local_pos.x() - pixmap.width() / 2
            pos_y = local_pos.y() - pixmap.height() / 2

            # Auf Seite beschränken
            page_rect = page_item.boundingRect()
            pos_x = max(0, min(pos_x, page_rect.width() - pixmap.width()))
            pos_y = max(0, min(pos_y, page_rect.height() - pixmap.height()))

            image_item.setPos(pos_x, pos_y)

            self._setup_image_event_handlers(image_item)
            self.all_image_items.append(image_item)
            self.current_image_item = image_item
            self.image_mode = True
            image_item.setSelected(True)
            self._setup_image_shortcuts()
            self.update_menu_states()
            # "Bild eingefügt"
            self.say(self.tr("image_pasted"))
            return True

        except Exception as e:
            print(f"Fehler beim Einfügen des Bildes: {e}")
            return False

    def _toggle_aspect_ratio(self):
        """Schaltet Seitenverhältnis um"""
        if self.image_mode and self.current_image_item:
            self.current_image_item.aspect_ratio_mode = (
                not self.current_image_item.aspect_ratio_mode
            )
            status = (
                self.tr("image_aspect_on")
                if self.current_image_item.aspect_ratio_mode
                else self.tr("image_aspect_off")
            )
            # "Seitenverhältnis beibehalten {0}"
            self.say(self.tr("image_aspect_toggle", status))

    def _cancel_image_esc_handler(self):
        """ESC-Handler für Bild"""
        print("ESC-Handler für Bild aufgerufen")
        if self.image_mode and self.current_image_item:
            self._cleanup_image_mode()
            # "Bild verworfen"
            self.say(self.tr("image_discarded"))

    def _apply_image_settings_to_current(self):
        """Wendet die aktuellen globalen Einstellungen auf das aktuelle Bild an."""
        if not self.current_image_item:
            return

        # Einfach die bestehende Methode aufrufen
        self._open_image_customize_for_item(self.current_image_item)

    # Speichern
    def _show_image_save_dialog(self):
        """Zeigt Speicherdialog für Bilder (alle speichern, anpassen, verwerfen)."""
        if not self.image_mode or not self.current_image_item:
            return

        print("=== SPEICHERDIALOG FÜR BILD ===")

        img_page = getattr(self.current_image_item, "page_num", self.current_page)

        dialog = myUniversalDialog(
            self,
            # "Bild speichern"
            title=self.tr("save_dialog_title", self.tr("image_menu")),
            # "Bild wird auf Seite {0} gespeichert.\n\nWie möchten Sie fortfahren?"
            message=self.tr("save_dialog_message", self.tr("image_menu"), img_page + 1),
            text_alignment=Qt.AlignLeft,
            buttons=[
                # "Alle Bilder speichern"
                (self.tr("image_save_all"), "success", "save_all", 300),
                # "Bild anpassen"
                (self.tr("image_customize"), "primary", "customize", 300),
                # "Dieses Bild verwerfen"
                (self.tr("image_discard"), "danger", "clean", 250),
            ],
            icon_type="",
            # "Alle Bilder speichern, anpassen oder dieses verwerfen?"
            voice_message=self.tr("image_save_question"),
            default_button="save_all",
        )

        result = dialog.exec_()
        if result != QDialog.Accepted:
            return

        action = dialog.result_value
        if action == "save_all":
            print("Speichere alle Bilder...")
            self._save_all_images()
        elif action == "customize":
            print("Öffne Bildeinstellungen...")
            # Direkt die Methode für das aktuelle Bild aufrufen
            self._open_image_customize_for_item(self.current_image_item)
            # Nach dem Schließen des Dialogs den Speicherdialog wieder öffnen
            QTimer.singleShot(100, self._show_image_save_dialog)
        elif action == "clean":
            print("Verwerfe dieses Bild")
            self._cleanup_image_mode()

    def _save_all_images(self, reload_after_save=True):
        if not self.all_image_items:
            self.say(self.tr("no_images_to_save"))
            return

        print("\n=== ALLE BILDER SPEICHERN (MIT OFFSET) ===")
        settings = QSettings("BinhDiez", "PDFDarkView")
        offset_x = settings.value("image/offset_x", 0, type=int)
        offset_y = settings.value("image/offset_y", 0, type=int)

        images_data = []
        valid_items = []
        last_valid_item = None
        last_scene_pos = None

        for img_item in self.all_image_items:
            if img_item is None or sip.isdeleted(img_item):
                continue
            try:
                pos = img_item.pos()
                page = img_item.page_num
                scene_pos = img_item.scenePos()
                original_path = img_item.original_path
                pixmap = img_item.pixmap()
                images_data.append(
                    {
                        "page": page,
                        "pos": pos,
                        "scene_pos": scene_pos,
                        "original_path": original_path,
                        "pixmap": pixmap,
                    }
                )
                valid_items.append(img_item)
                last_valid_item = img_item
                last_scene_pos = scene_pos
            except RuntimeError:
                continue

        if not images_data:
            self.say(self.tr("no_valid_images"))
            return

        target_page = last_valid_item.page_num if last_valid_item else 0
        scene_pos = last_scene_pos if last_scene_pos else QPointF(0, 0)

        for img_item in valid_items:
            if img_item.scene() and not sip.isdeleted(img_item):
                img_item.scene().removeItem(img_item)
        self.all_image_items = [
            item for item in self.all_image_items if item not in valid_items
        ]
        if not self.all_image_items:
            self.image_mode = False
            self.current_image_item = None
            self._cleanup_image_shortcuts()
        else:
            self.current_image_item = self.all_image_items[0]
            self.image_mode = True
        self.update_menu_states()

        try:
            if (
                hasattr(self, "current_doc")
                and self.current_doc
                and not self.current_doc.is_closed
            ):
                doc = self.current_doc
                print("DEBUG: Verwende aktuelles Dokument für Bilder")
            else:
                doc = fitz.open(self.pdf_path)
                if hasattr(self, "current_password") and self.current_password:
                    doc.authenticate(self.current_password)
                    print("DEBUG: Dokument neu geöffnet mit Passwort")
                else:
                    print("DEBUG: Dokument neu geöffnet ohne Passwort")

            for data in images_data:
                page_num = data["page"]
                if page_num >= len(doc):
                    continue
                page = doc[page_num]
                if page_num >= len(self.page_items):
                    continue
                page_item = self.page_items[page_num]
                page_rect = page_item.boundingRect()
                local_pos = data["pos"]
                pdf_width = page.rect.width
                pdf_height = page.rect.height
                scale_x = pdf_width / page_rect.width()
                scale_y = pdf_height / page_rect.height()
                x_pixel = local_pos.x() + offset_x
                y_pixel = local_pos.y() + offset_y
                x_pt = x_pixel * scale_x
                y_pt = y_pixel * scale_y
                pixmap = data["pixmap"]
                width_pt = pixmap.width() * scale_x
                height_pt = pixmap.height() * scale_y
                rect = fitz.Rect(x_pt, y_pt, x_pt + width_pt, y_pt + height_pt)
                page.insert_image(rect, filename=data["original_path"])

            target_path = self.generate_custom_filename(
                suffixes=[self.tr("filename_with_image")]
            )
            final_path = self._prepare_overwrite_target(target_path)

            temp_dir = tempfile.gettempdir()
            temp_filename = (
                f"temp_images_{datetime.now().strftime('%Y%m%d_%H%M%S_%f')}.pdf"
            )
            temp_path = os.path.join(temp_dir, temp_filename)

            if hasattr(self, "current_password") and self.current_password:
                doc.save(
                    temp_path,
                    encryption=fitz.PDF_ENCRYPT_AES_256,
                    user_pw=self.current_password,
                    owner_pw=None,
                    permissions=fitz.PDF_PERM_PRINT | fitz.PDF_PERM_COPY,
                    garbage=4,
                    deflate=True,
                )
                print("DEBUG: Datei mit Passwort verschlüsselt gespeichert")
            else:
                doc.save(temp_path, garbage=4, deflate=True)
                print("DEBUG: Datei unverschlüsselt gespeichert")

            if not (hasattr(self, "current_doc") and doc is self.current_doc):
                doc.close()
            shutil.copy2(temp_path, final_path)
            os.remove(temp_path)

            # Passwort für die neue Datei speichern
            if hasattr(self, "current_password") and self.current_password:
                PDFPasswordManager.save_password(final_path, self.current_password)
                print(f"DEBUG: Passwort für neue Datei gespeichert: {final_path}")

            # Erfolgsmeldung
            settings = QSettings("BinhDiez", "PDFDarkView")
            behavior = settings.value("filename/behavior", "new_file", type=str)
            create_backup = settings.value("create_backup", True, type=bool)

            if behavior == "overwrite":
                if create_backup:
                    msg = self.tr("images_saved_overwrite_with_backup")
                    voice_msg = self.tr("images_saved_overwrite_with_backup")
                else:
                    msg = self.tr("images_saved_overwrite_no_backup")
                    voice_msg = self.tr("images_saved_overwrite_no_backup")
            else:
                msg = self.tr("images_saved_new_file", len(valid_items))
                voice_msg = self.tr("images_saved_voice", len(valid_items))

            self._success_title = self.tr("images_saved_title")
            self._success_message = msg
            self._success_voice_message = voice_msg
            self._show_success_dialog = True

            # Am Ende, nach erfolgreichem Speichern:
            if reload_after_save:
                QTimer.singleShot(
                    2500,
                    lambda: self._reload_pdf_after_save_with_position(
                        final_path,
                        target_page,
                        scene_pos,
                        (
                            self.current_password
                            if hasattr(self, "current_password")
                            else None
                        ),
                    ),
                )
            else:
                # Nur Erfolgsmeldung anzeigen, ohne Neuladen
                self._show_success_dialog_only()
                self._cleanup_all_modes()  # Alle Modi beenden

            self.setWindowTitle(
                f"{self.tr('app_title')} - {os.path.basename(final_path)}"
            )

        except Exception as e:
            print(f"\n❌ FEHLER beim Speichern der Bilder: {str(e)}")
            import traceback

            traceback.print_exc()
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('save_error')}:\n{str(e)}"
            )

    def _remove_image_item(self, img_item):
        """Entfernt ein einzelnes Bild aus der Szene und aktualisiert den Modus."""
        if img_item in self.all_image_items:
            self.all_image_items.remove(img_item)
        if img_item in self.scene.items():
            self.scene.removeItem(img_item)
        if img_item == self.current_image_item:
            self.current_image_item = None

        # Prüfe, ob noch Bilder vorhanden sind
        if self.all_image_items:
            self.current_image_item = self.all_image_items[0]
            self.image_mode = True
            self.current_image_item.setSelected(True)
            self._setup_image_shortcuts()
        else:
            self.image_mode = False
            self._cleanup_image_shortcuts()
            self._cleanup_image_mode()

        self.update_menu_states()
        self.scene.update()
        # "Bild verworfen"
        self.say(self.tr("image_discarded"))

    def _cleanup_image_shortcuts(self):
        """Entfernt alle Tastatur-Shortcuts für Bilder."""
        if hasattr(self, "image_shortcuts"):
            for sc in self.image_shortcuts:
                sc.setEnabled(False)
                sc.deleteLater()
            self.image_shortcuts.clear()

    def _cleanup_all_images(self):
        """Entfernt alle imageen aus der Szene (verwerfen) – mit Fehlerbehandlung."""
        if self._cleaning_up_image:
            return
        self._cleaning_up_image = True
        print("=== ALLE BILDER VERWERFEN ===")

        # Wichtig: Eine Kopie der Liste erstellen, da wir während der Iteration löschen
        images_to_remove = list(self.all_image_items)

        for image_item in images_to_remove:
            try:
                if image_item is not None and not sip.isdeleted(image_item):
                    if image_item.scene():
                        image_item.scene().removeItem(image_item)
            except (RuntimeError, AttributeError) as e:
                print(f"WARN: image-Item konnte nicht entfernt werden: {e}")
                continue

        # Listen leeren
        self.all_image_items.clear()
        self.image_mode = False
        self.current_image_item = None
        self.copied_image_data = None

        self._cleanup_image_shortcuts()
        self.scene.update()
        self.update_menu_states()
        self._cleaning_up_image = False
        # "Alle Bilder verworfen"
        self.say(self.tr("all_images_discarded"))

    def _cleanup_image_mode(self):
        """Entfernt das aktuell ausgewählte Bild-Item (verwerfen)."""
        if self._cleaning_up_image:
            return
        self._cleaning_up_image = True
        print("=== CLEANUP IMAGE (aktuelles Item) ===")

        if self.current_image_item:
            try:
                if self.current_image_item in self.all_image_items:
                    self.all_image_items.remove(self.current_image_item)
                if self.current_image_item in self.scene.items():
                    self.scene.removeItem(self.current_image_item)
            except Exception as e:
                print(f"Fehler beim Entfernen: {e}")
            self.current_image_item = None

        # Prüfe, ob noch Bilder vorhanden sind
        if self.all_image_items:
            self.current_image_item = self.all_image_items[0]
            self.image_mode = True
            self.current_image_item.setSelected(True)
            self._setup_image_shortcuts()
        else:
            self.image_mode = False
            self._cleanup_image_shortcuts()

        self.copied_image_data = None
        self.scene.update()
        self.update_menu_states()
        self._cleaning_up_image = False
        print("=== CLEANUP IMAGE ABGESCHLOSSEN ===")

    def _open_image_customize_for_item(self, img_item):
        """Öffnet den Anpassungsdialog für ein bestimmtes Bild."""
        # Prüfen ob img_item existiert
        if img_item is None:
            print("DEBUG: Bild-Item ist None")
            return

        # Prüfen ob das Item noch in der Szene existiert (nicht gelöscht)
        try:
            if sip.isdeleted(img_item):
                print("DEBUG: Bild-Item wurde bereits gelöscht")
                return
        except:
            print("DEBUG: Fehler beim Prüfen des Bild-Items")
            return

        # Prüfen ob es ein ImageItem ist (hat original_path)
        if not hasattr(img_item, "original_path"):
            print(f"DEBUG: Item {type(img_item)} ist kein ImageItem")
            # Versuche das aktuelle Bild aus der Liste zu holen
            if self.current_image_item and hasattr(
                self.current_image_item, "original_path"
            ):
                img_item = self.current_image_item
                print("DEBUG: Verwende current_image_item stattdessen")
            else:
                return

        # Zusätzliche Prüfung ob original_path existiert
        if not hasattr(img_item, "original_path") or not img_item.original_path:
            print("DEBUG: ImageItem hat keinen original_path")
            return

        self.current_image_item = img_item
        self.image_mode = True
        self.current_image_item.setSelected(True)

        # Dialog öffnen
        dialog = ImageSettingsDialog(self)

        # Vor dem Anzeigen die ComboBox mit aktueller Bildgröße füllen
        if hasattr(img_item, "get_current_size_percent"):
            current_percent = img_item.get_current_size_percent()
            target_text = f"{current_percent}%"

            # Prüfen ob der Wert in der Liste ist
            index = dialog.default_size_combo.findText(target_text)
            if index >= 0:
                dialog.default_size_combo.setCurrentIndex(index)
            else:
                dialog.default_size_combo.setEditText(target_text)

            print(f"DEBUG: ComboBox auf {target_text} gesetzt")

        if dialog.exec_() == QDialog.Accepted:
            # Einstellungen aktualisieren
            self.image_settings = self.load_image_settings()

            # Prüfen ob img_item noch existiert
            try:
                if sip.isdeleted(img_item):
                    print("DEBUG: Bild-Item wurde während des Dialogs gelöscht")
                    return
            except:
                return

            # Größe des aktuellen Bildes ändern
            new_size_percent = self.image_settings.get("default_size_percent", 1.0)
            keep_aspect = self.image_settings.get("keep_aspect_ratio", True)

            # Seitenverhältnis aktualisieren
            img_item.aspect_ratio_mode = keep_aspect

            # Original-Bild laden
            original_pixmap = QPixmap(img_item.original_path)
            if not original_pixmap.isNull():
                # Neue Größe berechnen
                new_width = int(original_pixmap.width() * new_size_percent)
                new_height = int(original_pixmap.height() * new_size_percent)

                # Bild skalieren
                scaled_pixmap = original_pixmap.scaled(
                    new_width, new_height, Qt.KeepAspectRatio, Qt.SmoothTransformation
                )

                # Position anpassen (Mitte beibehalten)
                old_rect = img_item.boundingRect()
                old_center_x = img_item.pos().x() + old_rect.width() / 2
                old_center_y = img_item.pos().y() + old_rect.height() / 2

                new_x = old_center_x - new_width / 2
                new_y = old_center_y - new_height / 2

                # Auf Seite beschränken
                if self.page_items and img_item.page_num < len(self.page_items):
                    page_item = self.page_items[img_item.page_num]
                    page_rect = page_item.boundingRect()
                    new_x = max(0, min(new_x, page_rect.width() - new_width))
                    new_y = max(0, min(new_y, page_rect.height() - new_height))

                # Bild aktualisieren
                img_item.setPixmap(scaled_pixmap)
                img_item.setPos(new_x, new_y)
                img_item.original_pixmap = original_pixmap
                img_item.setScale(1.0)

                print(f"DEBUG: Bildgröße geändert auf {new_size_percent*100}%")

            self.say(self.tr("image_settings_updated"))

    def _open_image_settings_dialog(self):
        """Öffnet Bildeinstellungen für aktives Bild"""
        if not self.current_image_item:
            self.say(self.tr("no_image_selected"))
            return

        # Einfach die bestehende Methode aufrufen
        self._open_image_customize_for_item(self.current_image_item)

    def _toggle_image_aspect_ratio(self, image_item):
        """Schaltet Seitenverhältnis für ein bestimmtes Bild um"""
        if image_item:
            image_item.aspect_ratio_mode = not image_item.aspect_ratio_mode
            status = (
                self.tr("image_aspect_on")
                if image_item.aspect_ratio_mode
                else self.tr("image_aspect_off")
            )
            # "Seitenverhältnis beibehalten {0}"
            self.say(self.tr("image_aspect_toggle", status))

    def _reset_image_size(self, image_item):
        """Setzt Bild auf Originalgröße zurück"""
        if not image_item:
            return

        try:
            # Originalgröße aus Datei laden
            original_pixmap = QPixmap(image_item.original_path)
            if not original_pixmap.isNull():
                image_item.setPixmap(original_pixmap)
                image_item.original_pixmap = original_pixmap

                # Position zentrieren
                if image_item.parentItem():
                    page_rect = image_item.parentItem().boundingRect()
                    new_x = (page_rect.width() - original_pixmap.width()) / 2
                    new_y = (page_rect.height() - original_pixmap.height()) / 2
                    image_item.setPos(new_x, new_y)

                # "Bild auf Originalgröße zurückgesetzt"
                self.say(self.tr("image_reset"))

        except Exception as e:
            print(f"Fehler beim Zurücksetzen: {e}")

    def _replace_image(self, image_item):
        """Ersetzt ein bestehendes Bild"""
        if not image_item:
            return

        file_filter = self.tr("image_filter_all")
        filepath, _ = QFileDialog.getOpenFileName(
            self,
            # "Neues Bild auswählen"
            self.tr("image_replace_title"),
            (
                os.path.dirname(image_item.original_path)
                if image_item.original_path
                else os.path.expanduser("~/Pictures")
            ),
            file_filter,
        )

        if not filepath:
            return

        try:
            # Prüfe Bild
            from PIL import Image

            img = Image.open(filepath)
            img.verify()
            img.close()

            # Aktuelle Position merken
            old_pos = image_item.pos()
            old_page = image_item.page_num

            # Alte Temp-Datei löschen
            if image_item.temp_path and os.path.exists(image_item.temp_path):
                try:
                    os.remove(image_item.temp_path)
                except:
                    pass

            # Neues Bild vorbereiten
            current_size = (
                image_item.pixmap().width() / image_item.original_pixmap.width()
                if image_item.original_pixmap.width() > 0
                else 1.0
            )

            display_pixmap, temp_path = self._prepare_image_for_display(
                filepath, current_size, self.dark_mode
            )

            if not display_pixmap.isNull():
                image_item.setPixmap(display_pixmap)
                image_item.original_path = filepath
                image_item.temp_path = temp_path
                image_item.original_pixmap = display_pixmap

                # Position ggf. anpassen
                if image_item.parentItem():
                    page_rect = image_item.parentItem().boundingRect()
                    new_x = max(
                        0, min(old_pos.x(), page_rect.width() - display_pixmap.width())
                    )
                    new_y = max(
                        0,
                        min(old_pos.y(), page_rect.height() - display_pixmap.height()),
                    )
                    image_item.setPos(new_x, new_y)

                # "Bild ersetzt"
                self.say(self.tr("image_replaced"))

        except Exception as e:
            print(f"Fehler beim Ersetzen: {e}")
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('image_invalid')}:\n{str(e)}"
            )

    def _save_single_image(self, image_item):
        """Speichert ein einzelnes Bild sofort"""
        if image_item:
            self.current_image_item = image_item
            self.image_mode = True
            self._save_image_in_pdf(image_item)

    def show_image_guide(self):
        """Zeigt Anleitung zur Verwendung von Bildern."""
        dialog = myUniversalDialog(
            self,
            title=self.tr("image_guide_title"),
            message=self.tr("image_guide_html"),
            buttons=[(self.tr("btn_ok"), "primary", "ok")],
            icon_type="",
            voice_message=self.tr("image_guide_voice"),
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()

    ### ==================================
    ### FORMEN EINFÜGEN
    ### ==================================

    def _insert_form_from_menu(self, form_type):
        """Form über Menü einfügen."""
        print(f"DEBUG: _insert_form_from_menu aufgerufen mit form_type={form_type}")

        if not self.page_items or self.current_page >= len(self.page_items):
            self.say(self.tr("no_pdf_loaded"))
            return

        local_pos, page_num = self._get_insertion_position(default_y_ratio=0.5)
        if local_pos is None:
            return

        # Direkter Aufruf der Einfügemethode (ohne Umwege)
        self.insert_form_at_position(
            local_pos, page_num, form_type, rotation_checked=False
        )

    def insert_form_at_position(
        self, scene_position, page_num, form_type=None, rotation_checked=False
    ):
        """Fügt Form an Position ein."""
        print(f"=== insert_form_at_position ===")
        print(f"rotation_checked={rotation_checked}")

        if not rotation_checked:
            self.check_page_rotation(
                page_index=page_num,
                callback=self.insert_form_at_position,
                callback_args=(scene_position, page_num, form_type, True),
            )
            return

        if form_type is None:
            form_type = self.form_settings.get("default_type", "rectangle")

        # Modus-Konflikt-Prüfung (wie gehabt)
        if self.signature_mode or self.text_mode or self.image_mode:
            active_modes = []
            if self.signature_mode:
                active_modes.append(self.tr("active_mode_signature"))
            if self.text_mode:
                active_modes.append(self.tr("active_mode_text"))
            if self.image_mode:
                active_modes.append(self.tr("active_mode_image"))
            mode_text = self.tr("active_mode_and").join(active_modes)

            dialog = myUniversalDialog(
                self,
                title=self.tr("mode_conflict"),
                message=self.tr(
                    "mode_conflict_message", mode_text, self.tr("mode_replace_form")
                ),
                text_alignment=Qt.AlignLeft,
                buttons=[
                    (
                        self.tr("mode_replace", self.tr("mode_replace_form")),
                        "warning",
                        "replace",
                        300,
                    ),
                    (self.tr("mode_cancel"), "danger", "cancel", 200),
                ],
                icon_type="",
                voice_message=self.tr("mode_conflict_voice_form", mode_text),
                default_button="cancel",
            )
            dialog.exec_()
            if dialog.result_value != "replace":
                return
            if self.signature_mode:
                self._cleanup_signature_mode()
            if self.text_mode:
                self._cleanup_text_mode(speak=False)
            if self.image_mode:
                self._cleanup_image_mode()
            if self.form_mode:
                self._cleanup_form_mode()

        # Für Linien/Pfeile
        if form_type in ["line", "arrow"]:
            self.form_draw_mode = True
            self.form_draw_type = form_type
            self.form_first_point = scene_position
            self.say(self.tr("form_second_click", form_type))
            return

        # Zur richtigen Seite navigieren ==========
        if self.current_page != page_num:
            print(
                f"DEBUG: Wechsle von Seite {self.current_page+1} zu Seite {page_num+1}"
            )
            self.current_page = page_num
            with QSignalBlocker(self.page_spin):
                self.page_spin.setValue(page_num + 1)
            self.scroll_to_page(announce=False)

        # Für Rechtecke/Ellipsen: Verzögertes Einfügen (wie bei Kreuzen!)
        print("DEBUG: Verzögere Form-Einfügen um 100ms...")
        QTimer.singleShot(
            100,
            lambda: self._place_form_at_position(scene_position, page_num, form_type),
        )

    def _place_form_at_position(self, scene_position, page_num, form_type):
        """Platziert eine Form an der angegebenen Position - KORRIGIERT"""
        print(f"=== _place_form_at_position ===")
        print(f"page_num={page_num}, form_type={form_type}")

        if page_num >= len(self.page_items):
            print(f"FEHLER: Seite {page_num} existiert nicht")
            return

        try:
            page_item = self.page_items[page_num]
            settings = QSettings("BinhDiez", "PDFDarkView")
            line_width = settings.value("form/line_width", 3, type=int)
            line_color = QColor(settings.value("form/line_color", "#000000"))
            fill_color = QColor(settings.value("form/fill_color", "#FFFFFF"))
            transparent_bg = settings.value("form/transparent_bg", True, type=bool)
            default_width = settings.value("form/default_width", 100, type=int)
            default_height = settings.value("form/default_height", 100, type=int)

            # WICHTIG: Das Rechteck wird in LOKALEN Koordinaten (0,0 basierend) definiert
            rect = QRectF(0, 0, default_width, default_height)

            # Die Position wird SEPARAT mit setPos() gesetzt
            # Die Mitte des Rechtecks soll an der Klickposition sein
            pos_x = scene_position.x() - default_width / 2
            pos_y = scene_position.y() - default_height / 2

            # Auf Seite beschränken
            page_rect = page_item.boundingRect()
            pos_x = max(0, min(pos_x, page_rect.width() - default_width))
            pos_y = max(0, min(pos_y, page_rect.height() - default_height))

            form_item = FormItem(
                form_type=form_type,
                page_num=page_num,
                rect=rect,
                line_width=line_width,
                line_color=line_color,
                fill_color=fill_color if not transparent_bg else None,
                transparent_bg=transparent_bg,
            )

            form_item.viewer = self
            form_item.setParentItem(page_item)
            form_item.setPos(
                pos_x, pos_y
            )  # <-- Position wird hier gesetzt, nicht im rect
            form_item.setZValue(1000)

            if self.dark_mode:
                form_item.apply_dark_mode(True)

            self.all_form_items.append(form_item)
            self.current_form_item = form_item
            self.form_mode = True
            self.current_form_item.setSelected(True)

            self._setup_form_keyboard_shortcuts()
            self.update_menu_states()

            print(f"DEBUG: Form eingefügt bei ({pos_x:.1f}, {pos_y:.1f})")

        except Exception as e:
            print(f"Fehler beim Platzieren der Form: {e}")
            import traceback

            traceback.print_exc()

    def load_form_settings(self):
        """Lädt Formen-Einstellungen"""
        return FormSettingsDialog.load_form_settings(self)

    def open_form_settings(self):
        """Öffnet Formen-Einstellungen"""
        # Allgemeine Einstellungen (keine bestimmte Form)
        dialog = FormSettingsDialog(self)  # Ohne form_item
        if dialog.exec_() == QDialog.Accepted:
            self.form_settings = self.load_form_settings()
            self.say(self.tr("form_settings_updated"))

    def _open_form_customize_for_current_item(self, form_item=None):
        """Öffnet den Anpassungsdialog für eine Form."""

        # Wenn ein Form-Item übergeben wurde (Kontextmenü), verwende dieses
        target_item = form_item if form_item is not None else self.current_form_item

        # Wenn immer noch keine Form, suche nach ausgewählter Form in der Scene
        if target_item is None and self.scene:
            for item in self.scene.selectedItems():
                if isinstance(item, FormItem):
                    target_item = item
                    self.current_form_item = target_item
                    self.form_mode = True
                    break

        if not target_item:
            self.say(self.tr("no_form_selected"))
            return

        dialog = FormSettingsDialog(self, form_item=target_item)
        if dialog.exec_() == QDialog.Accepted:
            self.form_settings = self.load_form_settings()
            self.say(self.tr("form_customized"))
            self.scene.update()
            self.graphics_view.viewport().update()

    def _toggle_form_transparency_for_current_item(self, form_item=None):
        """Schaltet transparenten Hintergrund für Form um."""

        # Wenn ein Form-Item übergeben wurde (Kontextmenü), verwende dieses
        target_item = form_item if form_item is not None else self.current_form_item

        # WICHTIG: Prüfe ob target_item wirklich ein Form-Item ist
        if target_item is None or not isinstance(target_item, FormItem):
            # Versuche aus der Scene die ausgewählte Form zu holen
            if self.scene:
                for item in self.scene.selectedItems():
                    if isinstance(item, FormItem):
                        target_item = item
                        self.current_form_item = target_item
                        self.form_mode = True
                        break

        # Wenn immer noch kein gültiges Form-Item
        if not isinstance(target_item, FormItem):
            self.say(self.tr("no_form_selected"))
            return

        target_item.transparent_bg = not target_item.transparent_bg

        if target_item == self.current_form_item and hasattr(
            self, "form_transparent_action"
        ):
            self.form_transparent_action.setChecked(not target_item.transparent_bg)

        status = (
            self.tr("form_transparent_on")
            if target_item.transparent_bg
            else self.tr("form_transparent_off")
        )
        self.say(self.tr("form_transparent_toggled", status))

        target_item.update()
        self.scene.update()

    def _reset_form_size(self, form_item):
        """Setzt Form auf Standardgröße zurück"""
        if not form_item:
            return

        try:
            # Standardgröße
            default_size = 100

            if form_item.form_type in ["line", "arrow"]:
                # Für Linien: diagonale Linie
                center_x = (form_item.start_point.x() + form_item.end_point.x()) / 2
                center_y = (form_item.start_point.y() + form_item.end_point.y()) / 2
                form_item.start_point = QPointF(center_x - 40, center_y - 40)
                form_item.end_point = QPointF(center_x + 40, center_y + 40)
                form_item.update_rect_from_points()
            else:
                # Für Rechtecke/Ellipsen: zentriert
                center = form_item.rect.center()
                form_item.rect = QRectF(
                    center.x() - default_size / 2,
                    center.y() - default_size / 2,
                    default_size,
                    default_size,
                )

            form_item.prepareGeometryChange()
            form_item.update()
            # "Form auf Standardgröße zurückgesetzt"
            self.say(self.tr("form_reset"))

        except Exception as e:
            print(f"Fehler beim Zurücksetzen: {e}")

    def _apply_form_settings(self):
        """Wendet aktuelle Form-Einstellungen auf die aktive Form an"""
        if not self.form_mode or not self.current_form_item:
            return

        try:
            print("=== PASSE FORM AN (EINSTELLUNGEN) ===")

            item = self.current_form_item

            # Neue Einstellungen anwenden
            item.line_width = self.form_settings.get("line_width", 2)
            item.line_color = self.form_settings.get("line_color", QColor(0, 0, 0))
            item.fill_color = self.form_settings.get(
                "fill_color", QColor(255, 255, 255)
            )
            item.transparent_bg = self.form_settings.get("transparent_bg", True)
            item.dark_mode_inverted = self.form_settings.get("dark_mode_invert", True)

            # Originalfarben speichern
            item.original_line_color = QColor(item.line_color)
            item.original_fill_color = QColor(item.fill_color)

            # Dark Mode anwenden
            item.apply_dark_mode(self.dark_mode)

            item.update()
            print(f"Form angepasst")

        except Exception as e:
            print(f"Fehler beim Anpassen der Form: {e}")
            import traceback

            traceback.print_exc()

    def _insert_another_form(self, form_type, local_pos, page_num):
        """Fügt eine weitere Form ein, ohne den aktuellen Modus zu beenden."""
        if form_type in ["line", "arrow"]:
            # Für Linien/Pfeile: Zwei-Klick-Modus starten
            self.form_draw_mode = True
            self.form_draw_type = form_type
            self.form_first_point = local_pos
            # "Jetzt Endpunkt für {0} klicken"
            self.say(self.tr("form_second_click", form_type))
        else:
            self._place_form_at_position(local_pos, page_num, form_type)

    def _do_place_form(self, scene_position, page_num, form_type):
        """Eigentliches Platzieren der Form (nach Verzögerung)."""
        print(f"=== _do_place_form ===")
        print(
            f"scene_position={scene_position}, page_num={page_num}, form_type={form_type}"
        )

        if page_num >= len(self.page_items):
            print(f"FEHLER: Seite {page_num} existiert nicht")
            return

        try:
            page_item = self.page_items[page_num]
            page_rect = page_item.boundingRect()

            # Einstellungen laden
            settings = QSettings("BinhDiez", "PDFDarkView")
            line_width = settings.value("form/line_width", 3, type=int)
            line_color = QColor(settings.value("form/line_color", "#000000"))
            fill_color = QColor(settings.value("form/fill_color", "#FFFFFF"))
            transparent_bg = settings.value("form/transparent_bg", True, type=bool)
            default_width = settings.value("form/default_width", 100, type=int)
            default_height = settings.value("form/default_height", 100, type=int)

            # Rechteck erstellen (zentriert um die Klickposition)
            rect = QRectF(
                scene_position.x() - default_width / 2,
                scene_position.y() - default_height / 2,
                default_width,
                default_height,
            )

            form_item = FormItem(
                form_type=form_type,
                page_num=page_num,
                rect=rect,
                line_width=line_width,
                line_color=line_color,
                fill_color=fill_color if not transparent_bg else None,
                transparent_bg=transparent_bg,
            )

            form_item.viewer = self
            form_item.setParentItem(page_item)
            form_item.setPos(rect.topLeft())
            form_item.setZValue(1000)

            if self.dark_mode:
                form_item.apply_dark_mode(True)

            self.all_form_items.append(form_item)
            self.current_form_item = form_item
            self.form_mode = True
            self.current_form_item.setSelected(True)

            self._setup_form_keyboard_shortcuts()
            self.update_menu_states()

            print(
                f"DEBUG: Form eingefügt bei ({scene_position.x():.1f}, {scene_position.y():.1f})"
            )

        except Exception as e:
            print(f"Fehler beim Platzieren der Form: {e}")
            import traceback

            traceback.print_exc()

    def handle_form_second_click(self, scene_position, page_num):
        """Behandelt den zweiten Klick für Linien/Pfeile – mit Sicherheitsprüfungen"""
        print(f"\n{'='*40}")
        print(f"DEBUG: handle_form_second_click aufgerufen")
        print(f"  form_draw_mode: {self.form_draw_mode}")
        print(f"  form_draw_type: {self.form_draw_type}")
        print(f"  form_first_point: {self.form_first_point}")
        print(f"  zweiter Punkt: ({scene_position.x():.1f}, {scene_position.y():.1f})")
        print(f"  page_num: {page_num + 1}")
        print(f"{'='*40}")

        # Prüfe, ob der Modus aktiv und gültig ist
        if not self.form_draw_mode:
            print("DEBUG: Kein aktiver Zeichen-Modus – ignoriere")
            return

        if not self.form_draw_type:
            print("DEBUG: Kein gültiger form_draw_type – setze Modus zurück")
            self.form_draw_mode = False
            self.form_first_point = None
            return

        if self.form_first_point is None:
            print("DEBUG: Kein erster Punkt gespeichert – setze Modus zurück")
            self.form_draw_mode = False
            self.form_draw_type = None
            return

        # Stelle sicher, dass die Zielseite existiert
        if page_num >= len(self.page_items):
            print(f"DEBUG: Seite {page_num + 1} existiert nicht – ignoriere")
            self.form_draw_mode = False
            self.form_draw_type = None
            self.form_first_point = None
            return

        # Konvertiere Scene-Position in lokale Koordinaten der Seite
        page_item = self.page_items[page_num]
        local_pos = page_item.mapFromScene(scene_position)

        # Erste Punkt bereits in lokalen Koordinaten (wurde beim ersten Klick so gespeichert)
        first_local = self.form_first_point

        # Form erstellen
        result = self._place_line_form(
            first_local, local_pos, page_num, self.form_draw_type
        )

        # Modus zurücksetzen
        self.form_draw_mode = False
        self.form_draw_type = None
        self.form_first_point = None
        print(f"DEBUG: Zeichen-Modus zurückgesetzt, Ergebnis: {result}")

    def _place_line_form(self, start_local, end_local, page_num, form_type):
        """Platziert Linie/Pfeil zwischen zwei Punkten - VOLLSTÄNDIG KORRIGIERT"""
        print(f"\n{'='*50}")
        print(f"DEBUG: _place_line_form aufgerufen")
        print(f"  form_type: {form_type}")
        print(f"  page_num: {page_num + 1}")
        print(f"  start_local: ({start_local.x():.1f}, {start_local.y():.1f})")
        print(f"  end_local: ({end_local.x():.1f}, {end_local.y():.1f})")
        print(f"{'='*50}")

        try:
            if page_num >= len(self.page_items):
                return False

            page_item = self.page_items[page_num]
            page_rect = page_item.boundingRect()

            # Begrenze die Punkte auf den Seitenbereich (optional)
            start_local.setX(max(0, min(start_local.x(), page_rect.width())))
            start_local.setY(max(0, min(start_local.y(), page_rect.height())))
            end_local.setX(max(0, min(end_local.x(), page_rect.width())))
            end_local.setY(max(0, min(end_local.y(), page_rect.height())))

            # WICHTIG: Berechne relative Punkte für das Item
            min_x = min(start_local.x(), end_local.x())
            min_y = min(start_local.y(), end_local.y())

            # Relative Punkte (bezogen auf die linke obere Ecke)
            rel_start = QPointF(start_local.x() - min_x, start_local.y() - min_y)
            rel_end = QPointF(end_local.x() - min_x, end_local.y() - min_y)

            # Form-Item erstellen
            form_item = FormItem(
                form_type=form_type,
                page_num=page_num,
                start_point=rel_start,
                end_point=rel_end,
                line_width=self.form_settings.get("line_width", 2),
                line_color=self.form_settings.get("line_color", QColor(0, 0, 0)),
                fill_color=self.form_settings.get("fill_color", QColor(255, 255, 255)),
                transparent_bg=self.form_settings.get("transparent_bg", True),
            )
            form_item.viewer = self

            # Dark Mode
            form_item.dark_mode_inverted = self.form_settings.get(
                "dark_mode_invert", True
            )
            form_item.apply_dark_mode(self.dark_mode)

            # Parent setzen
            form_item.setParentItem(page_item)

            # WICHTIG: Item an die Minimal-Position setzen
            form_item.setPos(min_x, min_y)

            # Flags
            form_item.setFlag(QGraphicsItem.ItemIsMovable, True)
            form_item.setFlag(QGraphicsItem.ItemIsSelectable, True)
            form_item.setZValue(1000)
            form_item.setVisible(True)

            # Zur Liste hinzufügen
            self.all_form_items.append(form_item)

            # Zustand setzen
            self.current_form_item = form_item
            self.form_mode = True
            form_item.setSelected(True)

            # Scene aktualisieren
            form_item.update()
            self.scene.update()
            self.graphics_view.viewport().update()
            QApplication.processEvents()

            # Shortcuts
            self._setup_form_keyboard_shortcuts()

            # Sprachausgabe
            form_names = {"line": self.tr("form_line"), "arrow": self.tr("form_arrow")}
            # "{0} auf Seite {1} eingefügt"
            self.say(
                self.tr(
                    "form_inserted",
                    form_names.get(form_type, self.tr("form_unknown")),
                    page_num + 1,
                )
            )

            # Menü-Zustände
            self.update_menu_states()

            return True

        except Exception as e:
            print(f"\n❌ FEHLER in _place_line_form: {str(e)}")
            import traceback

            traceback.print_exc()
            return False

    def _force_form_update(self, form_item):
        """Erzwingt ein erneutes Zeichnen der Form"""
        if form_item and form_item.scene() is not None:
            print(f"DEBUG: Erzwinge zusätzliches Update für Form")
            form_item.update()
            form_item.setSelected(True)
            self.scene.update()
            self.graphics_view.viewport().update()
            QApplication.processEvents()

    def _setup_form_keyboard_shortcuts(self):
        """Richtet Tastatur-Shortcuts für Form-Modus ein"""
        # Alte Shortcuts entfernen
        if hasattr(self, "form_shortcuts"):
            for shortcut in self.form_shortcuts:
                try:
                    shortcut.setEnabled(False)
                    shortcut.deleteLater()
                except:
                    pass
            self.form_shortcuts.clear()
        else:
            self.form_shortcuts = []

        # Enter zum Speichern
        shortcut_save = QShortcut(QKeySequence("Return"), self.graphics_view)
        shortcut_save.activated.connect(self._show_form_save_dialog)
        self.form_shortcuts.append(shortcut_save)

        shortcut_save2 = QShortcut(QKeySequence("Enter"), self.graphics_view)
        shortcut_save2.activated.connect(self._show_form_save_dialog)
        self.form_shortcuts.append(shortcut_save2)

        # ESC zum Abbrechen
        shortcut_cancel = QShortcut(QKeySequence("Escape"), self.graphics_view)
        shortcut_cancel.activated.connect(self._cancel_form_esc_handler)
        self.form_shortcuts.append(shortcut_cancel)

        # Pfeiltasten für Bewegung
        arrow_keys = [
            (Qt.Key_Up, 0, -1),
            (Qt.Key_Down, 0, 1),
            (Qt.Key_Left, -1, 0),
            (Qt.Key_Right, 1, 0),
        ]

        for key, dx, dy in arrow_keys:
            shortcut = QShortcut(QKeySequence(key), self.graphics_view)
            shortcut.activated.connect(lambda dx=dx, dy=dy: self._move_form(dx, dy))
            self.form_shortcuts.append(shortcut)

            # Strg für größere Schritte
            shortcut_ctrl = QShortcut(QKeySequence(f"Ctrl+{key}"), self.graphics_view)
            shortcut_ctrl.activated.connect(
                lambda dx=dx * 5, dy=dy * 5: self._move_form(dx, dy)
            )
            self.form_shortcuts.append(shortcut_ctrl)

            # Shift für mittlere Schritte
            shortcut_shift = QShortcut(QKeySequence(f"Shift+{key}"), self.graphics_view)
            shortcut_shift.activated.connect(
                lambda dx=dx * 10, dy=dy * 10: self._move_form(dx, dy)
            )
            self.form_shortcuts.append(shortcut_shift)

        print(f"{len(self.form_shortcuts)} Form-Shortcuts eingerichtet")

    def _move_form(self, dx, dy):
        """Bewegt Form mit Tastatur"""
        if not self.form_mode or not self.current_form_item:
            return

        item = self.current_form_item

        # Für Linien/Pfeile: Beide Punkte verschieben
        if item.form_type in ["line", "arrow"]:
            item.start_point += QPointF(dx, dy)
            item.end_point += QPointF(dx, dy)
            item.update_rect_from_points()
        else:
            # Für Rechtecke/Ellipsen: Rechteck verschieben
            item.rect.translate(dx, dy)

        # Auf Seite beschränken
        if self.page_items and item.page_num < len(self.page_items):
            page_item = self.page_items[item.page_num]
            page_rect = page_item.boundingRect()

            if item.form_type in ["line", "arrow"]:
                # Für Linien: Prüfe ob Punkte innerhalb der Seite bleiben
                if (
                    item.start_point.x() < 0
                    or item.start_point.x() > page_rect.width()
                    or item.start_point.y() < 0
                    or item.start_point.y() > page_rect.height()
                    or item.end_point.x() < 0
                    or item.end_point.x() > page_rect.width()
                    or item.end_point.y() < 0
                    or item.end_point.y() > page_rect.height()
                ):
                    # Zurücksetzen
                    item.start_point -= QPointF(dx, dy)
                    item.end_point -= QPointF(dx, dy)
            else:
                # Für Rechtecke: Prüfe ob Rechteck innerhalb bleibt
                if (
                    item.rect.left() < 0
                    or item.rect.right() > page_rect.width()
                    or item.rect.top() < 0
                    or item.rect.bottom() > page_rect.height()
                ):
                    item.rect.translate(-dx, -dy)

        item.prepareGeometryChange()
        item.update()

    def _copy_form_item(self, form_item):
        """Kopiert die Daten einer Form."""
        if not form_item:
            return
        data = {
            "form_type": form_item.form_type,
            "line_width": form_item.line_width,
            "line_color": form_item.original_line_color,
            "fill_color": form_item.original_fill_color,
            "transparent_bg": form_item.transparent_bg,
            "dark_mode_inverted": form_item.dark_mode_inverted,
        }
        if form_item.form_type in ["line", "arrow"]:
            data["start_point"] = QPointF(form_item.start_point)
            data["end_point"] = QPointF(form_item.end_point)
        else:
            data["rect"] = QRectF(form_item.rect)
        self.copied_form_data = data
        # "Form kopiert"
        self.say(self.tr("form_copied"))

    def _paste_form_at_position(self, local_pos, page_num):
        """Fügt die kopierte Form an der angegebenen Position ein – zentriert an Klickposition."""
        if self.copied_form_data is None:
            # "Keine kopierte Form vorhanden"
            self.say(self.tr("no_copied_form"))
            return False

        try:
            if page_num >= len(self.page_items):
                return False

            page_item = self.page_items[page_num]
            data = self.copied_form_data

            if data["form_type"] in ["line", "arrow"]:
                # Für Linien/Pfeile: Mittelpunkt der Linie an Klickposition
                start = QPointF(data["start_point"])
                end = QPointF(data["end_point"])
                center_rel = QPointF(
                    (start.x() + end.x()) / 2, (start.y() + end.y()) / 2
                )

                world_start = start - center_rel + local_pos
                world_end = end - center_rel + local_pos

                min_x = min(world_start.x(), world_end.x())
                min_y = min(world_start.y(), world_end.y())

                new_start_rel = world_start - QPointF(min_x, min_y)
                new_end_rel = world_end - QPointF(min_x, min_y)

                form_item = FormItem(
                    form_type=data["form_type"],
                    page_num=page_num,
                    start_point=new_start_rel,
                    end_point=new_end_rel,
                    line_width=data["line_width"],
                    line_color=data["line_color"],
                    fill_color=data["fill_color"],
                    transparent_bg=data["transparent_bg"],
                )
                form_item.setPos(min_x, min_y)

            else:  # rectangle oder ellipse
                rect_rel = data["rect"]
                # Zentriere das Rechteck an der Klickposition
                world_rect = QRectF(
                    local_pos.x() - rect_rel.width() / 2,
                    local_pos.y() - rect_rel.height() / 2,
                    rect_rel.width(),
                    rect_rel.height(),
                )
                new_rect_rel = QRectF(0, 0, rect_rel.width(), rect_rel.height())

                form_item = FormItem(
                    form_type=data["form_type"],
                    page_num=page_num,
                    rect=new_rect_rel,
                    line_width=data["line_width"],
                    line_color=data["line_color"],
                    fill_color=data["fill_color"],
                    transparent_bg=data["transparent_bg"],
                )
                form_item.setPos(world_rect.topLeft())

            form_item.viewer = self
            form_item.setParentItem(page_item)
            form_item.dark_mode_inverted = data["dark_mode_inverted"]
            form_item.apply_dark_mode(self.dark_mode)

            form_item.setFlag(QGraphicsItem.ItemIsMovable, True)
            form_item.setFlag(QGraphicsItem.ItemIsSelectable, True)
            form_item.setZValue(1000)
            form_item.setVisible(True)

            self.all_form_items.append(form_item)
            self.current_form_item = form_item
            self.form_mode = True
            form_item.setSelected(True)

            self._setup_form_keyboard_shortcuts()
            self.scene.update()
            self.update_menu_states()
            # "Form eingefügt"
            self.say(self.tr("form_pasted"))
            return True

        except Exception as e:
            print(f"Fehler beim Einfügen der Form: {e}")
            import traceback

            traceback.print_exc()
            return False

    def _cancel_form_esc_handler(self):
        """ESC-Handler für Form"""
        print("ESC-Handler für Form aufgerufen")
        if self.form_mode and self.current_form_item:
            self._cleanup_form_mode()
            # "Form verworfen"
            self.say(self.tr("form_discarded"))
        elif self.form_draw_mode:
            self.form_draw_mode = False
            self.form_draw_type = None
            self.form_first_point = None
            # "Linien-Zeichnen abgebrochen"
            self.say(self.tr("form_line_cancel"))

    def _show_form_save_dialog(self):
        """Zeigt Speicherdialog für Formen (alle speichern, anpassen, verwerfen)."""
        if not self.form_mode or not self.current_form_item:
            return

        form_page = getattr(self.current_form_item, "page_num", self.current_page)
        form_names = {
            "rectangle": self.tr("form_rectangle"),
            "ellipse": self.tr("form_ellipse"),
            "line": self.tr("form_line"),
            "arrow": self.tr("form_arrow"),
        }
        form_type_name = form_names.get(
            self.current_form_item.form_type, self.tr("form_unknown")
        )

        dialog = myUniversalDialog(
            self,
            title=self.tr("save_dialog_title", self.tr("form_menu")),
            message=self.tr("save_dialog_message", form_type_name, form_page + 1),
            text_alignment=Qt.AlignLeft,
            buttons=[
                (self.tr("form_save_all"), "success", "save_all", 300),
                (
                    self.tr("form_customize"),
                    "primary",
                    "customize",
                    300,
                ),  # Hier wird jetzt customize aufgerufen
                (self.tr("form_discard"), "danger", "clean", 300),
            ],
            icon_type="",
            voice_message=self.tr("form_save_question"),
            default_button="save_all",
        )

        result = dialog.exec_()
        if result != QDialog.Accepted:
            return

        action = dialog.result_value
        if action == "save_all":
            print("Speichere alle Formen...")
            self._save_all_forms()
        elif action == "customize":
            print("Öffne Formen-Einstellungen...")
            # GEÄNDERT: Jetzt wird die aktuelle Form übergeben
            settings_dialog = FormSettingsDialog(self, form_item=self.current_form_item)
            if settings_dialog.exec_() == QDialog.Accepted:
                self.form_settings = self.load_form_settings()
                # Einstellungen wurden bereits auf die Form angewendet
                self.scene.update()
                # Dialog erneut anzeigen (optional)
                QTimer.singleShot(100, self._show_form_save_dialog)
        elif action == "clean":
            print("Verwerfe diese Form")
            self._cleanup_form_mode()

    # Speicher Form in PDF
    def _save_all_forms(self, reload_after_save=True):
        if not self.all_form_items:
            self.say(self.tr("no_forms_to_save"))
            return

        print("\n=== ALLE FORMEN SPEICHERN (MIT OFFSET) ===")
        settings = QSettings("BinhDiez", "PDFDarkView")
        offset_x = settings.value("form/offset_x", 0, type=int)
        offset_y = settings.value("form/offset_y", 0, type=int)

        forms_data = []
        valid_items = []
        last_valid_item = None
        last_scene_pos = None

        for form_item in self.all_form_items:
            if form_item is None or sip.isdeleted(form_item):
                continue
            try:
                pos = form_item.pos()
                page = form_item.page_num
                scene_pos = form_item.scenePos()
                forms_data.append(
                    {
                        "page": page,
                        "pos": pos,
                        "scene_pos": scene_pos,
                        "form_type": form_item.form_type,
                        "line_width": form_item.line_width,
                        "line_color": form_item.original_line_color,
                        "fill_color": form_item.original_fill_color,
                        "transparent_bg": form_item.transparent_bg,
                        "rect": form_item.rect if hasattr(form_item, "rect") else None,
                        "start_point": (
                            form_item.start_point
                            if hasattr(form_item, "start_point")
                            else None
                        ),
                        "end_point": (
                            form_item.end_point
                            if hasattr(form_item, "end_point")
                            else None
                        ),
                    }
                )
                valid_items.append(form_item)
                last_valid_item = form_item
                last_scene_pos = scene_pos
            except RuntimeError:
                continue

        if not forms_data:
            self.say(self.tr("no_valid_forms"))
            return

        target_page = last_valid_item.page_num if last_valid_item else 0
        scene_pos = last_scene_pos if last_scene_pos else QPointF(0, 0)

        for form_item in valid_items:
            if form_item.scene() and not sip.isdeleted(form_item):
                form_item.scene().removeItem(form_item)
        self.all_form_items = [
            item for item in self.all_form_items if item not in valid_items
        ]
        if not self.all_form_items:
            self.form_mode = False
            self.current_form_item = None
            self._cleanup_form_keyboard_shortcuts()
        else:
            self.current_form_item = self.all_form_items[0]
            self.form_mode = True
        self.update_menu_states()

        try:
            if (
                hasattr(self, "current_doc")
                and self.current_doc
                and not self.current_doc.is_closed
            ):
                doc = self.current_doc
                print("DEBUG: Verwende aktuelles Dokument für Formen")
            else:
                doc = fitz.open(self.pdf_path)
                if hasattr(self, "current_password") and self.current_password:
                    doc.authenticate(self.current_password)
                    print("DEBUG: Dokument neu geöffnet mit Passwort")
                else:
                    print("DEBUG: Dokument neu geöffnet ohne Passwort")

            for data in forms_data:
                page_num = data["page"]
                if page_num >= len(doc):
                    continue
                page = doc[page_num]
                if page_num >= len(self.page_items):
                    continue
                page_item = self.page_items[page_num]
                page_rect = page_item.boundingRect()
                local_pos = data["pos"]
                pdf_width = page.rect.width
                pdf_height = page.rect.height
                scale_x = pdf_width / page_rect.width()
                scale_y = pdf_height / page_rect.height()

                x_pixel = local_pos.x() + offset_x
                y_pixel = local_pos.y() + offset_y

                color_rgb = (
                    data["line_color"].red() / 255.0,
                    data["line_color"].green() / 255.0,
                    data["line_color"].blue() / 255.0,
                )
                line_width_pdf = data["line_width"] * ((scale_x + scale_y) / 2)

                if data["form_type"] in ["line", "arrow"]:
                    start_pdf = fitz.Point(
                        (x_pixel + data["start_point"].x()) * scale_x,
                        (y_pixel + data["start_point"].y()) * scale_y,
                    )
                    end_pdf = fitz.Point(
                        (x_pixel + data["end_point"].x()) * scale_x,
                        (y_pixel + data["end_point"].y()) * scale_y,
                    )
                    page.draw_line(
                        start_pdf, end_pdf, color=color_rgb, width=line_width_pdf
                    )
                    if data["form_type"] == "arrow":
                        distance = math.hypot(
                            end_pdf.x - start_pdf.x, end_pdf.y - start_pdf.y
                        )
                        if distance > 30:
                            dx = end_pdf.x - start_pdf.x
                            dy = end_pdf.y - start_pdf.y
                            angle = math.atan2(dy, dx)
                            arrow_size = 15 + data["line_width"] * 2
                            arrow_p1 = fitz.Point(
                                end_pdf.x - arrow_size * math.cos(angle - 0.3),
                                end_pdf.y - arrow_size * math.sin(angle - 0.3),
                            )
                            arrow_p2 = fitz.Point(
                                end_pdf.x - arrow_size * math.cos(angle + 0.3),
                                end_pdf.y - arrow_size * math.sin(angle + 0.3),
                            )
                            page.draw_line(
                                end_pdf, arrow_p1, color=color_rgb, width=line_width_pdf
                            )
                            page.draw_line(
                                end_pdf, arrow_p2, color=color_rgb, width=line_width_pdf
                            )
                else:
                    rect_pdf = fitz.Rect(
                        (x_pixel + data["rect"].x()) * scale_x,
                        (y_pixel + data["rect"].y()) * scale_y,
                        (x_pixel + data["rect"].x() + data["rect"].width()) * scale_x,
                        (y_pixel + data["rect"].y() + data["rect"].height()) * scale_y,
                    )
                    fill = (
                        None
                        if data["transparent_bg"]
                        else (
                            data["fill_color"].red() / 255.0,
                            data["fill_color"].green() / 255.0,
                            data["fill_color"].blue() / 255.0,
                        )
                    )
                    if data["form_type"] == "rectangle":
                        page.draw_rect(
                            rect_pdf, color=color_rgb, fill=fill, width=line_width_pdf
                        )
                    elif data["form_type"] == "ellipse":
                        page.draw_oval(
                            rect_pdf, color=color_rgb, fill=fill, width=line_width_pdf
                        )

            # Speichern
            target_path = self.generate_custom_filename(
                suffixes=[self.tr("filename_with_forms")]
            )
            final_path = self._prepare_overwrite_target(target_path)

            temp_dir = tempfile.gettempdir()
            temp_filename = (
                f"temp_forms_{datetime.now().strftime('%Y%m%d_%H%M%S_%f')}.pdf"
            )
            temp_path = os.path.join(temp_dir, temp_filename)

            if hasattr(self, "current_password") and self.current_password:
                doc.save(
                    temp_path,
                    encryption=fitz.PDF_ENCRYPT_AES_256,
                    user_pw=self.current_password,
                    owner_pw=None,
                    permissions=fitz.PDF_PERM_PRINT | fitz.PDF_PERM_COPY,
                    garbage=4,
                    deflate=True,
                )
                print("DEBUG: Datei mit Passwort verschlüsselt gespeichert")
            else:
                doc.save(temp_path, garbage=4, deflate=True)
                print("DEBUG: Datei unverschlüsselt gespeichert")

            if not (hasattr(self, "current_doc") and doc is self.current_doc):
                doc.close()
            shutil.copy2(temp_path, final_path)
            os.remove(temp_path)

            # Passwort für die neue Datei speichern
            if hasattr(self, "current_password") and self.current_password:
                PDFPasswordManager.save_password(final_path, self.current_password)
                print(f"DEBUG: Passwort für neue Datei gespeichert: {final_path}")

            # Erfolgsmeldung
            settings = QSettings("BinhDiez", "PDFDarkView")
            behavior = settings.value("filename/behavior", "new_file", type=str)
            create_backup = settings.value("create_backup", True, type=bool)

            if behavior == "overwrite":
                if create_backup:
                    msg = self.tr("forms_saved_overwrite_with_backup")
                    voice_msg = self.tr("forms_saved_overwrite_with_backup")
                else:
                    msg = self.tr("forms_saved_overwrite_no_backup")
                    voice_msg = self.tr("forms_saved_overwrite_no_backup")
            else:
                msg = self.tr("forms_saved_new_file", len(forms_data))
                voice_msg = self.tr("forms_saved_voice", len(forms_data))

            self._success_title = self.tr("form_saved_title")
            self._success_message = msg
            self._success_voice_message = voice_msg
            self._show_success_dialog = True

            # Am Ende, nach erfolgreichem Speichern:
            if reload_after_save:
                QTimer.singleShot(
                    2500,
                    lambda: self._reload_pdf_after_save_with_position(
                        final_path,
                        target_page,
                        scene_pos,
                        (
                            self.current_password
                            if hasattr(self, "current_password")
                            else None
                        ),
                    ),
                )
            else:
                # Nur Erfolgsmeldung anzeigen, ohne Neuladen
                self._show_success_dialog_only()
                self._cleanup_all_modes()  # Alle Modi beenden

            self.setWindowTitle(
                f"{self.tr('app_title')} - {os.path.basename(final_path)}"
            )

        except Exception as e:
            print(f"\n❌ FEHLER beim Speichern der Formen: {str(e)}")
            import traceback

            traceback.print_exc()
            QMessageBox.critical(
                self, self.tr("error"), f"{self.tr('save_error')}:\n{str(e)}"
            )

    def _cleanup_form_keyboard_shortcuts(self):
        """Entfernt alle Tastatur-Shortcuts für Formen."""
        if hasattr(self, "form_shortcuts"):
            for sc in self.form_shortcuts:
                try:
                    sc.setEnabled(False)
                    sc.deleteLater()
                except:
                    pass
            self.form_shortcuts.clear()

    def _cleanup_all_forms(self):
        """Entfernt alle Formen aus der Szene (verwerfen) – mit Fehlerbehandlung."""
        if self._cleaning_up_form:
            return
        self._cleaning_up_form = True
        print("=== ALLE FORMEN VERWERFEN ===")

        # Wichtig: Eine Kopie der Liste erstellen, da wir während der Iteration löschen
        forms_to_remove = list(self.all_form_items)

        for form_item in forms_to_remove:
            try:
                if form_item is not None and not sip.isdeleted(form_item):
                    if form_item.scene():
                        form_item.scene().removeItem(form_item)
            except (RuntimeError, AttributeError) as e:
                print(f"WARN: Form-Item konnte nicht entfernt werden: {e}")
                continue

        # Listen leeren
        self.all_form_items.clear()
        self.form_mode = False
        self.current_form_item = None
        self.copied_form_data = None

        self._cleanup_form_keyboard_shortcuts()
        self.scene.update()
        self.update_menu_states()
        self._cleaning_up_form = False
        # "Alle Formen verworfen"
        self.say(self.tr("all_forms_discarded"))

    def _remove_form_item(self, form_item):
        """Entfernt eine einzelne Form aus der Szene und aktualisiert den Modus."""
        if form_item in self.all_form_items:
            self.all_form_items.remove(form_item)
        if form_item in self.scene.items() and not sip.isdeleted(form_item):
            self.scene.removeItem(form_item)
        if form_item == self.current_form_item:
            self.current_form_item = None

        # Prüfe, ob noch Formen vorhanden sind
        if self.all_form_items:
            self.current_form_item = self.all_form_items[0]
            self.form_mode = True
            self.current_form_item.setSelected(True)
            self._setup_form_keyboard_shortcuts()
        else:
            self.form_mode = False
            self._cleanup_form_keyboard_shortcuts()
            self.copied_form_data = None

        self.update_menu_states()
        self.scene.update()
        # "Form gelöscht"
        self.say(self.tr("form_deleted"))

    def _cleanup_form_mode(self):
        """Entfernt Form SICHER und einfach – mit Timer-Stopp und Schutz."""
        if self._cleaning_up_form:
            return
        self._cleaning_up_form = True
        print("=== CLEANUP FORM ===")

        # 1. Timer stoppen, die noch auf diese Form verweisen könnten
        for timer in self._active_timers:
            if timer.isActive():
                timer.stop()
                timer.deleteLater()
        self._active_timers.clear()

        # 2. Form-Shortcuts entfernen
        try:
            if hasattr(self, "form_shortcuts"):
                for shortcut in self.form_shortcuts:
                    shortcut.setEnabled(False)
                    shortcut.deleteLater()
                self.form_shortcuts.clear()
        except:
            pass

        # 3. Aktuelle Form aus Liste entfernen und aufräumen
        if self.current_form_item:
            try:
                print(f"Entferne Form-Item: {self.current_form_item}")

                # Event-Handler zurücksetzen (Signalverbindungen trennen)
                try:
                    self.current_form_item.disconnect()
                except:
                    pass

                # Aus der Liste aller Formen entfernen
                if self.current_form_item in self.all_form_items:
                    self.all_form_items.remove(self.current_form_item)

                # Aus Scene entfernen
                if self.current_form_item in self.scene.items():
                    self.scene.removeItem(self.current_form_item)

            except Exception as e:
                print(f"Fehler beim Entfernen: {e}")

            self.current_form_item = None

        # 4. Modus beenden
        self.form_mode = False

        # 5. Zeichen-Modus zurücksetzen
        self.form_draw_mode = False
        self.form_draw_type = None
        self.form_first_point = None

        # 6. kopierte Formen zurücksetzen
        self.copied_form_data = None

        # 7. Scene aktualisieren
        self.scene.update()
        self.graphics_view.viewport().update()

        # 8. Menü-Zustände aktualisieren
        self.update_menu_states()

        self._cleaning_up_form = False
        print("=== CLEANUP FORM ABGESCHLOSSEN ===")

    def show_form_guide(self):
        """Zeigt Anleitung für Formen."""
        dialog = myUniversalDialog(
            self,
            title=self.tr("form_guide_title"),
            message=self.tr("form_guide_html"),
            buttons=[(self.tr("btn_ok"), "primary", "ok")],
            icon_type="",
            voice_message=self.tr("form_guide_voice"),
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()

    ### =====================================
    ### SEITENZAHLEN EINFÜGEN
    ### =====================================

    def _add_page_numbers(self):
        """Fügt Seitenzahlen zu allen Seiten der PDF hinzu."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            self._show_no_pdf_dialog()
            return

        dialog = PageNumberDialog(self)
        if dialog.exec_() != QDialog.Accepted:
            self.say(self.tr("page_numbers_cancel"))
            return

        settings = dialog.get_data()
        self.say(self.tr("page_numbers_start"))

        try:
            # Suffix basierend auf dem gewählten Inhaltstyp
            tab_index = settings.get("tab_index", 0)
            if tab_index == 0:
                suffix = self.tr("filename_with_pagenumber")
            elif tab_index == 1:
                suffix = self.tr("filename_with_page_declaration")
            elif tab_index == 2:
                suffix = self.tr("filename_with_date")
            else:
                suffix = self.tr("filename_with_my_page_declaration")

            # Zielpfad mit generate_custom_filename erstellen
            output_path = self.generate_custom_filename(
                suffixes=[suffix], force_new_file=True
            )

            # PDF öffnen
            doc = fitz.open(self.pdf_path)

            # Falls passwortgeschützt, authentifizieren
            if doc.is_encrypted or doc.needs_pass:
                if hasattr(self, "current_password") and self.current_password:
                    if not doc.authenticate(self.current_password):
                        raise Exception(self.tr("password_wrong"))
                else:
                    raise Exception(self.tr("pdf_encrypted"))

            # Schriftart-Einstellungen
            font_name = settings["font_family"]
            font_size = settings["font_size"]

            # Versuche, die Schriftart-Datei zu finden
            font_file = self._find_font_file(
                font_name, settings["bold"], settings["italic"]
            )

            # Position bestimmen
            position_map = {
                "top-left": (0, 0),
                "top-center": (1, 0),
                "top-right": (2, 0),
                "middle-left": (0, 1),
                "middle-center": (1, 1),
                "middle-right": (2, 1),
                "bottom-left": (0, 2),
                "bottom-center": (1, 2),
                "bottom-right": (2, 2),
            }
            x_align, y_align = position_map.get(settings["position"], (1, 2))

            margin_x = settings["margin_x"]
            margin_y = settings["margin_y"]
            color_rgb = (
                settings["color"].red() / 255.0,
                settings["color"].green() / 255.0,
                settings["color"].blue() / 255.0,
            )

            text_generator = settings["text_generator"]
            total_pages = doc.page_count

            # Fortschritts-Dialog
            progress_dialog = QProgressDialog(
                self.tr("page_numbers_progress"),
                self.tr("btn_cancel"),
                0,
                doc.page_count,
                self,
            )
            progress_dialog.setWindowModality(Qt.WindowModal)
            progress_dialog.setMinimumWidth(300)
            progress_dialog.setStyleSheet("""
                QProgressDialog {
                    background-color: #2D2D2D;
                    color: #E0E0E0;
                }
            """)

            # Seitenzahlen hinzufügen
            for page_num in range(doc.page_count):
                if progress_dialog.wasCanceled():
                    doc.close()
                    self.say(self.tr("page_numbers_cancel"))
                    return

                page_num_display = page_num + 1

                # Prüfen ob in gewähltem Bereich
                if (
                    page_num_display < settings["start_page"]
                    or page_num_display > settings["end_page"]
                ):
                    progress_dialog.setValue(page_num + 1)
                    continue

                page = doc[page_num]
                page_rect = page.rect

                # Text generieren
                page_text = text_generator(page_num_display, total_pages)

                # Text-Größe berechnen (ungefähre Breite)
                text_width = len(page_text) * font_size * 0.6

                # X-Position berechnen
                if x_align == 0:  # Links
                    x = margin_x
                elif x_align == 1:  # Mitte
                    x = (page_rect.width - text_width) / 2
                else:  # Rechts
                    x = page_rect.width - text_width - margin_x

                # Y-Position berechnen
                if y_align == 0:  # Oben
                    y = margin_y
                elif y_align == 1:  # Mitte
                    y = page_rect.height / 2
                else:  # Unten
                    y = page_rect.height - margin_y

                # Text auf Seite einfügen
                try:
                    if font_file and os.path.exists(font_file):
                        page.insert_text(
                            (x, y),
                            page_text,
                            fontsize=font_size,
                            fontfile=font_file,
                            color=color_rgb,
                        )
                    else:
                        # Fallback: Verwende Helvetica
                        page.insert_text(
                            (x, y),
                            page_text,
                            fontsize=font_size,
                            fontname="helv",
                            color=color_rgb,
                        )
                except Exception as e:
                    # Letzter Fallback
                    print(f"Font-Fallback: {e}")
                    page.insert_text(
                        (x, y), page_text, fontsize=font_size, color=color_rgb
                    )

                progress_dialog.setValue(page_num + 1)
                QApplication.processEvents()

            progress_dialog.close()

            # PDF speichern
            doc.save(output_path, garbage=4, deflate=True)
            doc.close()

            # Erfolgsmeldung mit dem Dateinamen
            filename = os.path.basename(output_path)
            success_message = self.tr("page_numbers_success", filename)

            confirm_dialog = myUniversalDialog(
                self,
                title=self.tr("success"),
                message=success_message,
                text_alignment=Qt.AlignLeft,
                buttons=[
                    (self.tr("confirm_yes"), "primary", "yes"),
                    (self.tr("confirm_no"), "danger", "no"),
                ],
                icon_type="",
                voice_message=self.tr("page_numbers_complete"),
                default_button="yes",
            )
            confirm_dialog.exec_()

            if confirm_dialog.result_value == "yes":
                self.close_current_pdf()
                self.load_pdf(output_path)

        except Exception as e:
            error_msg = self.tr("page_numbers_error_format", str(e))
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                text_alignment=Qt.AlignLeft,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()
            print(f"Fehler beim Einfügen von Seitenzahlen: {e}")
            traceback.print_exc()

    def _find_font_file(self, font_name, bold=False, italic=False):
        """Findet die Schriftart-Datei für den gegebenen Schriftnamen."""
        import platform

        # Baue den vollständigen Schriftnamen
        if bold and italic:
            style = "BoldItalic"
        elif bold:
            style = "Bold"
        elif italic:
            style = "Italic"
        else:
            style = "Regular"

        full_font_name = f"{font_name}-{style}"

        # System-spezifische Schriftverzeichnisse
        if platform.system() == "Windows":
            font_dirs = [
                os.environ.get("WINDIR", "C:\\Windows") + "\\Fonts",
                os.environ.get("LOCALAPPDATA", "") + "\\Microsoft\\Windows\\Fonts",
            ]
            extensions = [".ttf", ".ttc", ".otf"]
        elif platform.system() == "Darwin":  # macOS
            font_dirs = [
                "/System/Library/Fonts/",
                "/Library/Fonts/",
                os.path.expanduser("~/Library/Fonts/"),
            ]
            extensions = [".ttf", ".ttc", ".otf", ".dfont"]
        else:  # Linux
            font_dirs = [
                "/usr/share/fonts/",
                "/usr/local/share/fonts/",
                os.path.expanduser("~/.fonts/"),
                os.path.expanduser("~/.local/share/fonts/"),
            ]
            extensions = [".ttf", ".ttc", ".otf"]

        # Suche nach der Schriftart-Datei
        for font_dir in font_dirs:
            if not os.path.exists(font_dir):
                continue

            # Suche nach exaktem Namen
            for ext in extensions:
                font_path = os.path.join(font_dir, full_font_name + ext)
                if os.path.exists(font_path):
                    return font_path

            # Suche nach Basisnamen mit Wildcard
            try:
                for file in os.listdir(font_dir):
                    base_name = os.path.splitext(file)[0]
                    # Normalisiere den Vergleich
                    if base_name.lower() == full_font_name.lower():
                        return os.path.join(font_dir, file)
                    # Suche auch nach Teil-Übereinstimmungen
                    if font_name.lower() in file.lower():
                        if style.lower() in file.lower():
                            return os.path.join(font_dir, file)
            except:
                continue

        # Fallback: Bekannte Standardschriftarten
        common_fonts = {
            "Arial": ("arial.ttf", "Arial.ttf"),
            "Helvetica": ("helvetica.ttf", "Helvetica.ttf"),
            "Times New Roman": ("times.ttf", "Times New Roman.ttf"),
            "Courier": ("cour.ttf", "Courier New.ttf"),
        }

        if font_name in common_fonts:
            for font_dir in font_dirs:
                for candidate in common_fonts[font_name]:
                    font_path = os.path.join(font_dir, candidate)
                    if os.path.exists(font_path):
                        return font_path

        return None

    def _format_page_number(self, page_num, settings):
        """Formatiert eine einzelne Seitenzahl gemäß den Einstellungen."""
        format_type = settings["format_type"]

        if format_type == "arabic":
            return str(page_num)
        elif format_type == "roman_lower":
            return self._to_roman(page_num).lower()
        elif format_type == "roman_upper":
            return self._to_roman(page_num).upper()
        elif format_type == "letter":
            return self._to_letter(page_num)
        elif format_type == "custom":
            pattern = settings.get("custom_pattern", "{nummer}")
            return pattern.replace("{nummer}", str(page_num)).replace(
                "{total}", str(settings["total_pages"])
            )
        return str(page_num)

    def _to_roman(self, num):
        """Konvertiert eine Zahl in römische Ziffern."""
        roman_map = [
            (1000, "M"),
            (900, "CM"),
            (500, "D"),
            (400, "CD"),
            (100, "C"),
            (90, "XC"),
            (50, "L"),
            (40, "XL"),
            (10, "X"),
            (9, "IX"),
            (5, "V"),
            (4, "IV"),
            (1, "I"),
        ]
        result = ""
        for value, symbol in roman_map:
            while num >= value:
                result += symbol
                num -= value
        return result

    def _to_letter(self, num):
        """Konvertiert eine Zahl in Buchstaben (A, B, C, ...)."""
        result = ""
        while num > 0:
            num -= 1
            result = chr(65 + (num % 26)) + result
            num //= 26
        return result

