    def _add_fullpage_text_watermark(self):
        """Öffnet Dialog für diagonales Text-Wasserzeichen."""
        if not self.pdf_path:
            self.say(self.tr("no_pdf_loaded"))
            return

        dialog = FullPageTextWatermarkDialog(self)
        if dialog.exec_() == QDialog.Accepted:
            data = dialog.get_data()
            if not data["text"]:
                QMessageBox.warning(
                    self, self.tr("warning"), self.tr("watermark_empty_text")
                )
                return
            FullPageWatermarkRenderer.create_and_apply(
                self, self.pdf_path, "text", data
            )

    def _add_fullpage_image_watermark(self):
        """Öffnet Dialog für Bild-Wasserzeichen."""
        if not self.pdf_path:
            self.say(self.tr("no_pdf_loaded"))
            return

        dialog = FullPageImageWatermarkDialog(self)
        if dialog.exec_() == QDialog.Accepted:
            data = dialog.get_data()
            if not data["image_path"]:
                QMessageBox.warning(self, self.tr("warning"), self.tr("image_invalid"))
                return
            FullPageWatermarkRenderer.create_and_apply(
                self, self.pdf_path, "image", data
            )

    ### ==============================================
    ### SCHWÄRZEN / RADIERGUMMI - REDAKTION
    ### ==============================================

    def _add_redaction_rect(self, mode="black"):
        """Wird über Menüleiste aufgerufen – mode='black' oder 'white'."""
        if not self.page_items or self.current_page >= len(self.page_items):
            self.say(self.tr("no_pdf_loaded"))
            return

        local_pos, page_num = self._get_insertion_position(default_y_ratio=0.3)
        if local_pos is None:
            page_item = self.page_items[self.current_page]
            rect = page_item.boundingRect()
            local_pos = QPointF(rect.width() / 2, rect.height() / 2)
            page_num = self.current_page

        self._add_redaction_rect_at_position(
            local_pos, page_num, mode, rotation_checked=False
        )

    def _add_redaction_rect_at_position(
        self, local_pos, page_num, mode="black", rotation_checked=False
    ):
        if not self.page_items or page_num >= len(self.page_items):
            return

        if not rotation_checked:
            self.check_page_rotation(
                page_index=page_num,
                callback=self._add_redaction_rect_at_position,
                callback_args=(local_pos, page_num, mode, True),
            )
            return

        w, h = 150, 100
        rect = QRectF(local_pos.x() - w / 2, local_pos.y() - h / 2, w, h)
        page_item = self.page_items[page_num]
        page_rect = page_item.boundingRect()
        rect = rect.intersected(page_rect)
        if rect.width() < 20 or rect.height() < 20:
            rect = QRectF(10, 10, w, h)

        redact_item = RedactionItem(rect, page_num, self, mode)
        redact_item.setParentItem(page_item)
        redact_item.setPos(rect.topLeft())
        self._setup_redaction_event_handlers(redact_item)

        self.all_redaction_items.append(redact_item)
        self.current_redaction_item = redact_item
        self.redaction_mode = True
        redact_item.setSelected(True)
        self._setup_redaction_shortcuts()
        self.update_menu_states()

        # Sprachausgabe
        if mode == "white":
            self.say(self.tr("redact_added_white"))
        else:
            self.say(self.tr("redact_added_black"))

    def _setup_redaction_event_handlers(self, item):
        """Richtet Maus‑Event‑Handler für RedactionItem ein (ähnlich wie bei Formen)."""
        # Da RedactionItem bereits eigene mousePress/Move/Release hat,
        # müssen wir nur noch das Anklicken für die Auswahl implementieren.
        # Wir nutzen die bestehenden Methoden des Items und ergänzen das Setzen
        # als current_redaction_item.
        original_mouse_press = item.mousePressEvent

        def custom_mouse_press(event):
            if sip.isdeleted(item):
                return
            # Aktuelles Item im Viewer setzen
            if self.current_redaction_item != item:
                self.current_redaction_item = item
                self.redaction_mode = True
                # Andere deselektieren
                for other in self.all_redaction_items:
                    if other != item:
                        other.setSelected(False)
                item.setSelected(True)
                self.update_menu_states()
            # Originale Behandlung (Resize, etc.) aufrufen
            original_mouse_press(event)

        item.mousePressEvent = custom_mouse_press
        item.setAcceptHoverEvents(True)

    def _setup_redaction_shortcuts(self):
        """Richtet Tastatur‑Shortcuts für Redaction‑Modus ein."""
        if hasattr(self, "redaction_shortcuts"):
            for sc in self.redaction_shortcuts:
                sc.setEnabled(False)
                sc.deleteLater()
        self.redaction_shortcuts = []

        # Enter / Escape / Bewegung (wie bei Formen)
        sc_save = QShortcut(QKeySequence("Return"), self.graphics_view)
        sc_save.activated.connect(self._apply_all_redactions_and_save)
        self.redaction_shortcuts.append(sc_save)

        sc_cancel = QShortcut(QKeySequence("Escape"), self.graphics_view)
        sc_cancel.activated.connect(self._cleanup_redaction_mode)
        self.redaction_shortcuts.append(sc_cancel)

        # Pfeiltasten für Bewegung
        arrow_keys = [
            (Qt.Key_Up, 0, -1),
            (Qt.Key_Down, 0, 1),
            (Qt.Key_Left, -1, 0),
            (Qt.Key_Right, 1, 0),
        ]
        for key, dx, dy in arrow_keys:
            sc = QShortcut(QKeySequence(key), self.graphics_view)
            sc.activated.connect(lambda d=dx, ddy=dy: self._move_redaction(d, ddy))
            self.redaction_shortcuts.append(sc)

            sc_ctrl = QShortcut(QKeySequence(f"Ctrl+{key}"), self.graphics_view)
            sc_ctrl.activated.connect(
                lambda d=dx * 5, ddy=dy * 5: self._move_redaction(d, ddy)
            )
            self.redaction_shortcuts.append(sc_ctrl)

            sc_shift = QShortcut(QKeySequence(f"Shift+{key}"), self.graphics_view)
            sc_shift.activated.connect(
                lambda d=dx * 10, ddy=dy * 10: self._move_redaction(d, ddy)
            )
            self.redaction_shortcuts.append(sc_shift)

        print(f"{len(self.redaction_shortcuts)} Redaction‑Shortcuts eingerichtet")

    def _move_redaction(self, dx, dy):
        if not self.redaction_mode or not self.current_redaction_item:
            return
        if sip.isdeleted(self.current_redaction_item):
            self._cleanup_redaction_mode()
            return
        if not self.redaction_mode or not self.current_redaction_item:
            return
        item = self.current_redaction_item
        new_rect = item.rect.translated(dx, dy)
        # Begrenzung auf Seitenbereich
        page_item = self.page_items[item.page_num]
        page_rect = page_item.boundingRect()
        new_rect = new_rect.intersected(page_rect)
        if new_rect.width() >= 20 and new_rect.height() >= 20:
            item.rect = new_rect
            item.prepareGeometryChange()
            item.update()

    def _copy_redaction_item(self, item):
        """Kopiert ein Redaction-Item in die Zwischenablage."""
        if not item:
            return
        self.copied_redaction_data = {
            "rect": QRectF(item.rect),  # relative Koordinaten (lokal)
            "page_num": item.page_num,
            "is_redaction": True,
        }
        self.say(self.tr("redact_copied"))
        self.statusBar().showMessage(self.tr("redact_copied"), 2000)

    def _paste_redaction_at_position(self, local_pos, page_num):
        """Fügt eine kopierte Schwärzung an der angegebenen Position ein."""
        if (
            not hasattr(self, "copied_redaction_data")
            or self.copied_redaction_data is None
        ):
            self.say(self.tr("no_copied_redaction"))
            return False

        try:
            if page_num >= len(self.page_items):
                return False

            page_item = self.page_items[page_num]
            data = self.copied_redaction_data
            orig_rect = data["rect"]

            # Zentriere das Rechteck an der Klickposition
            new_rect = QRectF(
                local_pos.x() - orig_rect.width() / 2,
                local_pos.y() - orig_rect.height() / 2,
                orig_rect.width(),
                orig_rect.height(),
            )

            # Auf Seite beschränken
            page_rect = page_item.boundingRect()
            new_rect = new_rect.intersected(page_rect)
            if new_rect.width() < 20 or new_rect.height() < 20:
                new_rect = QRectF(10, 10, 150, 100)

            redact_item = RedactionItem(new_rect, page_num, self)
            redact_item.setParentItem(page_item)
            redact_item.setPos(new_rect.topLeft())
            self._setup_redaction_event_handlers(redact_item)

            self.all_redaction_items.append(redact_item)
            self.current_redaction_item = redact_item
            self.redaction_mode = True
            redact_item.setSelected(True)
            self._setup_redaction_shortcuts()
            self.update_menu_states()

            # Erzwinge sofortige Neuzeichnung
            self.scene.update()
            self.graphics_view.viewport().update()
            QApplication.processEvents()

            self.say(self.tr("redact_pasted"))
            return True

        except Exception as e:
            print(f"Fehler beim Einfügen der Schwärzung: {e}")
            return False

    def _remove_redaction_item(self, item):
        """Entfernt ein einzelnes Redaction-Item."""
        if item in self.all_redaction_items:
            self.all_redaction_items.remove(item)
        if item.scene() and not sip.isdeleted(item):
            item.scene().removeItem(item)
        if item == self.current_redaction_item:
            self.current_redaction_item = None
        # Falls noch andere existieren, eines auswählen
        if self.all_redaction_items:
            self.current_redaction_item = self.all_redaction_items[0]
            self.redaction_mode = True
            self.current_redaction_item.setSelected(True)
            self._setup_redaction_shortcuts()
        else:
            self.redaction_mode = False
            self._cleanup_redaction_shortcuts()
        self.update_menu_states()
        self.say(self.tr("redact_discarded"))

    def _cleanup_redaction_mode(self):
        """Löscht das aktuell ausgewählte Redaction‑Item."""
        if self._cleaning_up_redaction:
            return
        self._cleaning_up_redaction = True
        if self.current_redaction_item:
            item = self.current_redaction_item
            # Event‑Handler entkoppeln (falls nötig)
            try:
                item.setParentItem(None)
            except:
                pass
            # Aus Scene entfernen
            if item.scene():
                item.scene().removeItem(item)
            if item in self.all_redaction_items:
                self.all_redaction_items.remove(item)
            self.current_redaction_item = None
        if self.all_redaction_items:
            self.current_redaction_item = self.all_redaction_items[0]
            self.redaction_mode = True
            self.current_redaction_item.setSelected(True)
            self._setup_redaction_shortcuts()
        else:
            self.redaction_mode = False
            self._cleanup_redaction_shortcuts()
        self.update_menu_states()
        self._cleaning_up_redaction = False
        self.say(self.tr("redact_discarded"))

    def _cleanup_redaction_shortcuts(self):
        if hasattr(self, "redaction_shortcuts"):
            for sc in self.redaction_shortcuts:
                sc.setEnabled(False)
                sc.deleteLater()
            self.redaction_shortcuts.clear()

    def _cleanup_all_redactions(self):
        """Entfernt alle Redaction‑Items (verwerfen)."""
        if self._cleaning_up_redaction:
            return
        self._cleaning_up_redaction = True
        for item in self.all_redaction_items[:]:
            if item.scene():
                item.scene().removeItem(item)
        self.all_redaction_items.clear()
        self.redaction_mode = False
        self.current_redaction_item = None
        self._cleanup_redaction_shortcuts()
        self.update_menu_states()
        self._cleaning_up_redaction = False

    def _apply_all_redactions_and_save(self):
        """Wendet alle Schwärzungen dauerhaft an und speichert die PDF."""
        if not self.all_redaction_items:
            self.say(self.tr("no_redactions"))
            return

        # Bestätigungsdialog, weil irreversibel
        confirm = myUniversalDialog(
            self,
            title=self.tr("redact_confirm_title"),
            message=self.tr("redact_confirm_message"),
            buttons=[
                (self.tr("redact_apply"), "danger", "apply", 400),
                (self.tr("btn_cancel"), "primary", "cancel", 400),
            ],
            default_button="cancel",
            icon_type="",
            text_alignment=Qt.AlignLeft,
        )
        if confirm.exec_() != QDialog.Accepted or confirm.result_value != "apply":
            return

        # Sammle alle Redactions pro Seite (speichere auch die Item-Objekte für die Umrechnung)
        redactions_by_page = {}
        total_redactions = len(self.all_redaction_items)

        for item in self.all_redaction_items:
            page = item.page_num
            if page not in redactions_by_page:
                redactions_by_page[page] = []
            redactions_by_page[page].append(item)

        if not redactions_by_page:
            return

        # Position für späteren Sprung merken (letztes Item oder Seite 0)
        last_item = self.all_redaction_items[-1] if self.all_redaction_items else None
        if last_item:
            target_page = last_item.page_num
            # Mitte des Items in Scene-Koordinaten
            item_center = last_item.sceneBoundingRect().center()
            scene_pos = item_center
        else:
            target_page = 0
            scene_pos = QPointF(0, 0)

        # Temporäre Kopie der PDF erstellen
        try:
            # Backup, falls aktiviert
            if self.create_backup:
                backup_path = self.get_backup_filename(self.pdf_path)
                shutil.copy2(self.pdf_path, backup_path)
                print(f"Backup vor Schwärzung: {backup_path}")

            doc = fitz.open(self.pdf_path)
            if hasattr(self, "current_password") and self.current_password:
                doc.authenticate(self.current_password)

            # Für jede Seite: Redactions hinzufügen
            for page_num, items in redactions_by_page.items():
                if page_num >= len(doc):
                    continue
                page = doc[page_num]
                page_item = self.page_items[page_num]
                page_rect_px = page_item.boundingRect()
                # Umrechnungsfaktoren von Pixeln (GUI) zu PDF‑Punkten
                scale_x = page.rect.width / page_rect_px.width()
                scale_y = page.rect.height / page_rect_px.height()

                for item in items:
                    # Rechteck in Pixeln (GUI) – relativ zum Item
                    rect_px = item.rect
                    # Position des Items in Pixeln (relativ zur Seite)
                    pos_px = item.pos()
                    # Absolute Koordinaten in Pixeln
                    x0_px = pos_px.x() + rect_px.x()
                    y0_px = pos_px.y() + rect_px.y()
                    x1_px = x0_px + rect_px.width()
                    y1_px = y0_px + rect_px.height()

                    # Umrechnung in PDF‑Punkte
                    x0 = x0_px * scale_x
                    y0 = y0_px * scale_y
                    x1 = x1_px * scale_x
                    y1 = y1_px * scale_y
                    pdf_rect = fitz.Rect(x0, y0, x1, y1)

                    # Redaction‑Annotation hinzufügen
                    # Füllfarbe je nach Modus
                    if item.mode == "white":
                        fill_color = (1, 1, 1)  # Weiß (Radieren)
                    else:
                        fill_color = (0, 0, 0)  # Schwarz (Schwärzen)
                    page.add_redact_annot(pdf_rect, fill=fill_color)

                # Redactions auf der Seite anwenden
                page.apply_redactions()

            # Speichern
            target_path = self.generate_custom_filename(
                suffixes=[self.tr("filename_redacted")]
            )
            final_path = self._prepare_overwrite_target(target_path)

            temp_dir = tempfile.gettempdir()
            temp_name = f"temp_redact_{datetime.now().strftime('%Y%m%d_%H%M%S_%f')}.pdf"
            temp_path = os.path.join(temp_dir, temp_name)

            if hasattr(self, "current_password") and self.current_password:
                doc.save(
                    temp_path,
                    encryption=fitz.PDF_ENCRYPT_AES_256,
                    user_pw=self.current_password,
                    garbage=4,
                    deflate=True,
                )
            else:
                doc.save(temp_path, garbage=4, deflate=True)
            doc.close()

            shutil.move(temp_path, final_path)
            if hasattr(self, "current_password") and self.current_password:
                PDFPasswordManager.save_password(final_path, self.current_password)

            # Erfolgsmeldung für spätere Anzeige nach dem Neuladen (wie bei Texten/Bildern)
            self._success_title = self.tr("success")
            self._success_message = self.tr("redact_saved", total_redactions)
            self._success_voice_message = self.tr(
                "redact_saved_voice", total_redactions
            )
            self._show_success_dialog = True

            # Alle Redaction‑Items aus der Szene entfernen (sie werden neu geladen)
            self._cleanup_all_redactions()

            # Neuladen mit Verzögerung (wie bei Texten/Bildern)
            QTimer.singleShot(
                500,
                lambda: self._reload_pdf_after_save_with_position(
                    final_path,
                    target_page,
                    scene_pos,
                    (
                        self.current_password
                        if hasattr(self, "current_password")
                        else None
                    ),
                ),
            )

        except Exception as e:
            print(f"Fehler beim Schwärzen: {e}")
            traceback.print_exc()
            error_dialog = myUniversalDialog(
                self,
                title=self.tr("error"),
                message=f"{self.tr('redact_error')}:\n{str(e)}",
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
                text_alignment=Qt.AlignLeft,
            )
            error_dialog.exec_()

    ### ------------------------------------
    ### ZUSCHNEIDEN CROPPING
    ### ------------------------------------

    def crop_pdf(self):
        """Schneidet die PDF zu."""
        if not self.pdf_path or not os.path.exists(self.pdf_path):
            self._show_no_pdf_dialog()
            return

        dialog = CropDialog(self)
        if dialog.exec_() != QDialog.Accepted:
            self.say(self.tr("crop_cancel"))
            return

        settings = dialog.get_data()
        self.say(self.tr("crop_start"))

        try:
            # Suffix für Dateinamen
            suffix = self.tr("filename_crop_suffix")
            output_path = self.generate_custom_filename(
                suffixes=[suffix], force_new_file=True
            )

            # Crop-Thread starten
            self.crop_thread = CropPDFThread(self.pdf_path, output_path, settings)
            self.crop_thread.progress_updated.connect(self._update_crop_progress)
            self.crop_thread.finished.connect(self._on_crop_finished)

            # Fortschritts-Dialog
            self.crop_progress_dialog = QProgressDialog(
                self.tr("crop_progress"), self.tr("btn_cancel"), 0, 100, self
            )
            self.crop_progress_dialog.setWindowModality(Qt.WindowModal)
            self.crop_progress_dialog.setMinimumWidth(400)
            self.crop_progress_dialog.setStyleSheet("""
                QProgressDialog {
                    background-color: #2D2D2D;
                    color: #E0E0E0;
                }
            """)
            self.crop_progress_dialog.canceled.connect(self._cancel_crop)
            self.crop_progress_dialog.show()

            self.crop_thread.start()

        except Exception as e:
            error_msg = self.tr("crop_error_format", str(e))
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
            ).exec_()
            print(f"Fehler beim Zuschneiden: {e}")
            traceback.print_exc()

    def _update_crop_progress(self, progress, message):
        """Aktualisiert den Fortschritts-Dialog."""
        if hasattr(self, "crop_progress_dialog") and self.crop_progress_dialog:
            self.crop_progress_dialog.setValue(progress)
            if message:
                self.crop_progress_dialog.setLabelText(message)

    def _cancel_crop(self):
        """Bricht das Zuschneiden ab."""
        if hasattr(self, "crop_thread") and self.crop_thread:
            self.crop_thread.cancel()
            self.say(self.tr("crop_cancel"))

    def _on_crop_finished(self, success, message, output_path):
        """Behandelt das Ende des Zuschneidens."""
        if hasattr(self, "crop_progress_dialog") and self.crop_progress_dialog:
            self.crop_progress_dialog.close()
            self.crop_progress_dialog = None

        if success:
            success_message = self.tr("crop_success", output_path)
            confirm_dialog = myUniversalDialog(
                self,
                title=self.tr("success"),
                message=success_message,
                buttons=[
                    (self.tr("confirm_yes"), "primary", "yes"),
                    (self.tr("confirm_no"), "danger", "no"),
                ],
                icon_type="",
                voice_message=self.tr("crop_complete"),
                default_button="yes",
                text_alignment=Qt.AlignLeft,
            )
            confirm_dialog.exec_()

            if confirm_dialog.result_value == "yes":
                self.close_current_pdf()
                self.load_pdf(output_path)
        else:
            error_msg = self.tr("crop_error_format", message)
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=error_msg,
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=self.tr("error_occurred"),
                text_alignment=Qt.AlignLeft,
            ).exec_()

    ### ==============================================
    ### Aktionen im Menü Ansicht
    ### ==============================================

    ###-----------------------------
    ### DARK MODE CMD+D
    ###-----------------------------


    def toggle_dark_mode(self):
        """
        Schaltet zwischen Dark und Light Mode um - MIT POSITIONSERHALT

        Diese Version speichert nicht nur alle Overlay-Elemente, sondern auch
        die aktuelle Seite und die genaue Scroll-Position (Viewport-Mitte).

        FUNKTIONSWEISE:
        1. Speichert die aktuelle Scroll-Position (Viewport-Mitte in Scene-Koordinaten)
        2. Sichert ALLE Overlay-Elemente in self._saved_overlays
        3. Entfernt alle Qt-Objekte aus der grafischen Szene
        4. Schaltet den Dark Mode um
        5. Lädt die PDF neu
        6. Stellt alle Overlay-Elemente aus den gesicherten Daten wieder her
        7. Springt zur gespeicherten Position (Seite + Scroll-Position)

        WICHTIG FÜR DIE POSITIONSERHALT:
        - Die Viewport-Mitte wird in Scene-Koordinaten gespeichert
        - Nach dem Neuladen wird dorthin gescrollt
        - Funktioniert mit allen Zoom-Modi (page, two_pages, overview)
        - Die Position wird relativ zur Seite gespeichert (nicht absolut)
        """
        t0 = time.time()
        print("\n=== STARTE TOGGLE DARK MODE (MIT POSITIONSERHALT) ===")
        print(f"Dark Mode aktuell: {self.dark_mode}")
        print(f"Aktuelle Seite: {self.current_page + 1}")

        # ==================================================
        # SCHRITT 1: AKTUELLE POSITION SPEICHERN
        # ==================================================
        #
        # WAS WIRD GESPEICHERT?
        # - Die aktuelle Seite (current_page)
        # - Die Viewport-Mitte in Scene-Koordinaten
        # - Die relative Position auf der Seite (0..1 für X und Y)
        #
        # WARUM RELATIVE POSITION?
        # - Die Seite kann nach dem Neuladen eine andere Größe haben
        # - Durch relative Position (0..1) bleibt die Position erhalten
        # - Unabhängig von Zoom oder Seitenformat
        # ==================================================

        print("\n--- SCHRITT 1: Aktuelle Position speichern ---")

        # Aktuelle Seite merken
        saved_page = self.current_page

        # Viewport-Mitte in Scene-Koordinaten berechnen
        viewport_rect = self.graphics_view.viewport().rect()
        viewport_center = self.graphics_view.mapToScene(viewport_rect.center())

        print(f"   - Seite: {saved_page + 1}")
        print(
            f"   - Viewport-Mitte: ({viewport_center.x():.1f}, {viewport_center.y():.1f})"
        )

        # Prüfen ob die Viewport-Mitte auf einer Seite liegt
        target_page = saved_page
        relative_x = 0.5  # Default: Mitte
        relative_y = 0.5  # Default: Mitte

        if saved_page < len(self.page_items):
            page_item = self.page_items[saved_page]
            page_rect = page_item.boundingRect()
            page_pos = page_item.scenePos()

            # Relative Position auf der Seite berechnen (0..1)
            relative_x = (viewport_center.x() - page_pos.x()) / page_rect.width()
            relative_y = (viewport_center.y() - page_pos.y()) / page_rect.height()

            # Auf gültigen Bereich begrenzen (0..1)
            relative_x = max(0.0, min(1.0, relative_x))
            relative_y = max(0.0, min(1.0, relative_y))

            print(f"   - Relative Position: X={relative_x:.2f}, Y={relative_y:.2f}")
        else:
            print("   - ⚠️ Keine Seite gefunden - verwende Standardposition")

        # Position in einem Dictionary speichern
        scroll_position = {
            "page": saved_page,
            "relative_x": relative_x,
            "relative_y": relative_y,
            "scene_x": viewport_center.x(),
            "scene_y": viewport_center.y(),
        }

        # ============================================================
        # SCHRITT 2: OVERLAY-DATEN SICHERN
        # ============================================================

        print("\n--- SCHRITT 2: Overlay-Daten sichern ---")
        self._save_overlay_data()

        if self._saved_overlays:
            # Position in die Overlay-Daten einbetten
            # Wir fügen ein spezielles 'scroll' Element hinzu
            scroll_meta = {
                "type": "scroll",
                "page": scroll_position["page"],
                "relative_x": scroll_position["relative_x"],
                "relative_y": scroll_position["relative_y"],
            }

            # Das scroll-Meta als erstes Element einfügen (nach dem normalen meta)
            # Wir müssen es am Anfang einfügen, damit es beim Wiederherstellen zuerst verarbeitet wird
            if self._saved_overlays and self._saved_overlays[0].get("type") == "meta":
                # Füge scroll nach meta ein
                self._saved_overlays.insert(1, scroll_meta)
            else:
                # Fallback: am Anfang einfügen
                self._saved_overlays.insert(0, scroll_meta)

            print(f"✅ {len(self._saved_overlays)} Overlay-Elemente gesichert")
            print(
                f"   - Scroll-Position: Seite {scroll_position['page'] + 1}, "
                f"X={scroll_position['relative_x']:.2f}, Y={scroll_position['relative_y']:.2f}"
            )
        else:
            print("⚠️ Keine Overlay-Daten gesichert (nur Position wird gespeichert)")
            # Auch wenn keine Overlays vorhanden sind, speichern wir die Position
            self._saved_overlays = [
                {"type": "meta", "current_page": saved_page},
                scroll_meta,
            ]

        # =================================================
        # SCHRITT 3: ALLE ITEMS AUS DER SZENE ENTFERNEN
        # ==================================================

        print("\n--- SCHRITT 3: Items aus der Szene entfernen ---")
        self._clear_items_from_scene_only()

        # ==================================================
        # SCHRITT 4: DARK MODE UMSCHALTEN
        # ==================================================

        print("\n--- SCHRITT 4: Dark Mode umschalten ---")
        self.dark_mode = not self.dark_mode
        print(f"✅ Dark Mode neu: {'AKTIV' if self.dark_mode else 'INAKTIV'}")

        # Sichtbarkeit der Dark-Mode-spezifischen Menüs anpassen
        if hasattr(self, "invert_mode_menu"):
            self.invert_mode_menu.menuAction().setVisible(self.dark_mode)

        if self.dark_mode:
            if hasattr(self, "threshold_menu"):
                is_smart = self.invert_mode == "smart"
                self.threshold_menu.menuAction().setVisible(is_smart)
        else:
            if hasattr(self, "threshold_menu"):
                self.threshold_menu.menuAction().setVisible(False)

        # ==================================================
        # SCHRITT 5: PDF NEU LADEN
        # =================================================

        print("\n--- SCHRITT 5: PDF neu laden ---")
        current_mode = self.zoom_mode

        if hasattr(self, "pdf_path") and self.pdf_path:
            self.load_pdf()
            self.set_zoom_mode(current_mode)
            print("✅ PDF erfolgreich neu geladen")
        else:
            print("⚠️ Keine PDF geladen - Überspringe Neuladen")

        # ==================================================
        # SCHRITT 6: OVERLAYS WIEDERHERSTELLEN
        # ==================================================

        print("\n--- SCHRITT 6: Overlays wiederherstellen ---")

        if self._saved_overlays is not None and len(self._saved_overlays) > 1:
            QTimer.singleShot(200, self._restore_overlay_items)
            print("✅ Overlay-Wiederherstellung gestartet")
        else:
            if self._saved_overlays is None:
                print("⚠️ Keine Overlay-Daten vorhanden")
            else:
                print("⚠️ Nur Meta-Daten vorhanden")
            self._saved_overlays = None

        # =================================================
        # SCHRITT 7: ZUR GESPEICHERTEN POSITION SPRINGEN
        # =================================================
        #
        # WARUM VERZÖGERUNG?
        # - Die Szene muss erst vollständig geladen sein
        # - Die Overlays müssen wiederhergestellt sein
        # - Besonders wichtig für Windows Bundle
        #
        # WAS PASSIERT?
        # - Es wird zur gespeicherten Seite gesprungen
        # - Die Viewport-Mitte wird auf die gespeicherte Position gesetzt
        # - Die Position wird aus den gespeicherten relativen Koordinaten berechnet
        # ==================================================

        print("\n--- SCHRITT 7: Zur gespeicherten Position springen ---")

        # Die Position wird nach der Wiederherstellung der Overlays gesetzt
        # Dazu verwenden wir einen weiteren Timer, der nach der Overlay-Wiederherstellung läuft
        QTimer.singleShot(400, lambda: self._restore_scroll_position(scroll_position))
        print(
            f"✅ Springe zu Seite {scroll_position['page'] + 1}, "
            f"Position X={scroll_position['relative_x']:.2f}, Y={scroll_position['relative_y']:.2f}"
        )

        # ==================================================
        # SCHRITT 8: UI AKTUALISIEREN
        # ==================================================

        print("\n--- SCHRITT 8: UI aktualisieren ---")
        self.update_mode_action_text()
        self.save_app_settings()
        print("✅ UI aktualisiert")
        print("✅ Einstellungen gespeichert")

        # ==================================================
        # ABSCHLUSS
        # ==================================================

        print("\n=== TOGGLE DARK MODE ABGESCHLOSSEN ===")
        print(f"📊 Status nach Umschaltung:")
        print(f"   - Dark Mode: {'AKTIV' if self.dark_mode else 'INAKTIV'}")
        print(f"   - Aktuelle Seite: {self.current_page + 1}")
        print(f"   - Text-Modus: {self.text_mode}")
        print(f"   - Overlay-Daten erhalten: {self._saved_overlays is not None}")
        print("=" * 50 + "\n")
        print(f"[TIMING] toggle_dark_mode: {time.time() - t0:.3f}s")


    def _restore_scroll_position(self, scroll_position):
        """
        Stellt die gespeicherte Scroll-Position wieder her.

        Diese Methode wird NACH der Overlay-Wiederherstellung aufgerufen,
        um sicherzustellen, dass die Szene vollständig geladen ist.

        PARAMETER:
        - scroll_position: Dictionary mit den gespeicherten Positionsdaten
            {
                'page': int,           # Seitenindex (0-basiert)
                'relative_x': float,   # Relative X-Position (0..1)
                'relative_y': float,   # Relative Y-Position (0..1)
                'scene_x': float,      # Absolute Scene-X-Position
                'scene_y': float       # Absolute Scene-Y-Position
            }

        FUNKTIONSWEISE:
        1. Prüft ob die Seite existiert
        2. Berechnet die Zielposition in Scene-Koordinaten
        3. Scrollt zur Zielposition
        4. Aktualisiert den Seiten-Spin-Box-Wert

        RÜCKGABE:
        - True bei Erfolg, False bei Fehler
        """

        print("\n=== RESTORE SCROLL POSITION ===")

        if not scroll_position:
            print("⚠️ Keine Scroll-Position zum Wiederherstellen")
            return False

        page = scroll_position.get("page", 0)
        relative_x = scroll_position.get("relative_x", 0.5)
        relative_y = scroll_position.get("relative_y", 0.5)

        print(f"   - Ziel-Seite: {page + 1}")
        print(f"   - Relative Position: X={relative_x:.2f}, Y={relative_y:.2f}")

        # ===== 1. Prüfen ob Seite existiert =====
        if page >= len(self.page_items):
            print(
                f"⚠️ Seite {page + 1} existiert nicht (nur {len(self.page_items)} Seiten)"
            )
            return False

        # ===== 2. Zielposition in Scene-Koordinaten berechnen =====
        page_item = self.page_items[page]
        page_rect = page_item.boundingRect()
        page_pos = page_item.scenePos()

        target_x = page_pos.x() + (page_rect.width() * relative_x)
        target_y = page_pos.y() + (page_rect.height() * relative_y)

        print(f"   - Ziel-Scene-Position: ({target_x:.1f}, {target_y:.1f})")

        # ===== 3. Zur Zielposition scrollen =====
        # Verwende centerOn für sanftes Scrollen
        self.graphics_view.centerOn(target_x, target_y)

        # ===== 4. Seiten-Spin-Box aktualisieren =====
        with QSignalBlocker(self.page_spin):
            self.page_spin.setValue(page + 1)

        # ===== 5. Force Update =====
        self.graphics_view.viewport().update()
        QApplication.processEvents()

        print(f"✅ Erfolgreich zu Seite {page + 1} gesprungen")

        return True


