    def set_invert_mode(self, mode):
        if self.invert_mode == mode:
            return
        self.invert_mode = mode
        self.save_app_settings()

        # Sichtbarkeit des Threshold-Menüs: nur wenn Dark Mode an und smart
        if hasattr(self, "threshold_menu"):
            visible = self.dark_mode and mode == "smart"
            self.threshold_menu.menuAction().setVisible(visible)

        # PDF neu laden falls erforderlich
        if hasattr(self, "pdf_path") and self.pdf_path:
            self._save_overlay_data()
            self.load_pdf()

    def set_gray_threshold(self, value):
        """Setzt den Graustufen-Schwellwert und lädt PDF neu."""
        if self.gray_threshold == value:
            return

        self.gray_threshold = value
        self.save_app_settings()

        # Haken in den Menü-Aktionen aktualisieren (optional, da ActionGroup das automatisch tut)
        for action in self.threshold_actions:
            val = int(action.text().split("%")[0].strip())
            if val == value:
                action.setChecked(True)

        # PDF neu laden, falls eines geladen ist und wir im Smart-Modus sind
        if hasattr(self, "pdf_path") and self.pdf_path and self.invert_mode == "smart":
            self._save_overlay_data()
            self.load_pdf()
            self.say(self.tr("threshold_changed", value))

    def on_threshold_changed(self, index):
        """Wird aufgerufen, wenn der Benutzer einen neuen Wert aus der ComboBox wählt."""
        values = [10, 20, 30, 40, 50]
        if 0 <= index < len(values):
            self.set_gray_threshold(values[index])
            self.say(self.tr("threshold_changed", values[index]))

