    def save_app_settings(self):
        """Speichert ALLE Anwendungseinstellungen mit QSettings"""
        settings = QSettings("BinhDiez", "PDFDarkView")
        settings.setValue("voice_enabled", self.voice_enabled)
        settings.setValue("voice_speed", self.voice_speed)
        settings.setValue("dark_mode", self.dark_mode)
        settings.setValue("invert_mode", self.invert_mode)
        settings.setValue("gray_threshold", self.gray_threshold)
        settings.setValue("create_backup", self.create_backup)

        # Sprache speichern (mit Fallback)
        if hasattr(self, "lang"):
            settings.setValue("language", self.lang.get_language())
        else:
            settings.setValue("language", "de")

        settings.setValue("zoom_mode", self.zoom_mode)

        # Fenstergröße und -position
        settings.setValue("window_geometry", self.saveGeometry())
        settings.setValue("window_state", self.saveState())

        # Navigationsleiste Sichtbarkeit
        if hasattr(self, "nav_bar"):
            settings.setValue("navbar_visible", self.nav_bar.isVisible())

        settings.setValue("redact_white_mode", self.redact_white_mode)

        # Welcome-Marker NICHT speichern - wird separat verwaltet!
        # (nur zur Info: Der Welcome-Marker ist in Config.get_user_data_dir()/.welcome_shown)

        settings.sync()
        print("DEBUG: Anwendungseinstellungen gespeichert")

    def load_app_settings(self):
        """Lädt ALLE Anwendungseinstellungen aus QSettings"""
        settings = QSettings("BinhDiez", "PDFDarkView")

        # Sprachausgabe
        self.voice_enabled = settings.value("voice_enabled", True, type=bool)
        self.voice_speed = settings.value("voice_speed", 1.0, type=float)

        # Anzeige-Modi
        self.dark_mode = settings.value("dark_mode", True, type=bool)
        self.invert_mode = settings.value("invert_mode", "smart", type=str)
        self.gray_threshold = settings.value("gray_threshold", 30, type=int)
        self.create_backup = settings.value("create_backup", True, type=bool)

        # Sprache laden (falls vorhanden)
        if hasattr(self, "lang"):
            language = settings.value("language", None)
            if language and language in self.lang.available:
                self.lang.set_language(language)
                # print(f"🌍 Sprache aus Einstellungen geladen: {language}\n")
            else:
                # Falls keine Sprache gespeichert oder nicht verfügbar: Systemsprache verwenden
                # Die Language-Klasse hat bereits die Systemsprache erkannt
                current_lang = self.lang.get_language()
                print(f"🌍 Verwende Systemsprache: {current_lang}")
                # In den Einstellungen speichern für zukünftige Starts
                settings.setValue("language", current_lang)

        # Zoom-Modus laden
        self.zoom_mode = settings.value("zoom_mode", "page", type=str)

        # Fenstergröße und -position wiederherstellen
        geometry = settings.value("window_geometry")
        if geometry:
            self.restoreGeometry(geometry)
        state = settings.value("window_state")
        if state:
            self.restoreState(state)

        # Navigationsleiste Sichtbarkeit
        if hasattr(self, "nav_bar"):
            navbar_visible = settings.value("navbar_visible", True, type=bool)
            self.nav_bar.setVisible(navbar_visible)
            if hasattr(self, "toggle_navbar_action"):
                self.toggle_navbar_action.setChecked(navbar_visible)

        # Dateinamen-Einstellungen mit Defaults initialisieren (falls nicht vorhanden)
        if not settings.contains("filename/use_timestamp"):
            settings.setValue("filename/use_timestamp", True)
        if not settings.contains("filename/timestamp_format"):
            settings.setValue("filename/timestamp_format", "%Y%m%d_%H%M%S")
        if not settings.contains("filename/timestamp_position"):
            settings.setValue("filename/timestamp_position", "after")
        if not settings.contains("filename/separator"):
            settings.setValue("filename/separator", "_")

        # Schwärzen oder weiß = Radiergummi
        self.redact_white_mode = settings.value("redact_white_mode", False, type=bool)

        # print("DEBUG: Anwendungseinstellungen geladen")

    def open_signature_settings(self):
        """Öffnet den Signatur-Einstellungsdialog"""

        def show_and_save():
            """Zeigt den Dialog und speichert bei Erfolg"""
            dialog = SignatureSettingsDialog(self)
            if dialog.exec_() == QDialog.Accepted:
                # Einstellungen neu laden
                self.signature_settings = self.load_signature_settings()
                # "Signatur-Einstellungen gespeichert"
                self.say(self.tr("signature_settings_saved"))
                print("Signatur-Einstellungen aktualisiert")

        # Kein Master-PW → Frage, ob eingerichtet werden soll
        if not PDFPasswordManager.is_master_password_set():
            dialog = myUniversalDialog(
                self,
                # "Master-Passwort erforderlich"
                title=self.tr("master_password_required"),
                # "Um Signaturen verwenden zu können, müssen Sie ein Master-Passwort einrichten.\n\nMöchten Sie jetzt ein Master-Passwort einrichten?"
                message=self.tr("master_password_for_signatures"),
                buttons=[
                    # "Ja"
                    (self.tr("confirm_yes"), "primary", "yes"),
                    # "Nein"
                    (self.tr("confirm_no"), "danger", "no"),
                ],
                icon_type="",
                text_alignment=Qt.AlignLeft,
            )
            if dialog.exec_() == QDialog.Accepted and dialog.result_value == "yes":
                setup_dialog = MasterPasswordDialog(self, mode="setup")
                if setup_dialog.exec_() == QDialog.Accepted:
                    # Passwort wurde bereits im Dialog gespeichert
                    self.master_authenticated = True
                    self.open_signature_settings()
            return

        # Master-PW ist gesetzt
        if PDFPasswordManager.get_signature_auth_disabled():
            # Abfrage deaktiviert → sofort Dialog öffnen
            show_and_save()
            return

        # Abfrage aktiviert
        if self.master_authenticated:
            show_and_save()
            return

        # Authentifizierung notwendig
        auth_dialog = MasterPasswordDialog(self, mode="verify")
        if auth_dialog.exec_() == QDialog.Accepted:
            self.master_authenticated = True
            show_and_save()

