    ### EXPORT ALLER BENUTZEREINSTELLUNGEN
    ###=====================================

    def export_all_settings(self):
        """Exportiert ALLE Benutzereinstellungen"""

        # Prüfen ob Master-Passwort gesetzt ist
        has_master = PDFPasswordManager.is_master_password_set()
        master_password = None

        if has_master:
            # Wenn Master-PW gesetzt, fragen ob entschlüsselt exportiert werden soll
            msg = QMessageBox()
            msg.setIcon(QMessageBox.Question)
            msg.setWindowTitle("Passwort-Export")
            msg.setText(
                "Es ist ein Master-Passwort gesetzt.\n\n"
                "Möchten Sie die Passwörter entschlüsselt exportieren?\n"
                "(ansonsten werden sie verschlüsselt exportiert)"
            )

            btn_decrypt = msg.addButton(
                "Entschlüsselt exportieren", QMessageBox.YesRole
            )
            btn_encrypt = msg.addButton("Verschlüsselt exportieren", QMessageBox.NoRole)
            btn_cancel = msg.addButton("Abbrechen", QMessageBox.RejectRole)

            msg.exec_()

            if msg.clickedButton() == btn_cancel:
                return
            elif msg.clickedButton() == btn_decrypt:
                # Master-PW abfragen
                dialog = MasterPasswordDialog(self, mode="verify")
                if dialog.exec_() == QDialog.Accepted:
                    master_password = dialog.password
                    if not PDFPasswordManager.verify_master_auth(master_password):
                        QMessageBox.critical(
                            self, "Fehler", "Falsches Master-Passwort!"
                        )
                        return
                else:
                    return

        # Dateiauswahl-Dialog
        default_path = SettingsExporter.get_default_export_path()
        file_path, _ = QFileDialog.getSaveFileName(
            self, "Einstellungen exportieren", default_path, "ZIP Archive (*.zip)"
        )

        if not file_path:
            return

        # Export durchführen
        success, message = SettingsExporter.export_all_settings(
            file_path, master_password
        )

        if success:
            QMessageBox.information(self, "Export erfolgreich", message)
            self.say("Einstellungen wurden erfolgreich exportiert")
        else:
            QMessageBox.critical(self, "Export fehlgeschlagen", message)

    def import_all_settings(self):
        """Importiert ALLE Benutzereinstellungen aus einer ZIP-Datei"""

        # Dateiauswahl-Dialog
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "Einstellungen importieren",
            os.path.expanduser("~/Desktop"),
            "ZIP Archive (*.zip)",
        )

        if not file_path:
            return

        # Prüfen ob Master-Passwort für entschlüsselte Passwörter benötigt wird
        master_password = None

        # Master-PW abfragen falls vorhanden (optional)
        if PDFPasswordManager.is_master_password_set():
            dialog = MasterPasswordDialog(self, mode="verify")
            if dialog.exec_() == QDialog.Accepted:
                master_password = dialog.password
                if not PDFPasswordManager.verify_master_auth(master_password):
                    QMessageBox.critical(self, "Fehler", "Falsches Master-Passwort!")
                    return
            else:
                # Auch ohne Master-PW weitermachen, dann werden verschlüsselte Passwörter importiert
                pass

        # Import durchführen
        success, message = SettingsExporter.import_all_settings(
            file_path, master_password
        )

        if success:
            QMessageBox.information(self, "Import erfolgreich", message)
            self.say(
                "Einstellungen wurden erfolgreich importiert. Bitte starten Sie die Anwendung neu."
            )

            # Frage ob neu gestartet werden soll
            reply = QMessageBox.question(
                self,
                "Neustart erforderlich",
                "Möchten Sie die Anwendung jetzt neu starten?",
                QMessageBox.Yes | QMessageBox.No,
            )

            if reply == QMessageBox.Yes:
                self.safe_quit()
                # Neustart
                os.execl(sys.executable, sys.executable, *sys.argv)
        else:
            QMessageBox.critical(self, "Import fehlgeschlagen", message)

    def show_export_info(self):
        """Zeigt Informationen über den Export/Import"""

        dialog = myUniversalDialog(
            self,
            title=self.tr(
                "qsettings_export_import_title"
            ),  # "📦 Export / Import Information",
            message=self.tr("qsettings_export_import_info_html"),
            buttons=[("OK", "primary", "ok")],
            icon_type="",
            text_alignment=Qt.AlignLeft,
        )
        dialog.exec_()

