    def show_info(self):
        print("DEBUG: show_info wurde aufgerufen")  # Temporär zum Testen
        info = InfoWindow(self)
        info.exec_()

    def get_app_version_date(self):
        """Gibt das Datum der letzten Änderung dieser Datei zurück."""
        try:
            if getattr(sys, "frozen", False):
                # Build-Datum der EXE oder der App
                mtime = os.path.getmtime(sys.executable)
            else:
                # Datum der letzten Speicherung der *.py
                mtime = os.path.getmtime(__file__)

            return datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M:%S")
        except Exception as e:
            return "unknown"

    def show_version_info(self):
        """Zeigt eine MessageBox mit Versionsnummer ,, Zeitstempel der letzten PY Änderung und Copyright."""
        QMessageBox.information(
            self,
            self.tr("info_title"),
            f"{self.tr('app_title')}\n\n{self.tr('info_version')}: {APP_VERSION}\n{self.tr('info_copyright')}",
        )

