    def check_for_updates(self):
        """Startet die Hintergrund‑Prüfung (nur einmal pro Sitzung)."""
        if self._update_checked:
            return
        self._update_checked = True

        self.update_thread = UpdateCheckThread()
        self.update_thread.update_available.connect(self._show_update_dialog)
        self.update_thread.finished.connect(self.update_thread.deleteLater)
        self.update_thread.start()

    def _show_update_dialog(self, version, url):
        """Zeigt den Hinweis auf die neue Version."""
        from PyQt5.QtGui import QDesktopServices
        from PyQt5.QtCore import QUrl

        message = self.tr(
            "update_available_message", version, '<a href="{0}">{0}</a>'.format(url)
        )
        dialog = myUniversalDialog(
            self,
            title=self.tr("update_available_title"),
            message=message,
            buttons=[
                (self.tr("update_open_release"), "primary", "open", 300),
                (self.tr("btn_ok"), "success", "ok"),
            ],
            icon_type="",
            voice_message=self.tr("update_available_voice", version),
            text_alignment=Qt.AlignLeft,
            default_button="open",
        )
        dialog.exec_()
        if dialog.result_value == "open":
            QDesktopServices.openUrl(QUrl(url))

    ###===================================
    ### SEITENNAVIGATION
    ###===================================

    def scroll_to_page(self, announce=True, keep_markings=False):
        """Scrollt zur angegebenen Seite - Seitenanfang oben"""
        if not self.page_items or self.current_page >= len(self.page_items):
            return

        view = self.graphics_view
        view_height = view.viewport().height()

        try:
            item = self.page_items[self.current_page]

            if self.zoom_mode == "overview":
                # Bei Übersicht: Zur Zeile scrollen (Anfang der Zeile oben)
                COLS = 6
                row = self.current_page // COLS
                if row * COLS < len(self.page_items):
                    first_item_in_row = self.page_items[row * COLS]
                    target_pos = first_item_in_row.y() - 5  # Leichter Offset

            elif self.zoom_mode == "two_pages":
                # Bei zwei Seiten: Zur Zeile scrollen (Anfang der Zeile oben)
                row = self.current_page // 2
                if row * 2 < len(self.page_items):
                    first_item_in_row = self.page_items[row * 2]
                    target_pos = first_item_in_row.y() - 5

            else:
                # Standard: Seitenanfang oben anzeigen (nicht zentrieren)
                target_pos = item.y() - 10  # Leichter Offset vom oberen Rand

            view.verticalScrollBar().setValue(int(target_pos))

            # SpinBox aktualisieren
            with QSignalBlocker(self.page_spin):
                self.page_spin.setValue(self.current_page + 1)

            if announce:
                # "Seite {0}"
                self.say(self.tr("page_simple", self.current_page + 1))

            # Nach dem Scrollen Suchmarkierungen neu zeichnen, wenn aktiv
            if (
                keep_markings
                and hasattr(self, "search_results")
                and self.search_results
            ):
                QTimer.singleShot(50, self.draw_search_marks)

            # ===== NEU: Seiteninfo aktualisieren =====
            self.update_page_info()

        except Exception as e:
            print(f"Scroll error: {str(e)}")

    def scroll_to_page_top(self):
        """Scrollt zur aktuellen Seite mit Seitenanfang oben"""
        if not self.page_items or self.current_page >= len(self.page_items):
            return

        try:
            item = self.page_items[self.current_page]
            target_pos = item.y() - 10  # Seitenanfang oben mit leichtem Offset

            self.graphics_view.verticalScrollBar().setValue(int(target_pos))

            # SpinBox aktualisieren
            with QSignalBlocker(self.page_spin):
                self.page_spin.setValue(self.current_page + 1)

        except Exception as e:
            print(f"Scroll top error: {str(e)}")

    def _actual_scroll_to_page(self, announce=True):
        """Tatsächliche Scroll-Implementierung"""
        if not self.page_items or self.current_page >= len(self.page_items):
            return

        view = self.graphics_view
        view_height = view.viewport().height()

        try:
            item = self.page_items[self.current_page]

            if self.zoom_mode == "overview":
                # Bei Übersicht: Zur Zeile scrollen
                COLS = 6
                row = self.current_page // COLS
                target_pos = row * (item.boundingRect().height() + 15)

            elif self.zoom_mode == "two_pages":
                # Bei zwei Seiten: Zur Zeile scrollen
                row = self.current_page // 2
                target_pos = row * (item.boundingRect().height() + 20)

            else:
                # Standard: Seite zentrieren
                target_pos = (
                    item.y() - (view_height / 2) + (item.boundingRect().height() / 2)
                )

            view.verticalScrollBar().setValue(int(target_pos))

            # SpinBox aktualisieren
            with QSignalBlocker(self.page_spin):
                self.page_spin.setValue(self.current_page + 1)

            if announce:
                self.say(f"Seite {self.current_page + 1}")

        except Exception as e:
            print(f"Scroll error: {str(e)}")

    def handle_scroll(self):
        """Ermittelt die aktuelle Seite basierend auf Scroll-Position - für Übersicht optimiert"""
        if not self.page_items:
            return

        scroll_bar = self.graphics_view.verticalScrollBar()
        scroll_pos = scroll_bar.value()
        view_height = self.graphics_view.viewport().height()

        old_page = self.current_page

        if self.zoom_mode == "overview":
            # Spezielle Logik für Übersichtsmodus
            COLS = 6
            new_page = self.current_page

            for i, item in enumerate(self.page_items):
                item_top = item.y()
                item_bottom = item_top + item.boundingRect().height()

                # Seite gilt als sichtbar wenn ihr oberer Rand im oberen Viertel ist
                if item_top <= scroll_pos + (view_height / 4) <= item_bottom:
                    new_page = i
                    break

            if new_page != self.current_page:
                self.current_page = new_page
                with QSignalBlocker(self.page_spin):
                    self.page_spin.setValue(self.current_page + 1)

        else:
            # Normale Logik für andere Modi
            new_page = self.current_page

            for i, item in enumerate(self.page_items):
                item_top = item.y()
                item_bottom = item_top + item.boundingRect().height()

                if (
                    item_bottom > scroll_pos
                    and item_top < scroll_pos + view_height
                    and (item_bottom - scroll_pos) > (view_height * 0.3)
                ):

                    new_page = i
                    break

            if new_page != self.current_page:
                self.current_page = new_page
                with QSignalBlocker(self.page_spin):
                    self.page_spin.setValue(self.current_page + 1)

        # Wenn Seite gewechselt hat und Suche aktiv ist, Markierungen neu zeichnen
        if (
            old_page != self.current_page
            and hasattr(self, "search_results")
            and self.search_results
        ):
            QTimer.singleShot(100, self.draw_search_marks)

    def first_page(self):
        if hasattr(self, "total_pages") and self.total_pages > 0:
            self.current_page = 0
            self.page_spin.setValue(1)
            self.scroll_to_page(announce=False)
            self.say(self.tr("page_of", 1, self.total_pages), convert_numbers=True)

    def prev_page(self):
        if hasattr(self, "current_page") and self.current_page > 0:
            self.current_page -= 1
            self.page_spin.setValue(self.current_page + 1)
            self.scroll_to_page(announce=False)
            self.say(
                self.tr("page_of", self.current_page + 1, self.total_pages),
                convert_numbers=True,
            )

    def next_page(self):
        if (
            hasattr(self, "current_page")
            and hasattr(self, "total_pages")
            and self.current_page < self.total_pages - 1
        ):
            self.current_page += 1
            self.page_spin.setValue(self.current_page + 1)
            self.scroll_to_page(announce=False)
            self.say(
                self.tr("page_of", self.current_page + 1, self.total_pages),
                convert_numbers=True,
            )

    def last_page(self):
        if hasattr(self, "total_pages") and self.total_pages > 0:
            self.current_page = self.total_pages - 1
            self.page_spin.setValue(self.total_pages)
            self.scroll_to_page(announce=False)
            self.say(
                self.tr("page_of", self.total_pages, self.total_pages),
                convert_numbers=True,
            )

    def go_to_page(self, page_num):
        """Springt direkt zur angegebenen Seite - ERWEITERT für Signatur-Sichtbarkeit"""
        if not hasattr(self, "total_pages") or not self.total_pages:
            return

        # Seite ist 1-basiert in der SpinBox, 0-basiert intern
        target_page = page_num - 1

        if 0 <= target_page < self.total_pages and target_page != self.current_page:
            print(
                f"DEBUG: Wechsle zu Seite {target_page + 1} (vorher: {self.current_page + 1})"
            )

            self.current_page = target_page
            self.scroll_to_page(announce=False)

            # Signatur-Sichtbarkeit aktualisieren
            self._update_signature_visibility()

    ###---------------------------------------
    ### RECHTSKLICK - MENÜ Fild
    ###---------------------------------------
    # # mit QtAwesome Icons
    def show_context_menu(self, position):
        """Zeigt Kontextmenü für Seitenoperationen mit Übersetzungen"""
        view = self.graphics_view
        scene_pos = view.mapToScene(position)

        if not self.page_items:
            return

        # ===========================================
        # --- Seite und lokale Position ermitteln ---
        # ===========================================
        if self.zoom_mode == "page" and self.current_page < len(self.page_items):
            page_item = self.page_items[self.current_page]
            local_pos = page_item.mapFromScene(scene_pos)
            clicked_page = self.current_page
        else:
            clicked_page = None
            for i, item in enumerate(self.page_items):
                if item.contains(scene_pos - item.pos()):
                    clicked_page = i
                    page_item = item
                    local_pos = page_item.mapFromScene(scene_pos)
                    break
            if clicked_page is None:
                return
        self.context_page = clicked_page

        # ==================================================================
        # --- Items an der Mausposition erkennen (UNIVERSELLE ERKENNUNG) ---
        # ==================================================================
        items_at_pos = self.scene.items(scene_pos)

        # Dictionary für alle erkannten Item-Typen
        clicked_items = {
            "text": None,
            "cross": None,
            "image": None,
            "signature": None,
            "form": None,
            "redaction": None,
        }

        # Hilfsfunktionen für bessere Lesbarkeit
        def is_text_item(item):
            return item.__class__.__name__ == "CustomTextItem" or isinstance(
                item, CustomTextItem
            )

        def is_cross_item(item):
            return (
                item.__class__.__name__ == "CrossGraphicsItem"
                or isinstance(item, CrossGraphicsItem)
                or (hasattr(item, "item_type") and item.item_type == "cross")
            )

        def is_image_item(item):
            return (
                hasattr(item, "pixmap")
                and callable(item.pixmap)
                or hasattr(item, "setPixmap")
                or item.__class__.__name__ == "QGraphicsPixmapItem"
            )

        def is_signature_item(item):
            return item.__class__.__name__ == "SignatureItem" or isinstance(
                item, SignatureItem
            )

        def is_form_item(item):
            return (
                hasattr(item, "item_type")
                and item.item_type in ["rectangle", "ellipse", "line", "arrow"]
            ) or (
                hasattr(item, "pen")
                and hasattr(item, "brush")
                and hasattr(item, "setPos")
            )

        def is_redaction_item(item):
            return item.__class__.__name__ == "RedactionItem" or isinstance(
                item, RedactionItem
            )

        # Items erkennen
        for item in items_at_pos:
            if is_cross_item(item) and not clicked_items["cross"]:
                clicked_items["cross"] = item
            elif is_text_item(item) and not clicked_items["text"]:
                clicked_items["text"] = item
            elif is_image_item(item) and not clicked_items["image"]:
                clicked_items["image"] = item
            elif is_signature_item(item) and not clicked_items["signature"]:
                clicked_items["signature"] = item
            elif is_form_item(item) and not clicked_items["form"]:
                clicked_items["form"] = item
            elif is_redaction_item(item) and not clicked_items["redaction"]:  # neu
                clicked_items["redaction"] = item

        menu = QMenu(self)

        # ============================================================
        # PRIORITÄT 1: AKTIVE MODI (diese 4 blenden ALLES andere aus)
        # ============================================================

        # --------------------------------------------------------------------
        # TEXT-MODUS AKTIV (CustomTextItem ODER CrossGraphicsItem)
        # --------------------------------------------------------------------
        if self.text_mode:
            # Bestimme, ob es ein Kreuz oder Text ist
            target_item = (
                clicked_items["cross"]
                or clicked_items["text"]
                or self.current_text_item
            )
            is_cross = is_cross_item(target_item) if target_item else False

            # --- Anzahl der Elemente ermitteln ---
            text_count = sum(1 for item in self.all_text_items if is_text_item(item))
            cross_count = sum(1 for item in self.all_text_items if is_cross_item(item))
            total_count = len(self.all_text_items)

            # --- Neuen Text einfügen ---
            # "Neuen Text einfügen"
            insert_new_action = menu.addAction(
                qta.icon("fa5s.font"), self.tr("insert_another_text")
            )
            insert_new_action.triggered.connect(
                lambda: self.open_text_template_dialog(local_pos, clicked_page)
            )
            menu.addSeparator()

            # --- Neues Kreuz einfügen ---
            # "Neues Kreuz einfügen"
            x_action = menu.addAction(
                qta.icon("fa5s.times"), self.tr("insert_another_cross")
            )
            x_action.triggered.connect(
                lambda: self._insert_cross_at_position(
                    local_pos, clicked_page, rotation_checked=False
                )
            )
            menu.addSeparator()

            # --- Anpassen des aktuellen Elements ---
            if target_item:
                if is_cross:
                    # "Dieses Kreuz anpassen"
                    settings_action = menu.addAction(
                        qta.icon("fa5s.wrench"), self.tr("cross_customize")
                    )
                    settings_action.triggered.connect(
                        lambda: self._open_cross_customize_dialog(target_item)
                    )

                    # Alle Kreuze anpassen (nur anzeigen wenn mehrere Kreuze existieren)
                    if cross_count > 1:
                        # "Alle {0} Kreuze anpassen"
                        settings_all_action = menu.addAction(
                            qta.icon("fa5s.wrench"),
                            self.tr("cross_customize_all", cross_count),
                        )
                        settings_all_action.triggered.connect(
                            lambda: self._open_cross_customize_dialog_for_all()
                        )
                else:
                    # "Diesen Text anpassen"
                    settings_action = menu.addAction(
                        qta.icon("fa5s.edit"), self.tr("text_customize")
                    )
                    settings_action.triggered.connect(
                        self._open_text_customize_with_template_dialog
                    )
                menu.addSeparator()

            # --- Kopieren ---
            if target_item:
                # "Kopieren (Cmd+C)"
                copy_action = menu.addAction(qta.icon("fa5s.copy"), self.tr("copy"))
                copy_action.triggered.connect(
                    lambda checked, item=target_item: self._copy_text_item(item)
                )
                menu.addSeparator()

            # --- Einfügen (nur wenn kopierte Daten vorhanden) ---
            if self.copied_text_data is not None:
                # "Einfügen (Cmd+V)"
                paste_action = menu.addAction(qta.icon("fa5s.paste"), self.tr("paste"))
                paste_action.triggered.connect(
                    lambda: self._paste_from_context(local_pos, clicked_page)
                )
                menu.addSeparator()

            # --- Verwerfen des aktuellen Elements ---
            if target_item:
                if is_cross:
                    # "Dieses Kreuz verwerfen"
                    discard_action = menu.addAction(
                        qta.icon("fa5s.times", color="red"), self.tr("cross_discard")
                    )
                    discard_action.triggered.connect(
                        lambda: self._remove_cross_item(target_item)
                    )
                else:
                    # "Diesen Text verwerfen"
                    discard_action = menu.addAction(
                        qta.icon("fa5s.times", color="red"), self.tr("text_discard")
                    )
                    discard_action.triggered.connect(
                        lambda: self._cleanup_text_mode(speak=True)
                    )
                menu.addSeparator()

            # --- ALLE Elemente verwerfen (DYNAMISCH) ---
            if total_count > 1:
                if text_count > 0 and cross_count > 0:
                    # Gemischt: Texte und Kreuze
                    text_word = self.tr(
                        "text_word_plural" if text_count != 1 else "text_word_singular"
                    )
                    cross_word = self.tr(
                        "cross_word_plural"
                        if cross_count != 1
                        else "cross_word_singular"
                    )
                    # "Alle {0} {1} und {2} {3} verwerfen"
                    discard_all_text = self.tr(
                        "discard_mixed", text_count, text_word, cross_count, cross_word
                    )
                elif text_count > 1:
                    # "Alle {0} Texte verwerfen"
                    discard_all_text = self.tr("discard_texts", text_count)
                elif text_count == 1:
                    # "1 Text verwerfen"
                    discard_all_text = self.tr("discard_text_single")
                elif cross_count > 1:
                    # "Alle {0} Kreuze verwerfen"
                    discard_all_text = self.tr("discard_crosses", cross_count)
                elif cross_count == 1:
                    # "1 Kreuz verwerfen"
                    discard_all_text = self.tr("discard_cross_single")

                redact_count = len(self.all_redaction_items)
                if redact_count > 1:
                    text = self.tr("discard_redactions", redact_count)
                else:
                    text = self.tr("redact_discard_all")  # oder Singular
                discard_all_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"), text
                )

                discard_all_action.triggered.connect(self._remove_all_texts)
                menu.addSeparator()

            # --- ALLE Elemente speichern (DYNAMISCH) ---
            if self.all_text_items:
                if text_count > 0 and cross_count > 0:
                    text_word = self.tr(
                        "text_word_plural" if text_count != 1 else "text_word_singular"
                    )
                    cross_word = self.tr(
                        "cross_word_plural"
                        if cross_count != 1
                        else "cross_word_singular"
                    )
                    # "{0} {1} und {2} {3} speichern"
                    save_text = self.tr(
                        "save_mixed", text_count, text_word, cross_count, cross_word
                    )
                elif text_count > 1:
                    # "{0} Texte speichern"
                    save_text = self.tr("save_texts", text_count)
                elif text_count == 1:
                    # "1 Text speichern"
                    save_text = self.tr("save_text_single")
                elif cross_count > 1:
                    # "{0} Kreuze speichern"
                    save_text = self.tr("save_crosses", cross_count)
                elif cross_count == 1:
                    # "1 Kreuz speichern"
                    save_text = self.tr("save_cross_single")

                save_action = menu.addAction(qta.icon("fa5s.save"), save_text)
                save_action.triggered.connect(self._save_all_texts_and_crosses)

            menu.exec_(view.mapToGlobal(position))
            return

        # --------------------------------------------------------------------
        # SIGNATUR-MODUS AKTIV
        # --------------------------------------------------------------------
        elif self.signature_mode:
            # Neue Signatur einfügen
            # "Neu einfügen"
            insert_submenu = menu.addMenu(
                qta.icon("fa5s.pen"), self.tr("insert_another")
            )
            # "Signatur 1"
            sig1_action = insert_submenu.addAction(
                qta.icon("fa5s.signature"), self.tr("insert_another_signature_1")
            )
            sig1_action.triggered.connect(
                lambda: self._insert_another_signature(1, local_pos, clicked_page)
            )
            # "Signatur 2"
            sig2_action = insert_submenu.addAction(
                qta.icon("fa5s.signature"), self.tr("insert_another_signature_2")
            )
            sig2_action.triggered.connect(
                lambda: self._insert_another_signature(2, local_pos, clicked_page)
            )
            menu.addSeparator()

            # Angeklickte Signatur erkennen
            clicked_sig = clicked_items["signature"] or self.current_signature_item

            if clicked_sig:
                # Anpassen
                # "Signatur anpassen"
                settings_action = menu.addAction(
                    qta.icon("fa5s.wrench"), self.tr("signature_customize")
                )
                settings_action.triggered.connect(
                    lambda checked, sig=clicked_sig: self._open_signature_customize_for_item(
                        sig
                    )
                )
                menu.addSeparator()

                # Kopieren
                # "Kopieren (Cmd+C)"
                copy_action = menu.addAction(qta.icon("fa5s.copy"), self.tr("copy"))
                copy_action.triggered.connect(
                    lambda checked, sig=clicked_sig: self._copy_signature_item(sig)
                )
                menu.addSeparator()

                # Löschen
                # "Diese Signatur verwerfen"
                delete_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"), self.tr("signature_discard")
                )
                delete_action.triggered.connect(
                    lambda checked, sig=clicked_sig: self._remove_signature_item(sig)
                )
                menu.addSeparator()

            # --- Einfügen (wenn kopierte Signatur-Daten vorhanden) ---
            if (
                hasattr(self, "copied_signature_data")
                and self.copied_signature_data is not None
            ):
                # "Einfügen (Cmd+V)"
                paste_action = menu.addAction(qta.icon("fa5s.paste"), self.tr("paste"))
                paste_action.triggered.connect(
                    lambda: self._paste_from_context(local_pos, clicked_page)
                )
                menu.addSeparator()

            signature_count = len(self.all_signature_items)

            # --- Sammelaktionen (nur anzeigen wenn mehrere Signaturen vorhanden) ---
            if signature_count > 1:
                # "Alle {0} Signaturen verwerfen"
                discard_all_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"),
                    self.tr("discard_signatures", signature_count),
                )
                discard_all_action.triggered.connect(self._cleanup_all_signatures)
                menu.addSeparator()

            if self.all_signature_items:
                if signature_count == 1:
                    # "1 Signatur speichern"
                    save_text = self.tr("save_signature_single")
                else:
                    # "{0} Signaturen speichern"
                    save_text = self.tr("save_signatures", signature_count)
                save_all_action = menu.addAction(qta.icon("fa5s.save"), save_text)
                save_all_action.triggered.connect(self._save_all_signatures)

            menu.exec_(view.mapToGlobal(position))
            return

        # --------------------------------------------------------------------
        # BILD-MODUS AKTIV
        # --------------------------------------------------------------------
        elif self.image_mode:
            # Neues Bild einfügen
            # "Neu einfügen"
            insert_action = menu.addAction(
                qta.icon("fa5s.image"), self.tr("insert_another")
            )
            insert_action.triggered.connect(
                lambda: self._insert_another_image(local_pos, clicked_page)
            )
            menu.addSeparator()

            # Angeklicktes Bild erkennen
            clicked_img = clicked_items["image"] or self.current_image_item

            if clicked_img:
                # "Bild anpassen"
                if hasattr(clicked_img, "original_path"):
                    settings_action = menu.addAction(
                        qta.icon("fa5s.wrench"), self.tr("image_customize")
                    )
                    settings_action.triggered.connect(
                        lambda checked, img=clicked_img: self._open_image_customize_for_item(
                            img
                        )
                    )
                    menu.addSeparator()

                # Seitenverhältnis umschalten
                if hasattr(clicked_img, "aspect_ratio_mode"):
                    # "Seitenverhältnis beibehalten"
                    aspect_text = self.tr("image_aspect")
                    icon = (
                        "fa5s.lock" if clicked_img.aspect_ratio_mode else "fa5s.unlock"
                    )
                    aspect_action = menu.addAction(qta.icon(icon), f" {aspect_text}")
                    aspect_action.triggered.connect(self._toggle_aspect_ratio)
                    menu.addSeparator()

                # Kopieren
                # "Kopieren (Cmd+C)"
                copy_action = menu.addAction(qta.icon("fa5s.copy"), self.tr("copy"))
                copy_action.triggered.connect(
                    lambda checked, img=clicked_img: self._copy_image_item(img)
                )
                menu.addSeparator()

                # Löschen
                # "Dieses Bild verwerfen"
                delete_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"), self.tr("image_discard")
                )
                delete_action.triggered.connect(
                    lambda checked, img=clicked_img: self._remove_image_item(img)
                )
                menu.addSeparator()

            # Einfügen (wenn kopierte Bild-Daten vorhanden)
            if self.copied_image_data is not None:
                # "Einfügen (Cmd+V)"
                paste_action = menu.addAction(qta.icon("fa5s.paste"), self.tr("paste"))
                paste_action.triggered.connect(
                    lambda: self._paste_from_context(local_pos, clicked_page)
                )
                menu.addSeparator()

            image_count = len(self.all_image_items)

            # --- Sammelaktionen (nur anzeigen wenn mehrere Bilder vorhanden) ---
            if image_count > 1:
                # "Alle {0} Bilder verwerfen"
                discard_all_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"),
                    self.tr("discard_images", image_count),
                )
                discard_all_action.triggered.connect(self._cleanup_all_images)
                menu.addSeparator()

            if self.all_image_items:
                if image_count == 1:
                    # "1 Bild speichern"
                    save_text = self.tr("save_image_single")
                else:
                    # "{0} Bilder speichern"
                    save_text = self.tr("save_images", image_count)
                save_all_action = menu.addAction(qta.icon("fa5s.save"), save_text)
                save_all_action.triggered.connect(self._save_all_images)

            menu.exec_(view.mapToGlobal(position))
            return

        # --------------------------------------------------------------------
        # FORM-MODUS AKTIV
        # --------------------------------------------------------------------
        elif self.form_mode:
            # Untermenü für neue Form
            # "Neu einfügen"
            insert_submenu = menu.addMenu(
                qta.icon("fa5s.shapes"), self.tr("insert_another")
            )
            # "Rechteck"
            rect_action = insert_submenu.addAction(
                qta.icon("fa5s.square"), self.tr("insert_another_form_rect")
            )
            rect_action.triggered.connect(
                lambda: self._insert_another_form("rectangle", local_pos, clicked_page)
            )
            # "Ellipse"
            ellipse_action = insert_submenu.addAction(
                qta.icon("fa5s.circle"), self.tr("insert_another_form_ellipse")
            )
            ellipse_action.triggered.connect(
                lambda: self._insert_another_form("ellipse", local_pos, clicked_page)
            )
            insert_submenu.addSeparator()

            # "Linie (2 Klicks)"
            line_action = insert_submenu.addAction(
                qta.icon("fa5s.minus"), self.tr("insert_another_form_line")
            )
            line_action.triggered.connect(
                lambda: self._insert_another_form("line", local_pos, clicked_page)
            )

            # "Pfeil (2 Klicks)"
            arrow_action = insert_submenu.addAction(
                qta.icon("fa5s.long-arrow-alt-right"),
                self.tr("insert_another_form_arrow"),
            )
            arrow_action.triggered.connect(
                lambda: self._insert_another_form("arrow", local_pos, clicked_page)
            )
            insert_submenu.addSeparator()

            # " Einstellungen..." - ALLGEMEINE EINSTELLUNGEN (ohne Form-Item)
            form_settings_action = insert_submenu.addAction(
                qta.icon("fa5s.cog"), self.tr("form_settings")
            )
            form_settings_action.triggered.connect(self.open_form_settings)

            menu.addSeparator()

            # Angeklickte Form erkennen
            clicked_form = clicked_items["form"] or self.current_form_item

            if clicked_form:
                # Form anpassen
                # "Form anpassen"
                settings_action = menu.addAction(
                    qta.icon("fa5s.wrench"), self.tr("form_customize")
                )
                settings_action.triggered.connect(
                    lambda checked, f=clicked_form: self._open_form_customize_for_current_item(
                        f
                    )
                )
                menu.addSeparator()

                # Transparenz umschalten
                if hasattr(clicked_form, "transparent_bg"):
                    # "Transparenter Hintergrund"
                    trans_action = menu.addAction(
                        qta.icon(
                            "fa5s.eye"
                            if clicked_form.transparent_bg
                            else "fa5s.eye-slash"
                        ),
                        self.tr("form_transparent_toggle"),
                    )
                    trans_action.triggered.connect(
                        lambda checked, f=clicked_form: self._toggle_form_transparency_for_current_item(
                            f
                        )
                    )
                    menu.addSeparator()

                # Kopieren
                # "Kopieren (Cmd+C)"
                copy_action = menu.addAction(qta.icon("fa5s.copy"), self.tr("copy"))
                copy_action.triggered.connect(
                    lambda checked, f=clicked_form: self._copy_form_item(f)
                )
                menu.addSeparator()

                # Löschen
                # "Diese Form verwerfen"
                delete_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"), self.tr("form_discard")
                )
                delete_action.triggered.connect(
                    lambda checked, f=clicked_form: self._remove_form_item(f)
                )
                menu.addSeparator()

            # Einfügen (wenn kopierte Form-Daten vorhanden)
            if self.copied_form_data is not None:
                # "Einfügen (Cmd+V)"
                paste_action = menu.addAction(qta.icon("fa5s.paste"), self.tr("paste"))
                paste_action.triggered.connect(
                    lambda: self._paste_from_context(local_pos, clicked_page)
                )
                menu.addSeparator()

            form_count = len(self.all_form_items)

            # --- Sammelaktionen (nur anzeigen wenn mehrere Formen vorhanden) ---
            if form_count > 1:
                # "Alle {0} Formen verwerfen"
                discard_all_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"),
                    self.tr("discard_forms", form_count),
                )
                discard_all_action.triggered.connect(self._cleanup_all_forms)
                menu.addSeparator()

            if self.all_form_items:
                if form_count == 1:
                    # "1 Form speichern"
                    save_text = self.tr("save_form_single")
                else:
                    # "{0} Formen speichern"
                    save_text = self.tr("save_forms", form_count)
                save_all_action = menu.addAction(qta.icon("fa5s.save"), save_text)
                save_all_action.triggered.connect(self._save_all_forms)

            menu.exec_(view.mapToGlobal(position))
            return

        # --------------------------------------------------------------------
        # REDACTION-MODUS AKTIV
        # --------------------------------------------------------------------
        elif self.redaction_mode:
            # "Neue Auslöschung (schwarz)"
            new_black = menu.addAction(
                qta.icon("fa5s.eraser"), self.tr("redact_add_black")
            )
            new_black.triggered.connect(
                lambda: self._add_redaction_rect_at_position(
                    local_pos, clicked_page, "black"
                )
            )

            # "Neue Auslöschung (weiß)"
            new_white = menu.addAction(
                qta.icon("fa5s.eraser"), self.tr("redact_add_white")
            )
            new_white.triggered.connect(
                lambda: self._add_redaction_rect_at_position(
                    local_pos, clicked_page, "white"
                )
            )
            menu.addSeparator()

            # Angeklicktes Redaction-Item ermitteln
            clicked_redact = clicked_items["redaction"] or self.current_redaction_item

            if clicked_redact:
                # "Diese Schwärzung verwerfen"
                delete_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"), self.tr("redact_discard")
                )
                delete_action.triggered.connect(
                    lambda checked, r=clicked_redact: self._remove_redaction_item(r)
                )
                menu.addSeparator()

                # Kopieren
                copy_action = menu.addAction(qta.icon("fa5s.copy"), self.tr("copy"))
                copy_action.triggered.connect(
                    lambda checked, r=clicked_redact: self._copy_redaction_item(r)
                )
                menu.addSeparator()

            # Einfügen (wenn kopierte Redaction-Daten vorhanden)
            if (
                hasattr(self, "copied_redaction_data")
                and self.copied_redaction_data is not None
            ):
                paste_action = menu.addAction(qta.icon("fa5s.paste"), self.tr("paste"))
                paste_action.triggered.connect(
                    lambda: self._paste_from_context(local_pos, clicked_page)
                )
                menu.addSeparator()

            redact_count = len(self.all_redaction_items)

            # "Alle Schwärzungen verwerfen" (nur wenn mehrere)
            if redact_count > 1:
                discard_all_action = menu.addAction(
                    qta.icon("fa5s.times", color="red"), self.tr("redact_discard_all")
                )
                discard_all_action.triggered.connect(self._cleanup_all_redactions)
                menu.addSeparator()

            # "Alle Schwärzungen anwenden und speichern"
            apply_action = menu.addAction(
                qta.icon("fa5s.check"), self.tr("redact_apply_all")
            )
            apply_action.triggered.connect(self._apply_all_redactions_and_save)

            menu.exec_(view.mapToGlobal(position))
            return

        # -----------------------------------
        # ZOOM-MODUS AKTIV - NAVIGATION
        # -----------------------------------
        if not self.zoom_mode == "page":
            # " Zu Seite {0} springen"
            goto_action = menu.addAction(
                qta.icon("fa5s.search"), self.tr("context_goto_page", clicked_page + 1)
            )
            goto_action.triggered.connect(
                lambda: self.goto_page_full_view(clicked_page)
            )
            menu.addSeparator()

        # ================================================================
        # PRIORITÄT 2: VOLLES MENÜ (KEIN AKTIVER MODUS)
        # ================================================================

        # -----------------------------------
        # LESEZEICHEN (UNTERMENÜ) ---
        # -----------------------------------

        bookmarks = self.load_current_bookmarks()

        # Lesezeichen-Menü
        bookmark_menu = menu.addMenu(
            qta.icon("fa5s.bookmark"), self.tr("context_bookmarks")
        )

        # Lesezeichen für aktuelle Seite hinzufügen
        add_bm_action = bookmark_menu.addAction(
            qta.icon("fa5s.plus"), self.tr("context_bookmark_add_here")
        )
        add_bm_action.triggered.connect(
            lambda: self.add_bookmark_current_page_with_name(clicked_page, local_pos)
        )

        bookmark_menu.addSeparator()

        if bookmarks:
            # Überschrift für vorhandene Lesezeichen
            header_action = bookmark_menu.addAction(self.tr("context_bookmarks_jump"))
            header_action.setEnabled(False)

            for i, bm in enumerate(bookmarks[:20]):
                page_num = bm.get("page", 0) + 1
                name = bm.get("name", self.tr("bookmark_name_default", page_num))

                # Name für die Menüanzeige kürzen (max. 35 Zeichen für Kontextmenü)
                display_name = name[:32] + "..." if len(name) > 35 else name

                # Direkter Sprung zum Lesezeichen
                bookmark_action = bookmark_menu.addAction(
                    qta.icon("fa5s.bookmark"),
                    f"{self.tr('bookmark_page_display', page_num)}: {display_name}",
                )
                bookmark_action.triggered.connect(
                    lambda checked, b=bm: self.jump_to_bookmark_from_context(b)
                )

            bookmark_menu.addSeparator()

            # Lesezeichen verwalten (öffnet den Manager)
            manage_action = bookmark_menu.addAction(
                qta.icon("fa5s.list"), self.tr("bookmark_manage")
            )
            manage_action.triggered.connect(self.open_bookmark_manager)

        else:
            # Keine Lesezeichen vorhanden
            no_bm_action = bookmark_menu.addAction(self.tr("context_bookmarks_none"))
            no_bm_action.setEnabled(False)

            bookmark_menu.addSeparator()
            manage_action = bookmark_menu.addAction(
                qta.icon("fa5s.list"), self.tr("bookmark_manage")
            )
            manage_action.triggered.connect(self.open_bookmark_manager)

        menu.addSeparator()

        # -----------------------------------
        # SEITENOPERATIONEN (Hauptaktionen) ---
        # -----------------------------------
        # " Seite {0} drehen"
        rotate_action = menu.addAction(
            qta.icon("fa5s.undo-alt"), self.tr("context_rotate", clicked_page + 1)
        )
        rotate_action.triggered.connect(lambda: self.rotate_page(clicked_page))

        # " Seite {0} löschen"
        delete_action = menu.addAction(
            qta.icon("fa5s.times", color="red"),
            self.tr("context_delete", clicked_page + 1),
        )
        delete_action.triggered.connect(lambda: self.delete_page(clicked_page))

        # " Seite {0} exportieren"
        export_action = menu.addAction(
            qta.icon("fa5s.file-export"), self.tr("context_export", clicked_page + 1)
        )
        export_action.triggered.connect(self.export_current_page_auto)
        menu.addSeparator()

        # -----------------------------------
        # MARKIERUNGEN (als Untermenü) ---
        # -----------------------------------
        # " Seite markieren als..."
        mark_menu = menu.addMenu(qta.icon("fa5s.tag"), self.tr("context_mark_as"))

        # als leer markieren = zum Löschen vormerken
        if clicked_page in self.empty_pages:
            # " Nicht mehr leer"
            empty_action = mark_menu.addAction(
                qta.icon("fa5s.check"), self.tr("context_unmark_empty")
            )
        else:
            # " Leere Seite"
            empty_action = mark_menu.addAction(
                qta.icon("fa5s.file"), self.tr("context_mark_empty")
            )
        empty_action.triggered.connect(lambda: self.mark_page_empty(clicked_page))

        # zum Export vormerken
        if clicked_page in self.export_pages:
            # " Nicht mehr exportieren"
            export_mark_action = mark_menu.addAction(
                qta.icon("fa5s.check"), self.tr("context_unmark_export")
            )
        else:
            # " Für Export markieren"
            export_mark_action = mark_menu.addAction(
                qta.icon("fa5s.file-export"), self.tr("context_mark_export")
            )
        export_mark_action.triggered.connect(
            lambda: self.mark_page_export(clicked_page)
        )
        menu.addSeparator()

        # -----------------------------------------------------
        # SAMMELAKTIONEN (nur wenn relevant und mehr als 1) ---
        # -----------------------------------------------------
        has_batch_actions = False
        batch_menu = None

        if (self.empty_pages and len(self.empty_pages) > 1) or (
            self.export_pages and len(self.export_pages) > 1
        ):
            # " Sammelaktionen"
            batch_menu = menu.addMenu(
                qta.icon("fa5s.bolt"), self.tr("context_batch_actions")
            )
            has_batch_actions = True

        if self.empty_pages and len(self.empty_pages) > 1:
            # " Alle {0} leeren Seiten löschen"
            batch_menu.addAction(
                qta.icon("fa5s.trash", color="red"),
                self.tr("context_batch_delete_empty", len(self.empty_pages)),
                self.delete_all_empty_pages,
            )

        if self.export_pages and len(self.export_pages) > 1:
            # " Alle {0} Seiten (eine Datei)"
            batch_menu.addAction(
                qta.icon("fa5s.file-pdf"),
                self.tr("context_batch_export_single", len(self.export_pages)),
                self.export_marked_pages_auto,
            )
            # " Alle {0} Seiten (getrennt)"
            batch_menu.addAction(
                qta.icon("fa5s.copy"),  # 'fa5s.files' existiert nicht
                self.tr("context_batch_export_split", len(self.export_pages)),
                self.export_marked_pages_auto_split,
            )

        if has_batch_actions:
            menu.addSeparator()

        # --------------------------------------------
        # DRAG & DROP (nur im Zoom Mode Übersicht) ---
        # --------------------------------------------
        if self.zoom_mode == "overview":
            if self.drag_enabled:
                # " Drag & Drop beenden"
                drag_action = menu.addAction(
                    qta.icon("fa5s.hand-paper"), self.tr("context_drag_stop")
                )
            else:
                # " Drag & Drop starten"
                drag_action = menu.addAction(
                    qta.icon("fa5s.hand-rock"), self.tr("context_drag_start")
                )
            drag_action.triggered.connect(self._toggle_drag_mode_from_menu)
            menu.addSeparator()

        # ----------------------------------------------------
        # EINFÜGEN (immer verfügbar wenn kein Modus aktiv) ---
        # ----------------------------------------------------
        # " Einfügen"
        insert_section = menu.addMenu(qta.icon("fa5s.plus"), self.tr("context_insert"))

        # Seiten einfügen
        # " Seiten einfügen"
        page_action = insert_section.addAction(
            qta.icon("fa5s.file-pdf"), self.tr("context_insert_pages")
        )
        page_action.triggered.connect(lambda: self.insert_pages())
        insert_section.addSeparator()

        # Text einfügen
        # " Text einfügen"
        text_action = insert_section.addAction(
            qta.icon("fa5s.font"), self.tr("insert_another_text")
        )
        text_action.triggered.connect(
            lambda: self.open_text_template_dialog(local_pos, clicked_page)
        )
        insert_section.addSeparator()

        # Kreuz einfügen
        # " Kreuz einfügen"
        cross_action = insert_section.addAction(
            qta.icon("fa5s.times"), self.tr("insert_another_cross")
        )
        cross_action.triggered.connect(
            lambda: self._insert_cross_at_position(local_pos, clicked_page)
        )
        insert_section.addSeparator()

        # Unterschrift einfügen (Untermenü)
        # " Signatur einfügen"
        signature_submenu = insert_section.addMenu(
            qta.icon("fa5s.pen"), self.tr("signature_menu")
        )
        # " Signatur 1"
        sig1_action = signature_submenu.addAction(
            qta.icon("fa5s.signature"), self.tr("insert_another_signature_1")
        )
        sig1_action.triggered.connect(
            lambda: self.insert_signature_at_position(local_pos, 1)
        )
        # " Signatur 2"
        sig2_action = signature_submenu.addAction(
            qta.icon("fa5s.signature"), self.tr("insert_another_signature_2")
        )
        sig2_action.triggered.connect(
            lambda: self.insert_signature_at_position(local_pos, 2)
        )
        insert_section.addSeparator()

        # Bild einfügen
        # " Bild einfügen"
        image_action = insert_section.addAction(
            qta.icon("fa5s.image"), self.tr("insert_another_image")
        )
        image_action.triggered.connect(
            lambda: self.insert_image_at_position(local_pos, clicked_page)
        )
        insert_section.addSeparator()

        # Formen einfügen (Untermenü)
        # " Form einfügen"
        form_submenu = insert_section.addMenu(
            qta.icon("fa5s.shapes"), self.tr("form_menu")
        )
        # " Rechteck"
        rect_action = form_submenu.addAction(
            qta.icon("fa5s.square"), self.tr("insert_another_form_rect")
        )
        rect_action.triggered.connect(
            lambda: self.insert_form_at_position(
                local_pos, clicked_page, "rectangle", False
            )
        )
        # " Ellipse"
        ellipse_action = form_submenu.addAction(
            qta.icon("fa5s.circle"), self.tr("insert_another_form_ellipse")
        )
        ellipse_action.triggered.connect(
            lambda: self.insert_form_at_position(
                local_pos, clicked_page, "ellipse", False
            )
        )
        form_submenu.addSeparator()
        # " Linie (2 Klicks)"
        line_action = form_submenu.addAction(
            qta.icon("fa5s.minus"), self.tr("insert_another_form_line")
        )
        line_action.triggered.connect(
            lambda: self.insert_form_at_position(local_pos, clicked_page, "line", False)
        )
        # " Pfeil (2 Klicks)"
        arrow_action = form_submenu.addAction(
            qta.icon("fa5s.long-arrow-alt-right"),
            self.tr("insert_another_form_arrow", False),
        )
        arrow_action.triggered.connect(
            lambda: self.insert_form_at_position(local_pos, clicked_page, "arrow")
        )
        form_submenu.addSeparator()
        # " Einstellungen..." - ALLGEMEINE EINSTELLUNGEN (ohne Form-Item)
        form_settings_action = form_submenu.addAction(
            qta.icon("fa5s.cog"), self.tr("form_settings")
        )
        form_settings_action.triggered.connect(self.open_form_settings)

        insert_section.addSeparator()

        # Seitenzahlen einfügen
        page_number_action = insert_section.addAction(
            qta.icon("fa5s.hashtag"), self.tr("page_numbers_title")
        )
        page_number_action.triggered.connect(self._add_page_numbers)

        insert_section.addSeparator()

        # ===== VOLLBILD-WASSERZEICHEN (zwei separate Einträge) =====
        watermark_submenu = insert_section.addMenu(
            qta.icon("fa5s.tint"), self.tr("menu_watermark")
        )

        # Text Wasserzeichen
        fullpage_text_action = watermark_submenu.addAction(
            qta.icon("fa5s.font"), self.tr("fullpage_text_watermark_title")
        )
        fullpage_text_action.triggered.connect(self._add_fullpage_text_watermark)

        watermark_submenu.addSeparator()

        # Bild Wasserzeichen
        fullpage_image_action = watermark_submenu.addAction(
            qta.icon("fa5s.image"), self.tr("fullpage_image_watermark_title")
        )
        fullpage_image_action.triggered.connect(self._add_fullpage_image_watermark)

        watermark_submenu.addSeparator()
        insert_section.addSeparator()
        menu.addSeparator()

        # ----------------------------------------------------
        # AUSLÖSCHUNGEN (immer verfügbar wenn kein Modus aktiv) ---
        # ----------------------------------------------------
        # " Einfügen"
        redact_section = menu.addMenu(qta.icon("fa5s.eraser"), self.tr("menu_redact"))

        # Auslöschungen (zwei separate Einträge)
        redact_black_action = redact_section.addAction(
            qta.icon("fa5s.eraser"), self.tr("redact_add_black")
        )
        redact_black_action.triggered.connect(
            lambda: self._add_redaction_rect_at_position(
                local_pos, clicked_page, "black"
            )
        )

        redact_section.addSeparator()

        redact_white_action = redact_section.addAction(
            qta.icon("fa5s.eraser"), self.tr("redact_add_white")
        )
        redact_white_action.triggered.connect(
            lambda: self._add_redaction_rect_at_position(
                local_pos, clicked_page, "white"
            )
        )

        redact_section.addSeparator()
        insert_section.addSeparator()

        # -----------------------------------
        # ZOOM-MENÜ (ganz unten) ---
        # -----------------------------------
        menu.addSeparator()
        # "Zoom"
        zoom_menu_ctx = QMenu(self.tr("context_zoom"), self)
        zoom_menu_ctx.setIcon(qta.icon("fa5s.search-plus"))
        zoom_menu_ctx.addAction(self.zoom_page_action)
        zoom_menu_ctx.addAction(self.zoom_two_pages_action)
        zoom_menu_ctx.addAction(self.zoom_overview_action)
        menu.addMenu(zoom_menu_ctx)

        self.update_zoom_menu()
        self.update_zoom_menu_checks()

        menu.exec_(view.mapToGlobal(position))

    def update_zoom_menu(self):
        """Zoom wird deaktiviert wenn Suche aktiv (für beide Menüs)"""
        state = not self.search_active
        self.zoom_page_action.setEnabled(state)
        self.zoom_two_pages_action.setEnabled(state)
        self.zoom_overview_action.setEnabled(state)

    def update_zoom_menu_checks(self):
        """Aktualisiert die Haken im Zoom-Menü basierend auf dem aktuellen Modus"""
        # Alle Checks zurücksetzen
        self.zoom_page_action.setChecked(False)
        self.zoom_two_pages_action.setChecked(False)
        self.zoom_overview_action.setChecked(False)

        # Aktiven Modus markieren
        if self.zoom_mode == "page":
            self.zoom_page_action.setChecked(True)
        elif self.zoom_mode == "two_pages":
            self.zoom_two_pages_action.setChecked(True)
        elif self.zoom_mode == "overview":
            self.zoom_overview_action.setChecked(True)

    def goto_page_full_view(self, page_index):
        """Springt zur Seite und wechselt zur Standard-Vollansicht - Seitenanfang oben"""
        # Zoom-Modus zuerst ändern
        self.zoom_mode = "page"
        self.last_zoom_mode = "page"

        # Scene neu aufbauen
        self.scene.clear()
        self.page_items = []
        self._arrange_single_pages()

        # Zoom anwenden
        self.graphics_view.resetTransform()

        # Zur korrekten Seite springen (Seitenanfang oben)
        self.current_page = page_index

        # Kurze Verzögerung für stabileres Scrolling
        QTimer.singleShot(100, lambda: self.scroll_to_page_top())

        # "Vollansicht Seite {0}"
        self.say(self.tr("full_view_page", page_index + 1))

    ###-------------------------------------------

    def mark_page_empty(self, page_index):
        """Markiert eine Seite als leer"""
        if not 0 <= page_index < len(self.page_items):
            return

        if page_index in self.empty_pages:
            # Seite bereits als leer markiert -> Markierung entfernen
            self.empty_pages.remove(page_index)
            self._remove_empty_markings(page_index)
            message = self.tr("mark_removed", page_index + 1)
            self.say(message, convert_numbers=True)
        else:
            # Prüfen ob nach dem Markieren alle Seiten leer wären
            total_pages = len(self.page_items)
            if len(self.empty_pages) + 1 >= total_pages:
                # Es muss mindestens eine Seite im Dolument verbleiben!
                self.say(self.tr("pages_cannot_delete_all_pages"))

                dialog = myUniversalDialog(
                    self,
                    title=self.tr("warning"),
                    message=self.tr("pages_cannot_delete_all_pages"),
                    text_alignment=Qt.AlignLeft,
                    buttons=[(self.tr("btn_ok"), "success", "ok")],
                    default_button="ok",
                    icon_type="",
                    voice_message="",
                )
                dialog.exec_()
                return

            # Als leer markieren
            self.empty_pages.append(page_index)
            self._add_empty_markings(page_index)
            message = self.tr("mark_empty", page_index + 1)
            self.say(message, convert_numbers=True)

    def _add_empty_markings(self, page_index):
        """Fügt visuelle Markierungen für leere Seiten hinzu"""
        item = self.page_items[page_index]
        rect = item.boundingRect()

        # Roter Rahmen
        border = QGraphicsRectItem(item.x(), item.y(), rect.width(), rect.height())
        border.setPen(QPen(QColor(255, 0, 0), 4))
        border.setData(0, f"empty_marking_{page_index}")
        self.scene.addItem(border)

        # "LEER" Text
        text = self.scene.addText("LEER")
        if self.dark_mode:
            text.setDefaultTextColor(QColor(255, 100, 100))
        else:
            text.setDefaultTextColor(QColor(200, 0, 0))

        font = text.font()
        font.setPointSize(20)
        font.setBold(True)
        text.setFont(font)

        text_width = text.boundingRect().width()
        text_height = text.boundingRect().height()
        text.setPos(
            item.x() + rect.width() / 2 - text_width / 2,
            item.y() + rect.height() / 2 - text_height / 2,
        )
        text.setData(0, f"empty_text_{page_index}")
        self.scene.addItem(text)

    def _remove_empty_markings(self, page_index):
        """Entfernt Markierungen von leeren Seiten"""
        for item in self.scene.items():
            if isinstance(item, (QGraphicsRectItem, QGraphicsTextItem)) and item.data(
                0
            ) in [f"empty_marking_{page_index}", f"empty_text_{page_index}"]:
                self.scene.removeItem(item)

    ###------------------------------------------

    def delete_page(self, page_index):
        """Löscht eine Seite aus dem PDF.
        - Backup aktiv: Original überschreiben, Backup mit Zeitstempel.
        - Backup inaktiv: Original bleibt, neue Datei mit Suffix und Zeitstempel.
        """
        if not 0 <= page_index < len(self.page_pixmaps):
            return

        # Prüfen ob es die letzte Seite ist
        if len(self.page_pixmaps) == 1:
            self.say(self.tr("pages_cannot_delete_last_page"))
            myUniversalDialog(
                self,
                title=self.tr("warning"),
                message=self.tr("pages_cannot_delete_last_page"),
                buttons=[(self.tr("btn_ok"), "success", "ok")],
                icon_type="",
                voice_message=self.tr("pages_cannot_delete_last_page"),
                text_alignment=Qt.AlignLeft,
            ).exec_()
            return

        dialog = myUniversalDialog(
            self,
            title=self.tr("pages_delete"),
            message=self.tr("delete_page_confirm", page_index + 1),
            text_alignment=Qt.AlignLeft,
            buttons=[
                (self.tr("confirm_yes"), "danger", "yes"),
                (self.tr("confirm_no"), "dark", "no"),
            ],
            default_button="no",
            icon_type="",
            voice_message=self.tr("delete_page_confirm_voice", page_index + 1),
        )
        dialog.exec_()
        if dialog.result_value != "yes":
            return

        try:
            current_mode = self.zoom_mode
            backup_path = None

            # 1. Backup erstellen (nur wenn aktiv)
            if self.create_backup:
                backup_path = self.get_backup_filename(self.pdf_path)
                shutil.copy2(self.pdf_path, backup_path)
                print(f"Backup vor Seitenlöschung erstellt: {backup_path}")

            # 2. Neue PDF ohne die gelöschte Seite erstellen
            doc = fitz.open(self.pdf_path)
            total_pages = len(doc)
            if total_pages == 1:
                doc.close()
                self.say(self.tr("pages_cannot_delete_last_page"))
                return

            new_doc = fitz.open()
            for i in range(total_pages):
                if i != page_index:
                    new_doc.insert_pdf(doc, from_page=i, to_page=i)
            doc.close()

            # 3. Zielpfad bestimmen
            if self.create_backup:
                # Backup aktiv: Original überschreiben
                final_path = self.pdf_path
                new_doc.save(final_path, garbage=4, deflate=True)
                result_path = final_path
            else:
                # Backup inaktiv: Neue Datei mit Suffix erstellen
                base_clean = FilenameGenerator.clean_base_name(
                    os.path.splitext(os.path.basename(self.pdf_path))[0]
                )
                suffix = self.tr("filename_pages_deleted")
                final_path = FilenameGenerator.generate(
                    pdf_path=self.pdf_path,
                    base_name=base_clean,
                    suffixes=[suffix],
                    is_protected=False,
                    update_timestamp=True,
                )
                counter = 1
                base, ext = os.path.splitext(final_path)
                while os.path.exists(final_path):
                    final_path = f"{base}_{counter}{ext}"
                    counter += 1
                new_doc.save(final_path, garbage=4, deflate=True)
                result_path = final_path

            new_doc.close()

            # 4. PDF neu laden (die geänderte oder neue Datei)
            self.pdf_path = result_path
            self.load_pdf()
            self.set_zoom_mode(current_mode)
            self.empty_pages = [p for p in self.empty_pages if p != page_index]

            # 5. Erfolgsmeldung
            if self.create_backup:
                self.say(self.tr("page_deleted", page_index + 1), convert_numbers=True)
                myUniversalDialog(
                    self,
                    title=self.tr("success"),
                    message=self.tr("page_deleted", page_index + 1),
                    buttons=[(self.tr("btn_ok"), "success", "ok")],
                    icon_type="",
                    voice_message="",
                    text_alignment=Qt.AlignLeft,
                ).exec_()
            else:
                msg = self.tr(
                    "page_deleted_new_file",
                    page_index + 1,
                    os.path.basename(final_path),
                )
                self.say(self.tr("page_deleted_voice", page_index + 1))
                dialog = myUniversalDialog(
                    self,
                    title=self.tr("success"),
                    message=msg,
                    buttons=[
                        (self.tr("btn_open"), "success", "open"),
                        (self.tr("btn_close"), "primary", "close"),
                    ],
                    icon_type="",
                    voice_message=self.tr("page_deleted_voice", page_index + 1),
                    text_alignment=Qt.AlignLeft,
                )
                dialog.exec_()
                if dialog.result_value == "open":
                    self.load_pdf(final_path)

        except Exception as e:
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=f"{self.tr('delete_error')}: {str(e)}",
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=f"{self.tr('delete_error')}: {str(e)}",
                text_alignment=Qt.AlignLeft,
            ).exec_()

    def delete_all_empty_pages(self):
        """Löscht alle als leer markierten Seiten.
        - Backup aktiv: Original überschreiben, Backup mit Zeitstempel.
        - Backup inaktiv: Original bleibt, neue Datei mit Suffix und Zeitstempel.
        """
        if not self.empty_pages:
            self.say(self.tr("no_empty_pages"))
            return

        empty_count = len(self.empty_pages)
        total_pages = len(self.page_pixmaps)

        if empty_count == total_pages or (total_pages - empty_count) == 0:
            self.say(self.tr("pages_cannot_delete_all_pages"))
            myUniversalDialog(
                self,
                title=self.tr("warning"),
                message=self.tr("pages_cannot_delete_all_pages"),
                buttons=[(self.tr("btn_ok"), "success", "ok")],
                icon_type="",
                voice_message="",
                text_alignment=Qt.AlignLeft,
            ).exec_()
            return

        dialog = myUniversalDialog(
            self,
            title=self.tr("pages_delete"),
            message=self.tr("delete_empty_confirm", empty_count),
            text_alignment=Qt.AlignLeft,
            buttons=[
                (self.tr("confirm_yes"), "danger", "yes"),
                (self.tr("confirm_no"), "dark", "no"),
            ],
            icon_type="",
            default_button="no",
            voice_message=self.tr("delete_empty_confirm_voice", empty_count),
        )
        dialog.exec_()
        if not (hasattr(dialog, "result_value") and dialog.result_value == "yes"):
            return

        try:
            current_mode = self.zoom_mode
            empty_pages_sorted = sorted(self.empty_pages, reverse=True)

            # 1. Backup erstellen (nur wenn aktiv)
            if self.create_backup:
                backup_path = self.get_backup_filename(self.pdf_path)
                shutil.copy2(self.pdf_path, backup_path)
                print(f"Backup vor Löschung leerer Seiten erstellt: {backup_path}")

            # 2. Neue PDF ohne leere Seiten erstellen
            doc = fitz.open(self.pdf_path)
            total_doc_pages = len(doc)
            if len(empty_pages_sorted) == total_doc_pages:
                doc.close()
                self.say(self.tr("pages_cannot_delete_all_pages"))
                return

            new_doc = fitz.open()
            for i in range(total_doc_pages):
                if i not in empty_pages_sorted:
                    new_doc.insert_pdf(doc, from_page=i, to_page=i)
            doc.close()

            # 3. Zielpfad bestimmen
            if self.create_backup:
                final_path = self.pdf_path
                new_doc.save(final_path, garbage=4, deflate=True)
                result_path = final_path
            else:
                base_clean = FilenameGenerator.clean_base_name(
                    os.path.splitext(os.path.basename(self.pdf_path))[0]
                )
                suffix = self.tr("filename_pages_deleted")
                final_path = FilenameGenerator.generate(
                    pdf_path=self.pdf_path,
                    base_name=base_clean,
                    suffixes=[suffix],
                    is_protected=False,
                    update_timestamp=True,
                )
                counter = 1
                base, ext = os.path.splitext(final_path)
                while os.path.exists(final_path):
                    final_path = f"{base}_{counter}{ext}"
                    counter += 1
                new_doc.save(final_path, garbage=4, deflate=True)
                result_path = final_path

            new_doc.close()

            # 4. PDF neu laden
            self.pdf_path = result_path
            self.load_pdf()
            self.set_zoom_mode(current_mode)
            self.empty_pages = []

            # 5. Erfolgsmeldung
            if self.create_backup:
                self.say(
                    self.tr("empty_pages_deleted", empty_count), convert_numbers=True
                )
                myUniversalDialog(
                    self,
                    title=self.tr("success"),
                    message=self.tr("empty_pages_deleted", empty_count),
                    buttons=[(self.tr("btn_ok"), "success", "ok")],
                    icon_type="",
                    voice_message="",
                    text_alignment=Qt.AlignLeft,
                ).exec_()
            else:
                msg = self.tr(
                    "empty_pages_deleted_new_file",
                    empty_count,
                    os.path.basename(final_path),
                )
                self.say(self.tr("empty_pages_deleted_voice", empty_count))
                dialog = myUniversalDialog(
                    self,
                    title=self.tr("success"),
                    message=msg,
                    buttons=[
                        (self.tr("btn_open"), "success", "open"),
                        (self.tr("btn_close"), "primary", "close"),
                    ],
                    icon_type="",
                    voice_message=self.tr("empty_pages_deleted_voice", empty_count),
                    text_alignment=Qt.AlignLeft,
                )
                dialog.exec_()
                if dialog.result_value == "open":
                    self.load_pdf(final_path)

        except Exception as e:
            myUniversalDialog(
                self,
                title=self.tr("error"),
                message=f"{self.tr('error_occurred')}: {str(e)}",
                buttons=[(self.tr("btn_ok"), "danger", "ok")],
                icon_type="error",
                voice_message=f"{self.tr('error_occurred')}: {str(e)}",
                text_alignment=Qt.AlignLeft,
            ).exec_()

