    def mark_page_export(self, page_index):
        """Markiert eine Seite für Export"""
        if not 0 <= page_index < len(self.page_items):
            return

        if page_index in self.export_pages:
            # Seite bereits für Export markiert -> Markierung entfernen
            self.export_pages.remove(page_index)
            self._remove_export_markings(page_index)
            # "Export-Markierung von Seite {0} entfernt"
            message = self.tr("mark_export_removed", page_index + 1)
            self.say(message, convert_numbers=True)
        else:
            # Für Export markieren
            self.export_pages.append(page_index)
            self._add_export_markings(page_index)
            # "Seite {0} für Export markiert"
            message = self.tr("mark_export", page_index + 1)
            self.say(message, convert_numbers=True)

    def _add_export_markings(self, page_index):
        """Fügt visuelle Markierungen für Export hinzu"""
        item = self.page_items[page_index]
        rect = item.boundingRect()

        # Blauer Rahmen
        border = QGraphicsRectItem(item.x(), item.y(), rect.width(), rect.height())
        border.setPen(QPen(QColor(0, 100, 255), 4))
        border.setData(0, f"export_marking_{page_index}")
        self.scene.addItem(border)

        # "EXPORT" Text
        text = self.scene.addText("EXPORT")
        if self.dark_mode:
            text.setDefaultTextColor(QColor(100, 150, 255))
        else:
            text.setDefaultTextColor(QColor(0, 50, 200))

        font = text.font()
        font.setPointSize(20)
        font.setBold(True)
        text.setFont(font)

        text_width = text.boundingRect().width()
        text_height = text.boundingRect().height()
        text.setPos(
            item.x() + rect.width() / 2 - text_width / 2,
            item.y() + rect.height() / 2 - text_height / 2,
        )
        text.setData(0, f"export_text_{page_index}")
        self.scene.addItem(text)

    def _remove_export_markings(self, page_index):
        """Entfernt Markierungen von Export-Seiten"""
        for item in self.scene.items():
            if isinstance(item, (QGraphicsRectItem, QGraphicsTextItem)) and item.data(
                0
            ) in [f"export_marking_{page_index}", f"export_text_{page_index}"]:
                self.scene.removeItem(item)

